{
  "name": "Thai Procurement Registry",
  "description": "A comprehensive procurement and hiring management system featuring Purchase Orders, Hiring Orders, Receiving Reports, and Dashboard analytics with automatic running number logic based on Thai government regulations."
}

export enum RecordType {
    PURCHASE = 'PURCHASE', // จัดซื้อ
    HIRING = 'HIRING',     // จัดจ้าง
}

export interface ProcurementRecord {
    id: string;
    requestId: string; // เลขที่ใบขอ (Key link)
    requestDate: string; // วัน/เดือน/ปี
    category: string; // หมวดพัสดุ
    itemCount: number; // จำนวนรายการ
    amount: number; // จำนวนเงิน
    company: string; // บริษัท
    remarks: string; // หมายเหตุ

    // Auto-generated or Logic-based fields
    officialNumber: string | null; // เลขสั่งซื้อ/สั่งจ้าง (Run if > 5000)
    type: RecordType;

    // Linked Data (from manual entry or separate linkage)
    considerationId?: string; // เลขพิจารณา
    considerationDate?: string; // วันที่พิจารณา

    createdAt: number;
}

export interface ReceivingReport {
    id: string;
    receiveDate: string; // วัน/เดือน/ปีใบรับของ
    deliveryNoteNo: string; // เลขที่ใบส่งของ
    requestId: string; // เลขที่ใบขอ (Link to ProcurementRecord)
    category: string; // หมวดพัสดุ
    createdAt: number;
}

export interface ConsiderationRecord {
    id: string;
    requestId: string;
    considerationNumber: string;
    considerationDate: string;
}

// For Dashboard
export interface DashboardStat {
    totalPurchase: number;
    totalHiring: number;
    purchaseCount: number;
    hiringCount: number;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord } from '../types';

interface AppContextType {
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber'>) => void;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    // Mock Data Initialization
    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);

    // Helper to generate Thai Year (e.g., 2567)
    const getThaiYear = (dateString: string) => {
        const date = new Date(dateString);
        return date.getFullYear() + 543;
    };

    // Helper to generate running number: e.g., 1/2567
    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        if (amount <= 5000) return null;

        const thaiYear = getThaiYear(dateStr);
        // Filter existing records of same type, same year, that have an official number
        const existingInYear = procurements.filter(p => 
            p.type === type && 
            p.officialNumber && 
            getThaiYear(p.requestDate) === thaiYear
        );

        // Simple max + 1 logic (In a real app, this needs robust backend locking)
        let maxNum = 0;
        existingInYear.forEach(p => {
            const parts = p.officialNumber?.split('/');
            if (parts && parts[0]) {
                const num = parseInt(parts[0]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });

        return `${maxNum + 1}/${thaiYear}`;
    };

    const addProcurement = (data: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber'>) => {
        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);

        const newRecord: ProcurementRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
            officialNumber
        };
        setProcurements(prev => [...prev, newRecord]);
    };

    const updateProcurement = (id: string, data: Partial<ProcurementRecord>) => {
        setProcurements(prev => prev.map(item => {
            if (item.id !== id) return item;

            // Re-calculate official number if amount changes crossing the 5000 threshold
            // Note: In real production, changing an assigned ID is risky, but we'll follow logic here.
            let newOfficialNumber = item.officialNumber;
            if (data.amount !== undefined && data.requestDate !== undefined) {
                 // Simplification: Only regenerate if it didn't exist and now should, or strictly enforcing the rule
                 if (data.amount > 5000 && !item.officialNumber) {
                     newOfficialNumber = generateRunningNumber(item.type, data.amount, data.requestDate);
                 } else if (data.amount <= 5000) {
                     newOfficialNumber = null;
                 }
            }

            return { ...item, ...data, officialNumber: newOfficialNumber };
        }));
    };

    const deleteProcurement = (id: string) => {
        setProcurements(prev => prev.filter(p => p.id !== id));
    };

    const addReceiving = (data: Omit<ReceivingReport, 'id' | 'createdAt'>) => {
        const newRecord: ReceivingReport = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
        };
        setReceivings(prev => [...prev, newRecord]);
    };

    const deleteReceiving = (id: string) => {
        setReceivings(prev => prev.filter(r => r.id !== id));
    };

    const addConsideration = (record: ConsiderationRecord) => {
        setConsiderations(prev => [...prev, { ...record, id: Math.random().toString(36).substr(2, 9) }]);
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    return (
        <AppContext.Provider value={{
            procurements,
            receivings,
            considerations,
            addProcurement,
            updateProcurement,
            deleteProcurement,
            addReceiving,
            deleteReceiving,
            addConsideration,
            getLinkedData
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

import React from 'react';
import { LayoutDashboard, ShoppingCart, Briefcase, Truck, FileText, PieChart } from 'lucide-react';

interface SidebarProps {
    activeTab: string;
    setActiveTab: (tab: string) => void;
}

