    return (
        <div className="w-64 bg-slate-900 text-white flex flex-col h-screen fixed left-0 top-0 overflow-y-auto">
            <div className="p-6 border-b border-slate-700">
                <h1 className="text-xl font-bold text-blue-400">Procurement OS</h1>
                <p className="text-xs text-slate-400 mt-1">ระบบบริหารงานพัสดุ</p>
            </div>
            <nav className="flex-1 p-4 space-y-2">
                {menuItems.map((item) => {
                    const Icon = item.icon;
                    return (
                        <button
                            key={item.id}
                            onClick={() => setActiveTab(item.id)}
                            className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                                activeTab === item.id 
                                ? 'bg-blue-600 text-white shadow-lg' 
                                : 'text-slate-300 hover:bg-slate-800'
                            }`}
                        >
                            <Icon size={20} />
                            <span>{item.label}</span>
                        </button>
                    );
                })}
            </nav>
            <div className="p-4 border-t border-slate-700">
                <div className="text-xs text-slate-500 text-center">
                    Version 1.0.0
                </div>
            </div>
        </div>
    );
};

export default Sidebar;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { RecordType, ProcurementRecord } from '../types';
import { Plus, Edit2, Trash2, X, Check } from 'lucide-react';

interface Props {
    type: RecordType;
    title: string;
}

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, addProcurement, updateProcurement, deleteProcurement, getLinkedData, considerations } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);

    // Form State
    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: ''
    });

    const filteredData = procurements.filter(p => p.type === type);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (editingId) {
            updateProcurement(editingId, formData);
        } else {
            addProcurement({
                ...formData,
                type: type
            });
        }
        closeModal();
    };

    const openEdit = (record: ProcurementRecord) => {
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks
        });
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setFormData({
            requestId: '',
            requestDate: '',
            category: '',
            itemCount: 0,
            amount: 0,
            company: '',
            remarks: ''
        });
    };

    // Auto-fill consideration if exists in considerations list when requestId changes
    const handleRequestIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setFormData({ ...formData, requestId: val });
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg shadow-sm transition-all"
                >
                    <Plus size={18} />
                    <span>บันทึกรายการใหม่</span>
                </button>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3">เลขที่ใบขอ</th>
                                <th className="px-4 py-3">วันที่ขอ</th>
                                <th className="px-4 py-3">เลขพิจารณา</th>
                                <th className="px-4 py-3">วันที่พิจารณา</th>
                                <th className="px-4 py-3 bg-blue-50">เลขสั่ง{type === RecordType.PURCHASE ? 'ซื้อ' : 'จ้าง'}</th>
                                <th className="px-4 py-3 bg-green-50">เลขรับของ</th>
                                <th className="px-4 py-3 bg-green-50">วันที่รับของ</th>
                                <th className="px-4 py-3 text-right">จำนวนเงิน</th>
                                <th className="px-4 py-3">บริษัท</th>
                                <th className="px-4 py-3 text-center">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredData.length === 0 ? (
                                <tr>
                                    <td colSpan={10} className="px-4 py-8 text-center text-slate-400">
                                        ไม่พบข้อมูล
                                    </td>
                                </tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    // Consideration can come from linked consideration record OR manual linkage logic
                                    // For now, let's use the Linked Data from Considerations module
                                    const consNum = linked.consideration?.considerationNumber || '-';
                                    const consDate = linked.consideration?.considerationDate || '-';

                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                                            <td className="px-4 py-3 font-medium text-slate-900">{item.requestId}</td>
                                            <td className="px-4 py-3">{item.requestDate}</td>
                                            <td className="px-4 py-3 text-orange-600">{consNum}</td>
                                            <td className="px-4 py-3">{consDate}</td>
                                            <td className="px-4 py-3 bg-blue-50 font-bold text-blue-700">
                                                {item.officialNumber || <span className="text-slate-300 font-normal italic">ไม่ถึงเกณฑ์</span>}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50 text-green-700">
                                                {linked.receiving?.deliveryNoteNo || '-'}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50">
                                                {linked.receiving?.receiveDate || '-'}
                                            </td>
                                            <td className="px-4 py-3 text-right font-medium">
                                                {item.amount.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[150px]">{item.company}</td>
                                            <td className="px-4 py-3 text-center">
                                                <div className="flex justify-center space-x-2">
                                                    <button onClick={() => openEdit(item)} className="p-1.5 hover:bg-slate-200 rounded text-slate-600">
                                                        <Edit2 size={16} />
                                                    </button>
                                                    <button onClick={() => deleteProcurement(item.id)} className="p-1.5 hover:bg-red-100 rounded text-red-500">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden animate-fade-in">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                            <h3 className="text-lg font-semibold text-slate-800">
                                {editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}
                            </h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">
                                <X size={24} />
                            </button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 grid grid-cols-2 gap-6">
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">เลขที่ใบขอ *</label>
                                <input 
                                    required
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.requestId}
                                    onChange={handleRequestIdChange}
                                    placeholder="เช่น REQ-001"
                                />
                                <p className="text-xs text-slate-400 mt-1">ใช้สำหรับเชื่อมโยงข้อมูลกับระบบอื่น</p>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">วัน/เดือน/ปี ที่ขอ *</label>
                                <input 
                                    required
                                    type="date" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.requestDate}
                                    onChange={e => setFormData({...formData, requestDate: e.target.value})}
                                />
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                <select 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.category}
                                    onChange={e => setFormData({...formData, category: e.target.value})}
                                >
                                    <option value="">เลือกหมวด...</option>
                                    <option value="office">วัสดุสำนักงาน</option>
                                    <option value="computer">คอมพิวเตอร์</option>
                                    <option value="service">จ้างเหมาบริการ</option>
                                    <option value="construction">ก่อสร้าง</option>
                                    <option value="other">อื่นๆ</option>
                                </select>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                <input 
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.company}
                                    onChange={e => setFormData({...formData, company: e.target.value})}
                                />
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                <input 
                                    type="number" 
                                    min="1"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.itemCount}
                                    onChange={e => setFormData({...formData, itemCount: Number(e.target.value)})}
                                />
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนเงิน (บาท) *</label>
                                <input 
                                    required
                                    type="number" 
                                    min="0"
                                    step="0.01"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none bg-blue-50"
                                    value={formData.amount}
                                    onChange={e => setFormData({...formData, amount: Number(e.target.value)})}
                                />
                                <p className="text-xs text-blue-500 mt-1">หากเกิน 5,000 จะออกเลขคุมอัตโนมัติ</p>
                            </div>

                            <div className="col-span-2">
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                <textarea 
                                    rows={3}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.remarks}
                                    onChange={e => setFormData({...formData, remarks: e.target.value})}
                                />
                            </div>

                            <div className="col-span-2 flex justify-end space-x-3 pt-4 border-t border-slate-100">
                                <button type="button" onClick={closeModal} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">
                                    ยกเลิก
                                </button>
                                <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-md transition-colors flex items-center">
                                    <Check size={18} className="mr-2" />
                                    บันทึกข้อมูล
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { Plus, Trash2, X, Check } from 'lucide-react';
import { RecordType } from '../types';

const ReceivingPage: React.FC = () => {
    const { receivings, procurements, addReceiving, deleteReceiving, considerations } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);

    const [formData, setFormData] = useState({
        receiveDate: '',
        deliveryNoteNo: '',
        requestId: '',
        category: ''
    });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        addReceiving(formData);
        setIsModalOpen(false);
        setFormData({ receiveDate: '', deliveryNoteNo: '', requestId: '', category: '' });
    };

    // Helper to find linked procurement info
    const getLinkedInfo = (requestId: string) => {
        const proc = procurements.find(p => p.requestId === requestId);
        const cons = considerations.find(c => c.requestId === requestId);
        return { proc, cons };
    };

    return (
        <div className="p-6">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-slate-800">ทะเบียนใบรับของ</h2>
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="flex items-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg shadow-sm transition-all"
                >
                    <Plus size={18} />
                    <span>สร้างใบรับของ</span>
                </button>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3">วันที่รับของ</th>
                                <th className="px-4 py-3">เลขที่ใบส่งของ</th>
                                <th className="px-4 py-3">เลขที่ใบขอ</th>
                                <th className="px-4 py-3 bg-blue-50">เลขสั่งซื้อ/จ้าง</th>
                                <th className="px-4 py-3">เลขที่ขออนุมัติ</th>
                                <th className="px-4 py-3">หมวดพัสดุ</th>
                                <th className="px-4 py-3 text-right">จำนวนรายการ</th>
                                <th className="px-4 py-3 text-right">จำนวนเงิน</th>
                                <th className="px-4 py-3 text-center">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {receivings.length === 0 ? (
                                <tr>
                                    <td colSpan={9} className="px-4 py-8 text-center text-slate-400">
                                        ยังไม่มีรายการใบรับของ
                                    </td>
                                </tr>
                            ) : (
                                receivings.map((item) => {
                                    const { proc, cons } = getLinkedInfo(item.requestId);
                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50">
