const Dashboard: React.FC = () => {
    const { procurements } = useApp();

    const purchase = procurements.filter(p => p.type === RecordType.PURCHASE);
    const hiring = procurements.filter(p => p.type === RecordType.HIRING);

    const totalPurchase = purchase.reduce((acc, curr) => acc + curr.amount, 0);
    const totalHiring = hiring.reduce((acc, curr) => acc + curr.amount, 0);

    const stats = [
        { title: 'มูลค่าจัดซื้อรวม', value: totalPurchase.toLocaleString(), icon: ShoppingCart, color: 'bg-blue-500' },
        { title: 'มูลค่าจัดจ้างรวม', value: totalHiring.toLocaleString(), icon: Briefcase, color: 'bg-indigo-500' },
        { title: 'จำนวนรายการจัดซื้อ', value: purchase.length, icon: TrendingUp, color: 'bg-sky-500' },
        { title: 'จำนวนรายการจัดจ้าง', value: hiring.length, icon: TrendingUp, color: 'bg-violet-500' },
    ];

    // Prepare chart data
    const dataByMonth = Array.from({ length: 12 }, (_, i) => {
        const month = i + 1;
        const pSum = purchase
            .filter(item => new Date(item.requestDate).getMonth() + 1 === month)
            .reduce((acc, curr) => acc + curr.amount, 0);
        const hSum = hiring
            .filter(item => new Date(item.requestDate).getMonth() + 1 === month)
            .reduce((acc, curr) => acc + curr.amount, 0);
        return {
            name: `Month ${month}`,
            Purchase: pSum,
            Hiring: hSum
        };
    });

    const pieData = [
        { name: 'จัดซื้อ (Purchase)', value: totalPurchase },
        { name: 'จัดจ้าง (Hiring)', value: totalHiring },
