                        <BarChart data={dataByMonth}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="name" fontSize={12} />
                            <YAxis fontSize={12} />
                            <Tooltip />
                            <Legend />
                            <Bar dataKey="Purchase" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                            <Bar dataKey="Hiring" fill="#6366f1" radius={[4, 4, 0, 0]} />
