                            <input 
                                type="text" 
                                className="flex-1 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none font-medium text-slate-700"
                                value={localSettings.requestIdPrefix}
                                onChange={e => setLocalSettings({...localSettings, requestIdPrefix: e.target.value})}
                                placeholder="เช่น สพ.๐๐๓๓.๐๒/"
                            />
                        </div>
                        <p className="text-xs text-slate-400 mt-2">
                            ค่าที่กำหนดจะถูกนำไปเติมให้อัตโนมัติเมื่อสร้างรายการจัดซื้อ/จัดจ้างใหม่
                        </p>
                    </div>

                    <div className="pt-4 flex items-center justify-between border-t border-slate-100">
                        {saved && (
                            <span className="text-green-600 text-sm font-medium animate-fade-in">
                                บันทึกเรียบร้อยแล้ว!
