                            </h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">
                                <X size={24} />
                            </button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 grid grid-cols-2 gap-6">
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">เลขที่ใบขอ *</label>
                                <input 
                                    required
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.requestId}
                                    onChange={handleRequestIdChange}
                                    placeholder={settings.requestIdPrefix || "เช่น REQ-001"}
                                />
                                <p className="text-xs text-slate-400 mt-1">ตั้งค่ารูปแบบได้ที่เมนู "ตั้งค่าระบบ"</p>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">วัน/เดือน/ปี ที่ขอ *</label>
                                <input 
                                    required
                                    type="date" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.requestDate}
                                    onChange={e => setFormData({...formData, requestDate: e.target.value})}
                                />
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                <select 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.category}
                                    onChange={e => setFormData({...formData, category: e.target.value})}
                                >
                                    <option value="">เลือกหมวด...</option>
                                    <option value="office">วัสดุสำนักงาน</option>
                                    <option value="computer">คอมพิวเตอร์</option>
                                    <option value="service">จ้างเหมาบริการ</option>
                                    <option value="construction">ก่อสร้าง</option>
                                    <option value="other">อื่นๆ</option>
                                </select>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                <input 
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.company}
                                    onChange={e => setFormData({...formData, company: e.target.value})}
                                />
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                <input 
                                    type="number" 
                                    min="1"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.itemCount}
                                    onChange={e => setFormData({...formData, itemCount: Number(e.target.value)})}
                                />
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนเงิน (บาท) *</label>
                                <input 
                                    required
                                    type="number" 
                                    min="0"
                                    step="0.01"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none bg-blue-50"
                                    value={formData.amount}
                                    onChange={e => setFormData({...formData, amount: Number(e.target.value)})}
                                />
                                <p className="text-xs text-blue-500 mt-1">หากเกิน 5,000 จะออกเลขคุมอัตโนมัติ</p>
                            </div>

                            <div className="col-span-2">
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                <textarea 
                                    rows={3}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                                    value={formData.remarks}
                                    onChange={e => setFormData({...formData, remarks: e.target.value})}
                                />
                            </div>

                            <div className="col-span-2 flex justify-end space-x-3 pt-4 border-t border-slate-100">
                                <button type="button" onClick={closeModal} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">
                                    ยกเลิก
                                </button>
                                <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-md transition-colors flex items-center">
                                    <Check size={18} className="mr-2" />
                                    บันทึกข้อมูล
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { useState } from 'react';
import { AppProvider } from './services/store';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import ProcurementTable from './pages/ProcurementTable';
import ReceivingPage from './pages/ReceivingPage';
import ConsiderationPage from './pages/ConsiderationPage';
import SettingsPage from './pages/SettingsPage';
import { RecordType } from './types';

const App: React.FC = () => {
    const [activeTab, setActiveTab] = useState('dashboard');

    const renderContent = () => {
        switch (activeTab) {
            case 'dashboard':
                return <Dashboard />;
            case 'purchase':
                return <ProcurementTable type={RecordType.PURCHASE} title="ทะเบียนคุมจัดซื้อ (Purchase Orders)" />;
            case 'hiring':
                return <ProcurementTable type={RecordType.HIRING} title="ทะเบียนคุมจัดจ้าง (Hiring Orders)" />;
            case 'receiving':
                return <ReceivingPage />;
            case 'consideration':
                return <ConsiderationPage />;
            case 'settings':
                return <SettingsPage />;
            default:
                return <Dashboard />;
        }
    };

    return (
        <AppProvider>
            <div className="flex h-screen bg-slate-50 text-slate-900 font-sans">
                <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
                <main className="flex-1 ml-64 overflow-y-auto">
                    {renderContent()}
                </main>
            </div>
        </AppProvider>
    );
};

