const LoginPage: React.FC = () => {
    const { login, registerUser } = useApp();
    const [isRegistering, setIsRegistering] = useState(false);

    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState(''); // For registration
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setSuccess('');

        if (isRegistering) {
            // Register
            if (!username || !password || !name) {
                setError('กรุณากรอกข้อมูลให้ครบถ้วน');
                return;
            }
            const result = registerUser({
                username,
                password,
                name,
                role: 'USER' // Default role for new sign-ups
            });

            if (result) {
                setSuccess('สมัครสมาชิกสำเร็จ! กรุณาเข้าสู่ระบบ');
                setIsRegistering(false);
                setPassword('');
                // Optionally keep username filled
            } else {
                setError('ชื่อผู้ใช้งานนี้ถูกใช้ไปแล้ว');
            }
        } else {
            // Login
            const result = login(username, password);
            if (!result) {
                setError('ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง');
            }
        }
    };

    return (
        <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden flex flex-col md:flex-row-reverse">

                {/* Form Section */}
