import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole } from '../types';

interface AppContextType {
    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth & Users
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => boolean;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => boolean;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber'>) => void;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    // Auth Data Initialization
    const [users, setUsers] = useState<User[]>([
        { id: '1', username: 'admin', password: 'password', name: 'ผู้ดูแลระบบ', role: 'ADMIN', departmentId: 'dept_1', createdAt: Date.now() },
        { id: '2', username: 'user', password: '1234', name: 'เจ้าหน้าที่พัสดุ', role: 'USER', departmentId: 'dept_2', createdAt: Date.now() }
    ]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    // Mock Data Initialization
    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [
            { id: 'dept_1', name: 'ฝ่ายบริหารงานทั่วไป' },
            { id: 'dept_2', name: 'ศูนย์เทคโนโลยีสารสนเทศ' },
            { id: 'dept_3', name: 'กลุ่มงานอาคารสถานที่' }
        ],
        categories: [
            { id: '1', name: 'วัสดุสำนักงาน', departmentId: 'dept_1' },
            { id: '2', name: 'วัสดุคอมพิวเตอร์', departmentId: 'dept_2' },
            { id: '3', name: 'จ้างเหมาบริการ', departmentId: 'dept_1' },
            { id: '4', name: 'วัสดุก่อสร้าง', departmentId: 'dept_3' },
            { id: '5', name: 'วัสดุงานบ้านงานครัว', departmentId: 'dept_1' },
            { id: '6', name: 'อื่นๆ', departmentId: 'dept_1' }
        ]
    });

    // --- Auth Functions ---
    const login = (u: string, p: string) => {
        const found = users.find(user => user.username === u && user.password === p);
        if (found) {
            setCurrentUser(found);
            return true;
        }
        return false;
    };

    const logout = () => {
        setCurrentUser(null);
    };

    const registerUser = (userData: Omit<User, 'id' | 'createdAt'>) => {
        if (users.some(u => u.username === userData.username)) {
            return false; // Username exists
        }
        const newUser: User = {
            ...userData,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now()
        };
        setUsers(prev => [...prev, newUser]);
        return true;
    };

    const deleteUser = (id: string) => {
        if (currentUser?.id === id) {
            alert("ไม่สามารถลบบัญชีที่กำลังใช้งานอยู่ได้");
            return;
        }
        setUsers(prev => prev.filter(u => u.id !== id));
    };

    const updateUser = (id: string, data: Partial<User>) => {
        setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
    };

    // --- Business Logic Helpers ---
    const getThaiYear = (dateString: string) => {
        const date = new Date(dateString);
        return date.getFullYear() + 543;
    };

    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        if (amount <= 5000) return null;

        const thaiYear = getThaiYear(dateStr);
        const existingInYear = procurements.filter(p => 
            p.type === type && 
            p.officialNumber && 
            getThaiYear(p.requestDate) === thaiYear
        );

        let maxNum = 0;
        existingInYear.forEach(p => {
            const parts = p.officialNumber?.split('/');
            if (parts && parts[0]) {
                const num = parseInt(parts[0]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });

        return `${maxNum + 1}/${thaiYear}`;
    };

    // --- Data Actions ---
    const addProcurement = (data: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber'>) => {
        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);

        const newRecord: ProcurementRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
            officialNumber
        };
        setProcurements(prev => [...prev, newRecord]);
    };

    const updateProcurement = (id: string, data: Partial<ProcurementRecord>) => {
        setProcurements(prev => prev.map(item => {
            if (item.id !== id) return item;

            let newOfficialNumber = item.officialNumber;
            if (data.amount !== undefined && data.requestDate !== undefined) {
                 if (data.amount > 5000 && !item.officialNumber) {
                     newOfficialNumber = generateRunningNumber(item.type, data.amount, data.requestDate);
                 } else if (data.amount <= 5000) {
                     newOfficialNumber = null;
                 }
            }

            return { ...item, ...data, officialNumber: newOfficialNumber };
        }));
    };

    const deleteProcurement = (id: string) => {
        setProcurements(prev => prev.filter(p => p.id !== id));
    };

    const addReceiving = (data: Omit<ReceivingReport, 'id' | 'createdAt'>) => {
        const newRecord: ReceivingReport = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
        };
        setReceivings(prev => [...prev, newRecord]);
    };

    const deleteReceiving = (id: string) => {
        setReceivings(prev => prev.filter(r => r.id !== id));
    };

    const addConsideration = (record: ConsiderationRecord) => {
        setConsiderations(prev => [...prev, { ...record, id: Math.random().toString(36).substr(2, 9) }]);
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = (newSettings: Partial<AppSettings>) => {
        setSettings(prev => ({ ...prev, ...newSettings }));
    };

    return (
        <AppContext.Provider value={{
            procurements,
            receivings,
            considerations,
            settings,
            currentUser,
            users,
            login,
            logout,
            registerUser,
            deleteUser,
            updateUser,
            addProcurement,
            updateProcurement,
            deleteProcurement,
            addReceiving,
            deleteReceiving,
            addConsideration,
            getLinkedData,
            updateSettings
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { Save, Plus, Trash2, Edit2, X, Check, Layers, Building } from 'lucide-react';
import { ProcurementCategory, Department } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, updateSettings } = useApp();
    const [localSettings, setLocalSettings] = useState(settings);
    const [saved, setSaved] = useState(false);

    // --- Department State ---
    const [newDeptName, setNewDeptName] = useState('');
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');

    // --- Category State ---
    const [newCategoryName, setNewCategoryName] = useState('');
    const [newCategoryDept, setNewCategoryDept] = useState('');
    const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
    const [editCatName, setEditCatName] = useState('');
    const [editCatDept, setEditCatDept] = useState('');

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        updateSettings(localSettings);
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
    };

    // --- Department Handlers ---
    const addDepartment = () => {
        if (!newDeptName.trim()) return;
        const newDept: Department = {
            id: `dept_${Date.now()}`,
            name: newDeptName.trim()
        };
        const updatedDepts = [...(localSettings.departments || []), newDept];
        const newSettings = { ...localSettings, departments: updatedDepts };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
        setNewDeptName('');
    };

    const deleteDepartment = (id: string) => {
        if (confirm('คุณต้องการลบฝ่ายนี้ใช่หรือไม่? ข้อมูลหมวดพัสดุที่เกี่ยวข้องจะถูกยกเลิกการเชื่อมโยง')) {
            const updatedDepts = localSettings.departments.filter(d => d.id !== id);
            // Unlink categories
            const updatedCats = localSettings.categories.map(c => 
                c.departmentId === id ? { ...c, departmentId: undefined } : c
            );

            const newSettings = { ...localSettings, departments: updatedDepts, categories: updatedCats };
            setLocalSettings(newSettings);
            updateSettings(newSettings);
        }
    };

    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id);
        setEditDeptName(dept.name);
    };

    const saveEditDept = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        const updatedDepts = localSettings.departments.map(d => 
            d.id === editingDeptId ? { ...d, name: editDeptName.trim() } : d
        );
        const newSettings = { ...localSettings, departments: updatedDepts };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
        setEditingDeptId(null);
    };

    // --- Category Handlers ---
    const addCategory = () => {
        if (!newCategoryName.trim()) return;
        const newCat: ProcurementCategory = {
            id: Date.now().toString(),
            name: newCategoryName.trim(),
            departmentId: newCategoryDept || undefined
        };
        const updatedCategories = [...localSettings.categories, newCat];
        const newSettings = { ...localSettings, categories: updatedCategories };
        setLocalSettings(newSettings);
        updateSettings(newSettings); 
        setNewCategoryName('');
        setNewCategoryDept('');
    };

    const deleteCategory = (id: string) => {
        if (confirm('คุณต้องการลบหมวดหมู่นี้ใช่หรือไม่?')) {
            const updatedCategories = localSettings.categories.filter(c => c.id !== id);
            const newSettings = { ...localSettings, categories: updatedCategories };
            setLocalSettings(newSettings);
            updateSettings(newSettings);
        }
    };

    const startEditCategory = (cat: ProcurementCategory) => {
        setEditingCategoryId(cat.id);
        setEditCatName(cat.name);
        setEditCatDept(cat.departmentId || '');
    };

    const saveEditCategory = () => {
        if (!editCatName.trim() || !editingCategoryId) return;

        const updatedCategories = localSettings.categories.map(c => 
            c.id === editingCategoryId ? { 
                ...c, 
                name: editCatName.trim(),
                departmentId: editCatDept || undefined
            } : c
        );

        const newSettings = { ...localSettings, categories: updatedCategories };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
        setEditingCategoryId(null);
    };

    return (
        <div className="p-6">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">ตั้งค่าระบบ (Settings)</h2>

            <div className="space-y-6">

                {/* 1. Document Format Settings */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
                    <div className="p-6 border-b border-slate-100 bg-slate-50">
                        <h3 className="text-lg font-semibold text-slate-800">รูปแบบเอกสาร</h3>
                        <p className="text-sm text-slate-500">กำหนดค่าเริ่มต้นสำหรับเลขที่เอกสาร</p>
                    </div>

                    <form onSubmit={handleSave} className="p-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                รูปแบบเลขที่ใบขอ (Prefix)
                            </label>
                            <div className="flex space-x-2">
                                <input 
                                    type="text" 
                                    className="flex-1 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none font-medium text-slate-700"
                                    value={localSettings.requestIdPrefix}
                                    onChange={e => setLocalSettings({...localSettings, requestIdPrefix: e.target.value})}
                                    placeholder="เช่น สพ.๐๐๓๓.๐๒/"
                                />
                                <button 
                                    type="submit" 
                                    className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg shadow-sm transition-all"
                                >
                                    <Save size={18} />
                                    <span>บันทึก</span>
                                </button>
                            </div>
                            <p className="text-xs text-slate-400 mt-2">
                                ค่านี้จะถูกนำไปเติมให้อัตโนมัติเมื่อสร้างรายการใหม่
                            </p>
                            {saved && (
                                <p className="text-green-600 text-sm font-medium animate-fade-in mt-2">
                                    บันทึกเรียบร้อยแล้ว!
                                </p>
                            )}
                        </div>
                    </form>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    {/* 2. Department Management */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit flex flex-col">
                        <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                            <div>
                                <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                    <Building size={20} className="mr-2 text-indigo-600"/> จัดการฝ่าย/งาน
                                </h3>
                                <p className="text-sm text-slate-500">รายชื่อฝ่ายภายในองค์กร</p>
                            </div>
                        </div>

                        <div className="p-6 flex-1 flex flex-col">
                            <div className="flex space-x-2 mb-4">
                                <input 
                                    type="text" 
                                    className="flex-1 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                                    placeholder="ชื่อฝ่าย/งานใหม่..."
