                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-slate-600">
                            <thead className="bg-slate-50 border-b border-slate-200 text-xs uppercase text-slate-700">
                                <tr>
                                    <th className="px-4 py-3">ชื่อ-นามสกุล</th>
                                    <th className="px-4 py-3">Username</th>
                                    <th className="px-4 py-3">ฝ่าย/งาน</th>
                                    <th className="px-4 py-3 text-center">สิทธิ์</th>
                                    <th className="px-4 py-3 text-center">จัดการ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredUsers.map(user => (
                                    <tr key={user.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                                        <td className="px-4 py-3 font-medium text-slate-900 flex items-center">
                                            <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center mr-3 text-slate-500 font-bold">
                                                {user.name.charAt(0)}
                                            </div>
                                            {user.name}
                                            {user.id === currentUser?.id && <span className="ml-2 text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full">คุณ</span>}
                                        </td>
                                        <td className="px-4 py-3">{user.username}</td>
                                        <td className="px-4 py-3">
                                            <div className="flex items-center text-slate-500">
                                                <Building size={14} className="mr-1.5 text-slate-400"/>
                                                {getDeptName(user.departmentId)}
