                                </tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const consNum = linked.consideration?.considerationNumber || '-';
                                    const consDate = linked.consideration?.considerationDate || '-';

                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors print:break-inside-avoid">
                                            <td className="px-4 py-3 font-medium text-slate-900">{item.requestId}</td>
                                            <td className="px-4 py-3">{item.requestDate}</td>
                                            <td className="px-4 py-3 text-orange-600 print:text-black">{consNum}</td>
                                            <td className="px-4 py-3">{consDate}</td>
                                            <td className="px-4 py-3 bg-blue-50 font-bold text-blue-700 print:bg-transparent print:text-black">
                                                {item.officialNumber || <span className="text-slate-300 font-normal italic print:hidden">ไม่ถึงเกณฑ์</span>}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50 text-green-700 print:bg-transparent print:text-black">
                                                {linked.receiving?.deliveryNoteNo || '-'}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50 print:bg-transparent">
                                                {linked.receiving?.receiveDate || '-'}
                                            </td>
                                            <td className="px-4 py-3 text-right font-medium">
                                                {item.amount.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[120px] print:max-w-none">{item.category}</td>
                                            <td className="px-4 py-3 truncate max-w-[150px] print:max-w-none">{item.company}</td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    <button onClick={() => openEdit(item)} className="p-1.5 hover:bg-slate-200 rounded text-slate-600">
                                                        <Edit2 size={16} />
                                                    </button>
                                                    <button onClick={() => deleteProcurement(item.id)} className="p-1.5 hover:bg-red-100 rounded text-red-500">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden relative max-h-[90vh] overflow-y-auto">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0 z-10">
                            <h3 className="text-lg font-semibold text-slate-800">
                                {editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}
                            </h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">
                                <X size={24} />
                            </button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 grid grid-cols-2 gap-6">

                            {/* Request Info Section */}
                            <div className="col-span-2">
                                <h4 className="text-sm font-semibold text-slate-500 uppercase mb-3 flex items-center border-b pb-1">
                                    <span className="bg-slate-100 text-slate-600 px-2 py-0.5 rounded mr-2">1</span> ข้อมูลใบขอ (Request)
                                </h4>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">เลขที่ใบขอ *</label>
                                <input 
                                    required
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none text-black text-base font-medium bg-blue-50/50"
                                    value={formData.requestId}
                                    onChange={handleRequestIdChange}
                                    placeholder={settings.requestIdPrefix || "เช่น REQ-001"}
                                />
                                <p className="text-xs text-red-500 mt-1">ตั้งค่ารูปแบบได้ที่เมนู "ตั้งค่าระบบ"</p>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">วัน/เดือน/ปี ที่ขอ *</label>
                                <div className="relative">
                                    <input 
                                        ref={dateInputRef}
                                        required
                                        type="date" 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 pl-3 pr-10 focus:ring-2 focus:ring-blue-500 outline-none text-black text-base font-medium bg-white cursor-pointer"
                                        value={formData.requestDate}
                                        onChange={e => setFormData({...formData, requestDate: e.target.value})}
                                        onClick={() => {
                                            try {
                                                if(dateInputRef.current && typeof dateInputRef.current.showPicker === 'function') {
                                                    dateInputRef.current.showPicker();
                                                }
                                            } catch (e) { }
                                        }}
                                    />
                                    <div className="absolute right-3 top-2.5 text-slate-400 pointer-events-none">
                                        <Calendar size={20} />
                                    </div>
                                    <style>{`
                                        input[type="date"]::-webkit-calendar-picker-indicator {
                                            position: absolute; top: 0; left: 0; width: 100%; height: 100%; margin: 0; padding: 0; opacity: 0; cursor: pointer;
                                        }
                                    `}</style>
                                </div>
                            </div>

                            {/* Consideration Info Section */}
                            <div className="col-span-2 mt-2">
                                <h4 className="text-sm font-semibold text-orange-600 uppercase mb-3 flex items-center border-b border-orange-100 pb-1">
                                    <FileText size={16} className="mr-2"/>
                                    <span className="bg-orange-50 text-orange-700 px-2 py-0.5 rounded mr-2">2</span> ข้อมูลบันทึกข้อความ / เลขพิจารณา
                                </h4>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">เลขพิจารณา</label>
                                <input 
                                    type="text" 
                                    className="w-full border border-orange-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-orange-500 outline-none text-black text-base font-medium bg-orange-50/30"
                                    value={formData.considerationNumber}
                                    onChange={e => setFormData({...formData, considerationNumber: e.target.value})}
                                    placeholder="เช่น CONS-001"
                                />
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">วันที่พิจารณา</label>
                                <div className="relative">
                                    <input 
                                        type="date" 
                                        className="w-full border border-orange-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-orange-500 outline-none text-black text-base font-medium bg-orange-50/30 cursor-pointer"
                                        value={formData.considerationDate}
                                        onChange={e => setFormData({...formData, considerationDate: e.target.value})}
                                    />
                                </div>
                            </div>

                            {/* Details Section */}
                            <div className="col-span-2 mt-2">
                                <h4 className="text-sm font-semibold text-slate-500 uppercase mb-3 flex items-center border-b pb-1">
                                    <span className="bg-slate-100 text-slate-600 px-2 py-0.5 rounded mr-2">3</span> รายละเอียดพัสดุ
                                </h4>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                <select 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none text-black text-base font-medium bg-white"
                                    value={formData.category}
                                    onChange={e => setFormData({...formData, category: e.target.value})}
                                >
                                    <option value="">เลือกหมวด...</option>
                                    {settings.categories?.map((cat) => (
                                        <option key={cat.id} value={cat.name}>
                                            {cat.name}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                <input 
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none text-black text-base font-medium bg-white"
                                    value={formData.company}
                                    onChange={e => setFormData({...formData, company: e.target.value})}
                                />
                            </div>

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                <input 
                                    type="number" 
                                    min="1"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none text-black text-base font-medium bg-white"
                                    value={formData.itemCount}
                                    onChange={e => setFormData({...formData, itemCount: Number(e.target.value)})}
                                />
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนเงิน (บาท) *</label>
                                <input 
                                    required
                                    type="number" 
                                    min="0"
                                    step="0.01"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none bg-blue-50 text-black text-base font-medium"
                                    value={formData.amount}
                                    onChange={e => setFormData({...formData, amount: Number(e.target.value)})}
                                />
                                <p className="text-xs text-red-500 mt-1">หากเกิน 5,000 จะออกเลขคุมอัตโนมัติ</p>
                            </div>

                            <div className="col-span-2">
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                <textarea 
                                    rows={3}
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none text-black text-base font-medium bg-white"
                                    value={formData.remarks}
                                    onChange={e => setFormData({...formData, remarks: e.target.value})}
                                />
                            </div>

                            <div className="col-span-2 flex justify-end space-x-3 pt-4 border-t border-slate-100">
                                <button type="button" onClick={closeModal} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">
                                    ยกเลิก
                                </button>
                                <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-md transition-colors flex items-center">
                                    <Check size={18} className="mr-2" />
                                    บันทึกข้อมูล
                                </button>
                            </div>
                        </form>

                        {/* Confirmation Overlay */}
                        {showConfirm && (
                            <div className="absolute inset-0 z-10 flex items-center justify-center p-4 bg-white/50 backdrop-blur-sm rounded-xl">
                                <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                                    <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-100 mb-4">
                                        <AlertCircle className="h-6 w-6 text-blue-600" />
                                    </div>
                                    <h3 className="text-lg font-bold text-slate-900 mb-2">ยืนยันการบันทึกข้อมูล?</h3>
                                    <p className="text-sm text-slate-500 mb-6">
                                        กรุณาตรวจสอบความถูกต้องของข้อมูล <br/>เมื่อยืนยันแล้วระบบจะทำการบันทึกทันที
                                    </p>
                                    <div className="flex justify-center space-x-3">
                                        <button 
                                            onClick={() => setShowConfirm(false)}
                                            className="px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium"
                                        >
                                            กลับไปแก้ไข
                                        </button>
                                        <button 
                                            onClick={handleConfirmSave}
                                            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors font-medium"
                                        >
                                            ยืนยัน
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { useState, useRef } from 'react';
import { useApp } from '../services/store';
import { RecordType, ProcurementRecord } from '../types';
import { Plus, Edit2, Trash2, X, Check, AlertCircle, Calendar, FileSpreadsheet, Printer, FileText } from 'lucide-react';

interface Props {
    type: RecordType;
    title: string;
}

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, addProcurement, updateProcurement, deleteProcurement, getLinkedData, upsertConsideration, settings } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);

    // Ref for date input
    const dateInputRef = useRef<HTMLInputElement>(null);

    // Form State
    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: '',
        // Consideration Fields
        considerationNumber: '',
        considerationDate: ''
    });

    const filteredData = procurements.filter(p => p.type === type);
    const isPurchase = type === RecordType.PURCHASE;

    // Define labels based on RecordType
    const fieldLabels = {
        requestId: isPurchase ? "เลขกำหนดขอบเขตงาน" : "เลขที่ใบขอ",
        requestDate: isPurchase ? "วันที่ขอเลขกำหนดขอบเขตงาน" : "วันที่ขอ",
        considerationNumber: isPurchase ? "เลขรายงานขอซื้อขอจ้าง" : "เลขพิจารณา",
        considerationDate: isPurchase ? "วันที่ขอเลขรายงานขอซื้อขอจ้าง" : "วันที่พิจารณา",
        receivingNumber: isPurchase ? "เลขรายงานผลการพิจารณา" : "เลขรับของ",
        receivingDate: isPurchase ? "วันที่ขอเลขรายงานผลการพิจารณา" : "วันที่รับของ"
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        // Show confirmation dialog instead of saving immediately
        setShowConfirm(true);
    };

    const handleConfirmSave = () => {
        // 1. Save Procurement Record
        if (editingId) {
            updateProcurement(editingId, {
                requestId: formData.requestId,
                requestDate: formData.requestDate,
                category: formData.category,
                itemCount: formData.itemCount,
                amount: formData.amount,
                company: formData.company,
                remarks: formData.remarks
            });
        } else {
            addProcurement({
                requestId: formData.requestId,
                requestDate: formData.requestDate,
                category: formData.category,
                itemCount: formData.itemCount,
                amount: formData.amount,
                company: formData.company,
                remarks: formData.remarks,
                type: type
            });
        }

        // 2. Save Consideration Record (Linked)
        // If user entered data, or cleared it (upsert handles both)
        upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);

        setShowConfirm(false);
        closeModal();
    };

    const openNew = () => {
        setEditingId(null);
        setFormData({
            requestId: settings.requestIdPrefix, // Pre-fill from settings
            requestDate: '',
            category: '',
            itemCount: 0,
            amount: 0,
            company: '',
            remarks: '',
            considerationNumber: '',
            considerationDate: ''
        });
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        const linked = getLinkedData(record.requestId);

        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || ''
        });
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
    };

    // Auto-fill consideration if exists in considerations list when requestId changes
    const handleRequestIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setFormData(prev => ({ ...prev, requestId: val }));

        // Optional: If we want to auto-fill consideration when typing Request ID (live lookup)
        // For now, let's keep it simple. It loads on 'Edit'.
    };

    // --- Export Functions ---

    const handleExportCSV = () => {
        // Define Headers
        const headers = [
            fieldLabels.requestId,
            fieldLabels.requestDate,
            fieldLabels.considerationNumber,
            fieldLabels.considerationDate,
            type === RecordType.PURCHASE ? 'เลขสั่งซื้อ' : 'เลขสั่งจ้าง',
            fieldLabels.receivingNumber,
            fieldLabels.receivingDate,
            'จำนวนเงิน',
            'บริษัท',
            'หมายเหตุ'
        ];

        // Map Data
        const rows = filteredData.map(item => {
            const linked = getLinkedData(item.requestId);
            const consNum = linked.consideration?.considerationNumber || '-';
            const consDate = linked.consideration?.considerationDate || '-';
            const officialNum = item.officialNumber || '-';
            const receiveNo = linked.receiving?.deliveryNoteNo || '-';
            const receiveDate = linked.receiving?.receiveDate || '-';

            // Escape double quotes for CSV format
            const safeCompany = `"${item.company.replace(/"/g, '""')}"`;
            const safeRemarks = `"${item.remarks.replace(/"/g, '""')}"`;

            return [
                item.requestId,
                item.requestDate,
                consNum,
                consDate,
                officialNum,
                receiveNo,
                receiveDate,
                item.amount,
                safeCompany,
                safeRemarks
            ].join(',');
        });

        // Combine with BOM for UTF-8 support (Thai language)
        const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');

        // Create Download Link
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `procurement_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handlePrint = () => {
        window.print();
    };

    return (
        <div className="p-6">
            {/* Print Styles */}
            <style>{`
                @media print {
                    @page { size: landscape; margin: 1cm; }
                    /* Hide Sidebar and other non-print elements */
                    .fixed.left-0.top-0 { display: none !important; } /* Sidebar */
                    main { margin-left: 0 !important; width: 100% !important; }
                    .no-print { display: none !important; }

                    /* Adjust table for print */
                    table { width: 100% !important; border-collapse: collapse; font-size: 10pt; }
                    th, td { border: 1px solid #cbd5e1 !important; padding: 4px 8px !important; }
                    thead th { background-color: #f1f5f9 !important; color: black !important; -webkit-print-color-adjust: exact; }
                }
            `}</style>

            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-slate-800">{title}</h2>

                <div className="flex space-x-3 no-print">
                    <button 
                        onClick={handleExportCSV}
                        className="flex items-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg shadow-sm transition-all"
                        title="Export to Excel (CSV)"
                    >
                        <FileSpreadsheet size={18} />
                        <span className="hidden sm:inline">Excel</span>
                    </button>
                    <button 
                        onClick={handlePrint}
                        className="flex items-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg shadow-sm transition-all"
                        title="Print / Save as PDF"
                    >
                        <Printer size={18} />
                        <span className="hidden sm:inline">PDF / Print</span>
                    </button>
                    <div className="w-px h-8 bg-slate-300 mx-2"></div>
                    <button 
                        onClick={openNew}
                        className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg shadow-sm transition-all"
                    >
                        <Plus size={18} />
                        <span>บันทึกรายการใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden print:border-0 print:shadow-none">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3 min-w-[120px]">{fieldLabels.requestId}</th>
                                <th className="px-4 py-3 min-w-[100px]">{fieldLabels.requestDate}</th>
                                <th className="px-4 py-3 min-w-[120px]">{fieldLabels.considerationNumber}</th>
                                <th className="px-4 py-3 min-w-[100px]">{fieldLabels.considerationDate}</th>
                                <th className="px-4 py-3 bg-blue-50 print:bg-transparent min-w-[100px]">เลขสั่ง{type === RecordType.PURCHASE ? 'ซื้อ' : 'จ้าง'}</th>
                                <th className="px-4 py-3 bg-green-50 print:bg-transparent min-w-[120px]">{fieldLabels.receivingNumber}</th>
                                <th className="px-4 py-3 bg-green-50 print:bg-transparent min-w-[100px]">{fieldLabels.receivingDate}</th>
                                <th className="px-4 py-3 text-right">จำนวนเงิน</th>
                                <th className="px-4 py-3">หมวดพัสดุ</th>
                                <th className="px-4 py-3">บริษัท</th>
                                <th className="px-4 py-3 text-center no-print">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredData.length === 0 ? (
                                <tr>
                                    <td colSpan={11} className="px-4 py-8 text-center text-slate-400">
                                        ไม่พบข้อมูล
                                    </td>
                                </tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const consNum = linked.consideration?.considerationNumber || '-';
                                    const consDate = linked.consideration?.considerationDate || '-';

                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors print:break-inside-avoid">
                                            <td className="px-4 py-3 font-medium text-slate-900">{item.requestId}</td>
                                            <td className="px-4 py-3">{item.requestDate}</td>
                                            <td className="px-4 py-3 text-orange-600 print:text-black">{consNum}</td>
