                                                                setQuickDateType('RECEIVING');
                                                                setQuickDateValue(new Date().toISOString().split('T')[0]);
                                                            }}
                                                            className="flex items-center text-green-600 hover:text-green-800 hover:bg-green-100 px-2 py-1 rounded transition-colors no-print"
                                                            title="ระบุวันที่ (รันเลขอัตโนมัติ)"
                                                        >
                                                            <CalendarPlus size={16} className="mr-1" />
                                                            <span className="text-xs font-medium">เพิ่มวันที่</span>
                                                        </button>
                                                     )
                                                )}
                                            </td>
                                            <td className="px-4 py-3 text-right font-medium">
                                                {item.amount.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[120px] print:max-w-none">{item.category}</td>
                                            <td className="px-4 py-3 truncate max-w-[150px] print:max-w-none">{item.company}</td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    <button onClick={() => openEdit(item)} className="p-1.5 hover:bg-slate-200 rounded text-slate-600">
                                                        <Edit2 size={16} />
                                                    </button>
                                                    <button onClick={() => deleteProcurement(item.id)} className="p-1.5 hover:bg-red-100 rounded text-red-500">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Quick Date Modal */}
            {quickDateId && quickDateType && (
                <div className="fixed inset-0 bg-black/30 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-lg shadow-xl p-5 w-full max-w-sm animate-fade-in border border-slate-200">
                        <div className="flex justify-between items-center mb-3">
                            <h3 className="font-bold text-slate-800">{quickDateTitle}</h3>
                            <button onClick={closeQuickDate} className="text-slate-400 hover:text-slate-600"><X size={18}/></button>
                        </div>
                        <div className="bg-blue-50 p-3 rounded-md mb-4 border border-blue-100">
                            <p className="text-xs text-slate-600">
                                ระบบจะกำหนดเลขเป็น <span className="font-bold text-blue-700">{previewNextNum}</span> (รันต่อจากเลขล่าสุด)
                            </p>
                        </div>
                        <input 
                            type="date"
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-6 focus:ring-2 focus:ring-blue-500 outline-none text-center font-medium"
                            value={quickDateValue}
                            onChange={(e) => setQuickDateValue(e.target.value)}
                            autoFocus
                        />
                        <div className="flex justify-end space-x-2">
                            <button 
                                onClick={closeQuickDate}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={handleSaveQuickDate}
                                className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 shadow-sm flex items-center"
                            >
                                <Check size={16} className="mr-1.5" />
                                บันทึก
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden relative max-h-[90vh] overflow-y-auto">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0 z-10">
