                                                            onClick={() => {
                                                                setQuickDateId(item.requestId);
                                                                setQuickDateType('RECEIVING');
                                                                setQuickDateValue(new Date().toISOString().split('T')[0]);
                                                            }}
                                                            className="flex items-center text-green-600 hover:text-green-800 hover:bg-green-100 px-2 py-1 rounded transition-colors no-print"
                                                            title="ระบุวันที่ (รันเลขอัตโนมัติ)"
                                                        >
                                                            <CalendarPlus size={16} className="mr-1" />
                                                            <span className="text-xs font-medium">เพิ่มวันที่</span>
                                                        </button>
                                                     )
                                                )}
                                            </td>
                                            <td className="px-4 py-3 text-right font-medium">
