                                                    <button onClick={() => deleteProcurement(item.id)} className="p-1.5 hover:bg-red-100 rounded text-red-500">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Quick Date Modal */}
            {quickDateId && quickDateType && (
                <div className="fixed inset-0 bg-black/30 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-lg shadow-xl p-5 w-full max-w-sm animate-fade-in border border-slate-200">
