                            <p className="text-xs text-slate-600">
                                ระบบจะกำหนดเลขเป็น <span className="font-bold text-blue-700">{previewNextNum}</span> (รันต่อจากเลขล่าสุด)
                            </p>
                        </div>
                        <input 
                            type="date"
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-6 focus:ring-2 focus:ring-blue-500 outline-none text-center font-medium"
                            value={quickDateValue}
                            onChange={(e) => setQuickDateValue(e.target.value)}
                            autoFocus
                        />
                        <div className="flex justify-end space-x-2">
                            <button 
                                onClick={closeQuickDate}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={handleSaveQuickDate}
                                className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 shadow-sm flex items-center"
                            >
                                <Check size={16} className="mr-1.5" />
                                บันทึก
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 no-print">
