            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขที่คำสั่ง/สัญญา"
        };
    }

    // Dynamic Theme based on Type
    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return {
                    name: 'violet',
                    bgSoft: 'bg-violet-50',
                    bgDeep: 'bg-violet-600',
                    bgHover: 'hover:bg-violet-700',
                    text: 'text-violet-700',
                    border: 'border-violet-200',
                    ring: 'focus:ring-violet-500',
                    inputBg: 'bg-violet-50/50'
                };
            case RecordType.OTHER:
                return {
                    name: 'orange',
                    bgSoft: 'bg-orange-50',
                    bgDeep: 'bg-orange-600',
                    bgHover: 'hover:bg-orange-700',
                    text: 'text-orange-700',
                    border: 'border-orange-200',
                    ring: 'focus:ring-orange-500',
                    inputBg: 'bg-orange-50/50'
                };
            default: // PURCHASE
                return {
                    name: 'blue',
                    bgSoft: 'bg-blue-50',
                    bgDeep: 'bg-blue-600',
                    bgHover: 'hover:bg-blue-700',
                    text: 'text-blue-700',
                    border: 'border-blue-200',
                    ring: 'focus:ring-blue-500',
                    inputBg: 'bg-blue-50/50'
                };
        }
    })();

    // --- Logic for Calculating Next Running Number ---
    const calculateNextRunNumber = () => {
        const prefix = settings.requestIdPrefix;
        if (!prefix) return '';

        // 1. Get IDs from Procurements (Request IDs)
        const reqIds = procurements
            .map(p => p.requestId)
            .filter(id => id && id.startsWith(prefix));

        // 2. Get IDs from Considerations (Report Numbers)
        const consIds = considerations
            .map(c => c.considerationNumber)
            .filter(id => id && id.startsWith(prefix));

        // 3. Get IDs from Receivings (Report Result Numbers)
        const recvIds = receivings
            .map(r => r.deliveryNoteNo)
            .filter(id => id && id.startsWith(prefix));

        const allIds = [...reqIds, ...consIds, ...recvIds];

        let maxNum = 0;
        allIds.forEach(id => {
            const suffix = id.substring(prefix.length);
            const normalizedSuffix = normalizeToNr(suffix);
            const num = parseInt(normalizedSuffix);
            if (!isNaN(num) && num > maxNum) {
                maxNum = num;
            }
        });

        return prefix + toThaiNr(maxNum + 1);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        // Show confirmation dialog instead of saving immediately
        setShowConfirm(true);
    };

    const handleConfirmSave = () => {
        // 1. Save Procurement Record
        if (editingId) {
            updateProcurement(editingId, {
                requestId: formData.requestId,
                requestDate: formData.requestDate,
                category: formData.category,
                itemCount: formData.itemCount,
                amount: formData.amount,
                company: formData.company,
                remarks: formData.remarks
            });
        } else {
            addProcurement({
                requestId: formData.requestId,
                requestDate: formData.requestDate,
                category: formData.category,
                itemCount: formData.itemCount,
                amount: formData.amount,
                company: formData.company,
                remarks: formData.remarks,
                type: type
            });
        }

        // 2. Save Consideration Record (Linked) - Only if fields are populated (backward compatibility)
        if(formData.considerationNumber || formData.considerationDate) {
             upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
        }

        setShowConfirm(false);
        closeModal();
    };

    // --- Delete Logic ---
    const handleDeleteClick = (id: string) => {
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const cancelDelete = () => {
        setDeleteId(null);
    };


    const openNew = () => {
        setEditingId(null);

        // Auto-generate Request ID logic using shared helper
        const nextRequestId = calculateNextRunNumber() || settings.requestIdPrefix || '';

        setFormData({
            requestId: nextRequestId,
            requestDate: '',
            category: '',
            itemCount: 0,
            amount: 0,
            company: '',
            remarks: '',
            considerationNumber: '',
            considerationDate: ''
        });
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        const linked = getLinkedData(record.requestId);

        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || ''
        });
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
    };

    // Auto-fill consideration if exists in considerations list when requestId changes
    const handleRequestIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setFormData(prev => ({ ...prev, requestId: val }));
    };

    // --- Quick Date Logic ---
    const handleSaveQuickDate = () => {
        if (quickDateId && quickDateValue && quickDateType) {
            // Rule: Number = Latest Running ID + 1
            let nextNumber = calculateNextRunNumber();

            // Fallback if no prefix logic matches
            if (!nextNumber) {
                // If prefix logic doesn't work, maybe just use QuickDateID (RequestId) as base or keep it empty
                nextNumber = quickDateId; 
            }

            if (quickDateType === 'CONSIDERATION') {
                upsertConsideration(quickDateId, nextNumber, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                upsertReceiving(quickDateId, nextNumber, quickDateValue);
            }

            setQuickDateId(null);
            setQuickDateValue('');
            setQuickDateType(null);
        }
    };

    const closeQuickDate = () => {
        setQuickDateId(null);
        setQuickDateValue('');
        setQuickDateType(null);
    };

    // --- Export Functions ---

    const handleExportCSV = () => {
        // Define Headers
        const headers = [
            fieldLabels.requestId,
            fieldLabels.requestDate,
            'ปีงบประมาณ',
            fieldLabels.considerationNumber,
            fieldLabels.considerationDate,
            fieldLabels.officialNumber,
            fieldLabels.receivingNumber,
            fieldLabels.receivingDate,
            'จำนวนเงิน',
            'บริษัท',
            'หมายเหตุ'
        ];

        // Map Data
        const rows = filteredData.map(item => {
            const linked = getLinkedData(item.requestId);
            const consNum = linked.consideration?.considerationNumber || '-';
            const consDate = linked.consideration?.considerationDate || '-';
            const officialNum = item.officialNumber || '-';
            const receiveNo = linked.receiving?.deliveryNoteNo || '-';
            const receiveDate = linked.receiving?.receiveDate || '-';
            const fiscalYear = getFiscalYear(item.requestDate);

            // Escape double quotes for CSV format
            const safeCompany = `"${item.company.replace(/"/g, '""')}"`;
            const safeRemarks = `"${item.remarks.replace(/"/g, '""')}"`;

            return [
                item.requestId,
                item.requestDate,
                fiscalYear,
                consNum,
                consDate,
                officialNum,
                receiveNo,
                receiveDate,
                item.amount,
                safeCompany,
                safeRemarks
            ].join(',');
        });

        // Combine with BOM for UTF-8 support (Thai language)
        const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');

        // Create Download Link
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `procurement_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handlePrint = () => {
        window.print();
    };

    // Calculate preview for modal
    const previewNextNum = (quickDateId && quickDateType) ? (calculateNextRunNumber() || quickDateId) : '';
    const quickDateTitle = quickDateType === 'CONSIDERATION' ? 'ระบุวันที่' : 'ระบุวันที่';

    return (
        <div className="p-6">
            {/* Print Styles */}
            <style>{`
                @media print {
                    @page { size: landscape; margin: 1cm; }
                    /* Hide Sidebar and other non-print elements */
                    .fixed.left-0.top-0 { display: none !important; } /* Sidebar */
                    main { margin-left: 0 !important; width: 100% !important; }
                    .no-print { display: none !important; }

                    /* Adjust table for print */
                    table { width: 100% !important; border-collapse: collapse; font-size: 10pt; }
                    th, td { border: 1px solid #cbd5e1 !important; padding: 4px 8px !important; }
                    thead th { background-color: #f1f5f9 !important; color: black !important; -webkit-print-color-adjust: exact; }
                }
            `}</style>

            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-slate-800">{title}</h2>

                <div className="flex space-x-3 no-print">
                    <button 
                        onClick={handleExportCSV}
                        className="flex items-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg shadow-sm transition-all"
                        title="Export to Excel (CSV)"
                    >
                        <FileSpreadsheet size={18} />
                        <span className="hidden sm:inline">Excel</span>
                    </button>
                    <button 
                        onClick={handlePrint}
                        className="flex items-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg shadow-sm transition-all"
                        title="Print / Save as PDF"
                    >
                        <Printer size={18} />
                        <span className="hidden sm:inline">PDF / Print</span>
                    </button>
                    <div className="w-px h-8 bg-slate-300 mx-2"></div>
                    <button 
                        onClick={openNew}
                        className={`flex items-center space-x-2 ${theme.bgDeep} ${theme.bgHover} text-white px-4 py-2 rounded-lg shadow-sm transition-all`}
                    >
                        <Plus size={18} />
                        <span>บันทึกรายการใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden print:border-0 print:shadow-none">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3 min-w-[120px]">{fieldLabels.requestId}</th>
                                <th className="px-4 py-3 min-w-[100px]">{fieldLabels.requestDate}</th>
                                <th className="px-4 py-3 min-w-[80px]">ปีงบประมาณ</th>
                                <th className="px-4 py-3 min-w-[120px]">{fieldLabels.considerationNumber}</th>
                                <th className="px-4 py-3 min-w-[100px]">{fieldLabels.considerationDate}</th>
                                <th className={`px-4 py-3 ${theme.bgSoft} print:bg-transparent min-w-[100px]`}>{fieldLabels.officialNumber}</th>
                                <th className="px-4 py-3 bg-green-50 print:bg-transparent min-w-[120px]">{fieldLabels.receivingNumber}</th>
                                <th className="px-4 py-3 bg-green-50 print:bg-transparent min-w-[100px]">{fieldLabels.receivingDate}</th>
                                <th className="px-4 py-3 text-right">จำนวนเงิน</th>
                                <th className="px-4 py-3">หมวดพัสดุ</th>
                                <th className="px-4 py-3">บริษัท</th>
                                <th className="px-4 py-3 text-center no-print">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredData.length === 0 ? (
                                <tr>
                                    <td colSpan={12} className="px-4 py-8 text-center text-slate-400">
                                        ไม่พบข้อมูล
                                    </td>
                                </tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const consNum = linked.consideration?.considerationNumber || '-';
                                    const consDate = linked.consideration?.considerationDate || '-';
                                    const receiveNo = linked.receiving?.deliveryNoteNo || '-';
                                    const receiveDate = linked.receiving?.receiveDate || '-';

                                    // Logic for Quick Date Button: Show if No Date present
                                    const showQuickDateConsideration = !linked.consideration?.considerationDate;
                                    const showQuickDateReceiving = !linked.receiving?.receiveDate;

                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors print:break-inside-avoid">
                                            <td className="px-4 py-3 font-medium text-slate-900">{item.requestId}</td>
                                            <td className="px-4 py-3">{item.requestDate}</td>
                                            <td className="px-4 py-3 text-center font-medium text-slate-500">
                                                {getFiscalYear(item.requestDate)}
                                            </td>
                                            <td className="px-4 py-3 text-orange-600 print:text-black">{consNum}</td>
                                            <td className="px-4 py-3">
                                                {consDate !== '-' ? consDate : (
                                                    showQuickDateConsideration && (
                                                        <button 
                                                            onClick={() => {
                                                                setQuickDateId(item.requestId);
                                                                setQuickDateType('CONSIDERATION');
                                                                setQuickDateValue(new Date().toISOString().split('T')[0]);
                                                            }}
                                                            className={`flex items-center ${theme.text} hover:opacity-80 ${theme.bgSoft} px-2 py-1 rounded transition-colors no-print`}
                                                            title="ระบุวันที่ (รันเลขอัตโนมัติ)"
                                                        >
                                                            <CalendarPlus size={16} className="mr-1" />
                                                            <span className="text-xs font-medium">เพิ่มวันที่</span>
                                                        </button>
                                                    )
                                                )}
                                            </td>
                                            <td className={`px-4 py-3 ${theme.bgSoft} font-bold ${theme.text} print:bg-transparent print:text-black`}>
                                                {item.officialNumber || <span className="text-slate-300 font-normal italic print:hidden">ไม่ถึงเกณฑ์</span>}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50 text-green-700 print:bg-transparent print:text-black">
                                                {receiveNo}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50 print:bg-transparent">
                                                {receiveDate !== '-' ? receiveDate : (
                                                     showQuickDateReceiving && (
                                                        <button 
                                                            onClick={() => {
                                                                setQuickDateId(item.requestId);
                                                                setQuickDateType('RECEIVING');
                                                                setQuickDateValue(new Date().toISOString().split('T')[0]);
                                                            }}
                                                            className="flex items-center text-green-600 hover:text-green-800 hover:bg-green-100 px-2 py-1 rounded transition-colors no-print"
                                                            title="ระบุวันที่ (รันเลขอัตโนมัติ)"
                                                        >
                                                            <CalendarPlus size={16} className="mr-1" />
                                                            <span className="text-xs font-medium">เพิ่มวันที่</span>
                                                        </button>
                                                     )
                                                )}
                                            </td>
                                            <td className="px-4 py-3 text-right font-medium">
                                                {item.amount.toLocaleString()}
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[120px] print:max-w-none">{item.category}</td>
                                            <td className="px-4 py-3 truncate max-w-[150px] print:max-w-none">{item.company}</td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    <button onClick={() => openEdit(item)} className="p-1.5 hover:bg-slate-200 rounded text-slate-600">
                                                        <Edit2 size={16} />
                                                    </button>
                                                    <button onClick={() => handleDeleteClick(item.id)} className="p-1.5 hover:bg-red-100 rounded text-red-500">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Quick Date Modal */}
            {quickDateId && quickDateType && (
                <div className="fixed inset-0 bg-black/30 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-lg shadow-xl p-5 w-full max-w-sm animate-fade-in border border-slate-200">
                        <div className="flex justify-between items-center mb-3">
                            <h3 className="font-bold text-slate-800">{quickDateTitle}</h3>
                            <button onClick={closeQuickDate} className="text-slate-400 hover:text-slate-600"><X size={18}/></button>
                        </div>
                        <div className={`${theme.bgSoft} p-3 rounded-md mb-4 border ${theme.border}`}>
                            <p className="text-xs text-slate-600">
                                ระบบจะกำหนดเลขเป็น <span className={`font-bold ${theme.text}`}>{previewNextNum}</span> (รันต่อจากเลขล่าสุด)
                            </p>
                        </div>
                        <input 
                            type="date"
                            className={`w-full border border-slate-300 rounded-lg px-3 py-2 mb-6 focus:ring-2 ${theme.ring} outline-none text-center font-medium`}
                            value={quickDateValue}
                            onChange={(e) => setQuickDateValue(e.target.value)}
                            autoFocus
                        />
                        <div className="flex justify-end space-x-2">
                            <button 
                                onClick={closeQuickDate}
                                className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={handleSaveQuickDate}
                                className={`px-4 py-2 ${theme.bgDeep} ${theme.bgHover} text-white rounded-lg text-sm font-medium shadow-sm flex items-center`}
                            >
                                <Check size={16} className="mr-1.5" />
                                บันทึก
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Delete Confirmation Modal */}
            {deleteId && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-xl shadow-2xl border border-red-100 p-6 max-w-sm w-full text-center animate-fade-in">
                        <div className="mx-auto flex items-center justify-center h-14 w-14 rounded-full bg-red-100 mb-5">
                            <AlertTriangle className="h-7 w-7 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการลบข้อมูล?</h3>
                        <p className="text-slate-500 mb-8 text-sm leading-relaxed">
                            คุณต้องการลบรายการนี้ใช่หรือไม่?<br/>
                            การกระทำนี้ไม่สามารถเรียกคืนข้อมูลกลับมาได้
                        </p>
                        <div className="flex justify-center space-x-3">
                            <button 
                                onClick={cancelDelete}
                                className="flex-1 px-4 py-2.5 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmDelete}
                                className="flex-1 px-4 py-2.5 bg-red-600 text-white rounded-lg hover:bg-red-700 shadow-lg transition-colors font-medium text-sm flex justify-center items-center"
                            >
                                <Trash2 size={16} className="mr-2" />
                                ลบข้อมูล
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden relative max-h-[90vh] overflow-y-auto">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0 z-10">
                            <h3 className="text-lg font-semibold text-slate-800">
                                {editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}
                            </h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">
                                <X size={24} />
                            </button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 grid grid-cols-2 gap-6">

                            {/* Request Info Section Header - Only for Complex Mode */}
                            {!isSimpleView && (
                                <div className="col-span-2">
                                    <h4 className="text-sm font-semibold text-slate-500 uppercase mb-3 flex items-center border-b pb-1">
                                        <span className="bg-slate-100 text-slate-600 px-2 py-0.5 rounded mr-2">1</span> 
                                        ข้อมูลใบขอ (Request)
                                    </h4>
                                </div>
                            )}

                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestId} *</label>
                                <input 
                                    required
                                    type="text" 
                                    className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none text-black text-base font-medium ${theme.inputBg}`}
                                    value={formData.requestId}
                                    onChange={handleRequestIdChange}
                                    placeholder={settings.requestIdPrefix || "เช่น REQ-001"}
                                />
                                <p className="text-xs text-red-500 mt-1">ตั้งค่ารูปแบบได้ที่เมนู "ตั้งค่าระบบ"</p>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestDate} *</label>
                                <div className="relative">
                                    <input 
                                        ref={dateInputRef}
                                        required
                                        type="date" 
                                        className={`w-full border border-slate-300 rounded-lg px-3 py-2 pl-3 pr-10 focus:ring-2 ${theme.ring} outline-none text-black text-base font-medium bg-white cursor-pointer`}
                                        value={formData.requestDate}
                                        onChange={e => setFormData({...formData, requestDate: e.target.value})}
                                        onClick={() => {
                                            try {
                                                if(dateInputRef.current && typeof dateInputRef.current.showPicker === 'function') {
                                                    dateInputRef.current.showPicker();
                                                }
                                            } catch (e) { }
                                        }}
                                    />
                                    <div className="absolute right-3 top-2.5 text-slate-400 pointer-events-none">
                                        <Calendar size={20} />
                                    </div>
                                    <style>{`
                                        input[type="date"]::-webkit-calendar-picker-indicator {
                                            position: absolute; top: 0; left: 0; width: 100%; height: 100%; margin: 0; padding: 0; opacity: 0; cursor: pointer;
                                        }
                                    `}</style>
                                </div>
                            </div>

                            {/* Consideration Info Section - Only for Complex Mode */}
                            {!isSimpleView && (
                                <>
                                    <div className="col-span-2 mt-2">
                                        <h4 className="text-sm font-semibold text-orange-600 uppercase mb-3 flex items-center border-b border-orange-100 pb-1">
                                            <FileText size={16} className="mr-2"/>
                                            <span className="bg-orange-50 text-orange-700 px-2 py-0.5 rounded mr-2">2</span> 
                                            ข้อมูลบันทึกข้อความ / เลขพิจารณา
                                        </h4>
                                    </div>

                                    <div className="col-span-1">
                                        <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.considerationNumber}</label>
