                                                item.type === RecordType.HIRING ? 'bg-violet-50 text-violet-700 border-violet-100' :
                                                'bg-orange-50 text-orange-700 border-orange-100'
                                            }`}>
                                                {item.type === RecordType.PURCHASE ? 'จัดซื้อ' : 
                                                 item.type === RecordType.HIRING ? 'จัดจ้าง' : 'อื่นๆ'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 font-medium text-slate-700">{item.requestId}</td>
                                        <td className="px-6 py-4 text-slate-600">
                                            <div className="flex flex-col">
                                                <span className="font-medium text-slate-900">{item.company}</span>
                                                <span className="text-xs text-slate-400 truncate max-w-[200px]">{item.category}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-slate-500">{item.requestDate}</td>
                                        <td className="px-6 py-4 text-right font-medium text-slate-900">
                                            {item.amount.toLocaleString()}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;

payload.text:
การเปลี่ยนจากระบบที่เก็บข้อมูลในตัวแปร (In-Memory) ไปใช้ฐานข้อมูล **MySQL** สามารถทำได้ครับ แต่จะต้องมีการปรับเปลี่ยนโครงสร้างระบบครั้งใหญ่ (Major Architectural Change) เนื่องจาก Browser (React) ไม่สามารถเชื่อมต่อกับ MySQL โดยตรงได้ด้วยเหตุผลด้านความปลอดภัย

ท่านจะต้องสร้าง **"สะพานเชื่อม" (Backend API)** ขึ้นมาคั่นกลางครับ

### โครงสร้างการทำงานใหม่
1.  **Frontend (React ตัวเดิม):** เปลี่ยนจากการสั่ง `setProcurements` ในตัวแปร เป็นการส่งคำสั่ง `fetch` หรือ `axios` ไปหา Backend
2.  **Backend (ต้องสร้างใหม่):** เป็น Server (เช่น Node.js, PHP, Go, หรือ Python) ที่ทำหน้าที่รับคำสั่งจาก Frontend
3.  **Database (MySQL):** เก็บข้อมูลลงตารางจริง

---

### ขั้นตอนการทำ (How-to)

หากท่านต้องการทำระบบจริงจัง ผมขอแนะนำขั้นตอนดังนี้ครับ:

#### 1. ออกแบบตารางใน MySQL (Database Schema)
ท่านต้องสร้างตารางให้สอดคล้องกับไฟล์ `types.ts` ที่เรามี นี่คือคำสั่ง SQL สำหรับสร้างตารางครับ:

```sql
-- ตารางผู้ใช้งาน
CREATE TABLE users (
    id VARCHAR(50) PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    password VARCHAR(255) NOT NULL, -- ควรเข้ารหัส Hash ก่อนเก็บ
    name VARCHAR(100),
    role ENUM('ADMIN', 'USER') DEFAULT 'USER',
    department_id VARCHAR(50),
    created_at BIGINT
);

-- ตารางหลัก: ทะเบียนคุม (จัดซื้อ/จัดจ้าง/อื่นๆ)
CREATE TABLE procurements (
    id VARCHAR(50) PRIMARY KEY,
    type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL,
    request_id VARCHAR(50) NOT NULL, -- เลขที่ใบขอ
    request_date DATE NOT NULL,
    category VARCHAR(100),
    item_count INT,
    amount DECIMAL(15, 2),
    company VARCHAR(255),
    remarks TEXT,
    official_number VARCHAR(50), -- เลขคุม
    created_at BIGINT
);

-- ตาราง: ใบรับของ/ตรวจรับ
CREATE TABLE receivings (
    id VARCHAR(50) PRIMARY KEY,
    request_id VARCHAR(50) NOT NULL, -- Link ไป procurements
    delivery_note_no VARCHAR(50),
    receive_date DATE,
    category VARCHAR(100),
    created_at BIGINT,
    FOREIGN KEY (request_id) REFERENCES procurements(id) ON DELETE CASCADE
);

-- ตาราง: เลขพิจารณา
CREATE TABLE considerations (
    id VARCHAR(50) PRIMARY KEY,
    request_id VARCHAR(50) NOT NULL,
    consideration_number VARCHAR(50),
    consideration_date DATE,
    FOREIGN KEY (request_id) REFERENCES procurements(id) ON DELETE CASCADE
);
```

#### 2. สร้าง Backend API (ตัวอย่างด้วย Node.js + Express)
ท่านต้องเขียนโค้ดฝั่ง Server เพื่อรับส่งข้อมูล ตัวอย่างคร่าวๆ:

```javascript
// server.js (Node.js)
const express = require('express');
const mysql = require('mysql2');
const app = express();

// เชื่อมต่อ MySQL
const db = mysql.createConnection({
    host: 'localhost',
    user: 'root',
    password: 'password',
    database: 'procurement_db'
});

// API ดึงข้อมูล
app.get('/api/procurements', (req, res) => {
    db.query('SELECT * FROM procurements', (err, results) => {
        if (err) throw err;
        res.json(results);
    });
});

// API บันทึกข้อมูล
app.post('/api/procurements', (req, res) => {
    const data = req.body;
    db.query('INSERT INTO procurements SET ?', data, (err, result) => {
        if (err) throw err;
        res.json({ success: true, id: result.insertId });
    });
});

app.listen(3001, () => console.log('Server running on port 3001'));
```

#### 3. ปรับแก้ Frontend (`services/store.tsx`)
ในไฟล์ React ปัจจุบัน ท่านต้องแก้โค้ดใน `AppProvider` เพื่อให้เชื่อมต่อกับ API แทนการเก็บ Array เปล่าๆ

**จากเดิม:**
```typescript
const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);

const addProcurement = (record) => {
    setProcurements([...procurements, record]);
}
```

**เปลี่ยนเป็น:**
```typescript
// โหลดข้อมูลตอนเข้าเว็บ
useEffect(() => {
    fetch('http://localhost:3001/api/procurements')
        .then(res => res.json())
        .then(data => setProcurements(data));
}, []);

// บันทึกข้อมูลลง Server
const addProcurement = async (record) => {
    await fetch('http://localhost:3001/api/procurements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(record)
    });
    // โหลดข้อมูลใหม่หลังจากบันทึก
    refreshData(); 
}
```

---

### ข้อแนะนำสำหรับตอนนี้

เนื่องจากการตั้งค่า Server และ MySQL ต้องทำนอกเหนือจากโค้ดชุดนี้ (ต้องติดตั้งโปรแกรมลงเครื่อง) ผมขอแนะนำทางเลือก 2 ทางครับ:

1.  **ถ้าท่านเป็น Developer และพร้อมทำ Backend:** ท่านสามารถนำ SQL Schema ด้านบนไปสร้าง Database และเริ่มเขียน API ได้เลยครับ
2.  **ถ้าท่านต้องการใช้งานเบื้องต้นไปก่อน (ยังไม่มี Server):** ผมสามารถแก้โค้ดให้เก็บลง **LocalStorage** ของ Browser ให้ได้ครับ ข้อมูลจะไม่หายเมื่อรีเฟรช (แต่อยู่แค่เครื่องเดิม)

**ท่านต้องการให้ผมปรับโค้ดเป็นแบบ LocalStorage ให้ก่อนไหมครับ เพื่อให้ใช้งานข้อมูลต่อเนื่องได้ทันที?**

การย้ายระบบจาก In-Memory ไปสู่ Linux Server + MySQL เป็นขั้นตอนที่ยอดเยี่ยมครับ จะทำให้ระบบใช้งานได้จริง เก็บข้อมูลถาวร และใช้งานพร้อมกันได้หลายคน

เนื่องจาก React (Frontend) ไม่สามารถคุยกับ MySQL โดยตรงได้ (เพื่อความปลอดภัย) เราต้องสร้าง **"API Server"** (Backend) มาคั่นกลางครับ

นี่คือขั้นตอนแบบละเอียด (Step-by-Step) สำหรับ Linux (Ubuntu/Debian):

---

### ส่วนที่ 1: เตรียม Server (Linux)

Login เข้า Linux Server ของคุณผ่าน Terminal แล้วทำตามนี้ครับ:

**1. อัปเดตเครื่องและติดตั้ง Node.js & MySQL**
```bash
# อัปเดตระบบ
sudo apt update && sudo apt upgrade -y

# ติดตั้ง Node.js (ตัวรัน JavaScript ฝั่ง Server)
curl -fsSL https://deb.nodesource.com/setup_18.x | sudo -E bash -
sudo apt install -y nodejs

# ติดตั้ง MySQL Server
sudo apt install -y mysql-server
```

**2. ตั้งค่าความปลอดภัย MySQL**
```bash
sudo mysql_secure_installation
# ตอบ Y และตั้งรหัสผ่านให้เรียบร้อย
```

**3. สร้าง Database และตาราง**
Login เข้า MySQL:
```bash
sudo mysql -u root -p
# ใส่รหัสผ่านที่ตั้งไว้
```

รันคำสั่ง SQL ต่อไปนี้ทีละชุดเพื่อสร้างตาราง (Copy ไปวางได้เลยครับ):

```sql
-- สร้างฐานข้อมูล
CREATE DATABASE procurement_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE procurement_db;

-- 1. ตารางผู้ใช้งาน (Users)
CREATE TABLE users (
    id VARCHAR(50) PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    password VARCHAR(255) NOT NULL,
    name VARCHAR(100) NOT NULL,
    role ENUM('ADMIN', 'USER') DEFAULT 'USER',
    department_id VARCHAR(50),
    created_at BIGINT
);
-- เพิ่ม User Admin เริ่มต้น (password: admin)
INSERT INTO users VALUES ('1', 'admin', 'admin', 'Administrator', 'ADMIN', 'dept_1', 1700000000000);

-- 2. ตารางหลัก ทะเบียนคุม (Procurements)
CREATE TABLE procurements (
    id VARCHAR(50) PRIMARY KEY,
    type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL,
    request_id VARCHAR(50) NOT NULL,
    request_date DATE NOT NULL,
    category VARCHAR(100),
    item_count INT,
    amount DECIMAL(15, 2),
    company VARCHAR(255),
    remarks TEXT,
    official_number VARCHAR(50),
    created_at BIGINT
);

-- 3. ตารางใบรับของ (Receivings)
CREATE TABLE receivings (
    id VARCHAR(50) PRIMARY KEY,
    request_id VARCHAR(50),
    delivery_note_no VARCHAR(50),
    receive_date DATE,
    category VARCHAR(100),
    created_at BIGINT
);

-- 4. ตารางเลขพิจารณา (Considerations)
CREATE TABLE considerations (
    id VARCHAR(50) PRIMARY KEY,
    request_id VARCHAR(50),
    consideration_number VARCHAR(50),
    consideration_date DATE
);

EXIT;
```

---

### ส่วนที่ 2: สร้าง Backend API (Node.js)

เราจะสร้างโฟลเดอร์สำหรับ Server แยกออกมาครับ

**1. สร้างโปรเจกต์**
```bash
mkdir my-procurement-api
cd my-procurement-api
npm init -y
```

**2. ติดตั้ง Library ที่จำเป็น**
```bash
npm install express mysql2 cors body-parser
```

**3. เขียนโค้ด Server (`server.js`)**
สร้างไฟล์ `nano server.js` แล้ววางโค้ดนี้ลงไป (แก้ตรง `password` ให้ตรงกับ MySQL ของคุณ):

```javascript
const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
app.use(cors()); // อนุญาตให้ React เข้าถึงได้
app.use(bodyParser.json());

// ตั้งค่าเชื่อมต่อ Database
const db = mysql.createPool({
    host: 'localhost',
    user: 'root',
    password: 'YOUR_MYSQL_PASSWORD', // <-- แก้รหัสผ่านตรงนี้
    database: 'procurement_db',
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

// --- API ROUTES ---

// 1. ดึงข้อมูลทั้งหมด (Procurements)
app.get('/api/procurements', (req, res) => {
    db.query('SELECT * FROM procurements ORDER BY created_at DESC', (err, results) => {
        if (err) return res.status(500).json(err);
        // แปลงวันที่ให้เป็น Format ที่ Frontend ชอบถ้าจำเป็น
        res.json(results);
    });
});

// 2. บันทึกข้อมูล (Add Procurement)
app.post('/api/procurements', (req, res) => {
    const { id, type, requestId, requestDate, category, itemCount, amount, company, remarks, officialNumber, createdAt } = req.body;

    const sql = `INSERT INTO procurements 
    (id, type, request_id, request_date, category, item_count, amount, company, remarks, official_number, created_at) 
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;

    const values = [id, type, requestId, requestDate, category, itemCount, amount, company, remarks, officialNumber, createdAt];

    db.query(sql, values, (err, result) => {
        if (err) return res.status(500).json(err);
        res.json({ message: 'Saved successfully', id: id });
    });
});

// 3. ลบข้อมูล
app.delete('/api/procurements/:id', (req, res) => {
    db.query('DELETE FROM procurements WHERE id = ?', [req.params.id], (err, result) => {
        if (err) return res.status(500).json(err);
        res.json({ message: 'Deleted' });
    });
});

// 4. Login (แบบง่าย)
app.post('/api/login', (req, res) => {
    const { username, password } = req.body;
    db.query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password], (err, results) => {
        if (err) return res.status(500).json(err);
        if (results.length > 0) {
            res.json({ success: true, user: results[0] });
        } else {
            res.json({ success: false, message: 'Invalid credentials' });
        }
    });
});

// รัน Server ที่ Port 3001
app.listen(3001, () => {
    console.log('Server running on port 3001');
});
```

**4. รัน Server**
```bash
node server.js
# ถ้าขึ้น Server running on port 3001 แสดงว่าผ่าน!
```

---

### ส่วนที่ 3: แก้ไข React Frontend (เชื่อมต่อ)

กลับมาที่โค้ด React บนเครื่องของคุณ (หรือบน Server ถ้าคุณ Build บนนั้น) ต้องแก้ไขไฟล์ `services/store.tsx` ให้เลิกใช้ Mock Data และไปเรียก API แทน

**ตัวอย่างการแก้ `services/store.tsx` (แนวทาง):**

1.  **เปลี่ยน `useState` เริ่มต้นให้ว่างเปล่า:**
    ```typescript
    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    ```

2.  **เพิ่ม `useEffect` เพื่อโหลดข้อมูลตอนเปิดเว็บ:**
    ```typescript
    useEffect(() => {
        // ดึงข้อมูลจาก API
        fetch('http://IP_ADDRESS_SERVER:3001/api/procurements')
            .then(res => res.json())
            .then(data => {
                // แปลงชื่อ Field จาก Database (snake_case) เป็น React (camelCase) ถ้าจำเป็น
                const formatted = data.map((item: any) => ({
                    id: item.id,
                    requestId: item.request_id,
                    requestDate: item.request_date,
                    // ... map ให้ครบทุก field
                }));
                setProcurements(formatted);
            })
            .catch(err => console.error("Error loading data:", err));
    }, []);
    ```

3.  **แก้ฟังก์ชัน `addProcurement` ให้ส่งข้อมูลไป Server:**
    ```typescript
    const addProcurement = async (record: any) => {
        // 1. คำนวณต่างๆ เหมือนเดิม
        const newRecord = { ...record, id: generateId(), ... };

        try {
            // 2. ยิงไปหา Server
            await fetch('http://IP_ADDRESS_SERVER:3001/api/procurements', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });

            // 3. ถ้าสำเร็จ ค่อยอัปเดตหน้าจอ
            setProcurements(prev => [...prev, newRecord]);
        } catch (error) {
            alert('บันทึกไม่สำเร็จ');
        }
    };
    ```

---

### สรุปภาพรวม
1.  **Database:** MySQL เก็บข้อมูลจริง
2.  **Backend (Node.js):** เปิด Port 3001 รอรับคำสั่ง (GET/POST) จาก React แล้วไปคุยกับ MySQL
3.  **Frontend (React):** เปิด Port 3000 (หรือ Build แล้ว) ใช้ `fetch()` ยิงไปที่ Port 3001

วิธีนี้เป็นมาตรฐานสากลครับ หากติดขัดขั้นตอนไหน (เช่น การเชื่อมต่อ Database Error หรือเขียนโค้ด React ไม่ผ่าน) แจ้งผมได้เลยครับ!

