    ]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    // Mock Data Initialization
    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [
            { id: 'dept_1', name: 'ฝ่ายบริหารงานทั่วไป' },
            { id: 'dept_2', name: 'ศูนย์เทคโนโลยีสารสนเทศ' },
            { id: 'dept_3', name: 'กลุ่มงานอาคารสถานที่' }
        ],
        categories: [
            { id: '1', name: 'วัสดุสำนักงาน', departmentId: 'dept_1' },
            { id: '2', name: 'วัสดุคอมพิวเตอร์', departmentId: 'dept_2' },
            { id: '3', name: 'จ้างเหมาบริการ', departmentId: 'dept_1' },
            { id: '4', name: 'วัสดุก่อสร้าง', departmentId: 'dept_3' },
            { id: '5', name: 'วัสดุงานบ้านงานครัว', departmentId: 'dept_1' },
            { id: '6', name: 'อื่นๆ', departmentId: 'dept_1' }
        ]
    });

    // --- Auth Functions ---
    const login = (u: string, p: string) => {
        const found = users.find(user => user.username === u && user.password === p);
        if (found) {
            setCurrentUser(found);
            return true;
        }
        return false;
    };

    const logout = () => {
        setCurrentUser(null);
    };

    const registerUser = (userData: Omit<User, 'id' | 'createdAt'>) => {
        if (users.some(u => u.username === userData.username)) {
            return false; // Username exists
        }
        const newUser: User = {
            ...userData,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now()
        };
        setUsers(prev => [...prev, newUser]);
        return true;
    };

    const deleteUser = (id: string) => {
        if (currentUser?.id === id) {
            alert("ไม่สามารถลบบัญชีที่กำลังใช้งานอยู่ได้");
            return;
        }
        setUsers(prev => prev.filter(u => u.id !== id));
    };

    const updateUser = (id: string, data: Partial<User>) => {
        setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
    };

    // --- Business Logic Helpers ---
    const getThaiYear = (dateString: string) => {
        const date = new Date(dateString);
        return date.getFullYear() + 543;
    };

    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        if (amount <= 5000) return null;

        const thaiYear = getThaiYear(dateStr);
        const existingInYear = procurements.filter(p => 
            p.type === type && 
            p.officialNumber && 
            getThaiYear(p.requestDate) === thaiYear
        );

        let maxNum = 0;
        existingInYear.forEach(p => {
            const parts = p.officialNumber?.split('/');
            if (parts && parts[0]) {
                const num = parseInt(parts[0]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });

        return `${maxNum + 1}/${thaiYear}`;
    };

    // --- Data Actions ---
    const addProcurement = (data: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>) => {
        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);

        const newRecord: ProcurementRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
            officialNumber,
            createdBy: currentUser?.id || 'unknown'
        };
        setProcurements(prev => [...prev, newRecord]);
    };

    const updateProcurement = (id: string, data: Partial<ProcurementRecord>) => {
        setProcurements(prev => prev.map(item => {
            if (item.id !== id) return item;

            let newOfficialNumber = item.officialNumber;
            if (data.amount !== undefined && data.requestDate !== undefined) {
                 if (data.amount > 5000 && !item.officialNumber) {
                     newOfficialNumber = generateRunningNumber(item.type, data.amount, data.requestDate);
                 } else if (data.amount <= 5000) {
                     newOfficialNumber = null;
                 }
            }

            return { ...item, ...data, officialNumber: newOfficialNumber };
        }));
    };

    const deleteProcurement = (id: string) => {
        setProcurements(prev => prev.filter(p => p.id !== id));
    };

    const addReceiving = (data: Omit<ReceivingReport, 'id' | 'createdAt'>) => {
        const newRecord: ReceivingReport = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
        };
        setReceivings(prev => [...prev, newRecord]);
    };

    const upsertReceiving = (requestId: string, number: string, date: string) => {
        setReceivings(prev => {
            const existing = prev.find(r => r.requestId === requestId);
            if (existing) {
                return prev.map(r => r.requestId === requestId ? { ...r, deliveryNoteNo: number, receiveDate: date } : r);
            }
            // Find procurement to populate category
            const procurement = procurements.find(p => p.requestId === requestId);
            const category = procurement ? procurement.category : '';

            if (number || date) {
                return [...prev, {
                    id: Math.random().toString(36).substr(2, 9),
                    requestId,
                    deliveryNoteNo: number,
                    receiveDate: date,
                    category,
                    createdAt: Date.now()
                }];
            }
            return prev;
        });
    };

    const deleteReceiving = (id: string) => {
        setReceivings(prev => prev.filter(r => r.id !== id));
    };

    const addConsideration = (record: ConsiderationRecord) => {
        setConsiderations(prev => [...prev, { ...record, id: Math.random().toString(36).substr(2, 9) }]);
    };

    const upsertConsideration = (requestId: string, number: string, date: string) => {
        setConsiderations(prev => {
            const existing = prev.find(c => c.requestId === requestId);
            if (existing) {
                return prev.map(c => c.requestId === requestId ? { ...c, considerationNumber: number, considerationDate: date } : c);
            }
            if (number || date) {
                return [...prev, {
                    id: Math.random().toString(36).substr(2, 9),
                    requestId,
                    considerationNumber: number,
                    considerationDate: date
                }];
            }
            return prev;
        });
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = (newSettings: Partial<AppSettings>) => {
        setSettings(prev => ({ ...prev, ...newSettings }));
    };

    return (
        <AppContext.Provider value={{
            procurements,
            receivings,
            considerations,
            settings,
            currentUser,
            users,
            login,
            logout,
            registerUser,
            deleteUser,
            updateUser,
            addProcurement,
            updateProcurement,
            deleteProcurement,
            addReceiving,
            upsertReceiving,
            deleteReceiving,
            addConsideration,
            upsertConsideration,
            getLinkedData,
            updateSettings
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

