import React, { useState, useMemo } from 'react';
import { useApp } from '../services/store';
import { RecordType } from '../types';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
    PieChart, Pie, Cell 
} from 'recharts';
import { ShoppingCart, Briefcase, Archive, Wallet, ArrowUpRight, Clock, Filter, Calendar } from 'lucide-react';

// Helper: Calculate Fiscal Year (Thai Government: Oct - Sep)
const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return new Date().getFullYear() + 543;
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return new Date().getFullYear() + 543;

    const month = date.getMonth(); // 0 = Jan, 9 = Oct
    const year = date.getFullYear();

    // If Month is Oct(9), Nov(10), Dec(11) -> Fiscal Year is next year
    return month >= 9 ? year + 1 + 543 : year + 543;
};

const Dashboard: React.FC = () => {
    const { procurements } = useApp();

    // 1. Setup Fiscal Year Logic
    const currentFiscalYear = useMemo(() => {
        const now = new Date();
        return now.getMonth() >= 9 ? now.getFullYear() + 1 + 543 : now.getFullYear() + 543;
    }, []);

    // Get list of available years from data + current year
    const availableYears = useMemo(() => {
        // Fix: Explicitly type the Set as number and parameters in sort as number to resolve arithmetic operation errors
        const years = new Set<number>(procurements.map(p => getFiscalYear(p.requestDate)));
        years.add(currentFiscalYear);
        return Array.from(years).sort((a: number, b: number) => b - a);
    }, [procurements, currentFiscalYear]);

    const [selectedYear, setSelectedYear] = useState<number>(currentFiscalYear);

    // 2. Filter Data by Selected Fiscal Year
    const yearData = useMemo(() => {
        return procurements.filter(p => getFiscalYear(p.requestDate) === selectedYear);
    }, [procurements, selectedYear]);

    // Split by type
    const purchase = yearData.filter(p => p.type === RecordType.PURCHASE);
    const hiring = yearData.filter(p => p.type === RecordType.HIRING);
    const other = yearData.filter(p => p.type === RecordType.OTHER);

    // 3. Calculate Totals
    const totalPurchase = purchase.reduce((acc, curr) => acc + curr.amount, 0);
    const totalHiring = hiring.reduce((acc, curr) => acc + curr.amount, 0);
    const totalOther = other.reduce((acc, curr) => acc + curr.amount, 0);
    const grandTotal = totalPurchase + totalHiring + totalOther;

    // 4. Prepare Chart Data: Monthly Trends (Fiscal Year Order: Oct -> Sep)
    const fiscalMonths = [
        { name: 'ต.ค.', monthIndex: 9 }, 
        { name: 'พ.ย.', monthIndex: 10 },
        { name: 'ธ.ค.', monthIndex: 11 },
        { name: 'ม.ค.', monthIndex: 0 },
        { name: 'ก.พ.', monthIndex: 1 },
        { name: 'มี.ค.', monthIndex: 2 },
        { name: 'เม.ย.', monthIndex: 3 },
        { name: 'พ.ค.', monthIndex: 4 },
        { name: 'มิ.ย.', monthIndex: 5 },
        { name: 'ก.ค.', monthIndex: 6 },
        { name: 'ส.ค.', monthIndex: 7 },
        { name: 'ก.ย.', monthIndex: 8 },
    ];

    const chartData = fiscalMonths.map((m) => {
        const filterByMonth = (items: typeof procurements) => 
            items.filter(item => {
                const date = new Date(item.requestDate);
                return date.getMonth() === m.monthIndex;
            }).reduce((acc, curr) => acc + curr.amount, 0);

        return {
            name: m.name,
            จัดซื้อ: filterByMonth(purchase),
            จัดจ้าง: filterByMonth(hiring),
            อื่นๆ: filterByMonth(other),
        };
    });

    // 5. Prepare Chart Data: Category Distribution (Top 5)
    const categoryMap = new Map<string, number>();
    yearData.forEach(p => {
        const current = categoryMap.get(p.category) || 0;
        categoryMap.set(p.category, current + p.amount);
    });

    const categoryData = Array.from(categoryMap.entries())
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 5); // Top 5 Categories

    // 6. Prepare Chart Data: Pie Distribution
    const pieData = [
        { name: 'จัดซื้อ (PO)', value: totalPurchase },
        { name: 'จัดจ้าง (HO)', value: totalHiring },
        { name: 'อื่นๆ (Other)', value: totalOther },
    ].filter(d => d.value > 0);

    // 7. Recent Activity (Filtered by Year)
    const recentItems = [...yearData]
        .sort((a, b) => b.createdAt - a.createdAt)
        .slice(0, 5);

    // Colors
    const COLORS = {
        purchase: '#3b82f6', // Blue
        hiring: '#8b5cf6',   // Violet
        other: '#f97316',    // Orange
        gray: '#cbd5e1'
    };
    const PIE_COLORS = [COLORS.purchase, COLORS.hiring, COLORS.other];

    return (
        <div className="p-6 space-y-6 animate-fade-in">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Dashboard ภาพรวม</h2>
                    <p className="text-sm text-slate-500">สรุปข้อมูลการจัดซื้อจัดจ้างและงบประมาณ</p>
                </div>

                {/* Fiscal Year Selector */}
                <div className="flex items-center space-x-3">
                    <div className="hidden sm:block text-right mr-2">
                        <p className="text-xs text-slate-400">ข้อมูล ณ วันที่</p>
                        <p className="text-sm font-medium text-slate-700">
                            {new Date().toLocaleDateString('th-TH', { year: 'numeric', month: 'long', day: 'numeric' })}
                        </p>
                    </div>
                    <div className="flex items-center space-x-2 bg-white rounded-lg border border-slate-200 px-3 py-2 shadow-sm hover:border-blue-300 transition-colors">
                        <div className="bg-blue-100 p-1 rounded text-blue-600">
                            <Filter size={14} />
                        </div>
                        <div className="flex flex-col">
                            <span className="text-[10px] text-slate-400 leading-none">ปีงบประมาณ</span>
                            <select 
                                value={selectedYear} 
                                onChange={(e) => setSelectedYear(Number(e.target.value))}
                                className="text-sm font-bold text-slate-700 outline-none bg-transparent cursor-pointer hover:text-blue-600 appearance-none pr-4"
                                style={{ backgroundImage: 'none' }}
                            >
                                {availableYears.map(y => (
                                    <option key={y} value={y}>พ.ศ. {y}</option>
                                ))}
                            </select>
                        </div>
                        <Calendar size={14} className="text-slate-400" />
                    </div>
                </div>
            </div>

            {/* --- 1. Summary Cards --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {/* Grand Total */}
                <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-xl p-5 text-white shadow-lg flex flex-col justify-between relative overflow-hidden">
                    <div className="z-10">
                        <p className="text-slate-300 text-sm mb-1">งบประมาณรวม (ปี {selectedYear})</p>
                        <h3 className="text-2xl font-bold">{grandTotal.toLocaleString()} <span className="text-sm font-normal text-slate-400">บาท</span></h3>
                    </div>
                    <div className="z-10 mt-4 flex items-center text-xs text-emerald-400 bg-emerald-500/10 w-fit px-2 py-1 rounded">
                        <ArrowUpRight size={14} className="mr-1" />
                        <span>{yearData.length} รายการ</span>
                    </div>
                    <Wallet className="absolute right-[-10px] bottom-[-10px] text-white/5 w-24 h-24 rotate-12" />
                </div>

                {/* Purchase Stats */}
                <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 relative overflow-hidden group hover:border-blue-200 transition-all">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-2 bg-blue-50 text-blue-600 rounded-lg group-hover:bg-blue-600 group-hover:text-white transition-colors">
                            <ShoppingCart size={20} />
                        </div>
                        <span className="text-xs font-semibold text-blue-600 bg-blue-50 px-2 py-1 rounded-full">{purchase.length} ใบ</span>
                    </div>
                    <p className="text-slate-500 text-xs">ยอดรวมจัดซื้อ</p>
                    <h3 className="text-xl font-bold text-slate-800">{totalPurchase.toLocaleString()}</h3>
                    <div className="w-full bg-slate-100 h-1 mt-3 rounded-full overflow-hidden">
                        <div className="bg-blue-500 h-full rounded-full" style={{ width: grandTotal > 0 ? `${(totalPurchase/grandTotal * 100)}%` : '0%' }}></div>
                    </div>
                </div>

                {/* Hiring Stats */}
                <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 relative overflow-hidden group hover:border-violet-200 transition-all">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-2 bg-violet-50 text-violet-600 rounded-lg group-hover:bg-violet-600 group-hover:text-white transition-colors">
                            <Briefcase size={20} />
                        </div>
                        <span className="text-xs font-semibold text-violet-600 bg-violet-50 px-2 py-1 rounded-full">{hiring.length} ใบ</span>
                    </div>
                    <p className="text-slate-500 text-xs">ยอดรวมจัดจ้าง</p>
                    <h3 className="text-xl font-bold text-slate-800">{totalHiring.toLocaleString()}</h3>
                    <div className="w-full bg-slate-100 h-1 mt-3 rounded-full overflow-hidden">
                        <div className="bg-violet-500 h-full rounded-full" style={{ width: grandTotal > 0 ? `${(totalHiring/grandTotal * 100)}%` : '0%' }}></div>
                    </div>
                </div>

                {/* Other Stats */}
                <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 relative overflow-hidden group hover:border-orange-200 transition-all">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-2 bg-orange-50 text-orange-600 rounded-lg group-hover:bg-orange-600 group-hover:text-white transition-colors">
                            <Archive size={20} />
                        </div>
                        <span className="text-xs font-semibold text-orange-600 bg-orange-50 px-2 py-1 rounded-full">{other.length} ใบ</span>
                    </div>
                    <p className="text-slate-500 text-xs">ยอดรวมอื่นๆ</p>
                    <h3 className="text-xl font-bold text-slate-800">{totalOther.toLocaleString()}</h3>
                    <div className="w-full bg-slate-100 h-1 mt-3 rounded-full overflow-hidden">
                        <div className="bg-orange-500 h-full rounded-full" style={{ width: grandTotal > 0 ? `${(totalOther/grandTotal * 100)}%` : '0%' }}></div>
                    </div>
                </div>
            </div>

            {/* --- 2. Main Charts Section --- */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* Monthly Trend */}
                <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-[400px]">
                    <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
                        <Clock size={18} className="mr-2 text-slate-400"/> สถิติรายเดือน (ปีงบประมาณ {selectedYear})
                    </h3>
                    <ResponsiveContainer width="100%" height="85%">
                        <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                            <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                            <YAxis fontSize={12} tickFormatter={(value) => value >= 1000 ? `${value/1000}k` : value} tickLine={false} axisLine={false} />
                            <Tooltip 
                                cursor={{fill: '#f1f5f9'}}
                                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                                formatter={(value: number) => value.toLocaleString()}
                            />
                            <Legend wrapperStyle={{ paddingTop: '20px' }} />
                            <Bar dataKey="จัดซื้อ" stackId="a" fill={COLORS.purchase} radius={[0, 0, 4, 4]} />
                            <Bar dataKey="จัดจ้าง" stackId="a" fill={COLORS.hiring} />
                            <Bar dataKey="อื่นๆ" stackId="a" fill={COLORS.other} radius={[4, 4, 0, 0]} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>

                {/* Pie Chart & Top Categories */}
                <div className="flex flex-col gap-6">
                    {/* Ratio Pie */}
                    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex-1 min-h-[250px]">
                        <h3 className="text-sm font-bold text-slate-700 mb-2">สัดส่วนงบประมาณ</h3>
