                        <h3 className="text-sm font-bold text-slate-700 mb-4">5 อันดับหมวดพัสดุสูงสุด</h3>
                        <div className="space-y-3">
                            {categoryData.length === 0 ? (
                                <p className="text-xs text-slate-400 text-center py-4">ยังไม่มีข้อมูล</p>
