            </div>

            {/* --- 3. Recent Activity Table --- */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                    <h3 className="text-lg font-bold text-slate-800">รายการล่าสุด (ปีงบประมาณ {selectedYear})</h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-50 text-xs uppercase text-slate-500 font-medium">
                            <tr>
                                <th className="px-6 py-3">ประเภท</th>
                                <th className="px-6 py-3">เลขที่เอกสาร</th>
                                <th className="px-6 py-3">บริษัท/รายละเอียด</th>
                                <th className="px-6 py-3">วันที่</th>
                                <th className="px-6 py-3 text-right">จำนวนเงิน</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {recentItems.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="px-6 py-8 text-center text-slate-400">ยังไม่มีรายการในปีนี้</td>
                                </tr>
                            ) : (
                                recentItems.map(item => (
                                    <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-6 py-4">
                                            <span className={`inline-flex items-center px-2 py-1 rounded text-xs font-medium border ${
                                                item.type === RecordType.PURCHASE ? 'bg-blue-50 text-blue-700 border-blue-100' :
                                                item.type === RecordType.HIRING ? 'bg-violet-50 text-violet-700 border-violet-100' :
                                                'bg-orange-50 text-orange-700 border-orange-100'
                                            }`}>
                                                {item.type === RecordType.PURCHASE ? 'จัดซื้อ' : 
                                                 item.type === RecordType.HIRING ? 'จัดจ้าง' : 'อื่นๆ'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 font-medium text-slate-700">{item.requestId}</td>
                                        <td className="px-6 py-4 text-slate-600">
                                            <div className="flex flex-col">
                                                <span className="font-medium text-slate-900">{item.company}</span>
                                                <span className="text-xs text-slate-400 truncate max-w-[200px]">{item.category}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-slate-500">{item.requestDate}</td>
                                        <td className="px-6 py-4 text-right font-medium text-slate-900">
                                            {item.amount.toLocaleString()}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

