                                    return (
                                        <div key={cat.id} className="p-3 bg-slate-50 border border-slate-100 rounded-lg group hover:border-green-200 transition-all">
                                            {editingCategoryId === cat.id ? (
                                                <div className="space-y-2">
                                                    <input 
                                                        className="w-full bg-white text-slate-900 border border-green-300 rounded px-2 py-1 text-sm outline-none"
                                                        value={editCatName}
                                                        onChange={e => setEditCatName(e.target.value)}
                                                    />
                                                    <div className="flex space-x-2">
                                                        <select 
                                                            className="flex-1 border border-green-300 rounded px-2 py-1 text-sm outline-none bg-white"
                                                            value={editCatDept}
                                                            onChange={e => setEditCatDept(e.target.value)}
                                                        >
                                                            <option value="">-- ไม่ระบุฝ่าย --</option>
                                                            {localSettings.departments?.map(d => (
                                                                <option key={d.id} value={d.id}>{d.name}</option>
                                                            ))}
                                                        </select>
                                                        <button onClick={saveEditCategory} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={18}/></button>
                                                        <button onClick={() => setEditingCategoryId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={18}/></button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex justify-between items-center">
                                                    <div>
                                                        <div className="text-slate-700 font-medium text-sm">{cat.name}</div>
                                                        {deptName && (
                                                            <div className="text-xs text-indigo-500 bg-indigo-50 px-2 py-0.5 rounded-full inline-block mt-1">
                                                                {deptName}
                                                            </div>
                                                        )}
                                                    </div>
                                                    <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                        <button onClick={() => startEditCategory(cat)} className="p-1.5 text-slate-400 hover:text-green-600"><Edit2 size={16}/></button>
                                                        <button onClick={() => deleteCategory(cat.id)} className="p-1.5 text-slate-400 hover:text-red-600"><Trash2 size={16}/></button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
};

export default SettingsPage;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { UserCog, User as UserIcon, Shield, Search, Edit, X, Check, Lock, Building, Power, PowerOff, AlertCircle } from 'lucide-react';
import { UserRole, User } from '../types';

const UserManagementPage: React.FC = () => {
    const { users, currentUser, deleteUser, updateUser, registerUser, settings } = useApp();
    const [searchTerm, setSearchTerm] = useState('');

    // Add User Form State
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [newName, setNewName] = useState('');
    const [newRole, setNewRole] = useState<UserRole>('USER');
    const [newDeptId, setNewDeptId] = useState('');

    // Edit User State
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [showEditConfirm, setShowEditConfirm] = useState(false);
    const [editFormData, setEditFormData] = useState({
        name: '',
        username: '',
        password: '',
        role: 'USER' as UserRole,
        departmentId: ''
    });

    const filteredUsers = users.filter(u => 
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        u.username.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleAddUser = (e: React.FormEvent) => {
        e.preventDefault();
        const success = registerUser({
            username: newUsername,
            password: newPassword,
            name: newName,
            role: newRole,
            departmentId: newDeptId || undefined
        });

        if (success) {
            setNewUsername('');
            setNewPassword('');
            setNewName('');
            setNewRole('USER');
            setNewDeptId('');
        } else {
            alert('Username นี้มีผู้ใช้งานแล้ว');
        }
    };

    const openEditModal = (user: User) => {
        setEditingUser(user);
        setEditFormData({
            name: user.name,
            username: user.username,
            password: '', // Leave blank to keep current password
            role: user.role,
            departmentId: user.departmentId || ''
        });
    };

    const handleUpdateUserSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowEditConfirm(true);
    };

    const confirmUpdateUser = () => {
        if (!editingUser) return;

        const updates: Partial<User> = {
            name: editFormData.name,
            role: editFormData.role,
            departmentId: editFormData.departmentId || undefined
        };

        if (editFormData.password.trim()) {
            updates.password = editFormData.password;
        }

        updateUser(editingUser.id, updates);
        setEditingUser(null);
        setShowEditConfirm(false);
    };

    const toggleStatus = (user: User) => {
        if (user.id === currentUser?.id) return;
        updateUser(user.id, { isActive: !user.isActive });
    };

    const toggleRole = (id: string, currentRole: UserRole) => {
        if (id === currentUser?.id) return;
        const newRole = currentRole === 'ADMIN' ? 'USER' : 'ADMIN';
        updateUser(id, { role: newRole });
    };

    const getDeptName = (deptId?: string) => {
        if (!deptId) return '-';
        return settings.departments?.find(d => d.id === deptId)?.name || '-';
    };

    return (
        <div className="p-6">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">จัดการผู้ใช้งาน (User Management)</h2>

            {/* Stats & Tools */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
                <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                        <h3 className="font-semibold text-slate-800 flex items-center">
                            <UserCog size={20} className="mr-2 text-blue-600" />
                            รายชื่อผู้ใช้งานทั้งหมด ({filteredUsers.length})
                        </h3>
                        <div className="relative w-full sm:w-auto">
                            <input 
                                type="text" 
                                placeholder="ค้นหา..." 
                                className="w-full sm:w-64 pl-9 pr-4 py-1.5 bg-white text-slate-900 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                            <Search size={16} className="absolute left-3 top-2 text-slate-400" />
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-slate-600">
                            <thead className="bg-slate-50 border-b border-slate-200 text-xs uppercase text-slate-700">
                                <tr>
                                    <th className="px-4 py-3">ชื่อ-นามสกุล</th>
                                    <th className="px-4 py-3">Username</th>
                                    <th className="px-4 py-3">ฝ่าย/งาน</th>
                                    <th className="px-4 py-3 text-center">สิทธิ์</th>
                                    <th className="px-4 py-3 text-center">สถานะ</th>
                                    <th className="px-4 py-3 text-center">จัดการ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredUsers.map(user => (
                                    <tr key={user.id} className={`border-b border-slate-100 hover:bg-slate-50 transition-colors ${!user.isActive ? 'bg-slate-50 opacity-60' : ''}`}>
                                        <td className="px-4 py-3 font-medium text-slate-900 flex items-center">
                                            <div className={`w-8 h-8 rounded-full flex items-center justify-center mr-3 font-bold ${user.isActive ? 'bg-slate-200 text-slate-500' : 'bg-red-100 text-red-500'}`}>
                                                {user.name.charAt(0)}
                                            </div>
                                            {user.name}
                                            {user.id === currentUser?.id && <span className="ml-2 text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full">คุณ</span>}
                                        </td>
                                        <td className="px-4 py-3">{user.username}</td>
                                        <td className="px-4 py-3">
                                            <div className="flex items-center text-slate-500">
                                                <Building size={14} className="mr-1.5 text-slate-400"/>
                                                {getDeptName(user.departmentId)}
                                            </div>
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            <button 
                                                onClick={() => toggleRole(user.id, user.role)}
                                                disabled={user.id === currentUser?.id || !user.isActive}
                                                className={`px-3 py-1 rounded-full text-xs font-semibold border ${
                                                    user.role === 'ADMIN' 
                                                    ? 'bg-purple-100 text-purple-700 border-purple-200 hover:bg-purple-200' 
                                                    : 'bg-slate-100 text-slate-600 border-slate-200 hover:bg-slate-200'
                                                } transition-colors ${user.id === currentUser?.id || !user.isActive ? 'cursor-default opacity-80' : 'cursor-pointer'}`}
                                            >
                                                {user.role}
                                            </button>
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${user.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {user.isActive ? 'ACTIVE' : 'INACTIVE'}
                                            </span>
                                        </td>
                                        <td className="px-4 py-3 text-center">
                                            <div className="flex items-center justify-center space-x-2">
                                                <button 
                                                    onClick={() => openEditModal(user)}
                                                    className="p-1.5 hover:bg-blue-100 text-blue-600 rounded transition-colors"
                                                    title="แก้ไขข้อมูล"
                                                >
                                                    <Edit size={16} />
                                                </button>
                                                {user.id !== currentUser?.id && (
                                                    <button 
                                                        onClick={() => toggleStatus(user)}
                                                        className={`p-1.5 rounded transition-colors ${user.isActive ? 'hover:bg-red-50 text-red-500' : 'hover:bg-green-50 text-green-600'}`}
                                                        title={user.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                    >
                                                        {user.isActive ? <PowerOff size={16} /> : <Power size={16} />}
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Add User Box */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 h-fit">
                    <h3 className="font-semibold text-slate-800 mb-4 flex items-center">
                        <UserIcon size={20} className="mr-2 text-green-600" />
                        เพิ่มผู้ใช้งานใหม่
                    </h3>
                    <form onSubmit={handleAddUser} className="space-y-4">
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">ชื่อ-นามสกุล</label>
                            <input 
                                required
                                type="text"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newName}
                                onChange={e => setNewName(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">Username</label>
                            <input 
                                required
                                type="text"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newUsername}
                                onChange={e => setNewUsername(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">Password</label>
                            <input 
                                required
                                type="password"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newPassword}
                                onChange={e => setNewPassword(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">ฝ่าย/งาน</label>
                            <select 
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newDeptId}
                                onChange={e => setNewDeptId(e.target.value)}
                            >
                                <option value="">-- ไม่ระบุ --</option>
                                {settings.departments?.map(d => (
                                    <option key={d.id} value={d.id}>{d.name}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">สิทธิ์การใช้งาน</label>
                            <select 
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newRole}
                                onChange={e => setNewRole(e.target.value as UserRole)}
                            >
                                <option value="USER">USER (ทั่วไป)</option>
                                <option value="ADMIN">ADMIN (ผู้ดูแลระบบ)</option>
                            </select>
                        </div>
                        <button 
                            type="submit" 
                            className="w-full py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm font-semibold transition-colors shadow-sm"
                        >
                            บันทึก
                        </button>
                    </form>
                </div>
            </div>

            {/* Edit User Modal */}
            {editingUser && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in relative">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                            <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                <Edit size={20} className="mr-2 text-blue-600" />
                                แก้ไขข้อมูลผู้ใช้งาน
                            </h3>
                            <button onClick={() => setEditingUser(null)} className="text-slate-400 hover:text-slate-600">
                                <X size={24} />
                            </button>
                        </div>
                        <form onSubmit={handleUpdateUserSubmit} className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">ชื่อ-นามสกุล</label>
                                <div className="relative">
                                    <input 
                                        required
                                        type="text"
                                        className="w-full pl-10 pr-4 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                        value={editFormData.name}
                                        onChange={e => setEditFormData({...editFormData, name: e.target.value})}
                                    />
                                    <UserIcon size={18} className="absolute left-3 top-2.5 text-slate-400" />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">
                                    Username <span className="text-xs text-red-400 font-normal">(แก้ไขไม่ได้)</span>
                                </label>
                                <div className="relative">
                                    <input 
                                        type="text"
                                        disabled
                                        className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg bg-slate-100 text-slate-500 cursor-not-allowed outline-none"
