                                            editFormData.role === 'USER' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                                        }`}
                                    >
                                        USER
                                    </button>
                                    <button
                                        type="button"
                                        onClick={() => setEditFormData({...editFormData, role: 'ADMIN'})}
                                        className={`flex-1 py-1.5 px-3 rounded-md text-sm font-medium transition-all ${
                                            editFormData.role === 'ADMIN' ? 'bg-white text-purple-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                                        }`}
