                                    <span className={`px-4 py-1.5 rounded-lg text-xs font-medium border transition-all ${newIsActive ? 'bg-green-600 text-white border-green-600 shadow-sm' : 'bg-white text-slate-400 border-slate-200'}`}>Active</span>
