                <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                        <h3 className="font-semibold text-slate-800 flex items-center">
                            <UserCog size={20} className="mr-2 text-blue-600" />
                            รายชื่อผู้ใช้งานทั้งหมด ({activeOrSuspendedUsers.length})
                        </h3>
                        <div className="relative w-full sm:w-auto">
                            <input 
                                type="text" 
                                placeholder="ค้นหา..." 
                                className="w-full sm:w-64 pl-9 pr-4 py-1.5 bg-white text-slate-900 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                            <Search size={16} className="absolute left-3 top-2 text-slate-400" />
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-slate-600">
                            <thead className="bg-slate-50 border-b border-slate-200 text-xs uppercase text-slate-700">
                                <tr>
                                    <th className="px-4 py-3 whitespace-nowrap">ชื่อ-นามสกุล</th>
                                    <th className="px-4 py-3 whitespace-nowrap">Username</th>
                                    <th className="px-4 py-3 whitespace-nowrap">ฝ่าย/งาน</th>
                                    <th className="px-4 py-3 text-center whitespace-nowrap">สิทธิ์</th>
                                    <th className="px-4 py-3 text-center whitespace-nowrap">สถานะ</th>
                                    <th className="px-4 py-3 text-center whitespace-nowrap">จัดการ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {activeOrSuspendedUsers.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูลผู้ใช้งาน</td>
                                    </tr>
                                ) : (
                                    activeOrSuspendedUsers.map(user => (
                                        <tr key={user.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                                            <td className="px-4 py-3 font-medium text-slate-900 flex items-center">
                                                <div className="w-8 h-8 rounded-full flex items-center justify-center mr-3 font-bold bg-slate-200 text-slate-500">
                                                    {user.name.charAt(0)}
                                                </div>
                                                <div className="flex flex-col">
                                                    <span>{user.name}</span>
                                                    {user.id === currentUser?.id && <span className="text-[10px] text-green-600 font-bold uppercase tracking-wider">บัญชีของคุณ</span>}
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-slate-900">{user.username}</td>
                                            <td className="px-4 py-3">
                                                <div className="flex items-center text-slate-900">
                                                    <Building size={14} className="mr-1.5 text-slate-400"/>
                                                    {getDeptName(user.departmentId)}
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <button 
                                                    onClick={() => toggleRole(user.id, user.role)}
                                                    disabled={user.id === currentUser?.id}
                                                    className={`px-3 py-1 rounded-full text-xs font-semibold border ${
                                                        user.role === 'ADMIN' 
                                                        ? 'bg-purple-100 text-purple-700 border-purple-200 hover:bg-purple-200' 
                                                        : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-100'
                                                    } transition-colors ${user.id === currentUser?.id ? 'cursor-default opacity-80' : 'cursor-pointer'}`}
                                                >
                                                    {user.role}
                                                </button>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${user.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700 border border-red-200'}`}>
                                                    {user.isActive ? 'ACTIVE' : 'SUSPENDED'}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <div className="flex items-center justify-center space-x-2">
                                                    <button 
                                                        onClick={() => openEditModal(user)}
                                                        className="p-1.5 hover:bg-blue-100 text-blue-600 rounded transition-colors"
                                                        title="แก้ไขข้อมูล"
                                                    >
                                                        <Edit size={16} />
                                                    </button>
                                                    {user.id !== currentUser?.id && (
                                                        <button 
                                                            onClick={() => toggleStatus(user)}
                                                            className={`p-1.5 rounded transition-all transform active:scale-90 ${user.isActive ? 'hover:bg-red-50 text-red-500' : 'hover:bg-green-50 text-green-600'}`}
                                                            title={user.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                        >
                                                            {user.isActive ? <PowerOff size={16} /> : <Power size={16} />}
                                                        </button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Add User Box (Admin creation) */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 h-fit relative overflow-hidden">
