    }
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole, Department, ProcurementCategory, UserStatus } from '../types';

interface AppContextType {
    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth & Users
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => { success: boolean, message?: string };
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => boolean;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>) => void;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    upsertReceiving: (requestId: string, number: string, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    upsertConsideration: (requestId: string, number: string, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper keys for LocalStorage
const STORAGE_KEYS = {
    USERS: 'procurement_users',
    PROCUREMENTS: 'procurement_data',
    RECEIVINGS: 'procurement_receivings',
    CONSIDERATIONS: 'procurement_considerations',
    SETTINGS: 'procurement_settings',
    CURRENT_USER: 'procurement_current_user_session' // Optional: mainly for keeping login state (security warning: not secure for real prod)
};

// Helper to load data or return default
const loadFromStorage = <T,>(key: string, defaultValue: T): T => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : defaultValue;
    } catch (e) {
        console.error(`Error loading ${key} from storage`, e);
        return defaultValue;
    }
};

