        await query(
            'INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, created_by, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
            [p.id, p.requestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, p.officialNumber, p.type, p.createdBy, p.createdAt]
        );
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

app.patch('/api/procurements/:id', async (req, res) => {
    const id = req.params.id;
    const p = req.body;
    try {
        let sql = "UPDATE procurements SET ";
        const fields = [];
        const params = [];
        const map = {
            requestId: 'request_id', requestDate: 'request_date', category: 'category',
            itemCount: 'item_count', amount: 'amount', company: 'company', remarks: 'remarks',
            officialNumber: 'official_number'
        };

        for (const [key, dbCol] of Object.entries(map)) {
            if (p[key] !== undefined) {
                fields.push(`${dbCol} = ?`);
                params.push(p[key]);
            }
        }

        if (fields.length > 0) {
            sql += fields.join(', ') + " WHERE id = ?";
            params.push(id);
            await query(sql, params);
        }
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

