app.post('/api/considerations', async (req, res) => {
    const c = req.body;
    try {
        const exists = await query('SELECT id FROM considerations WHERE request_id = ?', [c.requestId]);
        if (exists.length > 0) {
            await query('UPDATE considerations SET consideration_number = ?, consideration_date = ? WHERE request_id = ?', 
                [c.considerationNumber, c.considerationDate, c.requestId]);
        } else {
            await query('INSERT INTO considerations (id, request_id, consideration_number, consideration_date) VALUES (?, ?, ?, ?)',
                [c.id, c.requestId, c.considerationNumber, c.considerationDate]);
        }
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/receivings/upsert', async (req, res) => {
    const r = req.body;
    try {
        const exists = await query('SELECT id FROM receivings WHERE request_id = ?', [r.requestId]);
        if (exists.length > 0) {
            await query('UPDATE receivings SET delivery_note_no = ?, receive_date = ? WHERE request_id = ?', 
                [r.deliveryNoteNo, r.receiveDate, r.requestId]);
        } else {
             const id = Math.random().toString(36).substr(2, 9);
             await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?, ?, ?, ?, ?, ?)',
                [id, r.requestId, r.deliveryNoteNo, r.receiveDate, r.category || '', Date.now()]);
        }
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

