                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                <input 
                                    type="text" 
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-green-500 outline-none bg-slate-50"
