                const newDept: Department = {
                    id: `dept_${Date.now()}`,
                    name: newDeptName.trim(),
                    isActive: true
                };
                const updatedDepts = [...(localSettings.departments || []), newDept];
                const newSettings = { ...localSettings, departments: updatedDepts };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setNewDeptName('');
                setConfirmAction(null);
