                                    value={localSettings.requestIdPrefix}
                                    onChange={e => setLocalSettings({...localSettings, requestIdPrefix: e.target.value})}
                                    placeholder="เช่น สพ.๐๐๓๓.๐๒/"
                                />
                                <button 
                                    type="submit" 
                                    className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg shadow-sm transition-all"
                                >
