                            <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-start animate-shake">
                                <AlertCircle size={16} className="mr-2 flex-shrink-0 mt-0.5" />
                                <span>{error}</span>
                            </div>
                        )}
                        {success && (
                            <div className="bg-emerald-50 text-emerald-700 p-4 rounded-lg text-sm flex items-start animate-fade-in border border-emerald-100">
                                <CheckCircle size={18} className="mr-2 flex-shrink-0 mt-0.5" />
                                <span>{success}</span>
                            </div>
                        )}

                        {isRegistering && (
                            <>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1">ชื่อ-นามสกุล</label>
                                    <div className="relative">
                                        <input 
                                            type="text"
                                            required
                                            className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white text-slate-900"
                                            placeholder="เช่น สมชาย ใจดี"
                                            value={name}
                                            onChange={e => setName(e.target.value)}
                                        />
                                        <div className="absolute left-3 top-2.5 text-slate-400">
                                            <User size={18} />
                                        </div>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1">อีเมล</label>
                                    <div className="relative">
                                        <input 
                                            type="email"
                                            required
                                            className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white text-slate-900"
                                            placeholder="email@example.com"
                                            value={email}
                                            onChange={e => setEmail(e.target.value)}
                                        />
                                        <div className="absolute left-3 top-2.5 text-slate-400">
                                            <Mail size={18} />
                                        </div>
                                    </div>
                                </div>
