                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">ชื่อผู้ใช้งาน</label>
                            <div className="relative">
                                <input 
                                    type="text"
                                    required
                                    className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white text-slate-900"
                                    placeholder="Username"
                                    value={username}
                                    onChange={e => setUsername(e.target.value)}
                                />
                                <div className="absolute left-3 top-2.5 text-slate-400">
                                    <User size={18} />
                                </div>
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">รหัสผ่าน</label>
                            <div className="relative">
                                <input 
                                    type="password"
                                    required
                                    className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white text-slate-900"
                                    placeholder="••••••••"
                                    value={password}
                                    onChange={e => setPassword(e.target.value)}
                                />
                                <div className="absolute left-3 top-2.5 text-slate-400">
                                    <Lock size={18} />
                                </div>
                            </div>
                        </div>

                        {isRegistering && (
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">ฝ่าย/งาน (ถ้ามี)</label>
                                <div className="relative">
                                    <select 
                                        className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none transition-all appearance-none bg-white text-slate-900"
                                        value={deptId}
                                        onChange={e => setDeptId(e.target.value)}
                                    >
                                        <option value="">-- ไม่ระบุ --</option>
                                        {settings.departments?.map(d => (
                                            <option key={d.id} value={d.id}>{d.name}</option>
                                        ))}
                                    </select>
                                    <div className="absolute left-3 top-2.5 text-slate-400">
                                        <Building size={18} />
                                    </div>
                                </div>
                            </div>
                        )}

                        <button 
                            type="submit" 
                            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2.5 rounded-lg shadow-md transition-all flex items-center justify-center mt-2"
                        >
                            {isRegistering ? (
                                <>
                                    <UserPlus size={18} className="mr-2" /> สมัครสมาชิก
                                </>
                            ) : (
                                <>
                                    <LogIn size={18} className="mr-2" /> เข้าสู่ระบบ
                                </>
                            )}
                        </button>
                    </form>

                    <div className="mt-6 text-center">
                        <p className="text-sm text-slate-600">
                            {isRegistering ? 'มีบัญชีอยู่แล้ว?' : 'ยังไม่มีบัญชีผู้ใช้งาน?'}
                            <button 
                                onClick={() => {
                                    setIsRegistering(!isRegistering);
                                    setError('');
                                    setSuccess('');
                                    setUsername('');
                                    setPassword('');
                                    setName('');
                                    setEmail('');
                                    setDeptId('');
                                }}
                                className="ml-2 text-blue-600 font-semibold hover:underline outline-none"
                            >
                                {isRegistering ? 'เข้าสู่ระบบ' : 'สมัครสมาชิก'}
                            </button>
                        </p>
                    </div>
                </div>

                {/* Registration Confirmation Modal */}
                {showRegisterConfirm && (
                    <div className="absolute inset-0 z-50 flex items-center justify-center p-6 bg-white/95 backdrop-blur-md animate-fade-in">
                        <div className="text-center w-full max-w-sm">
                            <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-blue-50 mb-6 text-blue-600">
                                <HelpCircle size={32} />
                            </div>
                            <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการสมัครสมาชิก?</h3>
                            <div className="bg-slate-50 rounded-xl p-4 mb-6 text-left border border-slate-100">
                                <p className="text-xs text-slate-400 uppercase font-semibold mb-1">ชื่อผู้ใช้งาน</p>
                                <p className="text-sm font-bold text-slate-700 mb-3">{username}</p>
                                <p className="text-xs text-slate-400 uppercase font-semibold mb-1">ชื่อ-นามสกุล</p>
                                <p className="text-sm font-bold text-slate-700 mb-3">{name}</p>
                                <p className="text-xs text-slate-400 uppercase font-semibold mb-1">อีเมล</p>
                                <p className="text-sm font-bold text-slate-700">{email}</p>
                            </div>
                            <p className="text-xs text-slate-500 mb-8 px-4 leading-relaxed">
                                เมื่อสมัครสมาชิกแล้ว คุณจะยังไม่สามารถเข้าสู่ระบบได้ทันที 
                                <span className="font-bold text-orange-600 block mt-1 underline">ต้องรอผู้ดูแลระบบอนุมัติการใช้งานก่อน</span>
                            </p>
                            <div className="flex space-x-3">
                                <button 
                                    onClick={() => setShowRegisterConfirm(false)}
                                    className="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-bold transition-all"
                                >
                                    กลับไปแก้ไข
