import React, { useState } from 'react';
import { useApp } from '../services/store';
import { UserCog, User as UserIcon, Search, Edit, X, Check, Lock, Building, Power, PowerOff, AlertCircle, Trash2, RefreshCcw, Mail } from 'lucide-react';
import { UserRole, User, UserStatus } from '../types';

const UserManagementPage: React.FC = () => {
    const { users, currentUser, updateUser, registerUser, settings, deleteUser } = useApp();
    const [searchTerm, setSearchTerm] = useState('');

    // Add User Form State
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [newName, setNewName] = useState('');
    const [newEmail, setNewEmail] = useState(''); // Added email state
    const [newRole, setNewRole] = useState<UserRole>('USER');
    const [newDeptId, setNewDeptId] = useState('');
    const [showAddConfirm, setShowAddConfirm] = useState(false);

    // Confirmation State for Soft Delete/Suspend
    const [suspendConfirm, setSuspendConfirm] = useState<{ id: string, name: string } | null>(null);

    // Edit User State
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [showEditConfirm, setShowEditConfirm] = useState(false);
    const [editFormData, setEditFormData] = useState({
        name: '',
        email: '',
        username: '',
        password: '',
        role: 'USER' as UserRole,
        departmentId: ''
    });

    // Shows Active and Suspended users. Pending are in their own page.
    const activeOrSuspendedUsers = users.filter(u => 
        u.status !== 'PENDING' && (
            u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
            u.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
            (u.email && u.email.toLowerCase().includes(searchTerm.toLowerCase()))
        )
    );

    const handleAddUserRequest = (e: React.FormEvent) => {
        e.preventDefault();
        setShowAddConfirm(true);
    };

    const confirmAddUser = () => {
        const success = registerUser({
            username: newUsername,
            password: newPassword,
            name: newName,
            email: newEmail,
            role: newRole,
            departmentId: newDeptId || undefined,
            status: 'ACTIVE' // Admin creation defaults to active
        });

        if (success) {
            setNewUsername('');
            setNewPassword('');
            setNewName('');
            setNewEmail('');
            setNewRole('USER');
            setNewDeptId('');
            setShowAddConfirm(false);
        } else {
            alert('Username นี้มีผู้ใช้งานแล้ว');
            setShowAddConfirm(false);
        }
    };

    const openEditModal = (user: User) => {
        setEditingUser(user);
        setEditFormData({
            name: user.name,
            email: user.email || '',
            username: user.username,
            password: '', 
            role: user.role,
            departmentId: user.departmentId || ''
        });
    };

    const handleUpdateUserSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowEditConfirm(true);
    };

    const confirmUpdateUser = () => {
        if (!editingUser) return;

        const updates: Partial<User> = {
            name: editFormData.name,
            email: editFormData.email,
            role: editFormData.role,
            departmentId: editFormData.departmentId || undefined
        };

        if (editFormData.password.trim()) {
            updates.password = editFormData.password;
        }

        updateUser(editingUser.id, updates);
        setEditingUser(null);
        setShowEditConfirm(false);
    };

    const handleSoftDelete = (user: User) => {
        if (user.id === currentUser?.id) return;
        setSuspendConfirm({ id: user.id, name: user.name });
    };

    const confirmSuspend = () => {
        if (suspendConfirm) {
            deleteUser(suspendConfirm.id); // deleteUser is implemented as soft delete (status: SUSPENDED)
            setSuspendConfirm(null);
        }
    };

    const toggleStatus = (user: User) => {
        if (user.id === currentUser?.id) return;
        const nextStatus: UserStatus = user.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE';
        updateUser(user.id, { status: nextStatus });
    };

    const toggleRole = (id: string, currentRole: UserRole) => {
        if (id === currentUser?.id) return;
        const newRole = currentRole === 'ADMIN' ? 'USER' : 'ADMIN';
        updateUser(id, { role: newRole });
    };

    const getDeptName = (deptId?: string) => {
        if (!deptId) return '-';
        return settings.departments?.find(d => d.id === deptId)?.name || '-';
    };

    return (
        <div className="p-6 pb-20">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">จัดการผู้ใช้งาน (User Management)</h2>

            {/* Stats & Tools */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
                <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col">
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                        <h3 className="font-semibold text-slate-800 flex items-center">
                            <UserCog size={20} className="mr-2 text-blue-600" />
                            รายชื่อผู้ใช้งานทั้งหมด ({activeOrSuspendedUsers.length})
                        </h3>
                        <div className="relative w-full sm:w-auto">
                            <input 
                                type="text" 
                                placeholder="ค้นหาชื่อ, username, email..." 
                                className="w-full sm:w-64 pl-9 pr-4 py-1.5 bg-white text-slate-900 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                            <Search size={16} className="absolute left-3 top-2 text-slate-400" />
                        </div>
                    </div>

                    <div className="overflow-x-auto flex-1">
                        <table className="w-full text-sm text-left text-slate-600">
                            <thead className="bg-slate-50 border-b border-slate-200 text-xs uppercase text-slate-700">
                                <tr>
                                    <th className="px-4 py-3 whitespace-nowrap">ชื่อ-นามสกุล</th>
                                    <th className="px-4 py-3 whitespace-nowrap">ติดต่อ</th>
                                    <th className="px-4 py-3 whitespace-nowrap">ฝ่าย/งาน</th>
                                    <th className="px-4 py-3 text-center whitespace-nowrap">สิทธิ์</th>
                                    <th className="px-4 py-3 text-center whitespace-nowrap">สถานะ</th>
                                    <th className="px-4 py-3 text-center whitespace-nowrap">จัดการ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {activeOrSuspendedUsers.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูลผู้ใช้งาน</td>
                                    </tr>
                                ) : (
                                    activeOrSuspendedUsers.map(user => (
                                        <tr key={user.id} className={`border-b border-slate-100 hover:bg-slate-50 transition-colors ${user.status === 'SUSPENDED' ? 'bg-slate-50/50 grayscale-[0.5]' : ''}`}>
                                            <td className="px-4 py-3 font-medium text-slate-900 flex items-center">
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center mr-3 font-bold ${user.status === 'ACTIVE' ? 'bg-blue-100 text-blue-600' : 'bg-slate-200 text-slate-500'}`}>
                                                    {user.name.charAt(0)}
                                                </div>
                                                <div className="flex flex-col">
                                                    <span className={user.status === 'SUSPENDED' ? 'text-slate-400' : ''}>{user.name}</span>
                                                    {user.id === currentUser?.id && <span className="text-[10px] text-green-600 font-bold uppercase tracking-wider">บัญชีของคุณ</span>}
                                                </div>
                                            </td>
                                            <td className={`px-4 py-3 ${user.status === 'SUSPENDED' ? 'text-slate-400' : 'text-slate-900'}`}>
                                                <div className="flex flex-col">
                                                    <span className="text-xs font-semibold">{user.username}</span>
                                                    <span className="text-[10px] text-slate-500">{user.email}</span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3">
                                                <div className={`flex items-center ${user.status === 'SUSPENDED' ? 'text-slate-400' : 'text-slate-900'}`}>
                                                    <Building size={14} className="mr-1.5 opacity-40"/>
                                                    {getDeptName(user.departmentId)}
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <button 
                                                    onClick={() => toggleRole(user.id, user.role)}
                                                    disabled={user.id === currentUser?.id || user.status === 'SUSPENDED'}
                                                    className={`px-3 py-1 rounded-full text-xs font-semibold border transition-all ${
                                                        user.status === 'SUSPENDED' ? 'bg-slate-100 text-slate-300 border-slate-100 cursor-not-allowed' :
                                                        user.role === 'ADMIN' 
                                                        ? 'bg-purple-100 text-purple-700 border-purple-200 hover:bg-purple-200' 
                                                        : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-100'
                                                    } ${user.id === currentUser?.id ? 'cursor-default opacity-80' : ''}`}
                                                >
                                                    {user.role}
                                                </button>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${user.status === 'ACTIVE' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700 border border-red-200'}`}>
                                                    {user.status === 'ACTIVE' ? 'ACTIVE' : 'SUSPENDED'}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3 text-center">
                                                <div className="flex items-center justify-center space-x-1">
                                                    <button 
                                                        onClick={() => openEditModal(user)}
                                                        className="p-1.5 hover:bg-blue-100 text-blue-600 rounded transition-colors"
                                                        title="แก้ไขข้อมูล"
                                                        disabled={user.status === 'SUSPENDED'}
                                                    >
                                                        <Edit size={16} />
                                                    </button>
                                                    {user.id !== currentUser?.id && (
                                                        <>
                                                            {user.status === 'ACTIVE' ? (
                                                                <button 
                                                                    onClick={() => handleSoftDelete(user)}
                                                                    className="p-1.5 hover:bg-red-50 text-red-500 rounded transition-all"
                                                                    title="ลบ (ระงับการใช้งาน)"
                                                                >
                                                                    <Trash2 size={16} />
                                                                </button>
                                                            ) : (
                                                                <button 
                                                                    onClick={() => toggleStatus(user)}
                                                                    className="p-1.5 hover:bg-emerald-50 text-emerald-600 rounded transition-all"
                                                                    title="เปิดใช้งานใหม่"
                                                                >
                                                                    <RefreshCcw size={16} />
                                                                </button>
                                                            )}
                                                        </>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Add User Box */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 h-fit relative overflow-hidden">
                    <h3 className="font-semibold text-slate-800 mb-4 flex items-center">
                        <UserIcon size={20} className="mr-2 text-green-600" />
                        เพิ่มผู้ใช้งานใหม่
                    </h3>
                    <p className="text-xs text-slate-400 mb-4">กรณีแอดมินสร้างให้เอง ระบบจะเปิดใช้งานให้อัตโนมัติ</p>
                    <form onSubmit={handleAddUserRequest} className="space-y-4">
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">ชื่อ-นามสกุล</label>
                            <input 
                                required
                                type="text"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newName}
                                onChange={e => setNewName(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">อีเมล</label>
                            <input 
                                required
                                type="email"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newEmail}
                                onChange={e => setNewEmail(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">Username</label>
                            <input 
                                required
                                type="text"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newUsername}
                                onChange={e => setNewUsername(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">Password</label>
                            <input 
                                required
                                type="password"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newPassword}
                                onChange={e => setNewPassword(e.target.value)}
                            />
