const PendingUsersPage: React.FC = () => {
    const { users, updateUser, settings } = useApp();
    const [confirmAction, setConfirmAction] = useState<{ id: string, name: string, email: string, type: 'APPROVE' | 'REJECT' } | null>(null);

    const pendingUsers = users.filter(u => u.status === 'PENDING');

    const handleApprove = (id: string, email: string) => {
        updateUser(id, { status: 'ACTIVE' });
        // Simulation of Email Sending
        alert(`ระบบได้ทำการส่งอีเมลแจ้งผลการอนุมัติไปยัง ${email} เรียบร้อยแล้ว`);
        setConfirmAction(null);
    };

    const handleReject = (id: string) => {
        // Rejecting a new application: Mark as Suspended so they don't stay in pending list
        updateUser(id, { status: 'SUSPENDED' });
        setConfirmAction(null);
    };

    const getDeptName = (deptId?: string) => {
        if (!deptId) return 'ไม่ระบุ';
        return settings.departments?.find(d => d.id === deptId)?.name || 'ไม่ระบุ';
    };

    return (
        <div className="p-6">
