app.patch('/api/users/:id', async (req, res) => {
    const id = req.params.id;
    const data = req.body;

    const fields = [];
    const params = [];

    if (data.name) { fields.push('name = ?'); params.push(data.name); }
    if (data.email) { fields.push('email = ?'); params.push(data.email); }
    if (data.role) { fields.push('role = ?'); params.push(data.role); }
    if (data.departmentId !== undefined) { fields.push('department_id = ?'); params.push(data.departmentId); }
    if (data.status) { fields.push('status = ?'); params.push(data.status); }
    if (data.password) { fields.push('password = ?'); params.push(data.password); }

    if (fields.length === 0) return res.json({ success: true });

    let sql = 'UPDATE users SET ' + fields.join(', ') + ' WHERE id = ?';
    params.push(id);

    try {
        await query(sql, params);
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// 2. Data Fetching
app.get('/api/data', async (req, res) => {
    try {
        const procurements = await query('SELECT * FROM procurements');
        const receivings = await query('SELECT * FROM receivings');
        const considerations = await query('SELECT * FROM considerations');
        const departments = await query('SELECT * FROM departments');
        const categories = await query('SELECT * FROM procurement_categories');

        const mappedProcurements = procurements.map(p => ({
            id: p.id, requestId: p.request_id, requestDate: p.request_date, category: p.category,
            itemCount: p.item_count, amount: parseFloat(p.amount), company: p.company, remarks: p.remarks,
            officialNumber: p.official_number, type: p.type, createdBy: p.created_by, createdAt: p.created_at
        }));

        const mappedReceivings = receivings.map(r => ({
            id: r.id, requestId: r.request_id, deliveryNoteNo: r.delivery_note_no,
            receiveDate: r.receive_date, category: r.category, createdAt: r.created_at
        }));

        const mappedConsiderations = considerations.map(c => ({
            id: c.id, requestId: c.request_id, considerationNumber: c.consideration_number,
            considerationDate: c.consideration_date
        }));

        const mappedDepartments = departments.map(d => ({
