import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole, Department, ProcurementCategory, UserStatus } from '../types';

// ==========================================
// ตั้งค่าการเชื่อมต่อ Server (Backend)
// ==========================================
const BACKEND_PORT = 3002; // <-- เชื่อมต่อ Backend ที่ Port 3002

const getApiUrl = () => {
    // กรณีรันบน Server (SSR)
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api`;

    // กรณีรันบน Browser:
    let hostname = window.location.hostname;

    // ถ้าหา Hostname ไม่เจอ ให้ใช้ localhost
    if (!hostname || hostname.trim() === '') {
        hostname = 'localhost';
    }

    return `http://${hostname}:${BACKEND_PORT}/api`;
};

const API_URL = getApiUrl();
console.log(`🔌 Connecting to Backend API at: ${API_URL}`);

interface AppContextType {
    // State
    isLoading: boolean;
    serverError: boolean;
    retryConnection: () => void;

    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth & Users
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>) => void;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    upsertReceiving: (requestId: string, number: string, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    upsertConsideration: (requestId: string, number: string, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);

    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: []
    });

    // --- Data Loading ---
    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            // Fetch Users
            const userRes = await fetch(`${API_URL}/users`);
            if (!userRes.ok) throw new Error(`Server returned ${userRes.status}`);
            const userData = await userRes.json();
            setUsers(userData);

            // Fetch Business Data
            const dataRes = await fetch(`${API_URL}/data`);
            if (!dataRes.ok) throw new Error(`Server returned ${dataRes.status}`);
            const data = await dataRes.json();

            setProcurements(data.procurements);
            setReceivings(data.receivings);
            setConsiderations(data.considerations);
            setSettings(prev => ({
                ...prev,
                departments: data.settings.departments,
                categories: data.settings.categories
            }));

        } catch (error) {
            console.error("Failed to fetch data. Is the backend running on port " + BACKEND_PORT + "?", error);
            setServerError(true);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        // Restore session if needed
        const savedUser = localStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => {
        fetchData();
    };

    // --- Auth Functions ---
    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: u, password: p })
            });
            if (!res.ok) throw new Error("Server error");
            const result = await res.json();

            if (result.success) {
                setCurrentUser(result.user);
                localStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e) {
            return { success: false, message: "เชื่อมต่อเซิร์ฟเวอร์ไม่ได้ (Failed to fetch)" };
        }
    };

    const logout = () => {
        setCurrentUser(null);
        localStorage.removeItem('procurement_session_user');
    };

    const registerUser = async (userData: Omit<User, 'id' | 'createdAt'>) => {
        try {
            const newUser = {
                ...userData,
                id: Math.random().toString(36).substr(2, 9),
            };
            await fetch(`${API_URL}/register`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newUser)
            });
            fetchData(); // Refresh users list
            return true;
        } catch (e) {
            console.error(e);
            return false;
        }
    };

    const deleteUser = async (id: string) => {
        // Soft delete
        await updateUser(id, { status: 'SUSPENDED' });
    };

    const updateUser = async (id: string, data: Partial<User>) => {
        try {
            await fetch(`${API_URL}/users/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });
            setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
        } catch(e) { console.error(e); }
    };

    // --- Business Logic Helpers (Running Number) ---
    const getThaiYear = (dateString: string) => {
        const date = new Date(dateString);
        return date.getFullYear() + 543;
    };

    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        if (amount <= 5000) return null;
        const thaiYear = getThaiYear(dateStr);
        const existingInYear = procurements.filter(p => 
            p.type === type && 
            p.officialNumber && 
            getThaiYear(p.requestDate) === thaiYear
        );

        let maxNum = 0;
        existingInYear.forEach(p => {
            const parts = p.officialNumber?.split('/');
            if (parts && parts[0]) {
                const num = parseInt(parts[0]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });
        return `${maxNum + 1}/${thaiYear}`;
    };

    // --- Data Actions ---
    const addProcurement = async (data: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>) => {
        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);
        const newRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
            officialNumber,
            createdBy: currentUser?.id || 'unknown'
        };

        try {
            await fetch(`${API_URL}/procurements`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });
            setProcurements(prev => [...prev, newRecord as ProcurementRecord]);
        } catch(e) { console.error(e); }
    };

    const updateProcurement = async (id: string, data: Partial<ProcurementRecord>) => {
        // Calculate logic locally for responsiveness, then sync
        const currentItem = procurements.find(p => p.id === id);
        if (!currentItem) return;

        let newOfficialNumber = currentItem.officialNumber;
        const amount = data.amount !== undefined ? data.amount : currentItem.amount;
        const reqDate = data.requestDate || currentItem.requestDate;

        if (amount > 5000 && !newOfficialNumber) {
            newOfficialNumber = generateRunningNumber(currentItem.type, amount, reqDate);
        } else if (amount <= 5000) {
            newOfficialNumber = null;
        }

        const payload = { ...data, officialNumber: newOfficialNumber };

        try {
            await fetch(`${API_URL}/procurements/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            setProcurements(prev => prev.map(item => item.id !== id ? item : { ...item, ...payload }));
        } catch(e) { console.error(e); }
    };

    const deleteProcurement = async (id: string) => {
        try {
            await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
            setProcurements(prev => prev.filter(p => p.id !== id));
        } catch(e) { console.error(e); }
    };

    const addReceiving = async (data: Omit<ReceivingReport, 'id' | 'createdAt'>) => {
        const newRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
        };
        try {
            await fetch(`${API_URL}/receivings`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });
            setReceivings(prev => [...prev, newRecord as ReceivingReport]);
        } catch(e) { console.error(e); }
    };

    const deleteReceiving = async (id: string) => {
        try {
            await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' });
            setReceivings(prev => prev.filter(r => r.id !== id));
        } catch(e) { console.error(e); }
    };

    const addConsideration = async (record: ConsiderationRecord) => {
        const newRecord = { ...record, id: record.id || Math.random().toString(36).substr(2, 9) };
        try {
            await fetch(`${API_URL}/considerations`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });
            setConsiderations(prev => [...prev, newRecord]);
        } catch(e) { console.error(e); }
    };

    // Upsert Wrappers
    const upsertReceiving = async (requestId: string, number: string, date: string) => {
        const procurement = procurements.find(p => p.requestId === requestId);
        const category = procurement ? procurement.category : '';
        const payload = { requestId, deliveryNoteNo: number, receiveDate: date, category };

        try {
            await fetch(`${API_URL}/receivings/upsert`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            fetchData();
        } catch(e) { console.error(e); }
    };

    const upsertConsideration = async (requestId: string, number: string, date: string) => {
        const payload = { 
            id: Math.random().toString(36).substr(2, 9),
            requestId, 
            considerationNumber: number, 
            considerationDate: date 
        };
         try {
            await fetch(`${API_URL}/considerations`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            fetchData();
        } catch(e) { console.error(e); }
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = async (newSettings: Partial<AppSettings>) => {
        setSettings(prev => ({ ...prev, ...newSettings }));
    };

    return (
        <AppContext.Provider value={{
            isLoading,
            serverError,
            retryConnection,
            procurements,
            receivings,
            considerations,
            settings,
            currentUser,
            users,
            login,
            logout,
            registerUser,
            deleteUser,
            updateUser,
            addProcurement,
            updateProcurement,
            deleteProcurement,
            addReceiving,
            upsertReceiving,
            deleteReceiving,
            addConsideration,
            upsertConsideration,
            getLinkedData,
            updateSettings
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

import React, { useState } from 'react';
import { AppProvider, useApp } from './services/store';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import ProcurementTable from './pages/ProcurementTable';
import SettingsPage from './pages/SettingsPage';
import LoginPage from './pages/LoginPage';
import UserManagementPage from './pages/UserManagementPage';
import PendingUsersPage from './pages/PendingUsersPage';
import ReceivingPage from './pages/ReceivingPage';
import ConsiderationPage from './pages/ConsiderationPage';
import { RecordType } from './types';
import { Menu, ServerCrash, RefreshCw } from 'lucide-react';

const MainApp: React.FC = () => {
    const { currentUser, serverError, retryConnection, isLoading } = useApp();
    const [activeTab, setActiveTab] = useState('dashboard');
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    if (serverError) {
        return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-50 text-center p-6">
                <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-red-100">
                    <div className="mx-auto flex items-center justify-center h-20 w-20 rounded-full bg-red-100 mb-6 text-red-600 animate-pulse">
                        <ServerCrash size={40} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">ไม่สามารถเชื่อมต่อระบบได้</h2>
                    <p className="text-slate-500 mb-6">
                        กรุณาตรวจสอบว่าได้เปิดโปรแกรม Server (Backend) หรือไม่ <br/>
                        <code className="bg-slate-100 px-2 py-1 rounded text-xs mt-2 inline-block">Port: 3002</code>
                    </p>
                    <button 
                        onClick={retryConnection}
                        disabled={isLoading}
                        className="w-full flex items-center justify-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-semibold transition-all shadow-lg shadow-blue-200"
                    >
                        {isLoading ? (
                            <RefreshCw className="animate-spin" size={20} />
                        ) : (
                            <RefreshCw size={20} />
                        )}
                        <span>ลองเชื่อมต่อใหม่</span>
                    </button>
                </div>
            </div>
        );
    }

    if (!currentUser) {
        return <LoginPage />;
    }

    const renderContent = () => {
        switch (activeTab) {
            case 'dashboard':
                return <Dashboard />;
            case 'purchase':
                return <ProcurementTable type={RecordType.PURCHASE} title="ทะเบียนคุมจัดซื้อ (Purchase Orders)" />;
            case 'hiring':
                return <ProcurementTable type={RecordType.HIRING} title="ทะเบียนคุมจัดจ้าง (Hiring Orders)" />;
            case 'other':
                return <ProcurementTable type={RecordType.OTHER} title="ทะเบียนคุมอื่นๆ (Other Registry)" />;
            case 'receiving':
                return <ReceivingPage />;
            case 'consideration':
                return <ConsiderationPage />;
            case 'pending_users':
                return currentUser.role === 'ADMIN' ? <PendingUsersPage /> : <Dashboard />;
            case 'users':
                return currentUser.role === 'ADMIN' ? <UserManagementPage /> : <Dashboard />;
            case 'settings':
                return currentUser.role === 'ADMIN' ? <SettingsPage /> : <Dashboard />;
            default:
                return <Dashboard />;
        }
    };

    return (
        <div className="flex h-screen bg-slate-50 text-slate-900 font-sans relative">
            <Sidebar 
                activeTab={activeTab} 
                setActiveTab={setActiveTab} 
                isOpen={isSidebarOpen} 
                setIsOpen={setIsSidebarOpen}
            />

            <div className="flex-1 flex flex-col min-w-0 transition-all duration-300 lg:ml-64">
                {/* Mobile Header */}
                <header className="lg:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-40">
                    <button 
                        onClick={() => setIsSidebarOpen(true)}
                        className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg"
                    >
                        <Menu size={24} />
                    </button>
                    <h2 className="text-lg font-bold text-slate-800 truncate px-2">
                        {activeTab === 'dashboard' ? 'Dashboard' : 
                         activeTab === 'purchase' ? 'จัดซื้อ' : 
                         activeTab === 'hiring' ? 'จัดจ้าง' : 
                         activeTab === 'pending_users' ? 'รอยืนยัน' :
                         activeTab === 'other' ? 'อื่นๆ' : 'ระบบพัสดุ'}
                    </h2>
                    <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">
                        {currentUser.name.charAt(0)}
                    </div>
                </header>

                <main className="flex-1 overflow-y-auto">
                    {renderContent()}
                </main>
            </div>
        </div>
    );
};

const App: React.FC = () => {
    return (
        <AppProvider>
            <MainApp />
        </AppProvider>
    );
};

export default App;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole, Department, ProcurementCategory, UserStatus } from '../types';

// ==========================================
// ตั้งค่าการเชื่อมต่อ Server (Backend)
// ==========================================
const BACKEND_PORT = 3002; // <-- แก้ไขเป็น 3002 เพื่อให้ตรงกับ server/index.js

const getApiUrl = () => {
    // กรณีรันบน Server (SSR)
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api`;

    // กรณีรันบน Browser:
    let hostname = window.location.hostname;

    // ถ้าหา Hostname ไม่เจอ ให้ใช้ localhost
    if (!hostname || hostname.trim() === '') {
        hostname = 'localhost';
    }

    return `http://${hostname}:${BACKEND_PORT}/api`;
};

const API_URL = getApiUrl();
console.log(`🔌 Connecting to Backend API at: ${API_URL}`);

interface AppContextType {
    // State
    isLoading: boolean;
    serverError: boolean;
    retryConnection: () => void;

    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth & Users
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>) => void;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    upsertReceiving: (requestId: string, number: string, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    upsertConsideration: (requestId: string, number: string, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);

    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: []
    });

    // --- Data Loading ---
    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            // Fetch Users
            const userRes = await fetch(`${API_URL}/users`);
            if (!userRes.ok) throw new Error(`Server returned ${userRes.status}`);
            const userData = await userRes.json();
            setUsers(userData);

            // Fetch Business Data
            const dataRes = await fetch(`${API_URL}/data`);
            if (!dataRes.ok) throw new Error(`Server returned ${dataRes.status}`);
            const data = await dataRes.json();

            setProcurements(data.procurements);
            setReceivings(data.receivings);
            setConsiderations(data.considerations);
            setSettings(prev => ({
                ...prev,
                departments: data.settings.departments,
                categories: data.settings.categories
            }));

        } catch (error) {
            console.error("Failed to fetch data. Is the backend running on port " + BACKEND_PORT + "?", error);
            setServerError(true);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        // Restore session if needed
        const savedUser = localStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => {
        fetchData();
    };

    // --- Auth Functions ---
    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: u, password: p })
            });
            if (!res.ok) throw new Error("Server error");
            const result = await res.json();

            if (result.success) {
                setCurrentUser(result.user);
                localStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e) {
            return { success: false, message: "เชื่อมต่อเซิร์ฟเวอร์ไม่ได้ (Failed to fetch)" };
        }
    };

    const logout = () => {
        setCurrentUser(null);
        localStorage.removeItem('procurement_session_user');
    };

    const registerUser = async (userData: Omit<User, 'id' | 'createdAt'>) => {
        try {
            const newUser = {
                ...userData,
                id: Math.random().toString(36).substr(2, 9),
            };
            await fetch(`${API_URL}/register`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newUser)
            });
            fetchData(); // Refresh users list
            return true;
        } catch (e) {
            console.error(e);
            return false;
        }
    };

    const deleteUser = async (id: string) => {
        // Soft delete
        await updateUser(id, { status: 'SUSPENDED' });
    };

    const updateUser = async (id: string, data: Partial<User>) => {
        try {
            await fetch(`${API_URL}/users/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });
            setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
        } catch(e) { console.error(e); }
    };

    // --- Business Logic Helpers (Running Number) ---
    const getThaiYear = (dateString: string) => {
        const date = new Date(dateString);
        return date.getFullYear() + 543;
    };

    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        if (amount <= 5000) return null;
        const thaiYear = getThaiYear(dateStr);
        const existingInYear = procurements.filter(p => 
            p.type === type && 
            p.officialNumber && 
            getThaiYear(p.requestDate) === thaiYear
        );

        let maxNum = 0;
        existingInYear.forEach(p => {
            const parts = p.officialNumber?.split('/');
            if (parts && parts[0]) {
                const num = parseInt(parts[0]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });
        return `${maxNum + 1}/${thaiYear}`;
    };

    // --- Data Actions ---
    const addProcurement = async (data: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>) => {
        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);
        const newRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
            officialNumber,
            createdBy: currentUser?.id || 'unknown'
        };

        try {
            await fetch(`${API_URL}/procurements`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });
            setProcurements(prev => [...prev, newRecord as ProcurementRecord]);
        } catch(e) { console.error(e); }
    };

    const updateProcurement = async (id: string, data: Partial<ProcurementRecord>) => {
        // Calculate logic locally for responsiveness, then sync
        const currentItem = procurements.find(p => p.id === id);
        if (!currentItem) return;

        let newOfficialNumber = currentItem.officialNumber;
        const amount = data.amount !== undefined ? data.amount : currentItem.amount;
        const reqDate = data.requestDate || currentItem.requestDate;

        if (amount > 5000 && !newOfficialNumber) {
            newOfficialNumber = generateRunningNumber(currentItem.type, amount, reqDate);
        } else if (amount <= 5000) {
            newOfficialNumber = null;
        }

        const payload = { ...data, officialNumber: newOfficialNumber };

        try {
            await fetch(`${API_URL}/procurements/${id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            setProcurements(prev => prev.map(item => item.id !== id ? item : { ...item, ...payload }));
        } catch(e) { console.error(e); }
    };

    const deleteProcurement = async (id: string) => {
        try {
            await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
            setProcurements(prev => prev.filter(p => p.id !== id));
        } catch(e) { console.error(e); }
    };

    const addReceiving = async (data: Omit<ReceivingReport, 'id' | 'createdAt'>) => {
        const newRecord = {
            ...data,
            id: Math.random().toString(36).substr(2, 9),
            createdAt: Date.now(),
        };
        try {
            await fetch(`${API_URL}/receivings`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });
            setReceivings(prev => [...prev, newRecord as ReceivingReport]);
        } catch(e) { console.error(e); }
    };

    const deleteReceiving = async (id: string) => {
        try {
            await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' });
            setReceivings(prev => prev.filter(r => r.id !== id));
        } catch(e) { console.error(e); }
    };

    const addConsideration = async (record: ConsiderationRecord) => {
        const newRecord = { ...record, id: record.id || Math.random().toString(36).substr(2, 9) };
        try {
            await fetch(`${API_URL}/considerations`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newRecord)
            });
            setConsiderations(prev => [...prev, newRecord]);
        } catch(e) { console.error(e); }
    };

    // Upsert Wrappers
    const upsertReceiving = async (requestId: string, number: string, date: string) => {
        const procurement = procurements.find(p => p.requestId === requestId);
        const category = procurement ? procurement.category : '';
        const payload = { requestId, deliveryNoteNo: number, receiveDate: date, category };

        try {
            await fetch(`${API_URL}/receivings/upsert`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            fetchData();
        } catch(e) { console.error(e); }
    };

    const upsertConsideration = async (requestId: string, number: string, date: string) => {
        const payload = { 
            id: Math.random().toString(36).substr(2, 9),
            requestId, 
            considerationNumber: number, 
            considerationDate: date 
        };
         try {
            await fetch(`${API_URL}/considerations`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            fetchData();
        } catch(e) { console.error(e); }
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = async (newSettings: Partial<AppSettings>) => {
        setSettings(prev => ({ ...prev, ...newSettings }));
    };

    return (
        <AppContext.Provider value={{
            isLoading,
            serverError,
            retryConnection,
            procurements,
            receivings,
            considerations,
            settings,
            currentUser,
            users,
            login,
            logout,
            registerUser,
            deleteUser,
            updateUser,
            addProcurement,
            updateProcurement,
            deleteProcurement,
            addReceiving,
            upsertReceiving,
            deleteReceiving,
            addConsideration,
            upsertConsideration,
            getLinkedData,
            updateSettings
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
  }
})

const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
const port = 3001;

// Allow all CORS requests
app.use(cors());
app.use(bodyParser.json());

// ==========================================
// ส่วนตั้งค่าการเชื่อมต่อฐานข้อมูล
// ==========================================
const DB_CONFIG = {
    host: 'localhost',      // ใส่ IP ของ MySQL Server
    user: 'root',           // Username ของ MySQL
    password: '',           // Password ของ MySQL
    database: 'procurement_db', // ชื่อฐานข้อมูล
    port: 3306
};

// --- Database Connection ---
const db = mysql.createPool({
    ...DB_CONFIG,
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

// ตรวจสอบการเชื่อมต่อตอนเริ่มต้น
db.getConnection((err, connection) => {
    if (err) {
        console.error('❌ Error connecting to MySQL:', err.code, err.message);
        console.error('   Please check your IP, Username, Password in server/index.js');
    } else {
        console.log('✅ Connected to MySQL Server successfully!');
        connection.release();
    }
});

// Helper for Promisified Query
const query = (sql, params) => {
    return new Promise((resolve, reject) => {
        db.query(sql, params, (err, results) => {
            if (err) return reject(err);
            resolve(results);
        });
    });
};

// --- API Endpoints ---

// ✅ เพิ่มหน้าแรกสำหรับเช็คสถานะ Server
app.get('/', (req, res) => {
    res.send('<h1 style="color:green; font-family:sans-serif;">✅ Procurement API is running on Port ' + port + '!</h1><p>Database connection status: Check console logs.</p>');
});

// 1. Auth & Users
app.post('/api/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const users = await query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
        if (users.length > 0) {
            const u = users[0];
            const user = {
                id: u.id, username: u.username, name: u.name, email: u.email,
                role: u.role, departmentId: u.department_id, status: u.status, createdAt: u.created_at
            };

            if (user.status === 'PENDING') return res.json({ success: false, message: 'รอการอนุมัติ' });
            if (user.status === 'SUSPENDED') return res.json({ success: false, message: 'ถูกระงับการใช้งาน' });

            res.json({ success: true, user });
        } else {
            res.json({ success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' });
        }
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/register', async (req, res) => {
    const u = req.body;
    try {
        await query(
            'INSERT INTO users (id, username, password, name, email, role, department_id, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
            [u.id, u.username, u.password, u.name, u.email, u.role, u.departmentId, u.status, Date.now()]
        );
        res.json({ success: true });
    } catch (e) {
        res.status(500).json({ success: false, message: e.message });
    }
});

app.get('/api/users', async (req, res) => {
    try {
        const rows = await query('SELECT * FROM users');
        const users = rows.map(u => ({
            id: u.id, username: u.username, name: u.name, email: u.email,
            role: u.role, departmentId: u.department_id, status: u.status, createdAt: u.created_at
        }));
        res.json(users);
    } catch (e) { res.status(500).json([]); }
});

app.patch('/api/users/:id', async (req, res) => {
    const id = req.params.id;
    const data = req.body;

    const fields = [];
    const params = [];

    if (data.name) { fields.push('name = ?'); params.push(data.name); }
    if (data.email) { fields.push('email = ?'); params.push(data.email); }
    if (data.role) { fields.push('role = ?'); params.push(data.role); }
    if (data.departmentId !== undefined) { fields.push('department_id = ?'); params.push(data.departmentId); }
    if (data.status) { fields.push('status = ?'); params.push(data.status); }
    if (data.password) { fields.push('password = ?'); params.push(data.password); }

    if (fields.length === 0) return res.json({ success: true });

    let sql = 'UPDATE users SET ' + fields.join(', ') + ' WHERE id = ?';
    params.push(id);

    try {
        await query(sql, params);
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// 2. Data Fetching
app.get('/api/data', async (req, res) => {
    try {
        const procurements = await query('SELECT * FROM procurements');
        const receivings = await query('SELECT * FROM receivings');
        const considerations = await query('SELECT * FROM considerations');
        const departments = await query('SELECT * FROM departments');
        const categories = await query('SELECT * FROM procurement_categories');

        const mappedProcurements = procurements.map(p => ({
            id: p.id, requestId: p.request_id, requestDate: p.request_date, category: p.category,
            itemCount: p.item_count, amount: parseFloat(p.amount), company: p.company, remarks: p.remarks,
            officialNumber: p.official_number, type: p.type, createdBy: p.created_by, createdAt: p.created_at
        }));

        const mappedReceivings = receivings.map(r => ({
            id: r.id, requestId: r.request_id, deliveryNoteNo: r.delivery_note_no,
            receiveDate: r.receive_date, category: r.category, createdAt: r.created_at
        }));

        const mappedConsiderations = considerations.map(c => ({
            id: c.id, requestId: c.request_id, considerationNumber: c.consideration_number,
            considerationDate: c.consideration_date
        }));

        const mappedDepartments = departments.map(d => ({
            id: d.id, name: d.name, isActive: d.is_active === 1
        }));

        const mappedCategories = categories.map(c => ({
            id: c.id, name: c.name, departmentId: c.department_id, isActive: c.is_active === 1
        }));

        res.json({
            procurements: mappedProcurements,
            receivings: mappedReceivings,
            considerations: mappedConsiderations,
