                        <h3 className="text-lg font-bold mb-2">ยืนยันการลบ?</h3>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setDeleteId(null)} className="flex-1 py-2 bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-sm">ลบออก</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

export enum RecordType {
    PURCHASE = 'PURCHASE', // จัดซื้อ
    HIRING = 'HIRING',     // จัดจ้าง
    OTHER = 'OTHER',       // ทะเบียนคุมอื่นๆ
}

export interface ProcurementRecord {
    id: string;
    requestId: string; // เลขที่ใบขอ (Key link)
    requestDate: string; // วัน/เดือน/ปี
    category: string; // หมวดพัสดุ
    itemCount: number; // จำนวนรายการ
    amount: number; // จำนวนเงิน
    company: string; // บริษัท
    remarks: string; // หมายเหตุ

    // Auto-generated or Logic-based fields
    officialNumber: string | null; // เลขสั่งซื้อ/สั่งจ้าง (Run if > 5000)
    type: RecordType;
    departmentId?: string; // <-- New: Track which department owns this record

    // Ownership and Audit
    createdBy: string; // User ID who created this record
    createdAt: number;

    // Linked Data (from manual entry or separate linkage)
    considerationId?: string; // เลขพิจารณา
    considerationDate?: string; // วันที่พิจารณา
}

export interface ReceivingReport {
    id: string;
    receiveDate: string; // วัน/เดือน/ปีใบรับของ
    deliveryNoteNo: string; // เลขที่ใบส่งของ
    requestId: string; // เลขที่ใบขอ (Link to ProcurementRecord)
    category: string; // หมวดพัสดุ
    createdAt: number;
}

export interface ConsiderationRecord {
    id: string;
    requestId: string;
    considerationNumber: string;
    considerationDate: string;
}

export interface Department {
    id: string;
    name: string;
    prefix?: string; // <-- New: Department Prefix (e.g. "ทส.")
    isActive: boolean;
}

export interface ProcurementCategory {
    id: string;
    name: string;
    departmentId?: string; // Linked Department ID
    isActive: boolean;
}

export interface AppSettings {
    requestIdPrefix: string;
    categories: ProcurementCategory[];
    departments: Department[]; // List of available departments
}

// For Dashboard
export interface DashboardStat {
    totalPurchase: number;
    totalHiring: number;
    purchaseCount: number;
    hiringCount: number;
}

// --- Auth & Users ---
export type UserRole = 'ADMIN' | 'USER';
export type UserStatus = 'PENDING' | 'ACTIVE' | 'SUSPENDED';

export interface User {
    id: string;
    username: string;
    password: string; // Note: In a real app, never store plain text passwords
    name: string;
    email: string; // Added Email field
    role: UserRole;
    departmentId?: string; // User belongs to a department
    createdAt: number;
    status: UserStatus; // Lifecycle status
}

const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
const port = 3002; // Backend runs on 3002

// Allow all CORS requests
app.use(cors());
app.use(bodyParser.json());

// ==========================================
// ส่วนตั้งค่าการเชื่อมต่อฐานข้อมูล
// ==========================================
const DB_CONFIG = {
    host: 'localhost',      // ใส่ IP ของ MySQL Server
    user: 'root',           // Username ของ MySQL
    password: '',           // Password ของ MySQL
    database: 'procurement_db', // ชื่อฐานข้อมูล
    port: 3306
};

// --- Database Connection ---
const db = mysql.createPool({
    ...DB_CONFIG,
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

// ตรวจสอบการเชื่อมต่อตอนเริ่มต้น
db.getConnection((err, connection) => {
    if (err) {
        console.error('❌ Error connecting to MySQL:', err.code, err.message);
        console.error('   Please check your IP, Username, Password in server/index.js');
    } else {
        console.log('✅ Connected to MySQL Server successfully!');
        connection.release();
    }
});

// Helper for Promisified Query
const query = (sql, params) => {
    return new Promise((resolve, reject) => {
        db.query(sql, params, (err, results) => {
            if (err) return reject(err);
            resolve(results);
        });
    });
};

// --- API Endpoints ---

// ✅ เพิ่มหน้าแรกสำหรับเช็คสถานะ Server
app.get('/', (req, res) => {
    res.send('<h1 style="color:green; font-family:sans-serif;">✅ Procurement API is running on Port ' + port + '!</h1><p>Database connection status: Check console logs.</p>');
});

// 1. Auth & Users
app.post('/api/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const users = await query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
        if (users.length > 0) {
            const u = users[0];
            const user = {
                id: u.id, username: u.username, name: u.name, email: u.email,
                role: u.role, departmentId: u.department_id, status: u.status, createdAt: u.created_at
            };

            if (user.status === 'PENDING') return res.json({ success: false, message: 'รอการอนุมัติ' });
            if (user.status === 'SUSPENDED') return res.json({ success: false, message: 'ถูกระงับการใช้งาน' });

            res.json({ success: true, user });
        } else {
            res.json({ success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' });
        }
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

