            considerationNumber: "เลขรายงานขออนุมัติ",
            considerationDate: "วันที่รายงานขออนุมัติ",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขที่คำสั่ง/สัญญา"
        };
    }

    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return { name: 'violet', bgSoft: 'bg-violet-50', bgDeep: 'bg-violet-600', bgHover: 'hover:bg-violet-700', text: 'text-violet-700', border: 'border-violet-200', ring: 'focus:ring-violet-500', inputBg: 'bg-violet-50/50' };
            case RecordType.OTHER:
                return { name: 'orange', bgSoft: 'bg-orange-50', bgDeep: 'bg-orange-600', bgHover: 'hover:bg-orange-700', text: 'text-orange-700', border: 'border-orange-200', ring: 'focus:ring-orange-500', inputBg: 'bg-orange-50/50' };
            default:
                return { name: 'blue', bgSoft: 'bg-blue-50', bgDeep: 'bg-blue-600', bgHover: 'hover:bg-blue-700', text: 'text-blue-700', border: 'border-blue-200', ring: 'focus:ring-blue-500', inputBg: 'bg-blue-50/50' };
        }
    })();

    const calculateNextRunNumber = () => {
        const prefix = settings.requestIdPrefix;
        if (!prefix) return '';
        const reqIds = procurements.map(p => p.requestId).filter(id => id && id.startsWith(prefix));
        const consIds = considerations.map(c => c.considerationNumber).filter(id => id && id.startsWith(prefix));
        const recvIds = receivings.map(r => r.deliveryNoteNo).filter(id => id && id.startsWith(prefix));
        const allIds = [...reqIds, ...consIds, ...recvIds];
        let maxNum = 0;
        allIds.forEach(id => {
            const suffix = id.substring(prefix.length);
            const normalizedSuffix = normalizeToNr(suffix);
            const num = parseInt(normalizedSuffix);
            if (!isNaN(num) && num > maxNum) maxNum = num;
        });
        return prefix + toThaiNr(maxNum + 1);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowConfirm(true);
    };

    const handleConfirmSave = async (force: boolean = false) => {
        if (editingId) {
            updateProcurement(editingId, { ...formData });
        } else {
            const result = await addProcurement({ ...formData, type: type }, force);

            // Handle Warning (Soft Block)
            if (!result.success && result.isWarning) {
                setWarningMessage(result.message || "แจ้งเตือน");
                setShowConfirm(false); // Close normal confirm, wait for warning confirm
                return; 
            }

            if (!result.success && !result.isWarning) {
                alert(result.message);
                setShowConfirm(false);
                return;
            }
        }

        // Link Data logic
        if(formData.considerationNumber || formData.considerationDate) {
             upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
        }

        setWarningMessage(null);
        setShowConfirm(false);
        closeModal();
    };

    const handleDeleteClick = (id: string) => {
        const record = procurements.find(p => p.id === id);
        if (record && record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์ลบรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        const nextRequestId = calculateNextRunNumber() || settings.requestIdPrefix || '';
        setFormData({ requestId: nextRequestId, requestDate: '', category: '', itemCount: 0, amount: 0, company: '', remarks: '', considerationNumber: '', considerationDate: '' });
        setIsAutoFilled(true);
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        if (record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์แก้ไขรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        const linked = getLinkedData(record.requestId);
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || ''
        });
        setIsAutoFilled(false);
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
        setIsAutoFilled(false);
        setWarningMessage(null);
    };

    const handleSaveQuickDate = () => {
        if (quickDateId && quickDateValue && quickDateType) {
            let nextNumber = calculateNextRunNumber() || quickDateId;
            if (quickDateType === 'CONSIDERATION') {
                upsertConsideration(quickDateId, nextNumber, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                upsertReceiving(quickDateId, nextNumber, quickDateValue);
            }
            setQuickDateId(null);
            setQuickDateValue('');
            setQuickDateType(null);
        }
    };

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'ไม่ระบุ';

    const handleExportCSV = () => {
        const headers = [fieldLabels.requestId, fieldLabels.requestDate, 'ปีงบประมาณ', fieldLabels.considerationNumber, fieldLabels.considerationDate, fieldLabels.officialNumber, fieldLabels.receivingNumber, fieldLabels.receivingDate, 'จำนวนเงิน', 'บริษัท', 'ผู้บันทึก', 'หมายเหตุ'];
        const rows = filteredData.map(item => {
            const linked = getLinkedData(item.requestId);
            return [item.requestId, item.requestDate, getFiscalYear(item.requestDate), linked.consideration?.considerationNumber || '-', linked.consideration?.considerationDate || '-', item.officialNumber || '-', linked.receiving?.deliveryNoteNo || '-', linked.receiving?.receiveDate || '-', item.amount, `"${item.company.replace(/"/g, '""')}"`, getUserName(item.createdBy), `"${item.remarks.replace(/"/g, '""')}"`].join(',');
        });
        const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `procurement_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const previewNextNum = (quickDateId && quickDateType) ? (calculateNextRunNumber() || quickDateId) : '';

    return (
        <div className="p-4 sm:p-6">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 1cm; }
                    .lg\\:ml-64 { margin-left: 0 !important; }
                    .no-print { display: none !important; }
                    table { width: 100% !important; border-collapse: collapse; font-size: 10pt; }
                    th, td { border: 1px solid #cbd5e1 !important; padding: 4px 8px !important; }
                }
            `}</style>

            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                <h2 className="text-xl sm:text-2xl font-bold text-slate-800">{title}</h2>

                <div className="flex flex-wrap gap-2 no-print w-full sm:w-auto">
                    <button onClick={handleExportCSV} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <FileSpreadsheet size={16} />
                        <span>Excel</span>
                    </button>
                    <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <Printer size={16} />
                        <span>Print</span>
                    </button>
                    <button onClick={openNew} className={`w-full sm:w-auto flex items-center justify-center space-x-2 ${theme.bgDeep} ${theme.bgHover} text-white px-4 py-2 rounded-lg text-sm shadow-md`}>
                        <Plus size={16} />
                        <span>บันทึกใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestId}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestDate}</th>
                                <th className="px-4 py-3 whitespace-nowrap">ปีงบฯ</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.considerationNumber}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.considerationDate}</th>
                                <th className={`px-4 py-3 ${theme.bgSoft} whitespace-nowrap`}>{fieldLabels.officialNumber}</th>
                                <th className="px-4 py-3 bg-green-50 whitespace-nowrap">{fieldLabels.receivingNumber}</th>
                                <th className="px-4 py-3 bg-green-50 whitespace-nowrap">{fieldLabels.receivingDate}</th>
                                <th className="px-4 py-3 text-right whitespace-nowrap">จำนวนเงิน</th>
                                <th className="px-4 py-3 whitespace-nowrap">ผู้บันทึก</th>
                                <th className="px-4 py-3 whitespace-nowrap">บริษัท</th>
                                <th className="px-4 py-3 text-center no-print whitespace-nowrap">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredData.length === 0 ? (
                                <tr><td colSpan={12} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูล</td></tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const isOwner = item.createdBy === currentUser?.id || currentUser?.role === 'ADMIN';
                                    const isBackdated = checkChronologyIssue(item);

                                    return (
                                        <tr key={item.id} className={`border-b border-slate-100 transition-colors ${isBackdated ? 'bg-red-50 hover:bg-red-100' : 'hover:bg-slate-50'}`}>
                                            <td className="px-4 py-3 font-medium text-slate-900 whitespace-nowrap">{item.requestId}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                {item.requestDate}
                                                {isBackdated && (
                                                    <div className="inline-flex ml-2 text-red-500" title="วันที่ไม่สัมพันธ์กับเลขลำดับก่อนหน้า">
                                                        <AlertTriangle size={14} />
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-4 py-3 text-center whitespace-nowrap">{getFiscalYear(item.requestDate)}</td>
                                            <td className="px-4 py-3 text-orange-600 whitespace-nowrap">{linked.consideration?.considerationNumber || '-'}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                {linked.consideration?.considerationDate || (isOwner && (
                                                    <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('CONSIDERATION'); setQuickDateValue(new Date().toISOString().split('T')[0]); }} className={`flex items-center ${theme.text} ${theme.bgSoft} px-2 py-1 rounded no-print text-xs`}><CalendarPlus size={14} className="mr-1" /> เพิ่ม</button>
                                                )) || '-'}
                                            </td>
                                            <td className={`px-4 py-3 ${theme.bgSoft} font-bold ${theme.text} whitespace-nowrap`}>{item.officialNumber || '-'}</td>
                                            <td className="px-4 py-3 bg-green-50 text-green-700 whitespace-nowrap">{linked.receiving?.deliveryNoteNo || '-'}</td>
                                            <td className="px-4 py-3 bg-green-50 whitespace-nowrap">
                                                {linked.receiving?.receiveDate || (isOwner && (
                                                    <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('RECEIVING'); setQuickDateValue(new Date().toISOString().split('T')[0]); }} className="flex items-center text-green-600 bg-green-100 px-2 py-1 rounded no-print text-xs"><CalendarPlus size={14} className="mr-1" /> เพิ่ม</button>
                                                )) || '-'}
                                            </td>
                                            <td className="px-4 py-3 text-right whitespace-nowrap">{item.amount.toLocaleString()}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                <div className="flex items-center text-xs text-slate-500"><UserIcon size={12} className="mr-1 opacity-50"/>{getUserName(item.createdBy)}</div>
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[150px]">{item.company}</td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    {isOwner ? (
                                                        <>
                                                            <button onClick={() => openEdit(item)} className="p-1 text-slate-600 hover:bg-slate-200 rounded"><Edit2 size={16} /></button>
                                                            <button onClick={() => handleDeleteClick(item.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
                                                        </>
                                                    ) : <span className="text-[10px] text-slate-400">Read Only</span>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Warning Dialog (Soft Block) */}
            {warningMessage && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm no-print animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full text-center border-l-4 border-orange-500">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-orange-100 mb-6">
                            <AlertTriangle className="h-8 w-8 text-orange-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">แจ้งเตือนลำดับวันที่</h3>
                        <div className="text-sm text-slate-600 mb-8 leading-relaxed whitespace-pre-line bg-slate-50 p-3 rounded-lg border border-slate-200 text-left">
                            {warningMessage}
                        </div>
                        <div className="flex gap-4">
                            <button onClick={() => setWarningMessage(null)} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold transition-colors">กลับไปแก้ไข</button>
                            <button onClick={() => handleConfirmSave(true)} className="flex-1 py-3 bg-orange-600 hover:bg-orange-700 text-white rounded-xl text-sm font-semibold shadow-lg transition-colors">ยืนยันบันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Quick Date Modal */}
            {quickDateId && (
                <div className="fixed inset-0 bg-black/40 z-[100] flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold">ระบุวันที่</h3>
                            <button onClick={() => setQuickDateId(null)} className="text-slate-400"><X size={20}/></button>
                        </div>
                        <p className="text-xs text-slate-500 mb-4">ระบบจะรันเลข <span className="font-bold text-slate-800">{previewNextNum}</span> ให้อัตโนมัติ</p>
                        <input type="date" className="w-full border rounded-lg px-3 py-2 mb-6 outline-none focus:ring-2 ring-blue-500 text-slate-900 bg-white" value={quickDateValue} onChange={e => setQuickDateValue(e.target.value)} />
                        <div className="flex gap-2">
                            <button onClick={() => setQuickDateId(null)} className="flex-1 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={handleSaveQuickDate} className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium">บันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Form Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-0 sm:p-4 no-print">
                    <div className="bg-white sm:rounded-xl shadow-2xl w-full max-w-2xl h-full sm:h-auto max-h-screen flex flex-col overflow-hidden relative">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
                            <h3 className="text-lg font-semibold text-slate-800">{editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}</h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600 p-1"><X size={28} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 flex-1 overflow-y-auto">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestId} *</label>
                                    <input 
                                        required 
                                        type="text" 
                                        className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none bg-white font-medium ${isAutoFilled ? 'text-red-600' : 'text-slate-900'}`} 
                                        value={formData.requestId} 
                                        onChange={e => {
                                            setFormData({...formData, requestId: e.target.value});
                                            setIsAutoFilled(false);
                                        }} 
                                    />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestDate} *</label>
                                    <input required type="date" className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none bg-white text-slate-900" value={formData.requestDate} onChange={e => setFormData({...formData, requestDate: e.target.value})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                    <select className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                        <option value="">เลือกหมวด...</option>
                                        {settings.categories?.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                    <input type="text" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                    <input type="number" min="1" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.itemCount} onChange={e => setFormData({...formData, itemCount: Number(e.target.value)})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนเงิน *</label>
                                    <input required type="number" step="0.01" className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none bg-white text-slate-900`} value={formData.amount} onChange={e => setFormData({...formData, amount: Number(e.target.value)})} />
                                </div>
                                <div className="col-span-1 sm:col-span-2">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                    <textarea rows={2} className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
                                </div>
                            </div>
                            <div className="flex flex-col sm:flex-row justify-end gap-3 mt-8 pt-4 border-t sticky bottom-0 bg-white">
                                <button type="button" onClick={closeModal} className="order-2 sm:order-1 px-6 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">ยกเลิก</button>
                                <button type="submit" className={`order-1 sm:order-2 px-8 py-2.5 ${theme.bgDeep} ${theme.bgHover} text-white rounded-lg shadow-md flex justify-center items-center`}><Check size={18} className="mr-2" /> บันทึกข้อมูล</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirmation Dialog before Save */}
            {showConfirm && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-blue-50 mb-6">
                            <AlertCircle className="h-8 w-8 text-blue-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการบันทึกข้อมูล?</h3>
                        <p className="text-sm text-slate-500 mb-8 leading-relaxed">กรุณาตรวจสอบความถูกต้องของข้อมูลอีกครั้ง<br/>คุณต้องการบันทึกรายการนี้ใช่หรือไม่?</p>
                        <div className="flex gap-4">
                            <button onClick={() => setShowConfirm(false)} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold transition-colors">กลับไปแก้ไข</button>
                            <button onClick={() => handleConfirmSave(false)} className="flex-1 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-sm font-semibold shadow-lg transition-colors">ยืนยันบันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {deleteId && (
                <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/50 no-print">
                    <div className="bg-white rounded-xl p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4"><AlertTriangle className="text-red-600" /></div>
                        <h3 className="text-lg font-bold mb-2">ยืนยันการลบ?</h3>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setDeleteId(null)} className="flex-1 py-2 bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-sm">ลบออก</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { Save, Plus, Trash2, Edit2, X, Check, Layers, Building, Power, PowerOff, AlertCircle } from 'lucide-react';
import { ProcurementCategory, Department, AppSettings } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, updateSettings } = useApp();
    const [localSettings, setLocalSettings] = useState(settings);
    const [saved, setSaved] = useState(false);

    // --- Confirmation UI State ---
    const [confirmAction, setConfirmAction] = useState<{
        type: 'PREFIX' | 'ADD_DEPT' | 'EDIT_DEPT' | 'ADD_CAT' | 'EDIT_CAT';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // --- Department State ---
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState(''); // New State
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState(''); // New State

    // --- Category State ---
    const [newCategoryName, setNewCategoryName] = useState('');
    const [newCategoryDept, setNewCategoryDept] = useState('');
    const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
    const [editCatName, setEditCatName] = useState('');
    const [editCatDept, setEditCatDept] = useState('');

    const handleSavePrefixRequest = (e: React.FormEvent) => {
        e.preventDefault();
        setConfirmAction({
            type: 'PREFIX',
            title: 'ยืนยันการบันทึกรูปแบบเลขที่?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงรูปแบบเลขที่ใบขอใช่หรือไม่?',
            onConfirm: () => {
                updateSettings(localSettings);
                setSaved(true);
                setTimeout(() => setSaved(false), 2000);
                setConfirmAction(null);
            }
        });
    };

    // --- Department Handlers ---
    const addDepartmentRequest = () => {
        if (!newDeptName.trim()) return;
        setConfirmAction({
            type: 'ADD_DEPT',
            title: 'ยืนยันการเพิ่มฝ่าย/งาน?',
            message: `ต้องการเพิ่มฝ่าย "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                const newDept: Department = {
                    id: `dept_${Date.now()}`,
                    name: newDeptName.trim(),
                    prefix: newDeptPrefix.trim(), // Added Prefix
                    isActive: true
                };
                const updatedDepts = [...(localSettings.departments || []), newDept];
                const newSettings = { ...localSettings, departments: updatedDepts };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setNewDeptName('');
                setNewDeptPrefix('');
                setConfirmAction(null);
            }
        });
    };

    const toggleDeptStatus = (id: string) => {
        const updatedDepts = localSettings.departments.map(d => 
            d.id === id ? { ...d, isActive: !d.isActive } : d
        );
        const newSettings = { ...localSettings, departments: updatedDepts };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
    };

    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id);
        setEditDeptName(dept.name);
        setEditDeptPrefix(dept.prefix || '');
    };

    const saveEditDeptRequest = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT',
            title: 'ยืนยันการแก้ไขข้อมูล?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงชื่อฝ่ายใช่หรือไม่?',
            onConfirm: () => {
                const updatedDepts = localSettings.departments.map(d => 
                    d.id === editingDeptId ? { ...d, name: editDeptName.trim(), prefix: editDeptPrefix.trim() } : d
                );
                const newSettings = { ...localSettings, departments: updatedDepts };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setEditingDeptId(null);
                setConfirmAction(null);
            }
        });
    };

    // --- Category Handlers ---
    const addCategoryRequest = () => {
        if (!newCategoryName.trim()) return;
        setConfirmAction({
            type: 'ADD_CAT',
            title: 'ยืนยันการเพิ่มหมวดพัสดุ?',
            message: `ต้องการเพิ่มหมวดพัสดุ "${newCategoryName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                const newCat: ProcurementCategory = {
                    id: Date.now().toString(),
                    name: newCategoryName.trim(),
                    departmentId: newCategoryDept || undefined,
                    isActive: true
                };
                const updatedCategories = [...localSettings.categories, newCat];
                const newSettings = { ...localSettings, categories: updatedCategories };
                setLocalSettings(newSettings);
                updateSettings(newSettings); 
                setNewCategoryName('');
                setNewCategoryDept('');
                setConfirmAction(null);
            }
        });
    };

    const toggleCatStatus = (id: string) => {
        const updatedCategories = localSettings.categories.map(c => 
            c.id === id ? { ...c, isActive: !c.isActive } : c
        );
        const newSettings = { ...localSettings, categories: updatedCategories };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
    };

    const startEditCategory = (cat: ProcurementCategory) => {
        setEditingCategoryId(cat.id);
        setEditCatName(cat.name);
        setEditCatDept(cat.departmentId || '');
    };

    const saveEditCategoryRequest = () => {
        if (!editCatName.trim() || !editingCategoryId) return;
        setConfirmAction({
            type: 'EDIT_CAT',
            title: 'ยืนยันการแก้ไขหมวดพัสดุ?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงข้อมูลหมวดพัสดุใช่หรือไม่?',
            onConfirm: () => {
                const updatedCategories = localSettings.categories.map(c => 
                    c.id === editingCategoryId ? { 
                        ...c, 
                        name: editCatName.trim(),
                        departmentId: editCatDept || undefined
                    } : c
                );
                const newSettings = { ...localSettings, categories: updatedCategories };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setEditingCategoryId(null);
                setConfirmAction(null);
            }
        });
    };

    return (
        <div className="p-6 relative min-h-screen pb-20">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">ตั้งค่าระบบ (Settings)</h2>

            <div className="space-y-6">

                {/* 1. Document Format Settings */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit">
                    <div className="p-6 border-b border-slate-100 bg-slate-50">
                        <h3 className="text-lg font-semibold text-slate-800">รูปแบบเอกสาร</h3>
                        <p className="text-sm text-slate-500">กำหนดค่าเริ่มต้นสำหรับเลขที่เอกสาร</p>
                    </div>

                    <form onSubmit={handleSavePrefixRequest} className="p-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                รูปแบบเลขที่ใบขอ (Prefix)
                            </label>
                            <div className="flex space-x-2">
                                <input 
                                    type="text" 
                                    className="flex-1 bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none font-medium"
                                    value={localSettings.requestIdPrefix}
                                    onChange={e => setLocalSettings({...localSettings, requestIdPrefix: e.target.value})}
                                    placeholder="เช่น สพ.๐๐๓๓.๐๒/"
                                />
                                <button 
                                    type="submit" 
                                    className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg shadow-sm transition-all"
                                >
                                    <Save size={18} />
                                    <span>บันทึก</span>
                                </button>
                            </div>
                            <p className="text-xs text-red-500 mt-2 font-medium">
                                ค่านี้จะถูกนำไปเติมให้อัตโนมัติเมื่อสร้างรายการใหม่
                            </p>
                            {saved && (
                                <p className="text-green-600 text-sm font-medium animate-fade-in mt-2">
                                    บันทึกเรียบร้อยแล้ว!
                                </p>
                            )}
                        </div>
                    </form>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    {/* 2. Department Management */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit flex flex-col">
                        <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                            <div>
                                <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                    <Building size={20} className="mr-2 text-indigo-600"/> จัดการฝ่าย/งาน
                                </h3>
                                <p className="text-sm text-red-500 font-medium">รายชื่อฝ่ายและรหัสย่อ (สำหรับออกเลข)</p>
                            </div>
                        </div>

                        <div className="p-6 flex-1 flex flex-col">
                            <div className="flex space-x-2 mb-4">
                                <input 
                                    type="text" 
                                    className="flex-[2] bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                                    placeholder="ชื่อฝ่าย/งานใหม่..."
                                    value={newDeptName}
                                    onChange={e => setNewDeptName(e.target.value)}
                                />
                                <input 
                                    type="text" 
                                    className="flex-1 bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                                    placeholder="รหัสย่อ (เช่น ทส.)"
                                    value={newDeptPrefix}
                                    onChange={e => setNewDeptPrefix(e.target.value)}
                                />
                                <button onClick={addDepartmentRequest} disabled={!newDeptName.trim()} className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white px-3 py-2 rounded-lg shadow-sm">
                                    <Plus size={20} />
                                </button>
                            </div>

                            <div className="space-y-2 overflow-y-auto max-h-[300px] pr-2">
                                {localSettings.departments?.map((dept) => (
                                    <div key={dept.id} className={`flex items-center justify-between p-3 border rounded-lg group transition-all ${dept.isActive ? 'bg-white border-slate-200' : 'bg-slate-50 border-slate-200 opacity-60'}`}>
                                        {editingDeptId === dept.id ? (
                                            <div className="flex items-center space-x-2 flex-1">
                                                <input 
                                                    autoFocus
                                                    className="flex-[2] bg-white text-slate-900 border border-indigo-300 rounded px-2 py-1 text-sm outline-none"
                                                    value={editDeptName}
                                                    onChange={e => setEditDeptName(e.target.value)}
                                                />
                                                <input 
                                                    className="flex-1 bg-white text-slate-900 border border-indigo-300 rounded px-2 py-1 text-sm outline-none"
                                                    value={editDeptPrefix}
                                                    onChange={e => setEditDeptPrefix(e.target.value)}
                                                    placeholder="รหัสย่อ"
                                                />
                                                <button onClick={saveEditDeptRequest} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={16}/></button>
                                                <button onClick={() => setEditingDeptId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={16}/></button>
                                            </div>
                                        ) : (
                                            <>
                                                <div className="flex items-center flex-1">
                                                    <span className={`text-sm font-medium ${dept.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{dept.name}</span>
                                                    {dept.prefix && (
                                                        <span className="ml-2 text-[10px] bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded font-bold">{dept.prefix}</span>
                                                    )}
                                                    {!dept.isActive && <span className="ml-2 text-[10px] bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded">INACTIVE</span>}
                                                </div>
                                                <div className="flex items-center space-x-1">
                                                    <button onClick={() => startEditDept(dept)} className="p-1 text-slate-400 hover:text-indigo-600 opacity-0 group-hover:opacity-100 transition-opacity"><Edit2 size={14}/></button>
                                                    <button 
                                                        onClick={() => toggleDeptStatus(dept.id)} 
                                                        className={`p-1 rounded transition-colors ${dept.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-400 hover:text-green-600 hover:bg-green-50'}`}
                                                        title={dept.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                    >
                                                        {dept.isActive ? <Power size={14} /> : <PowerOff size={14} />}
                                                    </button>
                                                </div>
                                            </>
                                        )}
                                    </div>
                                ))}
                                {(!localSettings.departments || localSettings.departments.length === 0) && (
                                    <p className="text-center text-slate-400 text-sm py-4">ยังไม่มีข้อมูลฝ่าย</p>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* 3. Category Management (Linked to Departments) */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit flex flex-col">
                        <div className="p-6 border-b border-slate-100 bg-slate-50">
                            <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                <Layers size={20} className="mr-2 text-green-600"/> จัดการหมวดพัสดุ
                            </h3>
                            <p className="text-sm text-red-500 font-medium">สัมพันธ์กับฝ่ายที่รับผิดชอบ</p>
                        </div>

                        <div className="p-6 flex-1 flex flex-col">
                            <div className="flex flex-col space-y-2 mb-4">
                                <input 
                                    type="text" 
                                    className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-green-500 outline-none text-sm"
                                    placeholder="ชื่อหมวดหมู่..."
                                    value={newCategoryName}
                                    onChange={e => setNewCategoryName(e.target.value)}
                                />
                                <div className="flex space-x-2">
                                    <select 
                                        className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500 bg-white text-slate-900"
                                        value={newCategoryDept}
                                        onChange={e => setNewCategoryDept(e.target.value)}
                                    >
                                        <option value="">-- ไม่ระบุฝ่าย --</option>
                                        {localSettings.departments?.filter(d => d.isActive).map(d => (
                                            <option key={d.id} value={d.id}>{d.name}</option>
                                        ))}
                                    </select>
                                    <button onClick={addCategoryRequest} disabled={!newCategoryName.trim()} className="bg-green-600 hover:bg-green-700 disabled:bg-slate-300 text-white px-4 py-2 rounded-lg shadow-sm">
                                        <Plus size={20} />
                                    </button>
                                </div>
                            </div>

                            <div className="space-y-2 overflow-y-auto max-h-[300px] pr-2">
                                {localSettings.categories.map((cat) => {
                                    const deptName = localSettings.departments?.find(d => d.id === cat.departmentId)?.name;

                                    return (
                                        <div key={cat.id} className={`p-3 border rounded-lg group transition-all ${cat.isActive ? 'bg-white border-slate-100 hover:border-green-200' : 'bg-slate-50 border-slate-200 opacity-60'}`}>
                                            {editingCategoryId === cat.id ? (
                                                <div className="space-y-2">
                                                    <input 
                                                        className="w-full bg-white text-slate-900 border border-green-300 rounded px-2 py-1 text-sm outline-none"
                                                        value={editCatName}
                                                        onChange={e => setEditCatName(e.target.value)}
                                                    />
                                                    <div className="flex space-x-2">
                                                        <select 
                                                            className="flex-1 border border-green-300 rounded px-2 py-1 text-sm outline-none bg-white text-slate-900"
                                                            value={editCatDept}
                                                            onChange={e => setEditCatDept(e.target.value)}
                                                        >
                                                            <option value="">-- ไม่ระบุฝ่าย --</option>
                                                            {localSettings.departments?.filter(d => d.isActive).map(d => (
                                                                <option key={d.id} value={d.id}>{d.name}</option>
                                                            ))}
                                                        </select>
                                                        <button onClick={saveEditCategoryRequest} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={18}/></button>
                                                        <button onClick={() => setEditingCategoryId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={18}/></button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex justify-between items-center">
                                                    <div>
                                                        <div className={`font-medium text-sm ${cat.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{cat.name}</div>
                                                        {deptName && (
                                                            <div className={`text-xs px-2 py-0.5 rounded-full inline-block mt-1 ${cat.isActive ? 'text-indigo-500 bg-indigo-50' : 'text-slate-400 bg-slate-100'}`}>
                                                                {deptName}
                                                            </div>
                                                        )}
                                                    </div>
                                                    <div className="flex items-center space-x-1">
                                                        <button onClick={() => startEditCategory(cat)} className="p-1.5 text-slate-400 hover:text-green-600 opacity-0 group-hover:opacity-100 transition-opacity"><Edit2 size={16}/></button>
                                                        <button 
                                                            onClick={() => toggleCatStatus(cat.id)} 
                                                            className={`p-1.5 rounded transition-colors ${cat.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-400 hover:text-green-600 hover:bg-green-50'}`}
                                                            title={cat.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                        >
                                                            {cat.isActive ? <Power size={16} /> : <PowerOff size={16} />}
                                                        </button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Reusable Confirmation Modal Overlay */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-white/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4">
                            <AlertCircle className="h-6 w-6 text-blue-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                            {confirmAction.message}
                        </p>
                        <div className="flex justify-center space-x-3">
                            <button 
                                onClick={() => setConfirmAction(null)}
                                className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmAction.onConfirm}
                                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors font-medium text-sm"
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { UserCog, User as UserIcon, Search, Edit, X, Check, Lock, Building, Power, PowerOff, AlertCircle, Trash2, RefreshCcw, Mail } from 'lucide-react';
import { UserRole, User, UserStatus } from '../types';

const UserManagementPage: React.FC = () => {
    const { users, currentUser, updateUser, registerUser, settings, deleteUser } = useApp();
    const [searchTerm, setSearchTerm] = useState('');

    // Add User Form State
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [newName, setNewName] = useState('');
    const [newEmail, setNewEmail] = useState(''); // Added email state
    const [newRole, setNewRole] = useState<UserRole>('USER');
    const [newDeptId, setNewDeptId] = useState('');
    const [showAddConfirm, setShowAddConfirm] = useState(false);

    // Confirmation State for Soft Delete/Suspend
    const [suspendConfirm, setSuspendConfirm] = useState<{ id: string, name: string } | null>(null);

    // Edit User State
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [showEditConfirm, setShowEditConfirm] = useState(false);
    const [editFormData, setEditFormData] = useState({
        name: '',
        email: '',
        username: '',
        password: '',
        role: 'USER' as UserRole,
        departmentId: ''
    });

    // Shows Active and Suspended users. Pending are in their own page.
    const activeOrSuspendedUsers = users.filter(u => 
        u.status !== 'PENDING' && (
            u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
            u.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
            (u.email && u.email.toLowerCase().includes(searchTerm.toLowerCase()))
        )
    );

    const handleAddUserRequest = (e: React.FormEvent) => {
        e.preventDefault();
        setShowAddConfirm(true);
    };

    const confirmAddUser = () => {
        const success = registerUser({
            username: newUsername,
            password: newPassword,
            name: newName,
            email: newEmail,
            role: newRole,
            departmentId: newDeptId || undefined,
            status: 'ACTIVE' // Admin creation defaults to active
        });

        if (success) {
            setNewUsername('');
            setNewPassword('');
            setNewName('');
            setNewEmail('');
            setNewRole('USER');
            setNewDeptId('');
            setShowAddConfirm(false);
        } else {
            alert('Username นี้มีผู้ใช้งานแล้ว');
            setShowAddConfirm(false);
        }
    };

    const openEditModal = (user: User) => {
        setEditingUser(user);
        setEditFormData({
            name: user.name,
            email: user.email || '',
            username: user.username,
            password: '', 
            role: user.role,
            departmentId: user.departmentId || ''
        });
    };

    const handleUpdateUserSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowEditConfirm(true);
    };

    const confirmUpdateUser = () => {
        if (!editingUser) return;

        const updates: Partial<User> = {
            name: editFormData.name,
            email: editFormData.email,
            role: editFormData.role,
            departmentId: editFormData.departmentId || undefined
        };

        if (editFormData.password.trim()) {
            updates.password = editFormData.password;
        }

        updateUser(editingUser.id, updates);
        setEditingUser(null);
        setShowEditConfirm(false);
    };

    const handleSoftDelete = (user: User) => {
        if (user.id === currentUser?.id) return;
        setSuspendConfirm({ id: user.id, name: user.name });
    };

    const confirmSuspend = () => {
        if (suspendConfirm) {
            deleteUser(suspendConfirm.id); // deleteUser is implemented as soft delete (status: SUSPENDED)
            setSuspendConfirm(null);
        }
    };

    const toggleStatus = (user: User) => {
        if (user.id === currentUser?.id) return;
        const nextStatus: UserStatus = user.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE';
        updateUser(user.id, { status: nextStatus });
    };

    const toggleRole = (id: string, currentRole: UserRole) => {
        if (id === currentUser?.id) return;
        const newRole = currentRole === 'ADMIN' ? 'USER' : 'ADMIN';
        updateUser(id, { role: newRole });
    };

    const getDeptName = (deptId?: string) => {
        if (!deptId) return '-';
        return settings.departments?.find(d => d.id === deptId)?.name || '-';
    };

    return (
