    queueLimit: 0
});

const query = (sql, params) => {
    return new Promise((resolve, reject) => {
        db.query(sql, params, (err, results) => {
            if (err) return reject(err);
            resolve(results);
        });
    });
};

// --- Auto-Migration ---
async function initDatabase() {
    console.log('🔄 Checking database schema...');
    try {
        // Base Tables
        await query(`CREATE TABLE IF NOT EXISTS departments (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, prefix VARCHAR(20), is_active BOOLEAN DEFAULT TRUE)`);
        await query(`CREATE TABLE IF NOT EXISTS procurement_categories (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, department_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE)`);
        await query(`CREATE TABLE IF NOT EXISTS users (id VARCHAR(50) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), role ENUM('ADMIN', 'USER') DEFAULT 'USER', department_id VARCHAR(50), status ENUM('PENDING', 'ACTIVE', 'SUSPENDED') DEFAULT 'PENDING', created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS procurements (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, request_date DATE NOT NULL, category VARCHAR(255), item_count INT DEFAULT 0, amount DECIMAL(15, 2) DEFAULT 0.00, company VARCHAR(255), remarks TEXT, official_number VARCHAR(50), type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL, department_id VARCHAR(50), created_by VARCHAR(50), created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS receivings (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, delivery_note_no VARCHAR(50), receive_date DATE, category VARCHAR(255), created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS considerations (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, consideration_number VARCHAR(50), consideration_date DATE)`);

        // Fix Columns (Add if missing)
        const addColumn = async (table, col, def) => {
            try {
                const cols = await query(`SHOW COLUMNS FROM ${table} LIKE ?`, [col]);
                if (cols.length === 0) {
                    console.log(`✨ Adding column '${col}' to '${table}'`);
                    await query(`ALTER TABLE ${table} ADD COLUMN ${col} ${def}`);
                }
            } catch (e) { console.error(`⚠️ Col check failed: ${e.message}`); }
        };

        await addColumn('departments', 'prefix', 'VARCHAR(20)');
        await addColumn('users', 'department_id', 'VARCHAR(50)');
        await addColumn('users', 'email', 'VARCHAR(100)');
        await addColumn('procurements', 'department_id', 'VARCHAR(50)');
        await addColumn('procurement_categories', 'department_id', 'VARCHAR(50)');

        // Seed Admin
        const users = await query('SELECT count(*) as count FROM users');
        if (users[0].count === 0) {
            console.log('🌱 Seeding Admin...');
            await query("INSERT INTO departments (id, name, prefix) VALUES ('dept_1', 'บริหารทั่วไป', 'บห.') ON DUPLICATE KEY UPDATE name=name");
            await query("INSERT INTO users (id, username, password, name, email, role, department_id, status, created_at) VALUES ('1', 'admin', 'password', 'Admin', 'admin@system.com', 'ADMIN', 'dept_1', 'ACTIVE', ?)", [Date.now()]);
        }
        console.log('✅ Database Schema verified.');
    } catch (e) {
        console.error('❌ Database Initialization Failed:', e.message);
    }
}

db.getConnection((err, connection) => {
    if (err) {
        isDbConnected = false;
        dbConnectionError = err.message;
        console.error('❌ MySQL Connection Error:', err.message);
    } else {
        isDbConnected = true;
        console.log('✅ Connected to MySQL!');
        connection.release();
        initDatabase();
    }
});

