                        <div className="bg-red-50 text-red-800 text-xs p-3 rounded mb-4 text-left overflow-auto max-h-32 border border-red-200 font-mono">
                            {serverErrorMessage}
                        </div>
                    )}
                    <button 
                        onClick={retryConnection}
                        disabled={isLoading}
                        className="w-full flex items-center justify-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-semibold transition-all shadow-lg"
                    >
                        {isLoading ? <RefreshCw className="animate-spin" size={20} /> : <RefreshCw size={20} />}
                        <span>ลองเชื่อมต่อใหม่</span>
                    </button>
                </div>
            </div>
        );
    }

    if (!currentUser) return <LoginPage />;

    const renderContent = () => {
        switch (activeTab) {
            case 'dashboard': return <Dashboard />;
            case 'purchase': return <ProcurementTable type={RecordType.PURCHASE} title="ทะเบียนคุมจัดซื้อ (Purchase Orders)" />;
            case 'hiring': return <ProcurementTable type={RecordType.HIRING} title="ทะเบียนคุมจัดจ้าง (Hiring Orders)" />;
            case 'other': return <ProcurementTable type={RecordType.OTHER} title="ทะเบียนคุมอื่นๆ (Other Registry)" />;
            case 'receiving': return <ReceivingPage />;
            case 'consideration': return <ConsiderationPage />;
            case 'pending_users': return currentUser.role === 'ADMIN' ? <PendingUsersPage /> : <Dashboard />;
            case 'users': return currentUser.role === 'ADMIN' ? <UserManagementPage /> : <Dashboard />;
            case 'settings': return currentUser.role === 'ADMIN' ? <SettingsPage /> : <Dashboard />;
            default: return <Dashboard />;
        }
    };

    return (
        <div className="flex h-screen bg-slate-50 text-slate-900 font-sans relative">
            <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
            <div className="flex-1 flex flex-col min-w-0 transition-all duration-300 lg:ml-64">
                <header className="lg:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-40">
                    <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg"><Menu size={24} /></button>
                    <h2 className="text-lg font-bold text-slate-800 truncate px-2">ระบบพัสดุ</h2>
                    <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">{currentUser.name.charAt(0)}</div>
                </header>
                <main className="flex-1 overflow-y-auto">{renderContent()}</main>
            </div>
        </div>
    );
};

