        saveDB(db);
        return true;
    },
    updateUser: async (id: string, data: any) => {
        const db = loadDB();
        db.users = db.users.map((u: any) => u.id === id ? { ...u, ...data } : u);
        saveDB(db);
    },

    // Generic CRUD helpers
    addItem: async (collection: string, item: any) => {
        const db = loadDB();
        db[collection].push(item);
        saveDB(db);
    },
