        const db = loadDB();
        db[collection] = db[collection].map((item: any) => item.id === id ? { ...item, ...data } : item);
        saveDB(db);
    },
    deleteItem: async (collection: string, id: string) => {
        const db = loadDB();
        db[collection] = db[collection].filter((item: any) => item.id !== id);
        saveDB(db);
    },

