    upsertReceiving: async (data: any) => {
        const db = loadDB();
        const idx = db.receivings.findIndex((r: any) => r.requestId === data.requestId);
        if (idx >= 0) {
            db.receivings[idx] = { ...db.receivings[idx], ...data };
