            db.receivings.push({ ...data, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() });
        }
        saveDB(db);
    },
    upsertConsideration: async (data: any) => {
        const db = loadDB();
        const idx = db.considerations.findIndex((c: any) => c.requestId === data.requestId);
        if (idx >= 0) {
            db.considerations[idx] = { ...db.considerations[idx], ...data };
        } else {
            db.considerations.push({ ...data, id: Math.random().toString(36).substr(2, 9) });
        }
        saveDB(db);
    },

