            <h1>Procurement API Server</h1>
            <p>Port: <strong>${port}</strong></p>
            <div style="border: 1px solid #ccc; padding: 15px; border-radius: 8px; display: inline-block; text-align: left;">
                <p><strong>Database Status:</strong> <span style="color:${statusColor}">${statusIcon} ${dbMsg}</span></p>
            </div>
            <p style="color: #666; font-size: 12px; margin-top: 20px;">${new Date().toLocaleString()}</p>
        </div>
    `);
});

// 1. Auth & Users
app.post('/api/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const users = await query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
        if (users.length > 0) {
            const u = users[0];
            const user = {
                id: u.id, username: u.username, name: u.name, email: u.email,
                role: u.role, departmentId: u.department_id, status: u.status, createdAt: u.created_at
            };

            if (user.status === 'PENDING') return res.json({ success: false, message: 'รอการอนุมัติ' });
            if (user.status === 'SUSPENDED') return res.json({ success: false, message: 'ถูกระงับการใช้งาน' });

            res.json({ success: true, user });
        } else {
            res.json({ success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' });
        }
    } catch (e) {
        console.error(e);
        res.status(500).json({ error: e.message });
    }
});

