                                <button onClick={confirmRegistration} className="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-sm font-bold shadow-lg shadow-blue-200 transition-all">ยืนยันส่งข้อมูล</button>
