        const considerations = await query('SELECT * FROM considerations');
        const departments = await query('SELECT * FROM departments');
        const categories = await query('SELECT * FROM procurement_categories');

        const mappedProcurements = procurements.map(p => ({
            id: p.id, requestId: p.request_id, requestDate: p.request_date, category: p.category,
            itemCount: p.item_count, amount: parseFloat(p.amount), company: p.company, remarks: p.remarks,
