                                                        <div className="col-span-3 font-medium text-sm text-slate-800 truncate" title={dept.name}>{dept.name}</div>
                                                        <div className="col-span-3 text-xs text-slate-500 truncate">
                                                            {settings.workGroups?.find(g => g.id === dept.workGroupId)?.name || '-'}
                                                        </div>
                                                        <div className="col-span-3">
                                                            <span className="text-xs font-mono bg-slate-100 text-slate-600 px-2 py-1 rounded w-fit inline-block truncate max-w-full">
                                                                {dept.requestPrefix || '-'}
                                                            </span>
                                                        </div>
                                                        <div className="col-span-1 text-center">
                                                            <span className="text-xs font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded">{dept.prefix || '-'}</span>
                                                        </div>
                                                        <div className="col-span-2 flex justify-center space-x-2">
                                                            <button onClick={() => startEditDept(dept)} className="text-slate-400 hover:text-indigo-600 transition-colors"><Edit2 size={16}/></button>
                                                            <button onClick={() => toggleDeptStatus(dept.id)} className={`${dept.isActive ? 'text-green-500 hover:text-green-600' : 'text-red-400 hover:text-red-600'} transition-colors`}>
                                                                {dept.isActive ? <Power size={16}/> : <PowerOff size={16}/>}
                                                            </button>
                                                        </div>
                                                    </>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* 4. Categories */}
                    <div className="lg:col-span-3 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-fit flex flex-col mt-6">
                        <div className="p-6 border-b border-slate-100 bg-slate-50">
                            <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                <Layers size={20} className="mr-2 text-green-600"/> จัดการหมวดพัสดุ
                            </h3>
                            <p className="text-xs text-slate-500">หมวดหมู่สำหรับการจัดซื้อจัดจ้าง</p>
                        </div>
                        <div className="p-6">
                            <div className="flex space-x-2 mb-4 max-w-2xl">
                                <input className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500" placeholder="ชื่อหมวด (เช่น วัสดุสำนักงาน)..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
                                <select className="flex-1 border border-slate-300 rounded-lg px-2 text-sm outline-none focus:ring-2 focus:ring-green-500" value={newCategoryDept} onChange={e => setNewCategoryDept(e.target.value)}>
                                    <option value="">-- ฝ่ายที่รับผิดชอบ --</option>
                                    {settings.departments?.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                                </select>
                                <button onClick={addCategoryRequest} className="bg-green-600 hover:bg-green-700 text-white px-4 rounded-lg shadow-sm"><Plus size={18}/></button>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                                {localSettings.categories.map(c => (
                                    <div key={c.id} className={`flex justify-between items-center p-3 border rounded-lg transition-all ${!c.isActive ? 'bg-slate-50 opacity-60' : 'bg-white hover:border-green-300 hover:shadow-sm'}`}>
                                        {editingCategoryId === c.id ? (
                                            <>
                                                <div className="flex-1 flex flex-col gap-1 mr-2">
                                                    <input className="w-full border rounded px-1 py-0.5 text-sm" value={editCatName} onChange={e => setEditCatName(e.target.value)} />
                                                    <select className="w-full border rounded px-1 py-0.5 text-xs" value={editCatDept} onChange={e => setEditCatDept(e.target.value)}>
                                                        <option value="">-</option>
                                                        {settings.departments?.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                                                    </select>
                                                </div>
                                                <div className="flex flex-col gap-1">
                                                    <button onClick={saveEditCategoryRequest} className="text-green-600"><Check size={16}/></button>
                                                    <button onClick={() => setEditingCategoryId(null)} className="text-red-600"><X size={16}/></button>
                                                </div>
                                            </>
                                        ) : (
                                            <>
                                                <div className="flex flex-col">
                                                    <span className="font-medium text-sm text-slate-800">{c.name}</span>
                                                    <span className="text-[10px] text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded w-fit mt-1">
                                                        {settings.departments?.find(d=>d.id===c.departmentId)?.name || 'ไม่ระบุฝ่าย'}
                                                    </span>
                                                </div>
                                                <div className="flex items-center space-x-2">
                                                    <button onClick={() => startEditCategory(c)} className="text-slate-400 hover:text-green-600"><Edit2 size={14}/></button>
                                                    <button onClick={() => toggleCatStatus(c.id)} className={`${c.isActive ? 'text-green-500' : 'text-red-500'}`}><Power size={14}/></button>
                                                </div>
                                            </>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal Overlay */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4">
                            <AlertCircle className="h-6 w-6 text-blue-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">{confirmAction.message}</p>
                        <div className="flex justify-center space-x-3">
                            <button onClick={() => setConfirmAction(null)} className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors">ยกเลิก</button>
                            <button onClick={confirmAction.onConfirm} className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors">ยืนยัน</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { createContext, useContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole, Department, ProcurementCategory, WorkGroup } from '../types';

// ==========================================
// แก้ไข: ใช้ Port 3002 ให้ตรงกับ Backend
// ==========================================
const BACKEND_PORT = 3002; 

const getApiUrl = () => {
    // กรณีรันบน Server (SSR)
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api`;

    // กรณีรันบน Browser:
    let hostname = window.location.hostname;
    if (!hostname || hostname.trim() === '') {
        hostname = 'localhost';
    }
    return `http://${hostname}:${BACKEND_PORT}/api`;
};

const API_URL = getApiUrl();
console.log(`%c🔌 Connecting to Backend API at: ${API_URL}`, "color: green; font-weight: bold;");

interface AppContextType {
    isLoading: boolean;
    serverError: boolean;
    serverErrorMessage: string;
    retryConnection: () => void;

    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth & Users
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>, force?: boolean) => Promise<{ success: boolean, message?: string, isWarning?: boolean }>;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    upsertReceiving: (requestId: string, number: string, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    upsertConsideration: (requestId: string, number: string, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
    addDepartment: (dept: Department) => void;
    updateDepartment: (id: string, data: Partial<Department>) => void;
    addWorkGroup: (group: WorkGroup) => void;
    deleteWorkGroup: (id: string) => void;

    // Logic Validation
    checkChronologyIssue: (record: ProcurementRecord) => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);
    const [serverErrorMessage, setServerErrorMessage] = useState('');

    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    // Raw Data (All from DB)
    const [rawProcurements, setRawProcurements] = useState<ProcurementRecord[]>([]);
    const [rawReceivings, setRawReceivings] = useState<ReceivingReport[]>([]);
    const [rawConsiderations, setRawConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: [],
        workGroups: []
    });

    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            // Fetch Users
            const userRes = await fetch(`${API_URL}/users`);
            if (!userRes.ok) {
                const errorData = await userRes.json().catch(() => ({ error: userRes.statusText }));
                throw new Error(errorData.error || `User Fetch Failed (${userRes.status})`);
            }
            const userData = await userRes.json();
            setUsers(userData);

            // Fetch Business Data
            const dataRes = await fetch(`${API_URL}/data`);
            if (!dataRes.ok) {
                const errorData = await dataRes.json().catch(() => ({ error: dataRes.statusText }));
                throw new Error(errorData.error || `Data Fetch Failed (${dataRes.status})`);
            }
            const data = await dataRes.json();

            setRawProcurements(data.procurements);
            setRawReceivings(data.receivings);
            setRawConsiderations(data.considerations);
            setSettings(prev => ({
                ...prev,
                departments: data.settings.departments,
                categories: data.settings.categories,
                workGroups: data.settings.workGroups || []
            }));

        } catch (error: any) {
            console.error("Backend Error:", error);
            setServerError(true);
            setServerErrorMessage(error.message || `Failed to connect to server at Port ${BACKEND_PORT}`);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const savedUser = localStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => { fetchData(); };

    // --- VISIBILITY LOGIC ---
    // User sees data ONLY if they are ADMIN or the data belongs to their WORK GROUP
    const visibleData = useMemo(() => {
        if (!currentUser) return { procurements: [], receivings: [], considerations: [] };

        if (currentUser.role === 'ADMIN') {
            return {
                procurements: rawProcurements,
                receivings: rawReceivings,
                considerations: rawConsiderations
            };
        }

        // Standard User: Filter by WorkGroup
        const userDept = settings.departments.find(d => d.id === currentUser.departmentId);
        const userWorkGroupId = userDept?.workGroupId;

        if (!userWorkGroupId) {
            // If user has no work group, they only see what they created (fallback)
            const myProcs = rawProcurements.filter(p => p.createdBy === currentUser.id);
            return {
                procurements: myProcs,
                receivings: rawReceivings.filter(r => myProcs.some(p => p.requestId === r.requestId)),
                considerations: rawConsiderations.filter(c => myProcs.some(p => p.requestId === c.requestId))
            };
        }

        // Get all Departments in this Work Group
        const allowedDeptIds = settings.departments
            .filter(d => d.workGroupId === userWorkGroupId)
            .map(d => d.id);

        const allowedProcs = rawProcurements.filter(p => {
            // Check explicit department ID on record
            if (p.departmentId && allowedDeptIds.includes(p.departmentId)) return true;
            // Fallback: Check creator's department
            const creator = users.find(u => u.id === p.createdBy);
            return creator?.departmentId && allowedDeptIds.includes(creator.departmentId);
        });

        // Filter linked data based on allowed procurements
        const allowedRequestIds = new Set(allowedProcs.map(p => p.requestId));

        return {
            procurements: allowedProcs,
            receivings: rawReceivings.filter(r => allowedRequestIds.has(r.requestId)),
            considerations: rawConsiderations.filter(c => allowedRequestIds.has(c.requestId))
        };

    }, [currentUser, rawProcurements, rawReceivings, rawConsiderations, settings.departments, users]);


    // --- Auth Functions ---
    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: u, password: p })
            });

            const contentType = res.headers.get("content-type");
            if (!contentType || !contentType.includes("application/json")) {
                console.error("Server returned non-JSON. Check Port.");
                throw new Error(`Server connection failed (Port ${BACKEND_PORT}).`);
            }

            const result = await res.json();

            if (!res.ok) {
                throw new Error(result.message || result.error || 'Server Error');
            }

            if (result.success) {
                setCurrentUser(result.user);
                localStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e: any) {
            console.error("Login Error:", e);
            return { success: false, message: e.message || "เชื่อมต่อเซิร์ฟเวอร์ไม่ได้" };
        }
    };

    const logout = () => { setCurrentUser(null); localStorage.removeItem('procurement_session_user'); };

    const registerUser = async (userData: Omit<User, 'id' | 'createdAt'>) => {
        try {
            const newUser = { ...userData, id: Math.random().toString(36).substr(2, 9) };
            await fetch(`${API_URL}/register`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newUser) });
            fetchData(); return true;
        } catch (e) { return false; }
    };

    const deleteUser = async (id: string) => { updateUser(id, { status: 'SUSPENDED' }); };

    const updateUser = async (id: string, data: Partial<User>) => {
        try {
            await fetch(`${API_URL}/users/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
        } catch(e) { console.error(e); }
    };

    // --- Business Logic ---
    const getThaiYear = (dateString: string) => new Date(dateString).getFullYear() + 543;

    const parseRunningNumber = (officialNumber: string | null) => {
        if (!officialNumber) return 0;
        const parts = officialNumber.split('/');
        const match = parts[0]?.match(/(\d+)$/);
        return match ? parseInt(match[1], 10) : 0;
    };

    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        if (amount <= 5000) return null;

        // Find department prefix
        const currentDeptId = currentUser?.departmentId;
        const currentDept = settings.departments?.find(d => d.id === currentDeptId);
        const prefix = currentDept?.prefix ? currentDept.prefix.trim() : '';

        const thaiYear = getThaiYear(dateStr);

        // Filter existing by same department and year (Using RAW data to ensure uniqueness across DB)
        const existingInGroup = rawProcurements.filter(p => {
            if (p.type !== type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;

            // Try to match department
            let recordDeptId = p.departmentId || users.find(u => u.id === p.createdBy)?.departmentId;
            return recordDeptId === currentDeptId;
        });

        let maxNum = 0;
        existingInGroup.forEach(p => {
            const num = parseRunningNumber(p.officialNumber);
            if (!isNaN(num) && num > maxNum) maxNum = num;
        });
        return `${prefix ? prefix + ' ' : ''}${maxNum + 1}/${thaiYear}`;
    };

    const validateChronology = (type: RecordType, dateStr: string): { valid: boolean, message?: string } => {
        const thaiYear = getThaiYear(dateStr);
        const currentDeptId = currentUser?.departmentId;

        const existingInGroup = rawProcurements.filter(p => {
            if (p.type !== type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;
            let recordDeptId = p.departmentId || users.find(u => u.id === p.createdBy)?.departmentId;
            return recordDeptId === currentDeptId;
        });

        if (existingInGroup.length === 0) return { valid: true };

        let maxNum = 0;
        let maxRecord: ProcurementRecord | null = null;

        existingInGroup.forEach(p => {
            const num = parseRunningNumber(p.officialNumber);
            if (num > maxNum) { maxNum = num; maxRecord = p; }
        });

        if (maxRecord) {
            const latestDate = new Date((maxRecord as ProcurementRecord).requestDate).getTime();
            const newDate = new Date(dateStr).getTime();
            if (newDate < latestDate) {
                return { 
                    valid: false, 
                    message: `⚠️ วันที่ย้อนหลังกว่าเลขที่ล่าสุด\nเลขที่ล่าสุด: ${(maxRecord as ProcurementRecord).officialNumber}\nลงวันที่: ${(maxRecord as ProcurementRecord).requestDate}\nคุณกำลังบันทึก: ${dateStr}` 
                };
            }
        }
        return { valid: true };
    };

    const checkChronologyIssue = (record: ProcurementRecord): boolean => {
        if (!record.officialNumber || !record.requestDate) return false;

        const currentNum = parseRunningNumber(record.officialNumber);
        const currentDate = new Date(record.requestDate).getTime();
        const thaiYear = getThaiYear(record.requestDate);

        let ownerDeptId = record.departmentId || users.find(u => u.id === record.createdBy)?.departmentId;

        // Use visible data for display check
        return visibleData.procurements.some(p => {
            if (p.type !== record.type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;

            let pDeptId = p.departmentId || users.find(u => u.id === p.createdBy)?.departmentId;
            if (pDeptId !== ownerDeptId) return false;

            const pNum = parseRunningNumber(p.officialNumber);
            const pDate = new Date(p.requestDate).getTime();

            return (pNum < currentNum && pDate > currentDate); 
        });
    };

    const addProcurement = async (data: any, force = false) => {
        if (data.amount > 5000 && !force) {
            const validation = validateChronology(data.type, data.requestDate);
            if (!validation.valid) return { success: false, isWarning: true, message: validation.message };
        }

        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);
        const newRecord = { 
            ...data, 
            id: Math.random().toString(36).substr(2, 9), 
            createdAt: Date.now(), 
            officialNumber, 
            departmentId: currentUser?.departmentId, 
            createdBy: currentUser?.id || 'unknown' 
        };

        try {
            await fetch(`${API_URL}/procurements`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newRecord) });
            setRawProcurements(prev => [...prev, newRecord]);
            return { success: true };
        } catch(e) { return { success: false, message: "Server Error" }; }
    };

    const updateProcurement = async (id: string, data: Partial<ProcurementRecord>) => {
        const currentItem = rawProcurements.find(p => p.id === id);
        if (!currentItem) return;

        let newOfficialNumber = currentItem.officialNumber;
        const amount = data.amount !== undefined ? data.amount : currentItem.amount;
        const reqDate = data.requestDate || currentItem.requestDate;

        if (amount > 5000 && !newOfficialNumber) {
            newOfficialNumber = generateRunningNumber(currentItem.type, amount, reqDate);
        } else if (amount <= 5000) {
            newOfficialNumber = null;
        }

        const payload = { ...data, officialNumber: newOfficialNumber };
        try {
            await fetch(`${API_URL}/procurements/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
            setRawProcurements(prev => prev.map(p => p.id === id ? {...p, ...payload} : p));
        } catch(e) { console.error(e); }
    };

    const deleteProcurement = async (id: string) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
        setRawProcurements(prev => prev.filter(p => p.id !== id));
    };

    const addReceiving = async (data: any) => {
        const newRecord = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() };
        await fetch(`${API_URL}/receivings`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newRecord) });
        setRawReceivings(prev => [...prev, newRecord]);
    };

    const deleteReceiving = async (id: string) => {
        await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' });
        setRawReceivings(prev => prev.filter(r => r.id !== id));
    };

    const addConsideration = async (record: any) => {
        const newRecord = { ...record, id: record.id || Math.random().toString(36).substr(2, 9) };
        await fetch(`${API_URL}/considerations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newRecord) });
        setRawConsiderations(prev => [...prev, newRecord]);
    };

    const upsertReceiving = async (requestId: string, number: string, date: string) => {
        const procurement = rawProcurements.find(p => p.requestId === requestId);
        const payload = { requestId, deliveryNoteNo: number, receiveDate: date, category: procurement?.category || '' };
        await fetch(`${API_URL}/receivings/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
        fetchData();
    };

    const upsertConsideration = async (requestId: string, number: string, date: string) => {
        const payload = { id: Math.random().toString(36).substr(2, 9), requestId, considerationNumber: number, considerationDate: date };
        await fetch(`${API_URL}/considerations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
        fetchData();
    };

    const getLinkedData = (requestId: string) => {
        const receiving = rawReceivings.find(r => r.requestId === requestId);
        const consideration = rawConsiderations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = async (s: Partial<AppSettings>) => { setSettings(prev => ({ ...prev, ...s })); };

    const addDepartment = async (dept: Department) => {
        try {
            await fetch(`${API_URL}/department`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dept) });
            setSettings(prev => ({ ...prev, departments: [...prev.departments, dept] }));
        } catch(e) { console.error(e); }
    };

    const updateDepartment = async (id: string, data: Partial<Department>) => {
        try {
            await fetch(`${API_URL}/department/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            setSettings(prev => ({
                ...prev,
                departments: prev.departments.map(d => d.id === id ? { ...d, ...data } : d)
            }));
        } catch(e) { console.error(e); }
    };

    const addWorkGroup = async (group: WorkGroup) => {
        try {
            await fetch(`${API_URL}/workgroup`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(group) });
            setSettings(prev => ({ ...prev, workGroups: [...(prev.workGroups || []), group] }));
        } catch(e) { console.error(e); }
    };

    const deleteWorkGroup = async (id: string) => {
        try {
            await fetch(`${API_URL}/workgroup/${id}`, { method: 'DELETE' });
            setSettings(prev => ({ ...prev, workGroups: prev.workGroups?.filter(g => g.id !== id) || [] }));
        } catch(e) { console.error(e); }
    };

    return (
        <AppContext.Provider value={{
            isLoading, serverError, serverErrorMessage, retryConnection,
            procurements: visibleData.procurements, 
            receivings: visibleData.receivings, 
            considerations: visibleData.considerations,
            settings, currentUser, users,
            login, logout, registerUser, deleteUser, updateUser, addProcurement, updateProcurement, deleteProcurement,
            addReceiving, upsertReceiving, deleteReceiving, addConsideration, upsertConsideration, getLinkedData, updateSettings,
            addDepartment, updateDepartment, addWorkGroup, deleteWorkGroup,
            checkChronologyIssue
        }}>
            {children}
        </AppContext.Provider>
    );
};

