import React, { useState } from 'react';
import { useApp } from '../services/store';
import { Save, Plus, Trash2, Edit2, X, Check, Layers, Building, Power, PowerOff, AlertCircle, Briefcase } from 'lucide-react';
import { ProcurementCategory, Department, WorkGroup } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, updateSettings, addDepartment, updateDepartment, addWorkGroup, deleteWorkGroup } = useApp();
    const [localSettings, setLocalSettings] = useState(settings);
    const [saved, setSaved] = useState(false);

    // --- Confirmation UI State ---
    // แก้ไข: ใช้ type: string เพื่อรองรับ action type ใหม่ๆ ได้โดยไม่ติด TypeScript Error
    const [confirmAction, setConfirmAction] = useState<{
        type: string;
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // --- Work Group State ---
    const [newWorkGroupName, setNewWorkGroupName] = useState('');

    // --- Department State ---
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptRequestPrefix, setNewDeptRequestPrefix] = useState('');
    const [newDeptWorkGroup, setNewDeptWorkGroup] = useState('');

    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState('');
    const [editDeptRequestPrefix, setEditDeptRequestPrefix] = useState('');
    const [editDeptWorkGroup, setEditDeptWorkGroup] = useState('');

    // --- Category State ---
    const [newCategoryName, setNewCategoryName] = useState('');
    const [newCategoryDept, setNewCategoryDept] = useState('');
    const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
    const [editCatName, setEditCatName] = useState('');
    const [editCatDept, setEditCatDept] = useState('');

    const handleSavePrefixRequest = (e: React.FormEvent) => {
        e.preventDefault();
        setConfirmAction({
            type: 'PREFIX',
            title: 'ยืนยันการบันทึกรูปแบบเลขที่?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงรูปแบบเลขที่ใบขอใช่หรือไม่?',
            onConfirm: () => {
                updateSettings(localSettings);
                setSaved(true);
                setTimeout(() => setSaved(false), 2000);
                setConfirmAction(null);
            }
        });
    };

    // --- Work Group Handlers ---
    const addNewWorkGroup = () => {
        if (!newWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'ADD_GROUP',
            title: 'ยืนยันเพิ่มกลุ่มงาน?',
            message: `ต้องการเพิ่มกลุ่มงาน "${newWorkGroupName}" ใช่หรือไม่?`,
            onConfirm: () => {
                addWorkGroup({
                    id: `group_${Date.now()}`,
                    name: newWorkGroupName.trim(),
                    isActive: true
                });
                setNewWorkGroupName('');
                setConfirmAction(null);
            }
        });
    };

    const handleDeleteWorkGroup = (group: WorkGroup) => {
        setConfirmAction({
            type: 'DEL_GROUP',
            title: 'ยืนยันการลบกลุ่มงาน?',
            message: `ต้องการลบกลุ่มงาน "${group.name}" ใช่หรือไม่? ฝ่ายที่สังกัดกลุ่มงานนี้อาจได้รับผลกระทบ`,
            onConfirm: () => {
                deleteWorkGroup(group.id);
                setConfirmAction(null);
            }
        });
    };

    // --- Department Handlers ---
    const addDepartmentRequest = () => {
        if (!newDeptName.trim()) return;
        setConfirmAction({
            type: 'ADD_DEPT',
            title: 'ยืนยันการเพิ่มฝ่าย/งาน?',
            message: `ต้องการเพิ่มฝ่าย "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                const newDept: Department = {
                    id: `dept_${Date.now()}`,
                    name: newDeptName.trim(),
                    prefix: newDeptPrefix.trim(),
                    requestPrefix: newDeptRequestPrefix.trim(),
                    workGroupId: newDeptWorkGroup || undefined,
                    isActive: true
                };
                addDepartment(newDept);
                setNewDeptName('');
                setNewDeptPrefix('');
                setNewDeptRequestPrefix('');
                setNewDeptWorkGroup('');
                setConfirmAction(null);
            }
        });
    };

    const toggleDeptStatus = (id: string) => {
        const dept = settings.departments.find(d => d.id === id);
        if(dept) {
            updateDepartment(id, { isActive: !dept.isActive });
        }
    };

    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id);
        setEditDeptName(dept.name);
        setEditDeptPrefix(dept.prefix || '');
        setEditDeptRequestPrefix(dept.requestPrefix || '');
        setEditDeptWorkGroup(dept.workGroupId || '');
    };

    const saveEditDeptRequest = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT',
            title: 'ยืนยันการแก้ไขข้อมูล?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงชื่อฝ่ายใช่หรือไม่?',
            onConfirm: () => {
                updateDepartment(editingDeptId, {
                    name: editDeptName.trim(),
                    prefix: editDeptPrefix.trim(),
                    requestPrefix: editDeptRequestPrefix.trim(),
                    workGroupId: editDeptWorkGroup || undefined
                });
                setEditingDeptId(null);
                setConfirmAction(null);
            }
        });
    };

    // --- Category Handlers ---
    const addCategoryRequest = () => {
        if (!newCategoryName.trim()) return;
        setConfirmAction({
            type: 'ADD_CAT',
            title: 'ยืนยันการเพิ่มหมวดพัสดุ?',
            message: `ต้องการเพิ่มหมวดพัสดุ "${newCategoryName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                const newCat: ProcurementCategory = {
                    id: Date.now().toString(),
                    name: newCategoryName.trim(),
                    departmentId: newCategoryDept || undefined,
                    isActive: true
                };
                // Optimistic update handled by fetching data or local state if needed
                // For now, we rely on store update which triggers re-fetch or state update
                // But since addCategory isn't exposed directly in store interface in previous context, 
                // we assume updateSettings handles it or we need to add it to store.
                // Assuming updateSettings can handle category list update for now based on previous code.
