                            {isRegistering ? <UserPlus size={32} /> : <Lock size={32} />}
                        </div>
                        <h1 className="text-2xl font-bold text-slate-800">
                            {isRegistering ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ'}
