const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
const port = 3002; // Backend runs on 3002

// ==========================================
// ตั้งค่า CORS (Allow All)
// ==========================================
app.use(cors({
    origin: true, 
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    credentials: true
}));

app.options('*', cors());
app.use(bodyParser.json());

// ==========================================
// ตั้งค่า Database
// ==========================================
const DB_CONFIG = {
    host: '127.0.0.1',      // <-- ใช้ 127.0.0.1 เพื่อความเสถียร
    user: 'root',           
    password: '',           // <-- ⚠️ หาก Database ของคุณมีรหัสผ่าน ให้ใส่ตรงนี้
    database: 'procurement_db', 
    port: 3306
};

// Global DB Connection Status
let isDbConnected = false;
let dbConnectionError = null;

// --- Database Connection Pool ---
const db = mysql.createPool({
    ...DB_CONFIG,
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
});

// Helper for Promisified Query
const query = (sql, params) => {
    return new Promise((resolve, reject) => {
        db.query(sql, params, (err, results) => {
            if (err) return reject(err);
            resolve(results);
        });
    });
};

// --- Auto-Migration / Init Function ---
async function initDatabase() {
    console.log('🔄 Checking database schema...');
    try {
        // Create Work Groups Table (New)
        await query(`CREATE TABLE IF NOT EXISTS work_groups (
            id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, is_active BOOLEAN DEFAULT TRUE
        )`);

        await query(`CREATE TABLE IF NOT EXISTS departments (
            id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, prefix VARCHAR(20), request_prefix VARCHAR(100), work_group_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE
        )`);
        await query(`CREATE TABLE IF NOT EXISTS procurement_categories (
            id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, department_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE
        )`);
        await query(`CREATE TABLE IF NOT EXISTS users (
            id VARCHAR(50) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL,
            name VARCHAR(100) NOT NULL, email VARCHAR(100), role ENUM('ADMIN', 'USER') DEFAULT 'USER',
            department_id VARCHAR(50), status ENUM('PENDING', 'ACTIVE', 'SUSPENDED') DEFAULT 'PENDING', created_at BIGINT
        )`);
        await query(`CREATE TABLE IF NOT EXISTS procurements (
            id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, request_date DATE NOT NULL,
            category VARCHAR(255), item_count INT DEFAULT 0, amount DECIMAL(15, 2) DEFAULT 0.00,
            company VARCHAR(255), remarks TEXT, official_number VARCHAR(50),
            type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL, department_id VARCHAR(50),
            created_by VARCHAR(50), created_at BIGINT
        )`);
        await query(`CREATE TABLE IF NOT EXISTS receivings (
            id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, delivery_note_no VARCHAR(50),
            receive_date DATE, category VARCHAR(255), created_at BIGINT
        )`);
        await query(`CREATE TABLE IF NOT EXISTS considerations (
            id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, consideration_number VARCHAR(50), consideration_date DATE
        )`);

        // Migrations
        const addColumn = async (table, col, def) => {
            try {
                const cols = await query(`SHOW COLUMNS FROM ${table} LIKE ?`, [col]);
                if (cols.length === 0) {
                    console.log(`✨ Migrating: Adding column '${col}' to table '${table}'`);
                    await query(`ALTER TABLE ${table} ADD COLUMN ${col} ${def}`);
                }
            } catch (e) {
                console.error(`⚠️ Migration check failed for ${table}.${col}: ${e.message}`);
            }
        };

        await addColumn('departments', 'prefix', 'VARCHAR(20)');
        await addColumn('departments', 'request_prefix', 'VARCHAR(100)'); // For "สพ ๐๐๓๓..."
        await addColumn('departments', 'work_group_id', 'VARCHAR(50)'); // Link to Work Group
        await addColumn('users', 'department_id', 'VARCHAR(50)');
        await addColumn('users', 'email', 'VARCHAR(100)');
        await addColumn('procurements', 'department_id', 'VARCHAR(50)');
        await addColumn('procurement_categories', 'department_id', 'VARCHAR(50)');

        // Seed Admin & Default Group
        const users = await query('SELECT count(*) as count FROM users');
        if (users[0].count === 0) {
            console.log('🌱 Seeding default data...');
            // Create Default Group
            await query("INSERT INTO work_groups (id, name) VALUES ('group_1', 'กลุ่มงานบริหารทั่วไป')");

            // Create Default Dept
            const depts = await query("SELECT count(*) as count FROM departments");
            if(depts[0].count === 0) {
                 await query("INSERT INTO departments (id, name, prefix, request_prefix, work_group_id) VALUES ('dept_1', 'ฝ่ายบริหารทั่วไป', 'บห.', 'สพ ๐๐๓๓.๐๖/๑/๑/', 'group_1')");
            }
            await query("INSERT INTO users (id, username, password, name, email, role, department_id, status, created_at) VALUES ('1', 'admin', 'password', 'ผู้ดูแลระบบ', 'admin@system.com', 'ADMIN', 'dept_1', 'ACTIVE', ?)", [Date.now()]);
        }

        console.log('✅ Database Schema verified.');
    } catch (e) {
        console.error('❌ Database Initialization Failed:', e.message);
    }
}

// Check Connection
db.getConnection((err, connection) => {
    if (err) {
        isDbConnected = false;
        dbConnectionError = err.message;
        console.error('\n❌ ERROR: ไม่สามารถเชื่อมต่อฐานข้อมูลได้');
        console.error(`   Code: ${err.code}`);
        console.error(`   Message: ${err.message}`);

        if (err.code === 'ER_ACCESS_DENIED_ERROR') {
            console.error('\n⚠️  คำแนะนำ: รหัสผ่าน Database ไม่ถูกต้อง');
            console.error('   กรุณาตรวจสอบไฟล์ "server/index.js" บรรทัด DB_CONFIG');
            console.error('   และแก้ไข password ให้ตรงกับ MySQL ในเครื่องของคุณ');
        } else if (err.code === 'ECONNREFUSED') {
            console.error('\n⚠️  คำแนะนำ: MySQL อาจจะยังไม่เปิด');
            console.error('   กรุณาเปิดโปรแกรม XAMPP หรือ MySQL Server');
        }
        console.log('');
    } else {
        isDbConnected = true;
        dbConnectionError = null;
        console.log('✅ Connected to MySQL Server successfully!');
        connection.release();
        initDatabase();
    }
});

