import React, { useState } from 'react';
import { useApp } from '../services/store';
import { Lock, User, UserPlus, LogIn, AlertCircle, Building, CheckCircle, HelpCircle, Mail } from 'lucide-react';

const LoginPage: React.FC = () => {
    const { login, registerUser, settings } = useApp();
    const [isRegistering, setIsRegistering] = useState(false);

    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [deptId, setDeptId] = useState('');
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [showRegisterConfirm, setShowRegisterConfirm] = useState(false);

    const handleFormSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setSuccess('');

        if (isRegistering) {
            setShowRegisterConfirm(true);
        } else {
            const result = await login(username, password);
            if (!result.success) {
                setError(result.message || 'เกิดข้อผิดพลาดในการเข้าสู่ระบบ');
            }
        }
    };

    const confirmRegistration = async () => {
        if (!username || !password || !name || !email) {
            setError('กรุณากรอกข้อมูลให้ครบถ้วน');
            setShowRegisterConfirm(false);
            return;
        }

        const resultReal = await registerUser({
            username,
            password,
            name,
            email,
            role: 'USER',
            departmentId: deptId || undefined,
            status: 'PENDING'
        });

        if (resultReal) {
            setSuccess('สมัครสมาชิกสำเร็จ! กรุณารอผู้ดูแลระบบอนุมัติการใช้งานก่อนเข้าสู่ระบบ');
            setIsRegistering(false);
            setUsername('');
            setPassword('');
            setName('');
            setEmail('');
            setDeptId('');
        } else {
            setError('ชื่อผู้ใช้งานนี้ถูกใช้ไปแล้ว');
        }
        setShowRegisterConfirm(false);
    };

    return (
        <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden flex flex-col md:flex-row-reverse relative">

                <div className="w-full p-8 md:p-10">
                    <div className="text-center mb-8">
                        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-blue-100 text-blue-600 mb-4 shadow-inner">
                            {/* Use static div wrapper to prevent removeChild error during toggle */}
