                                {isRegistering ? <UserPlus size={32} /> : <Lock size={32} />}
                            </div>
                        </div>
                        <h1 className="text-2xl font-bold text-slate-800">
                            {isRegistering ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ'}
                        </h1>
                        <p className="text-slate-500 text-sm mt-1">
                            ระบบทะเบียนจัดซื้อ จัดจ้าง
                        </p>
                    </div>

                    <form onSubmit={handleFormSubmit} className="space-y-4">
                        {error && (
                            <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-start">
                                <AlertCircle size={16} className="mr-2 flex-shrink-0 mt-0.5" />
                                <span>{error}</span>
                            </div>
                        )}
                        {success && (
                            <div className="bg-emerald-50 text-emerald-700 p-4 rounded-lg text-sm flex items-start border border-emerald-100">
                                <CheckCircle size={18} className="mr-2 flex-shrink-0 mt-0.5" />
                                <span>{success}</span>
                            </div>
                        )}

                        {/* Separate block for registration inputs to maintain stable DOM structure */}
