    purchaseCount: number;
    hiringCount: number;
}

// --- Auth & Users ---
export type UserRole = 'ADMIN' | 'USER';
export type UserStatus = 'PENDING' | 'ACTIVE' | 'SUSPENDED';

export interface User {
    id: string;
    username: string;
    password: string; // Note: In a real app, never store plain text passwords
