    if(departmentId !== undefined) { sql+='department_id = ?, '; params.push(departmentId); }
    if(isActive !== undefined) { sql+='is_active = ?, '; params.push(isActive); }
    sql = sql.slice(0, -2) + ' WHERE id = ?'; params.push(req.params.id);
    await query(sql, params); res.json({success: true});
});

app.listen(port, '0.0.0.0', () => {
    console.log(`🚀 Backend API running at http://0.0.0.0:${port}`);
});

