const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
const port = 3002;

app.use(cors({ origin: true, methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'], allowedHeaders: ['Content-Type', 'Authorization'], credentials: true }));
app.use(bodyParser.json());

const DB_CONFIG = { host: '127.0.0.1', user: 'root', password: '', database: 'procurement_db', port: 3306 };
const db = mysql.createPool({ ...DB_CONFIG, waitForConnections: true, connectionLimit: 10 });
const query = (sql, params) => new Promise((resolve, reject) => db.query(sql, params, (err, res) => err ? reject(err) : resolve(res)));

async function initDatabase() {
    try {
        await query(`CREATE TABLE IF NOT EXISTS work_groups (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, is_active BOOLEAN DEFAULT TRUE)`);
        await query(`CREATE TABLE IF NOT EXISTS departments (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, prefix VARCHAR(20), request_prefix VARCHAR(100), work_group_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE)`);
        await query(`CREATE TABLE IF NOT EXISTS users (id VARCHAR(50) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), role ENUM('ADMIN', 'USER') DEFAULT 'USER', department_id VARCHAR(50), status ENUM('PENDING', 'ACTIVE', 'SUSPENDED') DEFAULT 'PENDING', created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS procurements (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, request_date DATE NOT NULL, category VARCHAR(255), item_count INT DEFAULT 0, amount DECIMAL(15, 2) DEFAULT 0.00, company VARCHAR(255), remarks TEXT, official_number VARCHAR(50), type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL, department_id VARCHAR(50), created_by VARCHAR(50), created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS receivings (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, delivery_note_no VARCHAR(50), receive_date DATE, category VARCHAR(255), created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS considerations (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, consideration_number VARCHAR(50), consideration_date DATE)`);

        const addCol = async (t, c, d) => {
            const cols = await query(`SHOW COLUMNS FROM ${t} LIKE ?`, [c]);
            if (cols.length === 0) await query(`ALTER TABLE ${t} ADD COLUMN ${c} ${d}`);
        };
        await addCol('departments', 'work_group_id', 'VARCHAR(50)');
        await addCol('departments', 'request_prefix', 'VARCHAR(100)');

        console.log('✅ Database v1.3.2 Ready');
    } catch (e) { console.error('❌ Init DB Failed:', e.message); }
}

initDatabase();

app.post('/api/login', async (req, res) => {
    const { username, password } = req.body;
    const users = await query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
    if (users.length > 0) {
        const u = users[0];
        if (u.status !== 'ACTIVE') return res.json({ success: false, message: 'บัญชีไม่อยู่ในสถานะใช้งาน' });
        res.json({ success: true, user: { id: u.id, username: u.username, name: u.name, role: u.role, departmentId: u.department_id } });
    } else res.json({ success: false, message: 'Username หรือ Password ไม่ถูกต้อง' });
});

app.get('/api/data', async (req, res) => {
    try {
        const [p, r, c, d, w] = await Promise.all([
            query('SELECT * FROM procurements'), query('SELECT * FROM receivings'),
            query('SELECT * FROM considerations'), query('SELECT * FROM departments'),
            query('SELECT * FROM work_groups')
        ]);
        res.json({
            procurements: p.map(x => ({ ...x, requestId: x.request_id, requestDate: x.request_date, officialNumber: x.official_number, departmentId: x.department_id, createdBy: x.created_by, createdAt: x.created_at })),
            receivings: r.map(x => ({ ...x, requestId: x.request_id, deliveryNoteNo: x.delivery_note_no, receiveDate: x.receive_date })),
            considerations: c.map(x => ({ ...x, requestId: x.request_id, considerationNumber: x.consideration_number, considerationDate: x.consideration_date })),
            settings: { departments: d.map(x => ({ ...x, workGroupId: x.work_group_id, requestPrefix: x.request_prefix, isActive: x.is_active === 1 })), workGroups: w, categories: [] }
        });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/procurements', async (req, res) => {
    const p = req.body;
    await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
        [p.id, p.requestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, p.officialNumber, p.type, p.departmentId, p.createdBy, p.createdAt]);
    res.json({ success: true });
});

app.patch('/api/department/:id', async (req, res) => {
    const d = req.body;
    await query('UPDATE departments SET name=?, prefix=?, request_prefix=?, work_group_id=? WHERE id=?', [d.name, d.prefix, d.requestPrefix, d.workGroupId, req.params.id]);
    res.json({ success: true });
});

app.post('/api/workgroup', async (req, res) => {
    const g = req.body;
    await query('INSERT INTO work_groups (id, name) VALUES (?,?)', [g.id, g.name]);
    res.json({ success: true });
});

app.get('/api/users', async (req, res) => { res.json(await query('SELECT id, username, name, role, department_id, status FROM users')); });

app.listen(port, () => console.log(`🚀 v1.3.2 Backend on port ${port}`));

