const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
const port = 3002;

app.use(cors({ origin: true, methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'], allowedHeaders: ['Content-Type', 'Authorization'], credentials: true }));
app.use(bodyParser.json());

const DB_CONFIG = { host: '127.0.0.1', user: 'root', password: '', database: 'procurement_db', port: 3306 };
const db = mysql.createPool({ ...DB_CONFIG, waitForConnections: true, connectionLimit: 10 });
const query = (sql, params) => new Promise((resolve, reject) => db.query(sql, params, (err, res) => err ? reject(err) : resolve(res)));

async function initDatabase() {
    try {
        await query(`CREATE TABLE IF NOT EXISTS work_groups (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, is_active BOOLEAN DEFAULT TRUE)`);
        await query(`CREATE TABLE IF NOT EXISTS departments (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, prefix VARCHAR(20), request_prefix VARCHAR(100), work_group_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE)`);
        await query(`CREATE TABLE IF NOT EXISTS users (id VARCHAR(50) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), role ENUM('ADMIN', 'USER') DEFAULT 'USER', department_id VARCHAR(50), status ENUM('PENDING', 'ACTIVE', 'SUSPENDED') DEFAULT 'PENDING', created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS procurements (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, request_date DATE NOT NULL, category VARCHAR(255), item_count INT DEFAULT 0, amount DECIMAL(15, 2) DEFAULT 0.00, company VARCHAR(255), remarks TEXT, official_number VARCHAR(50), type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL, department_id VARCHAR(50), created_by VARCHAR(50), created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS receivings (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, delivery_note_no VARCHAR(50), receive_date DATE, category VARCHAR(255), created_at BIGINT)`);
        await query(`CREATE TABLE IF NOT EXISTS considerations (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, consideration_number VARCHAR(50), consideration_date DATE)`);

        const addCol = async (t, c, d) => {
            const cols = await query(`SHOW COLUMNS FROM ${t} LIKE ?`, [c]);
            if (cols.length === 0) await query(`ALTER TABLE ${t} ADD COLUMN ${c} ${d}`);
        };
        await addCol('departments', 'work_group_id', 'VARCHAR(50)');
        await addCol('departments', 'request_prefix', 'VARCHAR(100)');

        console.log('✅ v1.3.2 Database Ready');
    } catch (e) { console.error('❌ Init DB Failed:', e.message); }
}

initDatabase();

