                    <p className="text-slate-500 text-xs">จัดซื้อ (PO)</p>
                    <h3 className="text-xl font-bold">{totalPurchase.toLocaleString()}</h3>
                </div>
                <div className="bg-white p-5 rounded-xl border shadow-sm">
