                                                    {editingDeptId === dept.id ? <input className="border rounded px-1 w-full text-center" value={editDeptPrefix} onChange={e=>setEditDeptPrefix(e.target.value)}/> : dept.prefix || '-'}
                                                </td>
                                                <td className="px-3 py-2 text-center">
                                                    {editingDeptId === dept.id ? (
                                                        <div className="flex justify-center space-x-1">
                                                            <button onClick={saveEditDeptRequest} className="text-green-600"><Check size={14}/></button>
                                                            <button onClick={()=>setEditingDeptId(null)} className="text-red-600"><X size={14}/></button>
                                                        </div>
                                                    ) : (
                                                        <button onClick={()=>startEditDept(dept)} className="text-slate-400 hover:text-indigo-600"><Edit2 size={14}/></button>
                                                    )}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

