                                    <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                                        <div 
                                            className="h-full rounded-full bg-gradient-to-r from-blue-500 to-indigo-500 group-hover:from-blue-400 group-hover:to-indigo-400 transition-all duration-500 ease-out" 
                                            style={{ width: `${(cat.value / (categoryData[0]?.value || 1)) * 100}%` }}
