                                    const isPurchase = item.type === RecordType.PURCHASE;
                                    const isHiring = item.type === RecordType.HIRING;
                                    const themeColor = isPurchase ? 'text-blue-600 bg-blue-100' : isHiring ? 'text-violet-600 bg-violet-100' : 'text-amber-600 bg-amber-100';

