                                                    {isPurchase ? <ShoppingCart size={18} /> : isHiring ? <Briefcase size={18} /> : <Archive size={18} />}
                                                </div>
                                                <div>
                                                    <div className="flex items-center gap-2">
                                                        <span className="text-sm font-bold text-slate-800">{item.requestId}</span>
                                                        <span className="text-[10px] text-slate-400 bg-white border border-slate-200 px-1.5 rounded">{item.requestDate}</span>
