                    <div className="p-4">
                        <div className="flex space-x-2 mb-4">
                            <input className="flex-1 border rounded-lg px-3 py-1.5 text-sm" placeholder="ชื่อกลุ่มงาน..." value={newWorkGroupName} onChange={e => setNewWorkGroupName(e.target.value)} />
                            <button onClick={addNewWorkGroup} className="bg-orange-600 text-white px-3 rounded-lg"><Plus size={18}/></button>
                        </div>
                        <div className="space-y-2 max-h-[300px] overflow-y-auto">
                            {settings.workGroups?.map(g => (
