// Helper: Calculate Fiscal Year (Thai Government: Oct - Sep)
const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return new Date().getFullYear() + 543;
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return new Date().getFullYear() + 543;

    const month = date.getMonth(); // 0 = Jan, 9 = Oct
    const year = date.getFullYear();

    // If Month is Oct(9), Nov(10), Dec(11) -> Fiscal Year is next year
    return month >= 9 ? year + 1 + 543 : year + 543;
};

const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
        return (
            <div className="bg-white/95 backdrop-blur-sm p-4 rounded-xl shadow-xl border border-slate-100 text-sm">
                <p className="font-bold text-slate-800 mb-2">{label}</p>
                {payload.map((entry: any, index: number) => (
                    <div key={index} className="flex items-center justify-between gap-6 mb-1">
                        <span className="flex items-center text-xs text-slate-500">
                            <span className="w-2 h-2 rounded-full mr-2 shadow-sm" style={{ backgroundColor: entry.color }}></span>
                            {entry.name}
                        </span>
                        <span className="font-semibold text-slate-700 font-mono">
                            {entry.value.toLocaleString()}
                        </span>
                    </div>
                ))}
            </div>
        );
    }
    return null;
};

