};

const db = mysql.createPool({ ...DB_CONFIG, waitForConnections: true, connectionLimit: 10 });
const query = (sql, params) => new Promise((resolve, reject) => db.query(sql, params, (err, res) => err ? reject(err) : resolve(res)));

