// ==========================================
// 📦 DATABASE INITIALIZATION & REPAIR (v1.3.5)
// ==========================================
async function initDatabase() {
    try {
        console.log('🔄 Checking Database Encoding...');

        // 1. Force Database Default to UTF8MB4
        await query(`ALTER DATABASE procurement_db CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci`);

        // 2. Create Tables (If not exist)
        await query(`CREATE TABLE IF NOT EXISTS work_groups (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, is_active BOOLEAN DEFAULT TRUE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
        await query(`CREATE TABLE IF NOT EXISTS departments (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, prefix VARCHAR(20), request_prefix VARCHAR(100), work_group_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
        await query(`CREATE TABLE IF NOT EXISTS procurement_categories (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, department_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
        await query(`CREATE TABLE IF NOT EXISTS users (id VARCHAR(50) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), role ENUM('ADMIN', 'USER') DEFAULT 'USER', department_id VARCHAR(50), status ENUM('PENDING', 'ACTIVE', 'SUSPENDED') DEFAULT 'PENDING', created_at BIGINT) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
        await query(`CREATE TABLE IF NOT EXISTS procurements (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, request_date DATE NOT NULL, category VARCHAR(255), item_count INT DEFAULT 0, amount DECIMAL(15, 2) DEFAULT 0.00, company VARCHAR(255), remarks TEXT, official_number VARCHAR(50), type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL, department_id VARCHAR(50), created_by VARCHAR(50), created_at BIGINT) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
        await query(`CREATE TABLE IF NOT EXISTS receivings (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, delivery_note_no VARCHAR(50), receive_date DATE, category VARCHAR(255), created_at BIGINT) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
        await query(`CREATE TABLE IF NOT EXISTS considerations (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, consideration_number VARCHAR(50), consideration_date DATE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);

        // 3. Migration: Add columns if missing
        const addCol = async (t, c, d) => {
            try {
                const cols = await query(`SHOW COLUMNS FROM ${t} LIKE ?`, [c]);
                if (cols.length === 0) await query(`ALTER TABLE ${t} ADD COLUMN ${c} ${d}`);
            } catch(e) {}
        };
        await addCol('departments', 'work_group_id', 'VARCHAR(50)');
        await addCol('departments', 'request_prefix', 'VARCHAR(100)');

        // 4. 🛠️ REPAIR MODE: Fix "Alien Language" (Mojibake)
        // เทคนิค: แปลงคอลัมน์เป็น BINARY ก่อน แล้วค่อยแปลงกลับเป็น UTF8MB4 (ช่วยแก้อาการรับค่า UTF8 มาเก็บในตาราง Latin1)
        const repairTable = async (table, columns) => {
            try {
                // เช็คก่อนว่าตารางนี้ Encoding อะไร ถ้าเป็น latin1 อยู่ ต้องแก้
                const tableInfo = await query(`SELECT CCSA.character_set_name FROM information_schema.\`TABLES\` T, information_schema.\`COLLATION_CHARACTER_SET_APPLICABILITY\` CCSA WHERE CCSA.collation_name = T.table_collation AND T.table_schema = 'procurement_db' AND T.table_name = ?`, [table]);

                // แปลง Table Default ก่อน
                await query(`ALTER TABLE ${table} CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);

                // ถ้ามีข้อมูลเก่าที่เป็นภาษาต่างดาว เราจะพยายามซ่อมคอลัมน์ที่เป็นข้อความ
                for (const col of columns) {
                    try {
                        // Step 1: Change to BINARY (เก็บ Byte เดิมไว้)
                        await query(`ALTER TABLE ${table} MODIFY ${col} VARBINARY(255)`);
                        // Step 2: Change back to VARCHAR with Correct Charset (บอกมันว่า Byte นี้คือ UTF8 นะ)
                        await query(`ALTER TABLE ${table} MODIFY ${col} VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
                    } catch (e) {
                        // ข้ามถ้ามี error (เช่น column เป็น TEXT อาจต้องใช้ BLOB แทน)
                    }
                }
                console.log(`   - Repaired table: ${table}`);
            } catch (e) { console.error(`   - Failed to repair ${table}:`, e.message); }
        };

        // รายชื่อคอลัมน์ที่มักมีปัญหาภาษาไทย
        await repairTable('procurements', ['company', 'remarks', 'category', 'official_number', 'request_id']);
        await repairTable('users', ['name', 'email']);
        await repairTable('departments', ['name', 'prefix', 'request_prefix']);
        await repairTable('work_groups', ['name']);
        await repairTable('procurement_categories', ['name']);

        console.log('✅ Database v1.3.5 Connected (UTF-8 Enforced & Repaired)');
    } catch (e) { 
        console.error('❌ Database Connection Failed:', e.message); 
    }
}

