                <div className="p-4 border-t border-slate-700">
                    <button 
                        onClick={logout}
                        className="w-full flex items-center justify-center space-x-2 px-4 py-2 bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white rounded-lg transition-all"
                    >
                        <LogOut size={18} />
                        <span>ออกจากระบบ</span>
                    </button>
                    <div className="text-xs text-slate-500 text-center mt-4 leading-tight space-y-1">
                        <p>โรงพยาบาลสามชุก</p>
                        <p>กลุ่มงานสุขภาพดิจิทัล</p>
                    </div>
                </div>
            </div>
        </>
    );
};

export default Sidebar;

import React, { useState } from 'react';
import { AppProvider, useApp } from './services/store';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import ProcurementTable from './pages/ProcurementTable';
import SettingsPage from './pages/SettingsPage';
import LoginPage from './pages/LoginPage';
import UserManagementPage from './pages/UserManagementPage';
import PendingUsersPage from './pages/PendingUsersPage';
import ConsiderationPage from './pages/ConsiderationPage';
import { RecordType } from './types';
import { Menu, ServerCrash, RefreshCw } from 'lucide-react';

const MainApp: React.FC = () => {
    const { currentUser, serverError, serverErrorMessage, retryConnection, isLoading } = useApp();
    const [activeTab, setActiveTab] = useState('dashboard');
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    if (serverError) {
        return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-50 text-center p-6">
                <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-red-100">
                    <div className="mx-auto flex items-center justify-center h-20 w-20 rounded-full bg-red-100 mb-6 text-red-600 animate-pulse">
                        <ServerCrash size={40} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">ไม่สามารถเชื่อมต่อระบบได้</h2>
                    <p className="text-slate-500 mb-4">
                        กรุณาตรวจสอบว่าได้เปิดโปรแกรม Server (Backend) หรือไม่ <br/>
                        <code className="bg-slate-100 px-2 py-1 rounded text-xs mt-2 inline-block">Port: 3002</code>
                    </p>

                    {serverErrorMessage && (
                        <div className="mb-6 bg-red-50 text-red-700 text-xs p-3 rounded-lg text-left overflow-auto max-h-32 border border-red-200">
                            <strong>Technical Detail:</strong><br/>
                            {serverErrorMessage}
                        </div>
                    )}

                    <button 
                        onClick={retryConnection}
                        disabled={isLoading}
                        className="w-full flex items-center justify-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-semibold transition-all shadow-lg shadow-blue-200"
                    >
                        {isLoading ? (
                            <RefreshCw className="animate-spin" size={20} />
                        ) : (
                            <RefreshCw size={20} />
                        )}
                        <span>ลองเชื่อมต่อใหม่</span>
                    </button>
                </div>
            </div>
        );
    }

    if (!currentUser) {
        return <LoginPage />;
    }

    const renderContent = () => {
        switch (activeTab) {
            case 'dashboard':
                return <Dashboard />;
            case 'purchase':
                return <ProcurementTable type={RecordType.PURCHASE} title="ทะเบียนคุมจัดซื้อ (Purchase Orders)" />;
            case 'hiring':
                return <ProcurementTable type={RecordType.HIRING} title="ทะเบียนคุมจัดจ้าง (Hiring Orders)" />;
            case 'other':
                return <ProcurementTable type={RecordType.OTHER} title="ทะเบียนคุมอื่นๆ (Other Registry)" />;
            case 'consideration':
                return <ConsiderationPage />;
            case 'pending_users':
                return currentUser.role === 'ADMIN' ? <PendingUsersPage /> : <Dashboard />;
            case 'users':
                return currentUser.role === 'ADMIN' ? <UserManagementPage /> : <Dashboard />;
            case 'settings':
                return currentUser.role === 'ADMIN' ? <SettingsPage /> : <Dashboard />;
            default:
                return <Dashboard />;
        }
    };

    return (
        <div className="flex h-screen bg-slate-50 text-slate-900 font-sans relative">
            <Sidebar 
                activeTab={activeTab} 
                setActiveTab={setActiveTab} 
                isOpen={isSidebarOpen} 
                setIsOpen={setIsSidebarOpen}
            />

            <div className="flex-1 flex flex-col min-w-0 transition-all duration-300 lg:ml-64">
                {/* Mobile Header */}
                <header className="lg:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-40">
                    <button 
                        onClick={() => setIsSidebarOpen(true)}
                        className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg"
                    >
                        <Menu size={24} />
                    </button>
                    <h2 className="text-lg font-bold text-slate-800 truncate px-2">
                        {activeTab === 'dashboard' ? 'Dashboard' : 
                         activeTab === 'purchase' ? 'จัดซื้อ' : 
                         activeTab === 'hiring' ? 'จัดจ้าง' : 
                         activeTab === 'pending_users' ? 'รอยืนยัน' :
                         activeTab === 'other' ? 'อื่นๆ' : 'ระบบพัสดุ'}
                    </h2>
                    <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">
                        {currentUser.name.charAt(0)}
                    </div>
                </header>

                <main className="flex-1 overflow-y-auto">
                    {renderContent()}
                </main>
            </div>
        </div>
    );
};

const App: React.FC = () => {
    return (
        <AppProvider>
            <MainApp />
        </AppProvider>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { UserCog, User as UserIcon, Search, Edit, Check, Lock, Building, Trash2, RefreshCcw, Mail, Briefcase, AlertCircle, X, Power } from 'lucide-react';
import { UserRole, User, UserStatus } from '../types';

const UserManagementPage: React.FC = () => {
    const { users, currentUser, updateUser, registerUser, settings, deleteUser } = useApp();
    const [searchTerm, setSearchTerm] = useState('');

    // --- Add User Form State ---
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [newName, setNewName] = useState('');
    const [newEmail, setNewEmail] = useState('');
    const [newRole, setNewRole] = useState<UserRole>('USER');

    // Selection State for Add
    const [newWorkGroupId, setNewWorkGroupId] = useState('');
    const [newDeptId, setNewDeptId] = useState('');

    const [showAddConfirm, setShowAddConfirm] = useState(false);

    // --- Confirmation State ---
    const [suspendConfirm, setSuspendConfirm] = useState<{ id: string, name: string } | null>(null);
    const [reactivateConfirm, setReactivateConfirm] = useState<{ id: string, name: string } | null>(null);

    // --- Edit User State ---
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [showEditConfirm, setShowEditConfirm] = useState(false);

    // Selection State for Edit
    const [editWorkGroupId, setEditWorkGroupId] = useState('');

    const [editFormData, setEditFormData] = useState({
        name: '',
        email: '',
        username: '',
        password: '',
        role: 'USER' as UserRole,
        departmentId: ''
    });

    // Filter Users
    const activeOrSuspendedUsers = users.filter(u => 
        u.status !== 'PENDING' && (
            u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
            u.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
            (u.email && u.email.toLowerCase().includes(searchTerm.toLowerCase()))
        )
    );

    // --- Helper Functions ---
    const getDeptInfo = (deptId?: string) => {
        if (!deptId) return { deptName: '-', workGroupName: '-' };
        const dept = settings.departments?.find(d => d.id === deptId);
        if (!dept) return { deptName: '-', workGroupName: '-' };

        const workGroup = settings.workGroups?.find(g => g.id === dept.workGroupId);
        return {
            deptName: dept.name,
            workGroupName: workGroup?.name || '-'
        };
    };

    // --- Handlers: Add User ---
    const handleAddUserRequest = (e: React.FormEvent) => {
        e.preventDefault();
        setShowAddConfirm(true);
    };

    const confirmAddUser = () => {
        const success = registerUser({
            username: newUsername,
            password: newPassword,
            name: newName,
            email: newEmail,
            role: newRole,
            departmentId: newDeptId || undefined,
            status: 'ACTIVE'
        });

        if (success) {
            setNewUsername('');
            setNewPassword('');
            setNewName('');
            setNewEmail('');
            setNewRole('USER');
            setNewWorkGroupId('');
            setNewDeptId('');
            setShowAddConfirm(false);
        } else {
            alert('Username นี้มีผู้ใช้งานแล้ว');
            setShowAddConfirm(false);
        }
    };

    // --- Handlers: Edit User ---
    const openEditModal = (user: User) => {
        setEditingUser(user);

        // Find WorkGroup based on current Department
        let initialWorkGroupId = '';
        if (user.departmentId) {
            const dept = settings.departments.find(d => d.id === user.departmentId);
            if (dept && dept.workGroupId) {
                initialWorkGroupId = dept.workGroupId;
            }
        }

        setEditWorkGroupId(initialWorkGroupId);
        setEditFormData({
            name: user.name,
            email: user.email || '',
            username: user.username,
            password: '', 
            role: user.role,
            departmentId: user.departmentId || ''
        });
    };

    const handleUpdateUserSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowEditConfirm(true);
    };

    const confirmUpdateUser = () => {
        if (!editingUser) return;

        const updates: Partial<User> = {
            name: editFormData.name,
            email: editFormData.email,
            role: editFormData.role,
            departmentId: editFormData.departmentId || undefined
        };

        if (editFormData.password.trim()) {
            updates.password = editFormData.password;
        }

        updateUser(editingUser.id, updates);
        setEditingUser(null);
        setShowEditConfirm(false);
    };

    // --- Handlers: Status Change ---
    const handleSoftDelete = (user: User) => {
        if (user.id === currentUser?.id) return;
        setSuspendConfirm({ id: user.id, name: user.name });
    };

    const confirmSuspend = () => {
        if (suspendConfirm) {
            deleteUser(suspendConfirm.id);
            setSuspendConfirm(null);
        }
    };

    const handleReactivateRequest = (user: User) => {
        if (user.id === currentUser?.id) return;
        setReactivateConfirm({ id: user.id, name: user.name });
    };

    const confirmReactivate = () => {
        if (reactivateConfirm) {
            updateUser(reactivateConfirm.id, { status: 'ACTIVE' });
            setReactivateConfirm(null);
        }
    };

    const toggleRole = (id: string, currentRole: UserRole) => {
        if (id === currentUser?.id) return;
        const newRole = currentRole === 'ADMIN' ? 'USER' : 'ADMIN';
        updateUser(id, { role: newRole });
    };

    return (
        <div className="p-6 pb-20">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">จัดการผู้ใช้งาน (User Management)</h2>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">

                {/* 1. User List Table */}
