                                required
                                type="password"
                                className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500"
                                value={newPassword}
                                onChange={e => setNewPassword(e.target.value)}
