// ==========================================
// 📦 DATABASE INITIALIZATION & REPAIR
// ==========================================
async function initDatabase() {
    try {
        // 1. Force Database Default
        await query(`ALTER DATABASE procurement_db CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci`);

        // 2. Ensure Tables Exist (UTF-8)
        const tables = [
            `CREATE TABLE IF NOT EXISTS work_groups (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, is_active BOOLEAN DEFAULT TRUE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`,
            `CREATE TABLE IF NOT EXISTS departments (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, prefix VARCHAR(20), request_prefix VARCHAR(100), work_group_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`,
            `CREATE TABLE IF NOT EXISTS procurement_categories (id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, department_id VARCHAR(50), is_active BOOLEAN DEFAULT TRUE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`,
            `CREATE TABLE IF NOT EXISTS users (id VARCHAR(50) PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), role ENUM('ADMIN', 'USER') DEFAULT 'USER', department_id VARCHAR(50), status ENUM('PENDING', 'ACTIVE', 'SUSPENDED') DEFAULT 'PENDING', created_at BIGINT) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`,
            `CREATE TABLE IF NOT EXISTS procurements (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, request_date DATE NOT NULL, category VARCHAR(255), item_count INT DEFAULT 0, amount DECIMAL(15, 2) DEFAULT 0.00, company VARCHAR(255), remarks TEXT, official_number VARCHAR(50), type ENUM('PURCHASE', 'HIRING', 'OTHER') NOT NULL, department_id VARCHAR(50), created_by VARCHAR(50), created_at BIGINT) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`,
            `CREATE TABLE IF NOT EXISTS receivings (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, delivery_note_no VARCHAR(50), receive_date DATE, category VARCHAR(255), created_at BIGINT) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`,
            `CREATE TABLE IF NOT EXISTS considerations (id VARCHAR(50) PRIMARY KEY, request_id VARCHAR(50) NOT NULL, consideration_number VARCHAR(50), consideration_date DATE) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`
        ];

        for (const sql of tables) { await query(sql); }

        // 3. Migration
        const addCol = async (t, c, d) => {
            try {
                const cols = await query(`SHOW COLUMNS FROM ${t} LIKE ?`, [c]);
                if (cols.length === 0) await query(`ALTER TABLE ${t} ADD COLUMN ${c} ${d}`);
            } catch(e) {}
        };
        await addCol('departments', 'work_group_id', 'VARCHAR(50)');
        await addCol('departments', 'request_prefix', 'VARCHAR(100)');

        // 4. 🛠️ DEEP REPAIR: Fix "Alien Language" (Mojibake)
        // Convert to Binary then back to UTF8 to fix double-encoding/latin1 storage issues
        const repairTable = async (table, columns) => {
            try {
                // Ensure table is UTF8MB4
                await query(`ALTER TABLE ${table} CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);

                for (const col of columns) {
                    try {
                        // Trick: VARBINARY -> VARCHAR (Correct Charset)
                        // This forces MySQL to reinterpret the bytes as UTF8
                        await query(`ALTER TABLE ${table} MODIFY ${col} VARBINARY(255)`);
                        await query(`ALTER TABLE ${table} MODIFY ${col} VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
                    } catch (e) { }
                }
                console.log(`   - Verified/Repaired table: ${table}`);
            } catch (e) { console.error(`   - Failed to repair ${table}:`, e.message); }
        };

        // Run repair on text-heavy tables
        await repairTable('procurements', ['company', 'remarks', 'category', 'official_number', 'request_id']);
        await repairTable('receivings', ['delivery_note_no', 'category']);
        await repairTable('considerations', ['consideration_number']);
        await repairTable('users', ['name', 'email']);
        await repairTable('departments', ['name', 'prefix', 'request_prefix']); // Critical for running numbers
        await repairTable('work_groups', ['name']);
        await repairTable('procurement_categories', ['name']);

        console.log('✅ Database v1.3.6 Ready (Connection Fixed & Tables Repaired)');
    } catch (e) { 
        console.error('❌ Database Init Failed:', e.message); 
    }
}

