                                        </div>
                                    </div>
                                </div>
                                <div className="p-4 bg-white flex space-x-3 mt-auto">
                                    <button 
                                        onClick={() => setConfirmAction({ id: user.id, name: user.name, email: user.email, type: 'REJECT' })}
