                        </p>
                        {confirmAction.type === 'APPROVE' && confirmAction.email && (
                            <div className="bg-blue-50 text-blue-700 p-3 rounded-lg text-xs mb-6 border border-blue-100 flex items-start">
                                <Mail size={14} className="mr-2 flex-shrink-0 mt-0.5"/>
