app.post('/api/send-approval-email', async (req, res) => {
    const { email, name, username } = req.body;

    if (!email) return res.json({ success: false, message: 'No email provided' });

    console.log(`📧 Attempting to send REAL email to ${email}...`);

    // Removed the "Simulated" block here.
    // If transporter auth is invalid, it WILL throw error below.

    const mailOptions = {
        from: `"Procurement System" <${transporter.options.auth.user}>`,
        to: email,
        subject: 'แจ้งผลการอนุมัติสิทธิ์การใช้งานระบบพัสดุ',
        text: `เรียนคุณ ${name},\n\nบัญชีผู้ใช้งานของคุณ (${username}) ได้รับการตรวจสอบและอนุมัติสิทธิ์การเข้าใช้งานระบบบริหารงานพัสดุเรียบร้อยแล้ว\n\nคุณสามารถเข้าสู่ระบบได้ทันที\n\nขอบคุณครับ\nทีมงานสุขภาพดิจิทัล`
    };

    try {
        await transporter.sendMail(mailOptions);
        console.log(`✅ Email sent to ${email} successfully.`);
        res.json({ success: true });
    } catch (error) {
        console.error('❌ Failed to send email (Check SMTP Config):', error.message);
