];

const REMARKS = [
    "ด่วนที่สุด", "งบประมาณประจำปี 2567", "โครงการพัฒนาระบบสารสนเทศ", 
    "สำรองจ่าย", "จัดซื้อตามแผน", "ทดแทนของเดิมที่ชำรุด", 
    "เตรียมความพร้อมรับการตรวจเยี่ยม", "", "", ""
];

const DEPTS = ['d1']; // Using default department created in index.js usually, or we query existing.

// Helper Functions
const randomInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const randomItem = (arr) => arr[Math.floor(Math.random() * arr.length)];
const randomDate = (start, end) => new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime()));

const toThaiDate = (date) => {
    return date.toISOString().split('T')[0];
};

const run = async () => {
    let connection;
    try {
        console.log('🔌 Connecting to database...');
        connection = await mysql.createConnection(DB_CONFIG);
        console.log('✅ Connected.');

        // 1. Get Setup Data
        const [users] = await connection.execute('SELECT id, department_id FROM users');
        const [depts] = await connection.execute('SELECT id FROM departments');

        let targetUser = users.find(u => u.username === 'admin') || users[0];
        let targetDept = depts.length > 0 ? depts[0].id : (targetUser?.department_id || 'd1');

        if (!targetUser) {
            console.log('⚠️ No users found. Creating admin user...');
            await connection.execute(`INSERT INTO users (id, username, password, name, role, status, created_at) VALUES ('admin', 'admin', 'password', 'System Admin', 'ADMIN', 'ACTIVE', ${Date.now()})`);
            targetUser = { id: 'admin' };
        }

        // 2. Clear Old Data (Optional - Uncomment if you want to wipe table first)
        console.log('🧹 Clearing old transaction data (Procurements, Receivings, Considerations)...');
        await connection.execute('DELETE FROM receivings');
        await connection.execute('DELETE FROM considerations');
        await connection.execute('DELETE FROM procurements');

        // 3. Generate 200 Records
        console.log('🚀 Generating 200 records...');

        const startDate = new Date();
        startDate.setMonth(startDate.getMonth() - 12); // Back 1 year
        const endDate = new Date();

        for (let i = 1; i <= 200; i++) {
            // Generate Data
            const id = Math.random().toString(36).substr(2, 9);
            const reqDateObj = randomDate(startDate, endDate);
            const reqDate = toThaiDate(reqDateObj);

            // Determine Fiscal Year for Running Number simulation
            const month = reqDateObj.getMonth();
            const year = reqDateObj.getFullYear();
            const fiscalYear = month >= 9 ? year + 1 : year; // Thai Fiscal Year
            const thaiYear = fiscalYear + 543;

            // Generate IDs
            const runNum = i.toString().padStart(4, '0'); // 0001, 0002...
            const requestId = `สพ.0033.06/${runNum}/${thaiYear}`;

            // Randomize Type
            const typeRand = Math.random();
            let type = 'PURCHASE';
            if (typeRand > 0.7) type = 'HIRING';
            if (typeRand > 0.95) type = 'OTHER';

            const category = randomItem(CATEGORIES);
            const company = randomItem(COMPANIES);
            const amount = type === 'PURCHASE' ? randomInt(500, 50000) : randomInt(2000, 200000);
            const itemCount = randomInt(1, 20);

            // Official Number (Only if amount > 5000 usually, but let's randomize)
            let officialNumber = null;
            if (amount > 5000 || Math.random() > 0.5) {
                officialNumber = `พด. ${runNum}/${thaiYear}`;
            }

            // Insert Procurement
            await connection.execute(
                `INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) 
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
                [
                    id, requestId, reqDate, category, itemCount, amount, company, randomItem(REMARKS), 
                    officialNumber, type, targetDept, targetUser.id, reqDateObj.getTime()
                ]
            );

            // 80% chance to have a Consideration Record (ใบขออนุมัติ)
            if (Math.random() > 0.2) {
                const consDateObj = new Date(reqDateObj);
                consDateObj.setDate(consDateObj.getDate() + randomInt(1, 5));

                await connection.execute(
                    `INSERT INTO considerations (id, request_id, consideration_number, consideration_date) VALUES (?, ?, ?, ?)`,
                    [
                        Math.random().toString(36).substr(2, 9),
                        requestId,
                        `บน. ${runNum}/${thaiYear}`,
                        toThaiDate(consDateObj)
                    ]
                );
            }

            // 70% chance to have a Receiving Record (ใบตรวจรับ)
            if (Math.random() > 0.3) {
                const recvDateObj = new Date(reqDateObj);
                recvDateObj.setDate(recvDateObj.getDate() + randomInt(7, 30));

                await connection.execute(
                    `INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?, ?, ?, ?, ?, ?)`,
                    [
                        Math.random().toString(36).substr(2, 9),
                        requestId,
                        `${randomInt(1000, 9999)}/67`, // Delivery Note No
                        toThaiDate(recvDateObj),
                        category,
                        recvDateObj.getTime()
                    ]
                );
            }

            if (i % 20 === 0) process.stdout.write('.');
        }

        console.log('\n✨ Database seeding completed! (200 records created)');

    } catch (err) {
        console.error('\n❌ Error seeding database:', err);
    } finally {
        if (connection) await connection.end();
    }
};

run();

