                                <th className="px-4 py-3">เลขที่ใบขอ</th>
                                <th className="px-4 py-3 bg-blue-50">เลขสั่งซื้อ/จ้าง</th>
                                <th className="px-4 py-3">เลขที่ขออนุมัติ</th>
                                <th className="px-4 py-3">หมวดพัสดุ</th>
                                <th className="px-4 py-3 text-right">จำนวนรายการ</th>
                                <th className="px-4 py-3 text-right">จำนวนเงิน</th>
                                <th className="px-4 py-3 text-center">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {receivings.length === 0 ? (
                                <tr>
                                    <td colSpan={9} className="px-4 py-8 text-center text-slate-400">
                                        ยังไม่มีรายการใบรับของ
                                    </td>
                                </tr>
                            ) : (
                                receivings.map((item) => {
                                    const { proc, cons } = getLinkedInfo(item.requestId);
                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50">
