                                            <td className="px-4 py-3 font-medium text-slate-900">{item.deliveryNoteNo}</td>
                                            <td className="px-4 py-3 text-blue-600">{item.requestId}</td>
                                            <td className="px-4 py-3 bg-blue-50 font-bold">
                                                {proc?.officialNumber || '-'}
                                            </td>
                                            <td className="px-4 py-3">
                                                {cons?.considerationNumber || '-'}
