import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
    PieChart, Pie, Cell 
} from 'recharts';
import { ShoppingCart, Briefcase, Archive, Wallet, ArrowUpRight, Clock, Filter, Calendar } from 'lucide-react';

// Helper: Calculate Fiscal Year (Thai Government: Oct - Sep)
const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return new Date().getFullYear() + 543;
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return new Date().getFullYear() + 543;

    const month = date.getMonth(); // 0 = Jan, 9 = Oct
    const year = date.getFullYear();

    // If Month is Oct(9), Nov(10), Dec(11) -> Fiscal Year is next year
    return month >= 9 ? year + 1 + 543 : year + 543;
};

// Helper: Format Currency (Safe version for string/number inputs)
const formatCurrency = (amount: number | string) => {
    const num = Number(amount);
    if (isNaN(num)) return '0.00';
    return num.toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

const Dashboard: React.FC = () => {
    const { procurements } = useApp();

    // 1. Setup Fiscal Year Logic
    const currentFiscalYear = useMemo(() => {
        const now = new Date();
        return now.getMonth() >= 9 ? now.getFullYear() + 1 + 543 : now.getFullYear() + 543;
    }, []);

    // Get list of available years from data + current year
    const availableYears = useMemo(() => {
        const years = new Set<number>(procurements.map(p => getFiscalYear(p.requestDate)));
        years.add(currentFiscalYear);
        return Array.from(years).sort((a: number, b: number) => b - a);
    }, [procurements, currentFiscalYear]);

    const [selectedYear, setSelectedYear] = useState<number>(currentFiscalYear);

    // 2. Filter Data by Selected Fiscal Year
    const yearData = useMemo(() => {
        return procurements.filter(p => getFiscalYear(p.requestDate) === selectedYear);
    }, [procurements, selectedYear]);

    // Split by type
    const purchase = yearData.filter(p => p.type === RecordType.PURCHASE);
    const hiring = yearData.filter(p => p.type === RecordType.HIRING);
    const other = yearData.filter(p => p.type === RecordType.OTHER);

    // 3. Calculate Totals (Ensure we parse Strings to Numbers first)
    const totalPurchase = purchase.reduce((acc, curr) => acc + Number(curr.amount), 0);
    const totalHiring = hiring.reduce((acc, curr) => acc + Number(curr.amount), 0);
    const totalOther = other.reduce((acc, curr) => acc + Number(curr.amount), 0);
    const grandTotal = totalPurchase + totalHiring + totalOther;

