const getApiUrl = () => {
    // Development Mode (npm run dev): Connect directly to Port 3002
    // Vite injects import.meta.env.DEV = true automatically in dev mode
    if (import.meta.env.DEV) {
        let hostname = window.location.hostname;
        if (!hostname || hostname.trim() === '') hostname = 'localhost';
        return `http://${hostname}:3002/api`;
    }

    // Production Mode (IIS/Build): Use relative path to go through IIS Reverse Proxy
    // Frontend at /procurement/ -> API at /procurement/api
    // This allows IIS to route 'api/*' to localhost:3002 while serving the app on port 80/443
    return '/procurement/api';
};

