const normalizeToNr = (str: string) => {
    if (!str) return '0';
    return str.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
};

const toThaiNr = (num: number) => {
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return num.toString().replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const month = date.getMonth(); 
    const year = date.getFullYear();
    const fiscalYear = month >= 9 ? year + 1 : year;
    return fiscalYear + 543;
};

// Helper: Format Date nicely (dd/mm/yyyy)
const formatDate = (dateStr: string | null | undefined) => {
    if (!dateStr) return '-';
    return dateStr.split('T')[0];
};

// Helper: Format Currency (Safe for string inputs)
const formatCurrency = (amount: number | string) => {
    const num = Number(amount);
    if (isNaN(num)) return '0.00';
    return num.toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, considerations, receivings, addProcurement, updateProcurement, deleteProcurement, getLinkedData, upsertConsideration, upsertReceiving, settings, currentUser, users, checkChronologyIssue } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [deleteId, setDeleteId] = useState<string | null>(null);

    // Quick Date Modal States
    const [quickDateId, setQuickDateId] = useState<string | null>(null);
    const [quickDateValue, setQuickDateValue] = useState('');
    const [quickDateNumber, setQuickDateNumber] = useState('');
    const [quickDateType, setQuickDateType] = useState<'CONSIDERATION' | 'RECEIVING' | null>(null);

    const [isAutoFilled, setIsAutoFilled] = useState(false);
    const [warningMessage, setWarningMessage] = useState<string | null>(null);

    // Pagination State
    const [itemsPerPage, setItemsPerPage] = useState<number>(10);
    const [currentPage, setCurrentPage] = useState<number>(1);

    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: '',
        considerationNumber: '',
        considerationDate: ''
    });

    const filteredData = procurements.filter(p => p.type === type);

    // Reset pagination when data changes or limit changes
    useEffect(() => {
        setCurrentPage(1);
    }, [itemsPerPage, type]);

    // Calculate Pagination
    const totalItems = filteredData.length;
    const totalPages = itemsPerPage === -1 ? 1 : Math.ceil(totalItems / itemsPerPage);
    const startIndex = itemsPerPage === -1 ? 0 : (currentPage - 1) * itemsPerPage;
    const paginatedData = itemsPerPage === -1 ? filteredData : filteredData.slice(startIndex, startIndex + itemsPerPage);

    let fieldLabels = {
        requestId: "เลขกำหนดขอบเขตงาน",
        requestDate: "วันที่กำหนดขอบเขตงาน",
        considerationNumber: "เลขรายงานขอซื้อ",
        considerationDate: "วันที่รายงานขอซื้อ",
        receivingNumber: "เลขรายงานผลการพิจารณา",
        receivingDate: "วันที่รายงานผลการพิจารณา",
        officialNumber: "เลขสั่งซื้อ"
    };

    if (type === RecordType.HIRING) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขอจ้าง",
            considerationDate: "วันที่รายงานขอจ้าง",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขสั่งจ้าง"
        };
    } else if (type === RecordType.OTHER) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขออนุมัติ",
            considerationDate: "วันที่รายงานขออนุมัติ",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขที่คำสั่ง/สัญญา"
        };
    }

    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return { name: 'violet', bgSoft: 'bg-violet-50', bgDeep: 'bg-violet-600', bgHover: 'hover:bg-violet-700', text: 'text-violet-700', border: 'border-violet-200', ring: 'focus:ring-violet-500', inputBg: 'bg-violet-50/50' };
            case RecordType.OTHER:
                return { name: 'orange', bgSoft: 'bg-orange-50', bgDeep: 'bg-orange-600', bgHover: 'hover:bg-orange-700', text: 'text-orange-700', border: 'border-orange-200', ring: 'focus:ring-orange-500', inputBg: 'bg-orange-50/50' };
            default:
                return { name: 'blue', bgSoft: 'bg-blue-50', bgDeep: 'bg-blue-600', bgHover: 'hover:bg-blue-700', text: 'text-blue-700', border: 'border-blue-200', ring: 'focus:ring-blue-500', inputBg: 'bg-blue-50/50' };
        }
    })();

    const calculateNextRunNumber = () => {
        const userDept = settings.departments.find(d => d.id === currentUser?.departmentId);
        const prefix = (userDept?.requestPrefix && userDept.requestPrefix.trim() !== '') 
            ? userDept.requestPrefix 
            : settings.requestIdPrefix;

        if (!prefix) return '';

        const reqIds = procurements.map(p => p.requestId).filter(id => id && id.startsWith(prefix));
        const consIds = considerations.map(c => c.considerationNumber).filter(id => id && id.startsWith(prefix));
        const recvIds = receivings.map(r => r.deliveryNoteNo).filter(id => id && id.startsWith(prefix));

        const allIds = [...reqIds, ...consIds, ...recvIds];

        let maxNum = 0;
        allIds.forEach(id => {
            const suffix = id.substring(prefix.length);
            const normalizedSuffix = normalizeToNr(suffix);
            const match = normalizedSuffix.match(/(\d+)/);
            if (match) {
                const num = parseInt(match[1]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });
        return prefix + toThaiNr(maxNum + 1);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowConfirm(true);
    };

    const handleConfirmSave = async (force: boolean = false) => {
        if (editingId) {
            updateProcurement(editingId, { ...formData });
        } else {
            const result = await addProcurement({ ...formData, type: type }, force);
            if (!result.success && result.isWarning) {
                setWarningMessage(result.message || "แจ้งเตือน");
                setShowConfirm(false);
                return; 
            }
            if (!result.success && !result.isWarning) {
                alert(result.message);
                setShowConfirm(false);
                return;
            }
        }

        if(formData.considerationNumber || formData.considerationDate) {
             upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
        }

        setWarningMessage(null);
        setShowConfirm(false);
        closeModal();
    };

    const handleDeleteClick = (id: string) => {
        const record = procurements.find(p => p.id === id);
        if (record && record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์ลบรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        const nextRequestId = calculateNextRunNumber() || settings.requestIdPrefix || '';
        setFormData({ requestId: nextRequestId, requestDate: '', category: '', itemCount: 0, amount: 0, company: '', remarks: '', considerationNumber: '', considerationDate: '' });
        setIsAutoFilled(true);
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        if (record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์แก้ไขรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        const linked = getLinkedData(record.requestId);
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || ''
        });
        setIsAutoFilled(false);
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
        setIsAutoFilled(false);
        setWarningMessage(null);
    };

    const handleSaveQuickDate = () => {
        if (quickDateId && quickDateValue && quickDateType) {
            if (quickDateType === 'CONSIDERATION') {
                upsertConsideration(quickDateId, quickDateNumber, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                upsertReceiving(quickDateId, quickDateNumber, quickDateValue);
            }
            setQuickDateId(null);
            setQuickDateValue('');
            setQuickDateNumber('');
            setQuickDateType(null);
        }
    };

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'ไม่ระบุ';

    const handleExportCSV = () => {
        const headers = [fieldLabels.requestId, fieldLabels.requestDate, 'ปีงบประมาณ', fieldLabels.considerationNumber, fieldLabels.considerationDate, fieldLabels.officialNumber, fieldLabels.receivingNumber, fieldLabels.receivingDate, 'จำนวนเงิน', 'บริษัท', 'ผู้บันทึก', 'หมายเหตุ'];
        const rows = filteredData.map(item => {
            const linked = getLinkedData(item.requestId);
            return [item.requestId, formatDate(item.requestDate), getFiscalYear(item.requestDate), linked.consideration?.considerationNumber || '-', formatDate(linked.consideration?.considerationDate), item.officialNumber || '-', linked.receiving?.deliveryNoteNo || '-', formatDate(linked.receiving?.receiveDate), item.amount, `"${item.company.replace(/"/g, '""')}"`, getUserName(item.createdBy), `"${item.remarks.replace(/"/g, '""')}"`].join(',');
        });
        const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `procurement_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const openQuickDate = (id: string, type: 'CONSIDERATION' | 'RECEIVING') => {
        setQuickDateId(id);
        setQuickDateType(type);
        setQuickDateValue(new Date().toISOString().split('T')[0]);
        const nextNum = calculateNextRunNumber() || settings.requestIdPrefix || '';
        setQuickDateNumber(nextNum);
    };

    return (
        <div className="p-4 sm:p-6 flex flex-col h-full">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 1cm; }
                    .lg\\:ml-64 { margin-left: 0 !important; }
                    .no-print { display: none !important; }
                    table { width: 100% !important; border-collapse: collapse; font-size: 10pt; }
                    th, td { border: 1px solid #cbd5e1 !important; padding: 4px 8px !important; }
                }
            `}</style>

            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                <h2 className="text-xl sm:text-2xl font-bold text-slate-800">{title}</h2>
                <div className="flex flex-wrap gap-2 no-print w-full sm:w-auto">
                    <button onClick={handleExportCSV} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <FileSpreadsheet size={16} />
                        <span>Excel</span>
                    </button>
                    <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <Printer size={16} />
                        <span>Print</span>
                    </button>
                    <button onClick={openNew} className={`w-full sm:w-auto flex items-center justify-center space-x-2 ${theme.bgDeep} ${theme.bgHover} text-white px-4 py-2 rounded-lg text-sm shadow-md`}>
                        <Plus size={16} />
                        <span>บันทึกใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestId}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestDate}</th>
                                <th className="px-4 py-3 whitespace-nowrap">ปีงบฯ</th>
                                {/* Consideration Group (Orange) */}
                                <th className="px-4 py-3 bg-orange-50 text-orange-800 whitespace-nowrap">{fieldLabels.considerationNumber}</th>
                                <th className="px-4 py-3 bg-orange-50 text-orange-800 whitespace-nowrap">{fieldLabels.considerationDate}</th>
                                <th className={`px-4 py-3 ${theme.bgSoft} whitespace-nowrap`}>{fieldLabels.officialNumber}</th>
                                {/* Receiving Group (Green) */}
                                <th className="px-4 py-3 bg-green-50 text-green-800 whitespace-nowrap">{fieldLabels.receivingNumber}</th>
                                <th className="px-4 py-3 bg-green-50 text-green-800 whitespace-nowrap">{fieldLabels.receivingDate}</th>
                                <th className="px-4 py-3 text-right whitespace-nowrap">จำนวนเงิน</th>
                                <th className="px-4 py-3 whitespace-nowrap">ผู้บันทึก</th>
                                <th className="px-4 py-3 whitespace-nowrap">บริษัท</th>
                                <th className="px-4 py-3 text-center no-print whitespace-nowrap">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {paginatedData.length === 0 ? (
                                <tr><td colSpan={12} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูล</td></tr>
                            ) : (
                                paginatedData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const isOwner = item.createdBy === currentUser?.id || currentUser?.role === 'ADMIN';
                                    const isBackdated = checkChronologyIssue(item);

                                    return (
                                        <tr key={item.id} className={`border-b border-slate-100 transition-colors ${isBackdated ? 'bg-red-50 hover:bg-red-100' : 'hover:bg-slate-50'}`}>
                                            <td className="px-4 py-3 font-medium text-slate-900 whitespace-nowrap">{item.requestId}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                {formatDate(item.requestDate)}
                                                {isBackdated && (
                                                    <div className="inline-flex ml-2 text-red-500" title="วันที่ไม่สัมพันธ์กับเลขลำดับก่อนหน้า">
                                                        <AlertTriangle size={14} />
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-4 py-3 text-center whitespace-nowrap">{getFiscalYear(item.requestDate)}</td>
                                            {/* Consideration Data (Orange) */}
                                            <td className="px-4 py-3 bg-orange-50 text-orange-800 whitespace-nowrap">{linked.consideration?.considerationNumber || '-'}</td>
                                            <td className="px-4 py-3 bg-orange-50 text-orange-800 whitespace-nowrap">
                                                {linked.consideration?.considerationDate ? formatDate(linked.consideration.considerationDate) : (isOwner && (
                                                    <button onClick={() => openQuickDate(item.requestId, 'CONSIDERATION')} className={`flex items-center text-orange-600 bg-white border border-orange-200 hover:bg-orange-100 px-2 py-1 rounded no-print text-xs`}><CalendarPlus size={14} className="mr-1" /> เพิ่ม</button>
                                                )) || '-'}
                                            </td>
                                            <td className={`px-4 py-3 ${theme.bgSoft} font-bold ${theme.text} whitespace-nowrap`}>{item.officialNumber || '-'}</td>
                                            {/* Receiving Data (Green) */}
                                            <td className="px-4 py-3 bg-green-50 text-green-800 whitespace-nowrap">{linked.receiving?.deliveryNoteNo || '-'}</td>
                                            <td className="px-4 py-3 bg-green-50 text-green-800 whitespace-nowrap">
                                                {linked.receiving?.receiveDate ? formatDate(linked.receiving.receiveDate) : (isOwner && (
                                                    <button onClick={() => openQuickDate(item.requestId, 'RECEIVING')} className="flex items-center text-green-600 bg-white border border-green-200 hover:bg-green-100 px-2 py-1 rounded no-print text-xs"><CalendarPlus size={14} className="mr-1" /> เพิ่ม</button>
                                                )) || '-'}
                                            </td>
                                            {/* Amount (Bold Red) */}
                                            <td className="px-4 py-3 text-right whitespace-nowrap font-bold text-red-600 font-mono">{formatCurrency(item.amount)}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                <div className="flex items-center text-xs text-slate-500"><UserIcon size={12} className="mr-1 opacity-50"/>{getUserName(item.createdBy)}</div>
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[150px]">{item.company}</td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    {isOwner ? (
                                                        <>
                                                            <button onClick={() => openEdit(item)} className="p-1 text-slate-600 hover:bg-slate-200 rounded"><Edit2 size={16} /></button>
                                                            <button onClick={() => handleDeleteClick(item.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
                                                        </>
                                                    ) : <span className="text-[10px] text-slate-400">Read Only</span>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div className="flex items-center justify-between px-4 py-3 border-t border-slate-200 bg-slate-50 no-print">
                    <div className="flex items-center text-sm text-slate-600">
                        <span>แสดง</span>
                        <select 
                            value={itemsPerPage} 
                            onChange={(e) => setItemsPerPage(Number(e.target.value))}
                            className="mx-2 border border-slate-300 rounded px-2 py-1 outline-none bg-white text-slate-800 focus:ring-1 focus:ring-blue-500"
                        >
                            <option value={10}>10</option>
                            <option value={50}>50</option>
                            <option value={100}>100</option>
                            <option value={-1}>ทั้งหมด</option>
                        </select>
                        <span>รายการ</span>
                        <span className="ml-4 text-slate-500">
                            (ทั้งหมด {totalItems} รายการ)
                        </span>
                    </div>

                    {itemsPerPage !== -1 && (
                        <div className="flex items-center space-x-2">
                            <button 
                                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                disabled={currentPage === 1}
                                className="p-1 rounded hover:bg-slate-200 disabled:opacity-50 disabled:hover:bg-transparent"
                            >
                                <ChevronLeft size={20} />
                            </button>
                            <span className="text-sm font-medium text-slate-700">
                                หน้า {currentPage} / {totalPages}
                            </span>
                            <button 
                                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                                disabled={currentPage === totalPages}
                                className="p-1 rounded hover:bg-slate-200 disabled:opacity-50 disabled:hover:bg-transparent"
                            >
                                <ChevronRight size={20} />
                            </button>
                        </div>
                    )}
                </div>
            </div>

            {/* Warning Dialog */}
            {warningMessage && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm no-print animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full text-center border-l-4 border-orange-500">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-orange-100 mb-6">
                            <AlertTriangle className="h-8 w-8 text-orange-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">แจ้งเตือนลำดับวันที่</h3>
                        <div className="text-sm text-slate-600 mb-8 leading-relaxed whitespace-pre-line bg-slate-50 p-3 rounded-lg border border-slate-200 text-left">
                            {warningMessage}
                        </div>
                        <div className="flex gap-4">
                            <button onClick={() => setWarningMessage(null)} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold transition-colors">กลับไปแก้ไข</button>
                            <button onClick={() => handleConfirmSave(true)} className="flex-1 py-3 bg-orange-600 hover:bg-orange-700 text-white rounded-xl text-sm font-semibold shadow-lg transition-colors">ยืนยันบันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Quick Date Modal */}
            {quickDateId && (
                <div className="fixed inset-0 bg-black/40 z-[100] flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold text-slate-800">บันทึกวันที่</h3>
                            <button onClick={() => setQuickDateId(null)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                        </div>

                        <div className="mb-4">
                            <label className="block text-sm font-medium text-slate-700 mb-1">เลขที่เอกสาร</label>
                            <input 
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none focus:ring-2 ring-blue-500 font-medium text-slate-900"
                                value={quickDateNumber}
                                onChange={e => setQuickDateNumber(e.target.value)}
                            />
                            <p className="text-xs text-slate-500 mt-1">หากเลขที่ผิดเพี้ยน (ภาษาต่างดาว) สามารถแก้ไขได้ที่นี่</p>
                        </div>

                        <div className="mb-6">
                            <label className="block text-sm font-medium text-slate-700 mb-1">วันที่</label>
                            <input 
                                type="date" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none focus:ring-2 ring-blue-500 text-slate-900 bg-white" 
                                value={quickDateValue} 
                                onChange={e => setQuickDateValue(e.target.value)} 
                            />
                        </div>

                        <div className="flex gap-2">
                            <button onClick={() => setQuickDateId(null)} className="flex-1 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={handleSaveQuickDate} className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors">บันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Form Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-0 sm:p-4 no-print">
