const express = require('express');
const mysql = require('mysql2');
const nodemailer = require('nodemailer');
const router = express.Router();

// ==========================================
// 🛠️ DATABASE CONFIGURATION
// ==========================================
const DB_CONFIG = { 
    host: '10.1.0.201', 
    user: 'sa', 
    password: 'Sam#11294', 
    database: 'procurement_db', 
    port: 3306,
    waitForConnections: true, 
    connectionLimit: 10,
    timezone: '+07:00',
    dateStrings: true,
    charset: 'UTF8MB4_GENERAL_CI'
};

const db = mysql.createPool(DB_CONFIG);

// Helper function for queries
const query = (sql, params) => new Promise((resolve, reject) => db.query(sql, params, (err, res) => err ? reject(err) : resolve(res)));

// ==========================================
// 📧 EMAIL CONFIGURATION
// ==========================================
const transporter = nodemailer.createTransport({
    service: 'gmail',
    auth: {
        user: 'your-email@gmail.com', // ⚠️ แก้ไขเป็นอีเมลของคุณ
        pass: 'your-app-password'     // ⚠️ แก้ไขเป็นรหัสผ่านแอพ
    }
});

// ==========================================
// API ROUTES (Relative to /api/procurement)
// ==========================================

// Login
router.post('/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const users = await query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
        if (users.length > 0) {
            const u = users[0];
            if (u.status !== 'ACTIVE') return res.json({ success: false, message: 'บัญชีรอการอนุมัติหรือถูกระงับ' });
            res.json({ success: true, user: { id: u.id, username: u.username, name: u.name, role: u.role, departmentId: u.department_id } });
        } else {
            res.json({ success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' });
        }
    } catch(e) { res.status(500).json({success: false, message: e.message}); }
});

// Send Email
router.post('/send-approval-email', async (req, res) => {
    const { email, name, username } = req.body;
    if (!email) return res.json({ success: false, message: 'No email provided' });

    const mailOptions = {
        from: `"Procurement System" <${transporter.options.auth.user}>`,
        to: email,
        subject: 'แจ้งผลการอนุมัติสิทธิ์การใช้งานระบบพัสดุ',
        text: `เรียนคุณ ${name},\n\nบัญชีผู้ใช้งานของคุณ (${username}) ได้รับการตรวจสอบและอนุมัติสิทธิ์การเข้าใช้งานระบบบริหารงานพัสดุเรียบร้อยแล้ว\n\nคุณสามารถเข้าสู่ระบบได้ทันที\n\nขอบคุณครับ\nทีมงานสุขภาพดิจิทัล`
    };

    try {
        await transporter.sendMail(mailOptions);
        res.json({ success: true });
    } catch (error) {
        console.error('❌ Failed to send email:', error.message);
        res.status(500).json({ success: false, message: 'SMTP Auth Failed', error: error.message });
    }
});

// Get Data
router.get('/data', async (req, res) => {
    try {
        const [p, r, c, d, w, cat] = await Promise.all([
            query('SELECT * FROM procurements'), 
            query('SELECT * FROM receivings'),
            query('SELECT * FROM considerations'), 
            query('SELECT * FROM departments'),
            query('SELECT * FROM work_groups'), 
            query('SELECT * FROM procurement_categories')
        ]);
        res.json({
            procurements: p.map(x => ({ ...x, requestId: x.request_id, requestDate: x.request_date, officialNumber: x.official_number, departmentId: x.department_id, createdBy: x.created_by, createdAt: x.created_at })),
            receivings: r.map(x => ({ ...x, requestId: x.request_id, deliveryNoteNo: x.delivery_note_no, receiveDate: x.receive_date })),
            considerations: c.map(x => ({ ...x, requestId: x.request_id, considerationNumber: x.consideration_number, considerationDate: x.consideration_date })),
            settings: { 
                departments: d.map(x => ({ ...x, workGroupId: x.work_group_id, requestPrefix: x.request_prefix, isActive: x.is_active === 1 })), 
                workGroups: w.map(x => ({ ...x, isActive: x.is_active === 1 })), 
                categories: cat.map(x => ({ ...x, departmentId: x.department_id, isActive: x.is_active === 1 }))
            }
        });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// Procurements
router.post('/procurements', async (req, res) => {
    const p = req.body;
    await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
        [p.id, p.requestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, p.officialNumber, p.type, p.departmentId, p.createdBy, p.createdAt]);
    res.json({ success: true });
});

router.patch('/procurements/:id', async (req, res) => {
    const id = req.params.id;
    const p = req.body;
    const map = { requestId: 'request_id', requestDate: 'request_date', category: 'category', itemCount: 'item_count', amount: 'amount', company: 'company', remarks: 'remarks', officialNumber: 'official_number', departmentId: 'department_id' };
    let sql = "UPDATE procurements SET ";
    const params = [];
    const fields = [];

    for (const [key, dbCol] of Object.entries(map)) {
        if (p[key] !== undefined) { fields.push(`${dbCol} = ?`); params.push(p[key]); }
    }
    if (fields.length > 0) {
        sql += fields.join(', ') + " WHERE id = ?"; 
        params.push(id); 
        await query(sql, params);
    }
    res.json({ success: true });
});

router.delete('/procurements/:id', async (req, res) => {
    await query('DELETE FROM procurements WHERE id = ?', [req.params.id]);
    res.json({ success: true });
});

// Receivings
router.post('/receivings', async (req, res) => {
    const r = req.body;
    await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?,?,?,?,?,?)', [r.id, r.requestId, r.deliveryNoteNo, r.receiveDate, r.category, r.createdAt]);
    res.json({ success: true });
});

router.post('/receivings/upsert', async (req, res) => {
    const r = req.body;
    const existing = await query('SELECT id FROM receivings WHERE request_id = ?', [r.requestId]);
    if (existing.length > 0) {
        await query('UPDATE receivings SET delivery_note_no=?, receive_date=?, category=? WHERE request_id=?', [r.deliveryNoteNo, r.receiveDate, r.category, r.requestId]);
    } else {
        const id = Math.random().toString(36).substr(2, 9);
        await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?,?,?,?,?,?)', [id, r.requestId, r.deliveryNoteNo, r.receiveDate, r.category, Date.now()]);
    }
    res.json({ success: true });
});

router.delete('/receivings/:id', async (req, res) => {
    await query('DELETE FROM receivings WHERE id = ?', [req.params.id]);
    res.json({ success: true });
});

// Considerations
router.post('/considerations', async (req, res) => {
    const c = req.body;
    const existing = await query('SELECT id FROM considerations WHERE request_id = ?', [c.requestId]);
    if (existing.length > 0) {
        await query('UPDATE considerations SET consideration_number=?, consideration_date=? WHERE request_id=?', [c.considerationNumber, c.considerationDate, c.requestId]);
    } else {
        await query('INSERT INTO considerations (id, request_id, consideration_number, consideration_date) VALUES (?,?,?,?)', [c.id, c.requestId, c.considerationNumber, c.considerationDate]);
    }
    res.json({ success: true });
});

// Settings (WorkGroup/Dept)
router.post('/workgroup', async (req, res) => {
    const g = req.body;
    await query('INSERT INTO work_groups (id, name) VALUES (?,?)', [g.id, g.name]);
    res.json({ success: true });
});
router.delete('/workgroup/:id', async (req, res) => {
    await query('DELETE FROM work_groups WHERE id = ?', [req.params.id]);
    res.json({ success: true });
});

router.post('/department', async (req, res) => {
    const d = req.body;
    await query('INSERT INTO departments (id, name, prefix, request_prefix, work_group_id) VALUES (?,?,?,?,?)', [d.id, d.name, d.prefix, d.requestPrefix, d.workGroupId]);
    res.json({ success: true });
});
router.patch('/department/:id', async (req, res) => {
    const d = req.body;
    await query('UPDATE departments SET name=?, prefix=?, request_prefix=?, work_group_id=? WHERE id=?', [d.name, d.prefix, d.requestPrefix, d.workGroupId, req.params.id]);
    res.json({ success: true });
});

// Users
router.post('/register', async (req, res) => {
    const u = req.body;
    try {
        await query('INSERT INTO users (id, username, password, name, email, role, department_id, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
            [u.id, u.username, u.password, u.name, u.email, u.role, u.departmentId, u.status, Date.now()]);
        res.json({ success: true });
    } catch(e) { res.status(500).json({success: false, message: 'Username นี้ถูกใช้ไปแล้ว'}); }
});

router.get('/users', async (req, res) => { 
    const rows = await query('SELECT id, username, name, email, role, department_id AS departmentId, status, created_at FROM users');
    res.json(rows);
});

router.patch('/users/:id', async (req, res) => {
    const u = req.body;
    let sql = 'UPDATE users SET '; const params = [];
    if(u.status) { sql+='status=?,'; params.push(u.status); }
    if(u.role) { sql+='role=?,'; params.push(u.role); }
    if(u.name) { sql+='name=?,'; params.push(u.name); }
    if(u.email) { sql+='email=?,'; params.push(u.email); }
    if(u.departmentId !== undefined) { sql+='department_id=?,'; params.push(u.departmentId); }
    if(u.password) { sql+='password=?,'; params.push(u.password); }

    sql = sql.slice(0, -1) + ' WHERE id=?'; params.push(req.params.id);
    await query(sql, params);
    res.json({ success: true });
});

module.exports = router;

