    const r = req.body;
    await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?,?,?,?,?,?)', [r.id, r.requestId, r.deliveryNoteNo, r.receiveDate, r.category, r.createdAt]);
    res.json({ success: true });
});

router.post('/receivings/upsert', async (req, res) => {
