                                        <th className="px-3 py-2 text-center">ตัวย่อ</th>
                                        <th className="px-3 py-2 text-center">จัดการ</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y">
                                    {sortedDepartments.length === 0 ? <tr><td colSpan={5} className="text-center py-4 text-slate-400">ไม่พบข้อมูลฝ่าย</td></tr> : 
                                    sortedDepartments.map(dept => (
                                        <tr key={dept.id} className={`hover:bg-slate-50 transition-colors ${dept.isActive ? '' : 'bg-slate-100 opacity-60'}`}>
                                            <td className="px-3 py-2 text-slate-500">
                                                {editingDeptId === dept.id ? (
                                                    <select className="border rounded px-1 w-full" value={editDeptWorkGroup} onChange={e=>setEditDeptWorkGroup(e.target.value)}>
                                                        <option value="">--</option>
                                                        {settings.workGroups?.filter(g=>g.isActive).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                                    </select>
                                                ) : settings.workGroups?.find(g=>g.id===dept.workGroupId)?.name || '-'}
                                            </td>
                                            <td className="px-3 py-2 font-medium">
                                                {editingDeptId === dept.id ? <input className="border rounded px-1 w-full" value={editDeptName} onChange={e=>setEditDeptName(e.target.value)}/> : 
                                                <span className={dept.isActive ? '' : 'line-through text-slate-500'}>{dept.name}</span>}
                                            </td>

                                            <td className="px-3 py-2 font-mono">
                                                {editingDeptId === dept.id ? <input className="border rounded px-1 w-full" value={editDeptRequestPrefix} onChange={e=>setEditDeptRequestPrefix(e.target.value)}/> : dept.requestPrefix || '-'}
                                            </td>
                                            <td className="px-3 py-2 text-center font-bold text-indigo-600">
                                                {editingDeptId === dept.id ? <input className="border rounded px-1 w-full text-center" value={editDeptPrefix} onChange={e=>setEditDeptPrefix(e.target.value)}/> : dept.prefix || '-'}
                                            </td>
                                            <td className="px-3 py-2 text-center">
                                                {editingDeptId === dept.id ? (
                                                    <div className="flex justify-center space-x-1">
                                                        <button onClick={handleEditDepartment} className="text-green-600 bg-green-50 p-1 rounded hover:bg-green-100"><Check size={14}/></button>
                                                        <button onClick={()=>setEditingDeptId(null)} className="text-red-600 bg-red-50 p-1 rounded hover:bg-red-100"><X size={14}/></button>
                                                    </div>
                                                ) : (
                                                    <div className="flex justify-center space-x-1">
                                                        <button onClick={()=>startEditDept(dept)} disabled={!dept.isActive} className="text-slate-400 hover:text-indigo-600 p-1 disabled:opacity-30"><Edit2 size={14}/></button>
                                                        <button onClick={()=>handleDeleteDepartment(dept)} disabled={!dept.isActive} className="text-slate-400 hover:text-red-600 p-1 disabled:opacity-30">
                                                            {dept.isActive ? <Trash2 size={14}/> : <PowerOff size={14}/>}
                                                        </button>
                                                    </div>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>

            {/* Reusable Confirmation Modal */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-white/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4">
                            <AlertCircle className="h-6 w-6 text-blue-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed whitespace-pre-line">
                            {confirmAction.message}
                        </p>
                        <div className="flex justify-center space-x-3">
                            <button 
                                onClick={() => setConfirmAction(null)}
                                className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmAction.onConfirm}
                                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors font-medium text-sm"
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

