router.patch('/users/:id', async (req, res) => {
    const u = req.body;
    let sql = 'UPDATE users SET '; const params = [];
    if(u.status) { sql+='status=?,'; params.push(u.status); }
    if(u.role) { sql+='role=?,'; params.push(u.role); }
    if(u.name) { sql+='name=?,'; params.push(u.name); }
    if(u.email) { sql+='email=?,'; params.push(u.email); }
    if(u.departmentId !== undefined) { sql+='department_id=?,'; params.push(u.departmentId); }
    if(u.password) { sql+='password=?,'; params.push(u.password); }

    sql = sql.slice(0, -1) + ' WHERE id=?'; params.push(req.params.id);
    await query(sql, params);
    res.json({ success: true });
});

