    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState('');
    const [editDeptRequestPrefix, setEditDeptRequestPrefix] = useState('');
    const [editDeptWorkGroup, setEditDeptWorkGroup] = useState('');

    // FIX 5: Confirmation Modal State
    const [confirmAction, setConfirmAction] = useState<{
        type: 'ADD_WG' | 'EDIT_WG' | 'DEL_WG' | 'ADD_DEPT' | 'EDIT_DEPT' | 'DEL_DEPT';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // --- Work Group Handlers ---
    // FIX 2: เพิ่มกลุ่มงาน (ภาษาไทย) + FIX 5 (Confirm)
    const handleAddWorkGroup = () => {
        if (!newWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'ADD_WG',
            title: 'ยืนยันการเพิ่มกลุ่มงาน',
            message: `คุณต้องการเพิ่มกลุ่มงาน "${newWorkGroupName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addWorkGroup({ id: `group_${Date.now()}`, name: newWorkGroupName.trim(), isActive: true });
                setNewWorkGroupName('');
                setConfirmAction(null);
            }
        });
    };

    const startEditWorkGroup = (g: WorkGroup) => {
        setEditingWorkGroupId(g.id);
        setEditWorkGroupName(g.name);
    };

    // FIX 4: แก้ไขกลุ่มงาน + FIX 5 (Confirm)
    const handleEditWorkGroup = () => {
        if (!editingWorkGroupId || !editWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'EDIT_WG',
            title: 'ยืนยันการแก้ไข',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงชื่อกลุ่มงานใช่หรือไม่?',
            onConfirm: () => {
                updateWorkGroup(editingWorkGroupId, editWorkGroupName.trim());
                setEditingWorkGroupId(null);
                setConfirmAction(null);
            }
        });
    };

    // FIX 3: ลบกลุ่มงาน (Soft Delete) + FIX 5 (Confirm)
    const handleDeleteWorkGroup = (g: WorkGroup) => {
        setConfirmAction({
            type: 'DEL_WG',
            title: 'ระงับการใช้งานกลุ่มงาน?',
            message: `คุณต้องการระงับการใช้งาน "${g.name}" ใช่หรือไม่? (ข้อมูลจะไม่ถูกลบจริง)`,
            onConfirm: () => {
                deleteWorkGroup(g.id); // Calls backend SOFT DELETE
                setConfirmAction(null);
            }
        });
    };

    // --- Department Handlers ---
    // FIX 6: เพิ่มฝ่าย (ภาษาไทย) + FIX 5 (Confirm)
    const handleAddDepartment = () => {
        if (!newDeptName.trim()) return;
        setConfirmAction({
            type: 'ADD_DEPT',
            title: 'ยืนยันการเพิ่มฝ่าย/งาน',
            message: `คุณต้องการเพิ่มฝ่าย "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addDepartment({
                    id: `dept_${Date.now()}`,
                    name: newDeptName.trim(),
                    prefix: newDeptPrefix.trim(),
                    requestPrefix: newDeptRequestPrefix.trim(),
                    workGroupId: newDeptWorkGroup || undefined,
                    isActive: true
                });
                setNewDeptName(''); setNewDeptPrefix(''); setNewDeptRequestPrefix(''); setNewDeptWorkGroup('');
                setConfirmAction(null);
            }
        });
    };

    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id);
        setEditDeptName(dept.name);
        setEditDeptPrefix(dept.prefix || '');
        setEditDeptRequestPrefix(dept.requestPrefix || '');
        setEditDeptWorkGroup(dept.workGroupId || '');
    };

    // FIX 7: แก้ไขฝ่าย + FIX 5 (Confirm)
    const handleEditDepartment = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT',
            title: 'ยืนยันการแก้ไขฝ่าย/งาน',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงข้อมูลฝ่าย/งานใช่หรือไม่?',
            onConfirm: () => {
                updateDepartment(editingDeptId, {
                    name: editDeptName.trim(),
                    prefix: editDeptPrefix.trim(),
                    requestPrefix: editDeptRequestPrefix.trim(),
                    workGroupId: editDeptWorkGroup || undefined
                });
                setEditingDeptId(null);
                setConfirmAction(null);
            }
        });
    };

    // FIX 8: ลบฝ่าย (Soft Delete) + FIX 5 (Confirm)
    const handleDeleteDepartment = (dept: Department) => {
        setConfirmAction({
            type: 'DEL_DEPT',
            title: 'ระงับการใช้งานฝ่าย/งาน?',
            message: `คุณต้องการระงับการใช้งาน "${dept.name}" ใช่หรือไม่? (ข้อมูลจะไม่ถูกลบจริง)`,
            onConfirm: () => {
                deleteDepartment(dept.id); // Calls backend SOFT DELETE
                setConfirmAction(null);
            }
        });
    };

    // Sort: Active first
    const sortedWorkGroups = [...(settings.workGroups || [])].sort((a,b) => (a.isActive === b.isActive) ? 0 : a.isActive ? -1 : 1);
    const sortedDepartments = [...(settings.departments || [])].sort((a,b) => (a.isActive === b.isActive) ? 0 : a.isActive ? -1 : 1);

    return (
        <div className="p-6 relative min-h-screen pb-20 bg-slate-50">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">ตั้งค่าระบบ (Settings)</h2>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* 1. Work Groups Management */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-fit">
                    <div className="p-4 border-b border-slate-100 bg-orange-50/50">
                        <h3 className="font-bold text-slate-800 flex items-center"><Briefcase size={18} className="mr-2 text-orange-600"/> จัดการกลุ่มงาน</h3>
                    </div>
                    <div className="p-4">
                        <div className="flex space-x-2 mb-4">
                            <input className="flex-1 border rounded-lg px-3 py-1.5 text-sm" placeholder="ชื่อกลุ่มงานใหม่..." value={newWorkGroupName} onChange={e => setNewWorkGroupName(e.target.value)} />
                            <button onClick={handleAddWorkGroup} disabled={!newWorkGroupName.trim()} className="bg-orange-600 text-white px-3 rounded-lg disabled:opacity-50 hover:bg-orange-700 transition-colors"><Plus size={18}/></button>
                        </div>
                        <div className="space-y-2 max-h-[400px] overflow-y-auto">
                            {sortedWorkGroups.map(g => (
                                <div key={g.id} className={`flex justify-between items-center p-2 border rounded-lg transition-colors ${g.isActive ? 'bg-white' : 'bg-slate-100 opacity-70'}`}>
                                    {editingWorkGroupId === g.id ? (
                                        <div className="flex flex-1 items-center space-x-2">
                                            <input 
                                                autoFocus
                                                className="flex-1 border border-orange-300 rounded px-2 py-1 text-sm outline-none"
                                                value={editWorkGroupName}
                                                onChange={e => setEditWorkGroupName(e.target.value)}
                                            />
                                            <button onClick={handleEditWorkGroup} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={16}/></button>
                                            <button onClick={() => setEditingWorkGroupId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={16}/></button>
                                        </div>
                                    ) : (
                                        <>
                                            <div className="flex items-center space-x-2">
                                                <span className={`text-sm font-medium ${g.isActive ? 'text-slate-700' : 'text-slate-500 line-through'}`}>{g.name}</span>
                                                {!g.isActive && <span className="text-[10px] bg-red-100 text-red-600 px-1 rounded">Inactive</span>}
                                            </div>
                                            <div className="flex items-center space-x-1">
                                                <button onClick={() => startEditWorkGroup(g)} disabled={!g.isActive} className="text-slate-400 hover:text-orange-600 p-1 disabled:opacity-30" title="แก้ไข"><Edit2 size={14}/></button>
                                                <button onClick={() => handleDeleteWorkGroup(g)} disabled={!g.isActive} className="text-slate-400 hover:text-red-600 p-1 disabled:opacity-30" title="ระงับการใช้งาน">
                                                    {g.isActive ? <Trash2 size={14}/> : <PowerOff size={14}/>}
                                                </button>
                                            </div>
                                        </>
                                    )}
                                </div>
                            ))}
                            {sortedWorkGroups.length === 0 && <p className="text-center text-xs text-slate-400 py-4">ไม่พบข้อมูลกลุ่มงาน</p>}
                        </div>
                    </div>
                </div>

                {/* 2. Departments Management */}
                <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-fit">
                    <div className="p-4 border-b border-slate-100 bg-indigo-50/50">
                        <h3 className="font-bold text-slate-800 flex items-center"><Building size={18} className="mr-2 text-indigo-600"/> จัดการฝ่าย/งาน</h3>
                    </div>
                    <div className="p-4">
                        <div className="bg-slate-50 p-4 rounded-xl border mb-6 grid grid-cols-1 md:grid-cols-2 gap-3">
                            <select className="border rounded-lg px-3 py-2 text-sm" value={newDeptWorkGroup} onChange={e => setNewDeptWorkGroup(e.target.value)}>
                                <option value="">-- เลือกกลุ่มงานสังกัด --</option>
                                {settings.workGroups?.filter(g=>g.isActive).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                            </select>
                            <input className="border rounded-lg px-3 py-2 text-sm" placeholder="ชื่อฝ่าย (เช่น งานพัสดุ)" value={newDeptName} onChange={e => setNewDeptName(e.target.value)} />

                            <input className="border rounded-lg px-3 py-2 text-sm" placeholder="เลขที่ใบขอ (Prefix เฉพาะฝ่าย)" value={newDeptRequestPrefix} onChange={e => setNewDeptRequestPrefix(e.target.value)} />
                            <input className="border rounded-lg px-3 py-2 text-sm" placeholder="ตัวย่อ (เช่น พด.)" value={newDeptPrefix} onChange={e => setNewDeptPrefix(e.target.value)} />
                            <button onClick={handleAddDepartment} disabled={!newDeptName.trim()} className="md:col-span-2 bg-indigo-600 text-white py-2 rounded-lg font-bold hover:bg-indigo-700 transition-colors disabled:opacity-50">เพิ่มฝ่าย</button>
                        </div>

                        <div className="overflow-x-auto">
                            <table className="w-full text-xs text-left">
                                <thead className="bg-slate-50 text-slate-500 uppercase">
                                    <tr>
                                        <th className="px-3 py-2">กลุ่มงาน</th>
                                        <th className="px-3 py-2">ชื่อฝ่าย</th>
                                        <th className="px-3 py-2">เลขที่ใบขอ</th>
                                        <th className="px-3 py-2 text-center">ตัวย่อ</th>
                                        <th className="px-3 py-2 text-center">จัดการ</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y">
                                    {sortedDepartments.length === 0 ? <tr><td colSpan={5} className="text-center py-4 text-slate-400">ไม่พบข้อมูลฝ่าย</td></tr> : 
                                    sortedDepartments.map(dept => (
                                        <tr key={dept.id} className={`hover:bg-slate-50 transition-colors ${dept.isActive ? '' : 'bg-slate-100 opacity-60'}`}>
                                            <td className="px-3 py-2 text-slate-500">
                                                {editingDeptId === dept.id ? (
                                                    <select className="border rounded px-1 w-full" value={editDeptWorkGroup} onChange={e=>setEditDeptWorkGroup(e.target.value)}>
                                                        <option value="">--</option>
                                                        {settings.workGroups?.filter(g=>g.isActive).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                                    </select>
                                                ) : settings.workGroups?.find(g=>g.id===dept.workGroupId)?.name || '-'}
                                            </td>
                                            <td className="px-3 py-2 font-medium">
                                                {editingDeptId === dept.id ? <input className="border rounded px-1 w-full" value={editDeptName} onChange={e=>setEditDeptName(e.target.value)}/> : 
                                                <span className={dept.isActive ? '' : 'line-through text-slate-500'}>{dept.name}</span>}
                                            </td>

                                            <td className="px-3 py-2 font-mono">
                                                {editingDeptId === dept.id ? <input className="border rounded px-1 w-full" value={editDeptRequestPrefix} onChange={e=>setEditDeptRequestPrefix(e.target.value)}/> : dept.requestPrefix || '-'}
                                            </td>
                                            <td className="px-3 py-2 text-center font-bold text-indigo-600">
                                                {editingDeptId === dept.id ? <input className="border rounded px-1 w-full text-center" value={editDeptPrefix} onChange={e=>setEditDeptPrefix(e.target.value)}/> : dept.prefix || '-'}
                                            </td>
                                            <td className="px-3 py-2 text-center">
                                                {editingDeptId === dept.id ? (
                                                    <div className="flex justify-center space-x-1">
                                                        <button onClick={handleEditDepartment} className="text-green-600 bg-green-50 p-1 rounded hover:bg-green-100"><Check size={14}/></button>
                                                        <button onClick={()=>setEditingDeptId(null)} className="text-red-600 bg-red-50 p-1 rounded hover:bg-red-100"><X size={14}/></button>
                                                    </div>
                                                ) : (
                                                    <div className="flex justify-center space-x-1">
                                                        <button onClick={()=>startEditDept(dept)} disabled={!dept.isActive} className="text-slate-400 hover:text-indigo-600 p-1 disabled:opacity-30" title="แก้ไข"><Edit2 size={14}/></button>
                                                        <button onClick={()=>handleDeleteDepartment(dept)} disabled={!dept.isActive} className="text-slate-400 hover:text-red-600 p-1 disabled:opacity-30" title="ระงับการใช้งาน">
                                                            {dept.isActive ? <Trash2 size={14}/> : <PowerOff size={14}/>}
                                                        </button>
                                                    </div>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>

            {/* Reusable Confirmation Modal */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-white/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4">
                            <AlertCircle className="h-6 w-6 text-blue-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed whitespace-pre-line">
                            {confirmAction.message}
                        </p>
                        <div className="flex justify-center space-x-3">
                            <button 
                                onClick={() => setConfirmAction(null)}
                                className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmAction.onConfirm}
                                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors font-medium text-sm"
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

