        if (users.length > 0) {
            const u = users[0];
            if (u.status !== 'ACTIVE') return res.json({ success: false, message: 'บัญชีรอการอนุมัติหรือถูกระงับ' });
            res.json({ success: true, user: { id: u.id, username: u.username, name: u.name, role: u.role, departmentId: u.department_id } });
        } else {
            res.json({ success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' });
        }
    } catch(e) { res.status(500).json({success: false, message: e.message}); }
});

