    // Departments Input
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptRequestPrefix, setNewDeptRequestPrefix] = useState('');
    const [newDeptWorkGroup, setNewDeptWorkGroup] = useState('');

    // Work Group Input
    const [newWorkGroupName, setNewWorkGroupName] = useState('');

    // Editing State: WorkGroup
    const [editingWorkGroupId, setEditingWorkGroupId] = useState<string | null>(null);
    const [editWorkGroupName, setEditWorkGroupName] = useState('');

    // Editing State: Department
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState('');
    const [editDeptRequestPrefix, setEditDeptRequestPrefix] = useState('');
    const [editDeptWorkGroup, setEditDeptWorkGroup] = useState('');

    // Confirmation Modal State (Fix 5: Confirmation)
    const [confirmAction, setConfirmAction] = useState<{
        type: 'ADD_WG' | 'EDIT_WG' | 'DEL_WG' | 'ADD_DEPT' | 'EDIT_DEPT' | 'DEL_DEPT';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // --- Work Group Handlers ---
    const handleAddWorkGroup = () => {
        if (!newWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'ADD_WG',
            title: 'ยืนยันการเพิ่มกลุ่มงาน',
            message: `คุณต้องการเพิ่มกลุ่มงาน "${newWorkGroupName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addWorkGroup({ id: `group_${Date.now()}`, name: newWorkGroupName.trim(), isActive: true });
                setNewWorkGroupName('');
                setConfirmAction(null);
            }
        });
    };

    const startEditWorkGroup = (g: WorkGroup) => {
        setEditingWorkGroupId(g.id);
        setEditWorkGroupName(g.name);
    };

    // Fix 4: Edit Work Group
    const handleEditWorkGroup = () => {
        if (!editingWorkGroupId || !editWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'EDIT_WG',
            title: 'ยืนยันการแก้ไข',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงชื่อกลุ่มงานใช่หรือไม่?',
            onConfirm: () => {
                updateWorkGroup(editingWorkGroupId, editWorkGroupName.trim());
                setEditingWorkGroupId(null);
                setConfirmAction(null);
            }
        });
    };

    // Fix 3: Soft Delete Work Group
    const handleDeleteWorkGroup = (g: WorkGroup) => {
        setConfirmAction({
            type: 'DEL_WG',
            title: 'ระงับการใช้งานกลุ่มงาน?',
            message: `คุณต้องการระงับการใช้งาน "${g.name}" ใช่หรือไม่? \n(ข้อมูลจะไม่ถูกลบจริง แต่จะถูกซ่อนไว้)`,
            onConfirm: () => {
                deleteWorkGroup(g.id);
                setConfirmAction(null);
            }
        });
