});
router.post('/considerations/upsert', async (req, res) => {
    const c = req.body;
    const existing = await query('SELECT id FROM considerations WHERE request_id = ?', [c.requestId]);
    if (existing.length > 0) {
        await query('UPDATE considerations SET consideration_number=?, consideration_date=? WHERE request_id=?', [c.considerationNumber, c.considerationDate, c.requestId]);
    } else {
        await query('INSERT INTO considerations (id, request_id, consideration_number, consideration_date) VALUES (?,?,?,?)', [c.id, c.requestId, c.considerationNumber, c.considerationDate]);
    }
    res.json({ success: true });
});

