router.patch('/department/:id', async (req, res) => {
    const d = req.body;
    let sql = "UPDATE departments SET ";
    const params = [];
    if (d.name) { sql += "name=?, "; params.push(d.name); }
    if (d.prefix !== undefined) { sql += "prefix=?, "; params.push(d.prefix); }
    if (d.requestPrefix !== undefined) { sql += "request_prefix=?, "; params.push(d.requestPrefix); }
    if (d.workGroupId !== undefined) { sql += "work_group_id=?, "; params.push(d.workGroupId); }

    sql = sql.slice(0, -2); // remove last comma
    sql += " WHERE id=?";
    params.push(req.params.id);

    if (params.length > 1) {
        await query(sql, params);
    }
    res.json({ success: true });
});

