    // Inputs
    const [newWorkGroupName, setNewWorkGroupName] = useState('');
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptRequestPrefix, setNewDeptRequestPrefix] = useState('');
    const [newDeptWorkGroup, setNewDeptWorkGroup] = useState('');

