    const [editingWorkGroupId, setEditingWorkGroupId] = useState<string | null>(null);
    const [editWorkGroupName, setEditWorkGroupName] = useState('');
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState('');
    const [editDeptRequestPrefix, setEditDeptRequestPrefix] = useState('');
