            onConfirm: () => {
                addWorkGroup({ id: `g_${Date.now()}`, name: newWorkGroupName.trim(), isActive: true });
                setNewWorkGroupName('');
                setConfirmAction(null);
            }
        });
    };

    const startEditWorkGroup = (g: WorkGroup) => {
        setEditingWorkGroupId(g.id);
        setEditWorkGroupName(g.name);
    };

    const handleEditWorkGroup = () => {
        if (!editingWorkGroupId) return;
        setConfirmAction({
            title: 'ยืนยันการแก้ไข',
            message: 'ต้องการบันทึกการแก้ไขชื่อกลุ่มงานใช่หรือไม่?',
