                                                        <button onClick={()=>startEditDept(d)} disabled={!d.isActive} className="text-slate-400 hover:text-indigo-600 disabled:opacity-30"><Edit2 size={14}/></button>
                                                        <button onClick={()=>handleDeleteDepartment(d)} disabled={!d.isActive} className="text-slate-400 hover:text-red-600 disabled:opacity-30">
                                                            {d.isActive ? <Trash2 size={14}/> : <PowerOff size={14}/>}
                                                        </button>
                                                    </div>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal */}
            {confirmAction && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                    <div className="bg-white p-6 rounded-xl shadow-xl max-w-sm w-full text-center">
                        <AlertCircle className="mx-auto text-blue-600 h-10 w-10 mb-4"/>
                        <h3 className="font-bold text-lg mb-2">{confirmAction.title}</h3>
                        <p className="text-slate-600 mb-6">{confirmAction.message}</p>
                        <div className="flex gap-2">
                            <button onClick={() => setConfirmAction(null)} className="flex-1 py-2 bg-slate-100 rounded hover:bg-slate-200">ยกเลิก</button>
                            <button onClick={confirmAction.onConfirm} className="flex-1 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">ยืนยัน</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

