                            <div className="flex flex-col space-y-2 mb-4 flex-shrink-0">
                                <input 
                                    type="text" 
                                    className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-green-500 outline-none text-sm"
                                    placeholder="ชื่อหมวดหมู่..."
                                    value={newCategoryName}
                                    onChange={e => setNewCategoryName(e.target.value)}
                                />
                                <div className="flex space-x-2">
                                    <select 
                                        className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500 bg-white text-slate-900"
                                        value={newCategoryDept}
                                        onChange={e => setNewCategoryDept(e.target.value)}
                                    >
                                        <option value="">-- ไม่ระบุฝ่าย --</option>
                                        {localSettings.departments?.filter(d => d.isActive).map(d => (
                                            <option key={d.id} value={d.id}>{d.name}</option>
                                        ))}
                                    </select>
                                    <button onClick={addCategoryRequest} disabled={!newCategoryName.trim()} className="bg-green-600 hover:bg-green-700 disabled:bg-slate-300 text-white px-4 py-2 rounded-lg shadow-sm">
                                        <Plus size={20} />
                                    </button>
                                </div>
                            </div>

                            {/* Scrollable List */}
                            <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                                {localSettings.categories.map((cat) => {
                                    const deptName = localSettings.departments?.find(d => d.id === cat.departmentId)?.name;

                                    return (
                                        <div key={cat.id} className={`p-3 border rounded-lg group transition-all ${cat.isActive ? 'bg-white border-slate-100 hover:border-green-200' : 'bg-slate-50 border-slate-200 opacity-60'}`}>
                                            {editingCategoryId === cat.id ? (
                                                <div className="space-y-2">
                                                    <input 
                                                        className="w-full bg-white text-slate-900 border border-green-300 rounded px-2 py-1 text-sm outline-none"
                                                        value={editCatName}
                                                        onChange={e => setEditCatName(e.target.value)}
                                                    />
                                                    <div className="flex space-x-2">
                                                        <select 
                                                            className="flex-1 border border-green-300 rounded px-2 py-1 text-sm outline-none bg-white text-slate-900"
                                                            value={editCatDept}
                                                            onChange={e => setEditCatDept(e.target.value)}
                                                        >
                                                            <option value="">-- ไม่ระบุฝ่าย --</option>
                                                            {localSettings.departments?.filter(d => d.isActive).map(d => (
                                                                <option key={d.id} value={d.id}>{d.name}</option>
                                                            ))}
                                                        </select>
                                                        <button onClick={saveEditCategoryRequest} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={18}/></button>
                                                        <button onClick={() => setEditingCategoryId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={18}/></button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex justify-between items-center">
                                                    <div>
                                                        <div className={`font-medium text-sm ${cat.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{cat.name}</div>
                                                        {deptName && (
                                                            <div className={`text-xs px-2 py-0.5 rounded-full inline-block mt-1 ${cat.isActive ? 'text-indigo-500 bg-indigo-50' : 'text-slate-400 bg-slate-100'}`}>
                                                                {deptName}
                                                            </div>
                                                        )}
                                                    </div>
                                                    <div className="flex items-center space-x-1">
                                                        <button onClick={() => startEditCategory(cat)} className="p-1.5 text-slate-400 hover:text-green-600 opacity-0 group-hover:opacity-100 transition-opacity"><Edit2 size={16}/></button>
                                                        <button 
                                                            onClick={() => toggleCatStatus(cat.id)} 
                                                            className={`p-1.5 rounded transition-colors ${cat.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-400 hover:text-green-600 hover:bg-green-50'}`}
                                                            title={cat.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                        >
                                                            {cat.isActive ? <Power size={16} /> : <PowerOff size={16} />}
                                                        </button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Reusable Confirmation Modal Overlay */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-white/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4">
                            <AlertCircle className="h-6 w-6 text-blue-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                            {confirmAction.message}
                        </p>
                        <div className="flex justify-center space-x-3">
                            <button 
                                onClick={() => setConfirmAction(null)}
                                className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmAction.onConfirm}
                                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors font-medium text-sm"
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React from 'react';
import { useApp } from '../services/store';
import { LayoutDashboard, ShoppingCart, Briefcase, Settings, Users, LogOut, User as UserIcon, Archive, X, UserCheck } from 'lucide-react';

interface SidebarProps {
    activeTab: string;
    setActiveTab: (tab: string) => void;
    isOpen: boolean;
    setIsOpen: (open: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isOpen, setIsOpen }) => {
    const { currentUser, logout, users } = useApp();

    const pendingCount = users.filter(u => u.status === 'PENDING').length;

    const menuItems = [
        { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
        { id: 'purchase', label: 'ทะเบียนคุมจัดซื้อ (PO)', icon: ShoppingCart },
        { id: 'hiring', label: 'ทะเบียนคุมจัดจ้าง (HO)', icon: Briefcase },
        { id: 'other', label: 'ทะเบียนคุมอื่นๆ', icon: Archive },
    ];

    const adminItems = [];
    if (currentUser?.role === 'ADMIN') {
        adminItems.push({ 
            id: 'pending_users', 
            label: 'รอยืนยันการสมัคร', 
            icon: UserCheck,
            badge: pendingCount > 0 ? pendingCount : null 
        });
        adminItems.push({ id: 'users', label: 'จัดการผู้ใช้งาน', icon: Users });
        adminItems.push({ id: 'settings', label: 'ตั้งค่าระบบ', icon: Settings });
    }

    const handleMenuClick = (id: string) => {
        setActiveTab(id);
        if (window.innerWidth < 1024) {
            setIsOpen(false);
        }
    };

    return (
        <>
            {/* Overlay for mobile */}
            {isOpen && (
                <div 
                    className="fixed inset-0 bg-black/50 z-[60] lg:hidden backdrop-blur-sm transition-opacity"
                    onClick={() => setIsOpen(false)}
                />
            )}

            {/* Sidebar Container */}
            <div className={`fixed left-0 top-0 h-screen bg-slate-900 text-white flex flex-col overflow-y-auto z-[70] transition-all duration-300 ease-in-out shadow-2xl
                ${isOpen ? 'w-64 translate-x-0' : 'w-64 -translate-x-full lg:translate-x-0'}`}>

                <div className="p-6 border-b border-slate-700 flex justify-between items-center">
                    <div>
                        <h1 className="text-xl font-bold text-blue-400">Procurement OS</h1>
                        <p className="text-xs text-slate-400 mt-1">ระบบบริหารงานพัสดุ</p>
                    </div>
                    <button onClick={() => setIsOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1">
                        <X size={24} />
                    </button>
                </div>

                {/* User Profile Summary */}
                <div className="px-6 py-4 flex items-center space-x-3 border-b border-slate-800">
                    <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-blue-300 flex-shrink-0">
                        <UserIcon size={20} />
                    </div>
                    <div className="overflow-hidden">
                        <p className="text-sm font-semibold truncate">{currentUser?.name}</p>
                        <p className="text-xs text-slate-500 uppercase">{currentUser?.role}</p>
                    </div>
                </div>

                <nav className="flex-1 p-4 space-y-1">
                    {menuItems.map((item) => {
                        const Icon = item.icon;
                        return (
                            <button
                                key={item.id}
                                onClick={() => handleMenuClick(item.id)}
                                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                                    activeTab === item.id 
                                    ? 'bg-blue-600 text-white shadow-lg' 
                                    : 'text-slate-300 hover:bg-slate-800'
                                }`}
                            >
                                <Icon size={20} />
                                <span className="font-medium text-sm">{item.label}</span>
                            </button>
                        );
                    })}

                    {adminItems.length > 0 && (
                        <div className="pt-4 pb-2">
                            <p className="px-4 text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2">Admin Panel</p>
                            {adminItems.map((item) => {
                                const Icon = item.icon;
                                return (
                                    <button
                                        key={item.id}
                                        onClick={() => handleMenuClick(item.id)}
                                        className={`w-full flex items-center justify-between px-4 py-3 rounded-lg transition-colors mb-1 ${
                                            activeTab === item.id 
                                            ? 'bg-indigo-600 text-white shadow-lg' 
                                            : 'text-slate-300 hover:bg-slate-800'
                                        }`}
                                    >
                                        <div className="flex items-center space-x-3">
                                            <Icon size={20} />
                                            <span className="font-medium text-sm">{item.label}</span>
                                        </div>
                                        {item.badge && (
                                            <span className="bg-red-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[18px] text-center animate-pulse">
                                                {item.badge}
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                    )}
                </nav>

                <div className="p-4 border-t border-slate-700">
                    <button 
                        onClick={logout}
                        className="w-full flex items-center justify-center space-x-2 px-4 py-2 bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white rounded-lg transition-all"
                    >
                        <LogOut size={18} />
                        <span>ออกจากระบบ</span>
                    </button>
                    <div className="text-xs text-slate-500 text-center mt-4 leading-tight space-y-1">
                        <p>โรงพยาบาลสามชุก</p>
                        <p>กลุ่มงานสุขภาพดิจิทัล</p>
                        <p className="opacity-60">Version 1.3.3</p>
                    </div>
                </div>
            </div>
        </>
    );
};

export default Sidebar;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { Save, Plus, Edit2, X, Check, Layers, Building, Power, PowerOff, AlertCircle } from 'lucide-react';
import { Department, ProcurementCategory } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, updateSettings } = useApp();
    const [localSettings, setLocalSettings] = useState(settings);
    const [saved, setSaved] = useState(false);

    // --- Confirmation UI State ---
    const [confirmAction, setConfirmAction] = useState<{
        type: 'PREFIX' | 'ADD_DEPT' | 'EDIT_DEPT' | 'ADD_CAT' | 'EDIT_CAT';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // --- Department State ---
    const [newDeptName, setNewDeptName] = useState('');
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');

    // --- Category State ---
    const [newCategoryName, setNewCategoryName] = useState('');
    const [newCategoryDept, setNewCategoryDept] = useState('');
    const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
    const [editCatName, setEditCatName] = useState('');
    const [editCatDept, setEditCatDept] = useState('');

    const handleSavePrefixRequest = (e: React.FormEvent) => {
        e.preventDefault();
        setConfirmAction({
            type: 'PREFIX',
            title: 'ยืนยันการบันทึกรูปแบบเลขที่?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงรูปแบบเลขที่ใบขอใช่หรือไม่?',
            onConfirm: () => {
                updateSettings(localSettings);
                setSaved(true);
                setTimeout(() => setSaved(false), 2000);
                setConfirmAction(null);
            }
        });
    };

    // --- Department Handlers ---
    const addDepartmentRequest = () => {
        if (!newDeptName.trim()) return;
        setConfirmAction({
            type: 'ADD_DEPT',
            title: 'ยืนยันการเพิ่มฝ่าย/งาน?',
            message: `ต้องการเพิ่มฝ่าย "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                const newDept: Department = {
                    id: `dept_${Date.now()}`,
                    name: newDeptName.trim(),
                    isActive: true
                };
                const updatedDepts = [...(localSettings.departments || []), newDept];
                const newSettings = { ...localSettings, departments: updatedDepts };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setNewDeptName('');
                setConfirmAction(null);
            }
        });
    };

    const toggleDeptStatus = (id: string) => {
        const updatedDepts = localSettings.departments.map(d => 
            d.id === id ? { ...d, isActive: !d.isActive } : d
        );
        const newSettings = { ...localSettings, departments: updatedDepts };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
    };

    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id);
        setEditDeptName(dept.name);
    };

    const saveEditDeptRequest = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT',
            title: 'ยืนยันการแก้ไขข้อมูล?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงชื่อฝ่ายใช่หรือไม่?',
            onConfirm: () => {
                const updatedDepts = localSettings.departments.map(d => 
                    d.id === editingDeptId ? { ...d, name: editDeptName.trim() } : d
                );
                const newSettings = { ...localSettings, departments: updatedDepts };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setEditingDeptId(null);
                setConfirmAction(null);
            }
        });
    };

    // --- Category Handlers ---
    const addCategoryRequest = () => {
        if (!newCategoryName.trim()) return;
        setConfirmAction({
            type: 'ADD_CAT',
            title: 'ยืนยันการเพิ่มหมวดพัสดุ?',
            message: `ต้องการเพิ่มหมวดพัสดุ "${newCategoryName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                const newCat: ProcurementCategory = {
                    id: Date.now().toString(),
                    name: newCategoryName.trim(),
                    departmentId: newCategoryDept || undefined,
                    isActive: true
                };
                const updatedCategories = [...localSettings.categories, newCat];
                const newSettings = { ...localSettings, categories: updatedCategories };
                setLocalSettings(newSettings);
                updateSettings(newSettings); 
                setNewCategoryName('');
                setNewCategoryDept('');
                setConfirmAction(null);
            }
        });
    };

    const toggleCatStatus = (id: string) => {
        const updatedCategories = localSettings.categories.map(c => 
            c.id === id ? { ...c, isActive: !c.isActive } : c
        );
        const newSettings = { ...localSettings, categories: updatedCategories };
        setLocalSettings(newSettings);
        updateSettings(newSettings);
    };

    const startEditCategory = (cat: ProcurementCategory) => {
        setEditingCategoryId(cat.id);
        setEditCatName(cat.name);
        setEditCatDept(cat.departmentId || '');
    };

    const saveEditCategoryRequest = () => {
        if (!editCatName.trim() || !editingCategoryId) return;
        setConfirmAction({
            type: 'EDIT_CAT',
            title: 'ยืนยันการแก้ไขหมวดพัสดุ?',
            message: 'คุณต้องการบันทึกการเปลี่ยนแปลงข้อมูลหมวดพัสดุใช่หรือไม่?',
            onConfirm: () => {
                const updatedCategories = localSettings.categories.map(c => 
                    c.id === editingCategoryId ? { 
                        ...c, 
                        name: editCatName.trim(),
                        departmentId: editCatDept || undefined
                    } : c
                );
                const newSettings = { ...localSettings, categories: updatedCategories };
                setLocalSettings(newSettings);
                updateSettings(newSettings);
                setEditingCategoryId(null);
                setConfirmAction(null);
            }
        });
    };

    return (
        // ✅ LAYOUT FIX: ใช้ h-screen และ flex-col เพื่อดันให้เต็มจอ (ตัด min-h-screen ออก)
        <div className="p-6 bg-slate-50 h-screen flex flex-col overflow-hidden pb-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6 flex-shrink-0">ตั้งค่าระบบ (Settings)</h2>

            <div className="flex flex-col h-full overflow-hidden space-y-6">

                {/* 1. Document Format Settings (Fixed Height) */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-shrink-0">
                    <div className="p-4 border-b border-slate-100 bg-slate-50">
                        <h3 className="text-lg font-semibold text-slate-800">รูปแบบเอกสาร</h3>
                        <p className="text-sm text-slate-500">กำหนดค่าเริ่มต้นสำหรับเลขที่เอกสาร</p>
                    </div>

                    <form onSubmit={handleSavePrefixRequest} className="p-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-2">
                                รูปแบบเลขที่ใบขอ (Prefix)
                            </label>
                            <div className="flex space-x-2">
                                <input 
                                    type="text" 
                                    className="flex-1 bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none font-medium"
                                    value={localSettings.requestIdPrefix}
                                    onChange={e => setLocalSettings({...localSettings, requestIdPrefix: e.target.value})}
                                    placeholder="เช่น สพ.๐๐๓๓.๐๒/"
                                />
                                <button 
                                    type="submit" 
                                    className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg shadow-sm transition-all"
                                >
                                    <Save size={18} />
                                    <span>บันทึก</span>
                                </button>
                            </div>
                            <p className="text-xs text-red-500 mt-2 font-medium">
                                ค่านี้จะถูกนำไปเติมให้อัตโนมัติเมื่อสร้างรายการใหม่
                            </p>
                            {saved && (
                                <p className="text-green-600 text-sm font-medium animate-fade-in mt-2">
                                    บันทึกเรียบร้อยแล้ว!
                                </p>
                            )}
                        </div>
                    </form>
                </div>

                {/* Main Grid Container: Fill remaining height */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0">

                    {/* 2. Department Management (Full Height) */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
                        <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center flex-shrink-0">
                            <div>
                                <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                    <Building size={20} className="mr-2 text-indigo-600"/> จัดการฝ่าย/งาน
                                </h3>
                                <p className="text-sm text-red-500 font-medium">รายชื่อฝ่ายภายในองค์กร</p>
                            </div>
                        </div>

                        <div className="p-4 flex-1 flex flex-col min-h-0">
                            <div className="flex space-x-2 mb-4 flex-shrink-0">
                                <input 
                                    type="text" 
                                    className="flex-1 bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                                    placeholder="ชื่อฝ่าย/งานใหม่..."
                                    value={newDeptName}
                                    onChange={e => setNewDeptName(e.target.value)}
                                    onKeyDown={e => e.key === 'Enter' && addDepartmentRequest()}
                                />
                                <button onClick={addDepartmentRequest} disabled={!newDeptName.trim()} className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white px-3 py-2 rounded-lg shadow-sm">
                                    <Plus size={20} />
                                </button>
                            </div>

                            {/* Scrollable List */}
                            <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                                {localSettings.departments?.map((dept) => (
                                    <div key={dept.id} className={`flex items-center justify-between p-3 border rounded-lg group transition-all ${dept.isActive ? 'bg-white border-slate-200' : 'bg-slate-50 border-slate-200 opacity-60'}`}>
                                        {editingDeptId === dept.id ? (
                                            <div className="flex items-center space-x-2 flex-1">
                                                <input 
                                                    autoFocus
                                                    className="flex-1 bg-white text-slate-900 border border-indigo-300 rounded px-2 py-1 text-sm outline-none"
                                                    value={editDeptName}
                                                    onChange={e => setEditDeptName(e.target.value)}
                                                    onKeyDown={e => e.key === 'Enter' && saveEditDeptRequest()}
                                                />
                                                <button onClick={saveEditDeptRequest} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={16}/></button>
                                                <button onClick={() => setEditingDeptId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={16}/></button>
                                            </div>
                                        ) : (
                                            <>
                                                <div className="flex items-center">
                                                    <span className={`text-sm font-medium ${dept.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{dept.name}</span>
                                                    {!dept.isActive && <span className="ml-2 text-[10px] bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded">INACTIVE</span>}
                                                </div>
                                                <div className="flex items-center space-x-1">
                                                    <button onClick={() => startEditDept(dept)} className="p-1 text-slate-400 hover:text-indigo-600 opacity-0 group-hover:opacity-100 transition-opacity"><Edit2 size={14}/></button>
                                                    <button 
                                                        onClick={() => toggleDeptStatus(dept.id)} 
                                                        className={`p-1 rounded transition-colors ${dept.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-400 hover:text-green-600 hover:bg-green-50'}`}
                                                        title={dept.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                    >
                                                        {dept.isActive ? <Power size={14} /> : <PowerOff size={14} />}
                                                    </button>
                                                </div>
                                            </>
                                        )}
                                    </div>
                                ))}
                                {(!localSettings.departments || localSettings.departments.length === 0) && (
                                    <p className="text-center text-slate-400 text-sm py-4">ยังไม่มีข้อมูลฝ่าย</p>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* 3. Category Management (Full Height) */}
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
                        <div className="p-4 border-b border-slate-100 bg-slate-50 flex-shrink-0">
                            <h3 className="text-lg font-semibold text-slate-800 flex items-center">
                                <Layers size={20} className="mr-2 text-green-600"/> จัดการหมวดพัสดุ
                            </h3>
                            <p className="text-sm text-red-500 font-medium">สัมพันธ์กับฝ่ายที่รับผิดชอบ</p>
                        </div>

                        <div className="p-4 flex-1 flex flex-col min-h-0">
                            <div className="flex flex-col space-y-2 mb-4 flex-shrink-0">
                                <input 
                                    type="text" 
                                    className="w-full bg-white text-slate-900 border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-green-500 outline-none text-sm"
                                    placeholder="ชื่อหมวดหมู่..."
                                    value={newCategoryName}
                                    onChange={e => setNewCategoryName(e.target.value)}
                                />
                                <div className="flex space-x-2">
                                    <select 
                                        className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500 bg-white text-slate-900"
                                        value={newCategoryDept}
                                        onChange={e => setNewCategoryDept(e.target.value)}
                                    >
                                        <option value="">-- ไม่ระบุฝ่าย --</option>
                                        {localSettings.departments?.filter(d => d.isActive).map(d => (
                                            <option key={d.id} value={d.id}>{d.name}</option>
                                        ))}
                                    </select>
                                    <button onClick={addCategoryRequest} disabled={!newCategoryName.trim()} className="bg-green-600 hover:bg-green-700 disabled:bg-slate-300 text-white px-4 py-2 rounded-lg shadow-sm">
                                        <Plus size={20} />
                                    </button>
                                </div>
                            </div>

                            {/* Scrollable List */}
                            <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                                {localSettings.categories.map((cat) => {
                                    const deptName = localSettings.departments?.find(d => d.id === cat.departmentId)?.name;

                                    return (
                                        <div key={cat.id} className={`p-3 border rounded-lg group transition-all ${cat.isActive ? 'bg-white border-slate-100 hover:border-green-200' : 'bg-slate-50 border-slate-200 opacity-60'}`}>
                                            {editingCategoryId === cat.id ? (
                                                <div className="space-y-2">
                                                    <input 
                                                        className="w-full bg-white text-slate-900 border border-green-300 rounded px-2 py-1 text-sm outline-none"
                                                        value={editCatName}
                                                        onChange={e => setEditCatName(e.target.value)}
                                                    />
                                                    <div className="flex space-x-2">
                                                        <select 
                                                            className="flex-1 border border-green-300 rounded px-2 py-1 text-sm outline-none bg-white text-slate-900"
                                                            value={editCatDept}
                                                            onChange={e => setEditCatDept(e.target.value)}
                                                        >
                                                            <option value="">-- ไม่ระบุฝ่าย --</option>
                                                            {localSettings.departments?.filter(d => d.isActive).map(d => (
                                                                <option key={d.id} value={d.id}>{d.name}</option>
                                                            ))}
                                                        </select>
                                                        <button onClick={saveEditCategoryRequest} className="text-green-600 hover:bg-green-100 p-1 rounded"><Check size={18}/></button>
                                                        <button onClick={() => setEditingCategoryId(null)} className="text-red-500 hover:bg-red-100 p-1 rounded"><X size={18}/></button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex justify-between items-center">
                                                    <div>
                                                        <div className={`font-medium text-sm ${cat.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{cat.name}</div>
                                                        {deptName && (
                                                            <div className={`text-xs px-2 py-0.5 rounded-full inline-block mt-1 ${cat.isActive ? 'text-indigo-500 bg-indigo-50' : 'text-slate-400 bg-slate-100'}`}>
                                                                {deptName}
                                                            </div>
                                                        )}
                                                    </div>
                                                    <div className="flex items-center space-x-1">
                                                        <button onClick={() => startEditCategory(cat)} className="p-1.5 text-slate-400 hover:text-green-600 opacity-0 group-hover:opacity-100 transition-opacity"><Edit2 size={16}/></button>
                                                        <button 
                                                            onClick={() => toggleCatStatus(cat.id)} 
                                                            className={`p-1.5 rounded transition-colors ${cat.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-400 hover:text-green-600 hover:bg-green-50'}`}
                                                            title={cat.isActive ? "ระงับการใช้งาน" : "เปิดใช้งาน"}
                                                        >
                                                            {cat.isActive ? <Power size={16} /> : <PowerOff size={16} />}
                                                        </button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Reusable Confirmation Modal Overlay */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-white/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl border border-slate-200 p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4">
                            <AlertCircle className="h-6 w-6 text-blue-600" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                            {confirmAction.message}
                        </p>
                        <div className="flex justify-center space-x-3">
                            <button 
                                onClick={() => setConfirmAction(null)}
                                className="flex-1 px-4 py-2 text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmAction.onConfirm}
                                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-lg transition-colors font-medium text-sm"
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

