                                            <td className="px-3 py-2 text-center">
                                                {editingDeptId === dept.id ? (
                                                    <div className="flex justify-center space-x-1">
                                                        <button onClick={requestSaveEditDept} className="text-green-600 bg-green-50 p-1 rounded hover:bg-green-100"><Check size={14}/></button>
                                                        <button onClick={()=>setEditingDeptId(null)} className="text-red-600 bg-red-50 p-1 rounded hover:bg-red-100"><X size={14}/></button>
                                                    </div>
                                                ) : (
                                                    <div className="flex justify-center space-x-1">
                                                        <button onClick={()=>startEditDept(dept)} className="text-slate-400 hover:text-indigo-600 p-1 hover:bg-indigo-50 rounded"><Edit2 size={14}/></button>
                                                        <button 
                                                            onClick={() => requestToggleDept(dept)} 
                                                            className={`p-1 rounded transition-colors ${dept.isActive ? 'text-slate-400 hover:text-red-500 hover:bg-red-50' : 'text-green-500 hover:text-green-600 hover:bg-green-50'}`}
                                                        >
                                                            {dept.isActive ? <Power size={14} /> : <PowerOff size={14} />}
                                                        </button>
                                                    </div>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>

            {/* ================= Confirmation Modal ================= */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-slate-100">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4 text-blue-600">
                            <AlertCircle className="h-6 w-6" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                            {confirmAction.message}
                        </p>
                        <div className="flex space-x-3">
                            <button 
                                onClick={() => setConfirmAction(null)}
                                className="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-semibold transition-all"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={confirmAction.onConfirm}
                                className="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-semibold shadow-md transition-all"
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

