const express = require('express');
const mysql = require('mysql2');
const nodemailer = require('nodemailer');
const router = express.Router();

// ==========================================
// 🛠️ DATABASE CONFIGURATION
// ==========================================
const DB_CONFIG = { 
    host: '10.1.0.201', 
    user: 'sa', 
    password: 'Sam#11294', 
    database: 'procurement_db', 
    port: 3306,
    waitForConnections: true, 
    connectionLimit: 10,
    timezone: '+07:00',
    dateStrings: true,
    // Note: We handle charset explicitly in the connection wrapper
    multipleStatements: true
};

const db = mysql.createPool(DB_CONFIG);

// Helper function for queries with ENFORCED UTF8MB4
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }

        // 🔥 CRITICAL FIX: Force charset session before every query
        // This ensures Thai characters are handled correctly (prevents Alien Language/Mojibake)
        connection.query("SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci'", (err) => {
            if (err) {
                connection.release();
                console.error("Charset Error:", err);
                return reject(err);
            }

            // Now run the actual query
            connection.query(sql, params, (err, res) => {
                connection.release(); // Always release connection back to pool
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

// ==========================================
// API ROUTES
// ==========================================

// Login
router.post('/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const users = await query('SELECT * FROM users WHERE username = ? AND password = ?', [username, password]);
        if (users.length > 0) {
            const u = users[0];
            if (u.status !== 'ACTIVE') return res.json({ success: false, message: 'บัญชีรอการอนุมัติหรือถูกระงับ' });
            res.json({ success: true, user: { id: u.id, username: u.username, name: u.name, role: u.role, departmentId: u.department_id } });
        } else {
            res.json({ success: false, message: 'ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง' });
        }
    } catch(e) { res.status(500).json({success: false, message: e.message}); }
});

// Get Data
router.get('/data', async (req, res) => {
    try {
        const [p, r, c, d, w, cat] = await Promise.all([
            query('SELECT * FROM procurements'), 
            query('SELECT * FROM receivings'),
            query('SELECT * FROM considerations'), 
            query('SELECT * FROM departments'),
            query('SELECT * FROM work_groups'), 
            query('SELECT * FROM procurement_categories')
        ]);
        res.json({
            procurements: p.map(x => ({ ...x, requestId: x.request_id, requestDate: x.request_date, officialNumber: x.official_number, departmentId: x.department_id, createdBy: x.created_by, createdAt: x.created_at })),
            receivings: r.map(x => ({ ...x, requestId: x.request_id, deliveryNoteNo: x.delivery_note_no, receiveDate: x.receive_date })),
            considerations: c.map(x => ({ ...x, requestId: x.request_id, considerationNumber: x.consideration_number, considerationDate: x.consideration_date })),
            settings: { 
                departments: d.map(x => ({ ...x, workGroupId: x.work_group_id, requestPrefix: x.request_prefix, isActive: x.is_active === 1 })), 
                workGroups: w.map(x => ({ ...x, isActive: x.is_active === 1 })), 
                categories: cat.map(x => ({ ...x, departmentId: x.department_id, isActive: x.is_active === 1 }))
            }
        });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// Procurements
router.post('/procurements', async (req, res) => {
    const p = req.body;
    await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
        [p.id, p.requestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, p.officialNumber, p.type, p.departmentId, p.createdBy, p.createdAt]);
    res.json({ success: true });
});

router.patch('/procurements/:id', async (req, res) => {
    const id = req.params.id;
    const p = req.body;
    const map = { requestId: 'request_id', requestDate: 'request_date', category: 'category', itemCount: 'item_count', amount: 'amount', company: 'company', remarks: 'remarks', officialNumber: 'official_number', departmentId: 'department_id' };
    let sql = "UPDATE procurements SET ";
    const params = [];
    const fields = [];

    for (const [key, dbCol] of Object.entries(map)) {
        if (p[key] !== undefined) { fields.push(`${dbCol} = ?`); params.push(p[key]); }
    }
    if (fields.length > 0) {
        sql += fields.join(', ') + " WHERE id = ?"; 
        params.push(id); 
        await query(sql, params);
    }
    res.json({ success: true });
});

router.delete('/procurements/:id', async (req, res) => {
    await query('DELETE FROM procurements WHERE id = ?', [req.params.id]);
    res.json({ success: true });
});

// Receivings & Considerations
router.post('/receivings', async (req, res) => {
    const r = req.body;
    await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?,?,?,?,?,?)', [r.id, r.requestId, r.deliveryNoteNo, r.receiveDate, r.category, r.createdAt]);
    res.json({ success: true });
});
router.delete('/receivings/:id', async (req, res) => {
    await query('DELETE FROM receivings WHERE id = ?', [req.params.id]);
    res.json({ success: true });
});
router.post('/considerations', async (req, res) => {
    const c = req.body;
    await query('INSERT INTO considerations (id, request_id, consideration_number, consideration_date) VALUES (?,?,?,?)', [c.id, c.requestId, c.considerationNumber, c.considerationDate]);
    res.json({ success: true });
});
router.post('/receivings/upsert', async (req, res) => {
    const r = req.body;
    const existing = await query('SELECT id FROM receivings WHERE request_id = ?', [r.requestId]);
    if (existing.length > 0) {
        await query('UPDATE receivings SET delivery_note_no=?, receive_date=?, category=? WHERE request_id=?', [r.deliveryNoteNo, r.receiveDate, r.category, r.requestId]);
