// Helper function for queries with STRICT UTF8MB4 ENFORCEMENT
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }

        // 🔥 CRITICAL FIX: Explicitly run SET NAMES before every single query session.
        // This fixes the "Alien Language" (Mojibake) issue on Windows/IIS MySQL servers.
        connection.query("SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci'", (err) => {
            if (err) {
                connection.release();
                console.error("Charset Encoding Error:", err);
                return reject(err);
            }

            // Execute the actual query
            connection.query(sql, params, (err, res) => {
                connection.release(); // Always release connection back to pool
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

