    host: '10.1.0.201', 
    user: 'sa', 
    password: 'Sam#11294', 
    database: 'procurement_db', 
    port: 3306,
    waitForConnections: true, 
    connectionLimit: 10,
    timezone: '+07:00',
    dateStrings: true,
    charset: 'utf8mb4', // Force charset in config
    supportBigNumbers: true,
    bigNumberStrings: true
};

const db = mysql.createPool(DB_CONFIG);

// Helper function for queries with EXTREME UTF8MB4 ENFORCEMENT
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }

        // 🔥 ULTIMATE FIX: Run 3 commands to force every aspect of the connection to UTF-8
        // 1. SET NAMES: Client encoding
        // 2. SET CHARACTER SET: Results encoding
        // 3. SET collation_connection: Sorting/Compare rules
        const setCharsetSql = "SET NAMES 'utf8mb4'; SET CHARACTER SET utf8mb4; SET SESSION collation_connection = 'utf8mb4_unicode_ci';";

        connection.query(setCharsetSql, (err) => {
            if (err) {
                connection.release();
                console.error("Charset Setup Error:", err);
                return reject(err);
            }

            // Execute the actual query
            connection.query(sql, params, (err, res) => {
                connection.release(); // Always release connection back to pool
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

