const run = async () => {
    let connection;
    try {
        console.log('🔌 Connecting to database...');
        connection = await mysql.createConnection(DB_CONFIG);
        await connection.query('SET NAMES utf8mb4');
        console.log('✅ Connected.');

        // Clean Data
        await connection.execute('DELETE FROM receivings');
        await connection.execute('DELETE FROM considerations');
        await connection.execute('DELETE FROM procurements');
        await connection.execute('DELETE FROM users');
        await connection.execute('DELETE FROM departments');
        await connection.execute('DELETE FROM work_groups');

        // Insert WorkGroups
        console.log('🏢 Seeding Work Groups...');
        for (const wg of MOCK_WORKGROUPS) {
            await connection.execute(
                `INSERT INTO work_groups (id, name, is_active) VALUES (?, ?, true)`,
                [wg.id, wg.name]
            );
        }

        // Insert Departments
        console.log('🏥 Seeding Departments...');
        for (const dept of MOCK_DEPARTMENTS) {
            await connection.execute(
                `INSERT INTO departments (id, name, prefix, request_prefix, work_group_id, is_active) VALUES (?, ?, ?, ?, ?, true)`,
                [dept.id, dept.name, dept.prefix, dept.reqPrefix, dept.groupId]
            );
        }

        // Insert Users
        console.log('👥 Seeding Users...');
        for (const user of MOCK_USERS) {
            await connection.execute(
                `INSERT INTO users (id, username, password, name, role, department_id, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
                [user.id, user.username, 'password', user.name, user.role, user.dept, 'ACTIVE', Date.now()]
            );
        }

        console.log('\n✨ Seed Complete!');
        console.log('   (รหัสผ่านของทุก User คือ "password")');

    } catch (err) {
        console.error('\n❌ Error seeding database:', err);
    } finally {
        if (connection) await connection.end();
    }
};

run();

