                    requestPrefix: newDeptRequestPrefix.trim(), workGroupId: newDeptWorkGroup || undefined, isActive: true
                });
                setNewDeptName(''); setNewDeptPrefix(''); setNewDeptRequestPrefix(''); setNewDeptWorkGroup(''); setConfirmAction(null);
            }
        });
    };
    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id); setEditDeptName(dept.name); setEditDeptPrefix(dept.prefix || '');
        setEditDeptRequestPrefix(dept.requestPrefix || ''); setEditDeptWorkGroup(dept.workGroupId || '');
