        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT', title: 'ยืนยันการแก้ไข', message: 'ต้องการบันทึกการเปลี่ยนแปลงข้อมูลฝ่าย/งานใช่หรือไม่?',
            onConfirm: () => {
                updateDepartment(editingDeptId, {
                    name: editDeptName.trim(), prefix: editDeptPrefix.trim(),
                    requestPrefix: editDeptRequestPrefix.trim(), workGroupId: editDeptWorkGroup || undefined
                });
                setEditingDeptId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleDept = (dept: Department) => {
        const action = dept.isActive ? 'ปิดการใช้งาน (Soft Delete)' : 'เปิดการใช้งาน';
        setConfirmAction({
            type: 'TOGGLE_DEPT', title: `ยืนยันการ${action}`, message: `ต้องการ${action} ฝ่าย "${dept.name}" ใช่หรือไม่?`,
            onConfirm: () => {
                updateDepartment(dept.id, { isActive: !dept.isActive });
                setConfirmAction(null);
            }
        });
