    // ================= Category Handlers =================
    const requestAddCategory = () => {
        if (!newCategoryName.trim()) return;
        setConfirmAction({
            type: 'ADD_CAT', title: 'ยืนยันการเพิ่มหมวดพัสดุ', message: `ต้องการเพิ่มหมวด "${newCategoryName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addCategory({
                    id: `cat_${Date.now()}`, name: newCategoryName.trim(), departmentId: newCategoryDept || undefined, isActive: true
                });
                setNewCategoryName(''); setNewCategoryDept(''); setConfirmAction(null);
            }
        });
    };
    const requestEditCategory = () => {
        if (!editingCatId || !editCatName.trim()) return;
        setConfirmAction({
            type: 'EDIT_CAT', title: 'ยืนยันการแก้ไขหมวด', message: 'ต้องการบันทึกการแก้ไขหมวดพัสดุใช่หรือไม่?',
            onConfirm: () => {
                updateCategory(editingCatId, { name: editCatName.trim(), departmentId: editCatDept || undefined });
                setEditingCatId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleCategory = (cat: ProcurementCategory) => {
        const action = cat.isActive ? 'ปิดการใช้งาน (Soft Delete)' : 'เปิดการใช้งาน';
        setConfirmAction({
            type: 'TOGGLE_CAT', title: `ยืนยันการ${action}`, message: `ต้องการ${action} หมวด "${cat.name}" ใช่หรือไม่?`,
            onConfirm: () => {
                updateCategory(cat.id, { isActive: !cat.isActive });
                setConfirmAction(null);
            }
        });
    };

    const getDeptName = (id?: string) => settings.departments.find(d => d.id === id)?.name || '-';

    return (
        <div className="p-6 relative min-h-screen pb-20 bg-slate-50">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">ตั้งค่าระบบ</h2>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* 1. Work Groups */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-fit">
                    <div className="p-4 border-b border-slate-100 bg-orange-50/50">
                        <h3 className="font-bold text-slate-800 flex items-center"><Briefcase size={18} className="mr-2 text-orange-600"/> จัดการกลุ่มงาน</h3>
                    </div>
                    <div className="p-4">
                        <div className="flex space-x-2 mb-4">
                            <input className="flex-1 border rounded-lg px-3 py-1.5 text-sm" placeholder="ชื่อกลุ่มงาน..." value={newWorkGroupName} onChange={e => setNewWorkGroupName(e.target.value)} />
                            <button onClick={requestAddWorkGroup} className="bg-orange-600 text-white px-3 rounded-lg hover:bg-orange-700 transition-colors"><Plus size={18}/></button>
                        </div>
                        <div className="space-y-2 max-h-[400px] overflow-y-auto">
                            {settings.workGroups?.map(g => (
                                <div key={g.id} className={`flex justify-between items-center p-2 border rounded-lg transition-colors ${g.isActive ? 'bg-white' : 'bg-slate-100 border-slate-200 opacity-70'}`}>
                                    {editingGroupId === g.id ? (
                                        <div className="flex-1 flex space-x-2">
                                            <input autoFocus className="flex-1 border border-orange-300 rounded px-2 py-1 text-sm outline-none" value={editGroupName} onChange={e => setEditGroupName(e.target.value)} />
                                            <button onClick={() => requestEditWorkGroup(g.id, editGroupName)} className="text-green-600 hover:bg-green-50 p-1 rounded"><Check size={16}/></button>
                                            <button onClick={() => setEditingGroupId(null)} className="text-red-500 hover:bg-red-50 p-1 rounded"><X size={16}/></button>
                                        </div>
                                    ) : (
                                        <>
                                            <span className={`text-sm font-medium ${g.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{g.name}</span>
                                            <div className="flex items-center space-x-1">
                                                <button onClick={() => { setEditingGroupId(g.id); setEditGroupName(g.name); }} className="p-1.5 text-slate-400 hover:text-orange-600 rounded hover:bg-orange-50 transition-colors"><Edit2 size={14}/></button>
                                                <button onClick={() => requestToggleWorkGroup(g)} className={`p-1.5 rounded transition-colors ${g.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-500 hover:text-green-600 hover:bg-green-50'}`}>
                                                    {g.isActive ? <X size={16} /> : <Power size={14} />} 
                                                </button>
                                            </div>
                                        </>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 2. Departments */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-fit">
                    <div className="p-4 border-b border-slate-100 bg-indigo-50/50">
                        <h3 className="font-bold text-slate-800 flex items-center"><Building size={18} className="mr-2 text-indigo-600"/> จัดการฝ่าย/งาน</h3>
                    </div>
                    <div className="p-4">
                        <div className="space-y-2 mb-4">
                            <input className="w-full border rounded-lg px-3 py-1.5 text-sm" placeholder="ชื่อฝ่าย..." value={newDeptName} onChange={e => setNewDeptName(e.target.value)} />
                            <input 
                                className="w-full border rounded-lg px-3 py-1.5 text-sm" 
                                placeholder="เลขที่ใบขอ (เช่น สพ ๐๐๓๓.๐๖/๑/๑/)" 
                                value={newDeptRequestPrefix} 
                                onChange={e => setNewDeptRequestPrefix(e.target.value)} 
                            />
                            <div className="flex space-x-2">
                                <input className="w-24 border rounded-lg px-3 py-1.5 text-sm text-center" placeholder="ตัวย่อ" value={newDeptPrefix} onChange={e => setNewDeptPrefix(e.target.value)} />
                                <select className="flex-1 border rounded-lg px-2 py-1.5 text-sm" value={newDeptWorkGroup} onChange={e => setNewDeptWorkGroup(e.target.value)}>
                                    <option value="">กลุ่มงาน...</option>
                                    {settings.workGroups?.filter(g=>g.isActive).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
