                        <div className="space-y-2 max-h-[400px] overflow-y-auto">
                            {settings.departments?.map(dept => (
                                <div key={dept.id} className={`p-2 border rounded-lg transition-colors ${dept.isActive ? 'bg-white' : 'bg-slate-100 border-slate-200 opacity-70'}`}>
                                    {editingDeptId === dept.id ? (
                                        <div className="space-y-2">
                                            <input className="w-full border border-indigo-300 rounded px-2 py-1 text-sm outline-none" value={editDeptName} onChange={e => setEditDeptName(e.target.value)} />
                                            <input className="w-full border border-indigo-300 rounded px-2 py-1 text-sm outline-none font-mono" value={editDeptRequestPrefix} onChange={e => setEditDeptRequestPrefix(e.target.value)} />
                                            <div className="flex space-x-2">
                                                <input className="w-20 border border-indigo-300 rounded px-2 py-1 text-sm outline-none text-center" value={editDeptPrefix} onChange={e => setEditDeptPrefix(e.target.value)} />
                                                <select className="flex-1 border border-indigo-300 rounded px-2 py-1 text-sm" value={editDeptWorkGroup} onChange={e => setEditDeptWorkGroup(e.target.value)}>
                                                    <option value="">กลุ่มงาน...</option>
                                                    {settings.workGroups?.filter(g=>g.isActive).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                                </select>
                                                <button onClick={requestSaveEditDept} className="text-green-600 hover:bg-green-50 p-1 rounded"><Check size={16}/></button>
                                                <button onClick={() => setEditingDeptId(null)} className="text-red-500 hover:bg-red-50 p-1 rounded"><X size={16}/></button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <div className={`text-sm font-medium ${dept.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>
