                                                </div>
                                                <div className="text-[10px] text-slate-400 font-mono mt-0.5">{dept.requestPrefix || '-'}</div>
                                                <div className="text-[10px] text-slate-400">{settings.workGroups?.find(g=>g.id===dept.workGroupId)?.name}</div>
                                            </div>
                                            <div className="flex items-center space-x-1">
                                                <button onClick={() => startEditDept(dept)} className="p-1.5 text-slate-400 hover:text-indigo-600 rounded hover:bg-indigo-50"><Edit2 size={14}/></button>
                                                <button onClick={() => requestToggleDept(dept)} className={`p-1.5 rounded transition-colors ${dept.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-500 hover:text-green-600 hover:bg-green-50'}`}>
                                                    {dept.isActive ? <X size={16} /> : <Power size={14} />} 
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 3. Categories (NEW) */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-fit">
                    <div className="p-4 border-b border-slate-100 bg-green-50/50">
                        <h3 className="font-bold text-slate-800 flex items-center"><Layers size={18} className="mr-2 text-green-600"/> จัดการหมวดพัสดุ</h3>
                    </div>
                    <div className="p-4">
                        <div className="space-y-2 mb-4">
                            <input className="w-full border rounded-lg px-3 py-1.5 text-sm" placeholder="ชื่อหมวด (เช่น วัสดุสำนักงาน)..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
                            <div className="flex space-x-2">
                                <select className="flex-1 border rounded-lg px-2 py-1.5 text-sm" value={newCategoryDept} onChange={e => setNewCategoryDept(e.target.value)}>
                                    <option value="">สังกัดฝ่าย (ถ้ามี)...</option>
                                    {settings.departments?.filter(d=>d.isActive).map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                                </select>
                                <button onClick={requestAddCategory} className="bg-green-600 text-white px-3 rounded-lg hover:bg-green-700 transition-colors"><Plus size={18}/></button>
                            </div>
                        </div>
                        <div className="space-y-2 max-h-[400px] overflow-y-auto">
                            {settings.categories?.map(cat => (
                                <div key={cat.id} className={`p-2 border rounded-lg transition-colors ${cat.isActive ? 'bg-white' : 'bg-slate-100 border-slate-200 opacity-70'}`}>
                                    {editingCatId === cat.id ? (
                                        <div className="space-y-2">
                                            <input className="w-full border border-green-300 rounded px-2 py-1 text-sm outline-none" value={editCatName} onChange={e => setEditCatName(e.target.value)} />
                                            <div className="flex space-x-2">
                                                <select className="flex-1 border border-green-300 rounded px-2 py-1 text-sm" value={editCatDept} onChange={e => setEditCatDept(e.target.value)}>
                                                    <option value="">สังกัดฝ่าย...</option>
                                                    {settings.departments?.filter(d=>d.isActive).map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                                                </select>
                                                <button onClick={requestEditCategory} className="text-green-600 hover:bg-green-50 p-1 rounded"><Check size={16}/></button>
                                                <button onClick={() => setEditingCatId(null)} className="text-red-500 hover:bg-red-50 p-1 rounded"><X size={16}/></button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="flex justify-between items-center">
                                            <div>
                                                <div className={`text-sm font-medium ${cat.isActive ? 'text-slate-700' : 'text-slate-400 line-through'}`}>{cat.name}</div>
                                                <div className="text-[10px] text-slate-400">{getDeptName(cat.departmentId)}</div>
                                            </div>
                                            <div className="flex items-center space-x-1">
                                                <button onClick={() => { setEditingCatId(cat.id); setEditCatName(cat.name); setEditCatDept(cat.departmentId || ''); }} className="p-1.5 text-slate-400 hover:text-green-600 rounded hover:bg-green-50"><Edit2 size={14}/></button>
                                                <button onClick={() => requestToggleCategory(cat)} className={`p-1.5 rounded transition-colors ${cat.isActive ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-500 hover:text-green-600 hover:bg-green-50'}`}>
                                                    {cat.isActive ? <X size={16} /> : <Power size={14} />} 
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

            </div>

            {/* ================= Confirmation Modal ================= */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-slate-100">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4 text-blue-600">
                            <AlertCircle className="h-6 w-6" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                            {confirmAction.message}
                        </p>
                        <div className="flex space-x-3">
                            <button onClick={() => setConfirmAction(null)} className="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-semibold transition-all">ยกเลิก</button>
                            <button onClick={confirmAction.onConfirm} className="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-semibold shadow-md transition-all">ยืนยัน</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { Plus, Edit2, X, Check, Building, Briefcase, Power, AlertCircle, Layers, Filter, ChevronRight, RefreshCcw } from 'lucide-react';
import { Department, WorkGroup, ProcurementCategory } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory } = useApp();

    // ================= Filter State (Cascading Logic) =================
    const [selectedWgId, setSelectedWgId] = useState<string | null>(null);
    const [selectedDeptId, setSelectedDeptId] = useState<string | null>(null);

    // ================= Confirmation Modal State =================
    const [confirmAction, setConfirmAction] = useState<{
        type: 'ADD_GROUP' | 'EDIT_GROUP' | 'TOGGLE_GROUP' | 'ADD_DEPT' | 'EDIT_DEPT' | 'TOGGLE_DEPT' | 'ADD_CAT' | 'EDIT_CAT' | 'TOGGLE_CAT';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // ================= Input States =================
    // 1. Work Groups
    const [newWorkGroupName, setNewWorkGroupName] = useState('');
    const [editingGroupId, setEditingGroupId] = useState<string | null>(null);
    const [editGroupName, setEditGroupName] = useState('');

    // 2. Departments
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptRequestPrefix, setNewDeptRequestPrefix] = useState('');
    const [newDeptWorkGroup, setNewDeptWorkGroup] = useState('');
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState('');
    const [editDeptRequestPrefix, setEditDeptRequestPrefix] = useState('');
    const [editDeptWorkGroup, setEditDeptWorkGroup] = useState('');

    // 3. Categories
    const [newCategoryName, setNewCategoryName] = useState('');
    const [newCategoryDept, setNewCategoryDept] = useState('');
    const [editingCatId, setEditingCatId] = useState<string | null>(null);
    const [editCatName, setEditCatName] = useState('');
    const [editCatDept, setEditCatDept] = useState('');

    // ================= Auto-fill Logic =================
    // เมื่อเลือก Filter ให้ Auto-select Dropdown ในช่องเพิ่มข้อมูล
    useEffect(() => {
        if (selectedWgId) setNewDeptWorkGroup(selectedWgId);
        else setNewDeptWorkGroup('');
    }, [selectedWgId]);

    useEffect(() => {
        if (selectedDeptId) setNewCategoryDept(selectedDeptId);
        else setNewCategoryDept('');
    }, [selectedDeptId]);

    // ================= Filtered Data Calculation =================
    const visibleDepartments = selectedWgId 
        ? settings.departments.filter(d => d.workGroupId === selectedWgId)
        : settings.departments;

    const visibleCategories = selectedDeptId
        ? settings.categories.filter(c => c.departmentId === selectedDeptId)
        : settings.categories;

    // ================= Handlers =================

    // --- Work Group ---
    const requestAddWorkGroup = () => {
        if (!newWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'ADD_GROUP', title: 'เพิ่มกลุ่มงาน', message: `ต้องการเพิ่ม "${newWorkGroupName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addWorkGroup({ id: `group_${Date.now()}`, name: newWorkGroupName.trim(), isActive: true });
                setNewWorkGroupName(''); setConfirmAction(null);
            }
        });
    };
    const requestEditWorkGroup = (id: string, newName: string) => {
        setConfirmAction({
            type: 'EDIT_GROUP', title: 'บันทึกการแก้ไข', message: 'ยืนยันการแก้ไขชื่อกลุ่มงาน',
            onConfirm: () => {
                updateWorkGroup(id, { name: newName });
                setEditingGroupId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleWorkGroup = (group: WorkGroup) => {
        setConfirmAction({
            type: 'TOGGLE_GROUP', title: group.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน', message: `ยืนยันการเปลี่ยนสถานะของ "${group.name}"`,
            onConfirm: () => { updateWorkGroup(group.id, { isActive: !group.isActive }); setConfirmAction(null); }
        });
    };

    // --- Department ---
    const requestAddDepartment = () => {
        if (!newDeptName.trim()) return;
        setConfirmAction({
            type: 'ADD_DEPT', title: 'เพิ่มฝ่าย/งาน', message: `ต้องการเพิ่ม "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addDepartment({
                    id: `dept_${Date.now()}`, name: newDeptName.trim(), prefix: newDeptPrefix.trim(),
                    requestPrefix: newDeptRequestPrefix.trim(), workGroupId: newDeptWorkGroup || undefined, isActive: true
                });
                setNewDeptName(''); setNewDeptPrefix(''); setNewDeptRequestPrefix(''); 
                // Don't reset workgroup if filtered
                if(!selectedWgId) setNewDeptWorkGroup(''); 
                setConfirmAction(null);
            }
        });
    };
    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id); setEditDeptName(dept.name); setEditDeptPrefix(dept.prefix || '');
        setEditDeptRequestPrefix(dept.requestPrefix || ''); setEditDeptWorkGroup(dept.workGroupId || '');
    };
    const requestSaveEditDept = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT', title: 'บันทึกการแก้ไข', message: 'ยืนยันการแก้ไขข้อมูลฝ่าย/งาน',
            onConfirm: () => {
                updateDepartment(editingDeptId, {
                    name: editDeptName.trim(), prefix: editDeptPrefix.trim(),
                    requestPrefix: editDeptRequestPrefix.trim(), workGroupId: editDeptWorkGroup || undefined
                });
                setEditingDeptId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleDept = (dept: Department) => {
        setConfirmAction({
            type: 'TOGGLE_DEPT', title: dept.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน', message: `ยืนยันการเปลี่ยนสถานะของ "${dept.name}"`,
            onConfirm: () => { updateDepartment(dept.id, { isActive: !dept.isActive }); setConfirmAction(null); }
        });
    };

    // --- Category ---
    const requestAddCategory = () => {
        if (!newCategoryName.trim()) return;
        setConfirmAction({
            type: 'ADD_CAT', title: 'เพิ่มหมวดพัสดุ', message: `ต้องการเพิ่มหมวด "${newCategoryName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addCategory({
                    id: `cat_${Date.now()}`, name: newCategoryName.trim(), departmentId: newCategoryDept || undefined, isActive: true
                });
                setNewCategoryName('');
                // Don't reset dept if filtered
                if(!selectedDeptId) setNewCategoryDept(''); 
                setConfirmAction(null);
            }
        });
    };
    const requestEditCategory = () => {
        if (!editingCatId || !editCatName.trim()) return;
        setConfirmAction({
            type: 'EDIT_CAT', title: 'บันทึกการแก้ไข', message: 'ยืนยันการแก้ไขหมวดพัสดุ',
            onConfirm: () => {
                updateCategory(editingCatId, { name: editCatName.trim(), departmentId: editCatDept || undefined });
                setEditingCatId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleCategory = (cat: ProcurementCategory) => {
        setConfirmAction({
            type: 'TOGGLE_CAT', title: cat.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน', message: `ยืนยันการเปลี่ยนสถานะของ "${cat.name}"`,
            onConfirm: () => { updateCategory(cat.id, { isActive: !cat.isActive }); setConfirmAction(null); }
        });
    };

    // Helper
    const getWorkGroupName = (id?: string) => settings.workGroups.find(g => g.id === id)?.name || 'ไม่ระบุ';
    const getDeptName = (id?: string) => settings.departments.find(d => d.id === id)?.name || 'ไม่ระบุ';

    return (
