                        <h3 className="font-bold text-slate-800 flex items-center text-sm"><Briefcase size={16} className="mr-2 text-orange-600"/> 1. จัดการกลุ่มงาน</h3>
                        <div className="text-xs text-orange-600 font-medium bg-white px-2 py-0.5 rounded-full border border-orange-200">{settings.workGroups.length}</div>
                    </div>

                    {/* Add Box */}
                    <div className="p-3 border-b border-slate-100 bg-slate-50/50">
                        <div className="flex space-x-2">
                            <input className="flex-1 border rounded px-2 py-1.5 text-sm focus:ring-1 focus:ring-orange-500 outline-none" placeholder="ชื่อกลุ่มงาน..." value={newWorkGroupName} onChange={e => setNewWorkGroupName(e.target.value)} />
                            <button onClick={requestAddWorkGroup} className="bg-orange-600 text-white px-3 rounded hover:bg-orange-700 transition-colors"><Plus size={18}/></button>
