                                        <div className="flex items-center opacity-0 group-hover:opacity-100 transition-opacity space-x-1">
                                            <button onClick={(e) => { e.stopPropagation(); setEditingGroupId(g.id); setEditGroupName(g.name); }} className="p-1 text-slate-400 hover:text-orange-600 hover:bg-white rounded"><Edit2 size={12}/></button>
                                            <button onClick={(e) => { e.stopPropagation(); requestToggleWorkGroup(g); }} className={`p-1 rounded ${g.isActive ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`}>
                                                <Power size={12} />
                                            </button>
                                        </div>
                                        {selectedWgId === g.id && <ChevronRight size={16} className="text-orange-400 ml-1"/>}
