                            {selectedWgId && (
                                <span className="text-[10px] bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full truncate border border-indigo-200 flex items-center">
                                    <Filter size={10} className="mr-1"/> {getWorkGroupName(selectedWgId)}
