                            <input className="w-1/3 border rounded px-2 py-1.5 text-xs text-center" placeholder="เลขที่ใบขอ (สพ..)" value={newDeptRequestPrefix} onChange={e => setNewDeptRequestPrefix(e.target.value)} />
                            <select className="flex-1 border rounded px-2 py-1.5 text-xs" value={newDeptWorkGroup} onChange={e => setNewDeptWorkGroup(e.target.value)} disabled={!!selectedWgId}>
