                                        <input className="w-full border border-indigo-300 rounded px-2 py-1 text-xs outline-none" value={editDeptName} onChange={e => setEditDeptName(e.target.value)} />
                                        <div className="flex space-x-1">
                                            <input className="w-1/2 border border-indigo-300 rounded px-2 py-1 text-[10px]" value={editDeptRequestPrefix} onChange={e => setEditDeptRequestPrefix(e.target.value)} placeholder="Prefix" />
                                            <select className="flex-1 border border-indigo-300 rounded px-1 py-1 text-[10px]" value={editDeptWorkGroup} onChange={e => setEditDeptWorkGroup(e.target.value)}>
                                                <option value="">กลุ่มงาน...</option>
                                                {settings.workGroups.filter(g => g.isActive).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                                            </select>
                                            <button onClick={requestSaveEditDept} className="text-green-600 hover:bg-green-50 p-1 rounded"><Check size={14}/></button>
                                            <button onClick={() => setEditingDeptId(null)} className="text-red-500 hover:bg-red-50 p-1 rounded"><X size={14}/></button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <div className={`text-sm font-medium ${selectedDeptId === dept.id ? 'text-indigo-900' : 'text-slate-700'}`}>{dept.name}</div>
                                            <div className="text-[10px] text-slate-400 font-mono">{dept.requestPrefix || '-'}</div>
                                            {!selectedWgId && <div className="text-[10px] text-slate-400 bg-slate-100 px-1.5 rounded w-fit mt-1">{getWorkGroupName(dept.workGroupId)}</div>}
                                        </div>
                                        <div className="flex flex-col items-end">
                                            <div className="flex items-center opacity-0 group-hover:opacity-100 transition-opacity space-x-1 mb-1">
                                                <button onClick={(e) => { e.stopPropagation(); startEditDept(dept); }} className="p-1 text-slate-400 hover:text-indigo-600 hover:bg-white rounded"><Edit2 size={12}/></button>
                                                <button onClick={(e) => { e.stopPropagation(); requestToggleDept(dept); }} className={`p-1 rounded ${dept.isActive ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`}>
                                                    <Power size={12} />
                                                </button>
                                            </div>
                                            {selectedDeptId === dept.id && <ChevronRight size={16} className="text-indigo-400"/>}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                {/* ================= COLUMN 3: CATEGORIES ================= */}
                <div className="flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <div className="p-3 border-b border-slate-100 bg-green-50 flex justify-between items-center">
                        <div className="flex items-center space-x-2 overflow-hidden">
                            <h3 className="font-bold text-slate-800 flex items-center text-sm flex-shrink-0"><Layers size={16} className="mr-2 text-green-600"/> 3. จัดการหมวดพัสดุ</h3>
                            {selectedDeptId && (
                                <span className="text-[10px] bg-green-100 text-green-700 px-2 py-0.5 rounded-full truncate border border-green-200 flex items-center">
                                    <Filter size={10} className="mr-1"/> {getDeptName(selectedDeptId)}
                                </span>
                            )}
                        </div>
                        <div className="text-xs text-green-600 font-medium bg-white px-2 py-0.5 rounded-full border border-green-200">{visibleCategories.length}</div>
                    </div>

                    {/* Add Box */}
                    <div className="p-3 border-b border-slate-100 bg-slate-50/50 space-y-2">
                        <input className="w-full border rounded px-2 py-1.5 text-sm focus:ring-1 focus:ring-green-500 outline-none" placeholder="ชื่อหมวด (เช่น วัสดุสำนักงาน)..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
                        <div className="flex space-x-2">
                            <select className="flex-1 border rounded px-2 py-1.5 text-xs" value={newCategoryDept} onChange={e => setNewCategoryDept(e.target.value)} disabled={!!selectedDeptId}>
                                <option value="">เลือกฝ่าย (ถ้ามี)...</option>
                                {settings.departments.filter(d => d.isActive).map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                            </select>
                            <button onClick={requestAddCategory} className="bg-green-600 text-white px-2.5 rounded hover:bg-green-700 transition-colors"><Plus size={18}/></button>
                        </div>
                    </div>

                    {/* List */}
                    <div className="flex-1 overflow-y-auto p-2 space-y-1">
                        {visibleCategories.length === 0 && (
                            <div className="text-center py-8 text-slate-400 text-xs">ไม่พบหมวดพัสดุ</div>
                        )}

                        {visibleCategories.map(cat => (
                            <div key={cat.id} className={`group p-2 rounded-lg border transition-all flex flex-col bg-white border-transparent hover:bg-slate-50 hover:border-slate-200 ${!cat.isActive ? 'opacity-60 grayscale' : ''}`}>
                                {editingCatId === cat.id ? (
                                    <div className="space-y-2">
                                        <input className="w-full border border-green-300 rounded px-2 py-1 text-xs outline-none" value={editCatName} onChange={e => setEditCatName(e.target.value)} />
                                        <div className="flex space-x-1">
                                            <select className="flex-1 border border-green-300 rounded px-1 py-1 text-[10px]" value={editCatDept} onChange={e => setEditCatDept(e.target.value)}>
                                                <option value="">สังกัดฝ่าย...</option>
                                                {settings.departments.filter(d => d.isActive).map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                                            </select>
                                            <button onClick={requestEditCategory} className="text-green-600 hover:bg-green-50 p-1 rounded"><Check size={14}/></button>
                                            <button onClick={() => setEditingCatId(null)} className="text-red-500 hover:bg-red-50 p-1 rounded"><X size={14}/></button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex justify-between items-center">
                                        <div>
                                            <div className="text-sm font-medium text-slate-700">{cat.name}</div>
                                            {!selectedDeptId && cat.departmentId && (
                                                <div className="text-[10px] text-slate-400 bg-slate-100 px-1.5 rounded w-fit mt-0.5">{getDeptName(cat.departmentId)}</div>
                                            )}
                                        </div>
                                        <div className="flex items-center opacity-0 group-hover:opacity-100 transition-opacity space-x-1">
                                            <button onClick={() => { setEditingCatId(cat.id); setEditCatName(cat.name); setEditCatDept(cat.departmentId || ''); }} className="p-1 text-slate-400 hover:text-green-600 hover:bg-white rounded"><Edit2 size={12}/></button>
                                            <button onClick={() => requestToggleCategory(cat)} className={`p-1 rounded ${cat.isActive ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`}>
                                                <Power size={12} />
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

            </div>

            {/* ================= Confirmation Modal ================= */}
            {confirmAction && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-slate-100">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-blue-50 mb-4 text-blue-600">
                            <AlertCircle className="h-6 w-6" />
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmAction.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                            {confirmAction.message}
                        </p>
                        <div className="flex space-x-3">
                            <button onClick={() => setConfirmAction(null)} className="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-semibold transition-all">ยกเลิก</button>
                            <button onClick={confirmAction.onConfirm} className="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-semibold shadow-md transition-all">ยืนยัน</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { Plus, Edit2, X, Check, Building, Briefcase, Power, AlertCircle, Layers, Filter, ChevronRight, RotateCcw } from 'lucide-react';
import { Department, WorkGroup, ProcurementCategory } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory } = useApp();

    // ================= Filter State (Cascading Logic) =================
    const [selectedWgId, setSelectedWgId] = useState<string | null>(null);
    const [selectedDeptId, setSelectedDeptId] = useState<string | null>(null);

    // ================= Confirmation Modal State =================
    const [confirmAction, setConfirmAction] = useState<{
        type: 'ADD_GROUP' | 'EDIT_GROUP' | 'TOGGLE_GROUP' | 'ADD_DEPT' | 'EDIT_DEPT' | 'TOGGLE_DEPT' | 'ADD_CAT' | 'EDIT_CAT' | 'TOGGLE_CAT';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // ================= Input States =================
    // 1. Work Groups
    const [newWorkGroupName, setNewWorkGroupName] = useState('');
    const [editingGroupId, setEditingGroupId] = useState<string | null>(null);
    const [editGroupName, setEditGroupName] = useState('');

    // 2. Departments
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptRequestPrefix, setNewDeptRequestPrefix] = useState('');
    const [newDeptWorkGroup, setNewDeptWorkGroup] = useState('');
    const [editingDeptId, setEditingDeptId] = useState<string | null>(null);
    const [editDeptName, setEditDeptName] = useState('');
    const [editDeptPrefix, setEditDeptPrefix] = useState('');
    const [editDeptRequestPrefix, setEditDeptRequestPrefix] = useState('');
    const [editDeptWorkGroup, setEditDeptWorkGroup] = useState('');

    // 3. Categories
    const [newCategoryName, setNewCategoryName] = useState('');
    const [newCategoryDept, setNewCategoryDept] = useState('');
    const [editingCatId, setEditingCatId] = useState<string | null>(null);
    const [editCatName, setEditCatName] = useState('');
    const [editCatDept, setEditCatDept] = useState('');

    // ================= Auto-fill Logic =================
    useEffect(() => {
        if (selectedWgId) setNewDeptWorkGroup(selectedWgId);
        else setNewDeptWorkGroup('');
    }, [selectedWgId]);

    useEffect(() => {
        if (selectedDeptId) setNewCategoryDept(selectedDeptId);
        else setNewCategoryDept('');
    }, [selectedDeptId]);

    // ================= Filtered Data Calculation =================
    const visibleDepartments = selectedWgId 
        ? settings.departments.filter(d => d.workGroupId === selectedWgId)
        : settings.departments;

    const visibleCategories = selectedDeptId
        ? settings.categories.filter(c => c.departmentId === selectedDeptId)
        : settings.categories;

    // ================= Handlers =================

    // --- Work Group ---
    const requestAddWorkGroup = () => {
        if (!newWorkGroupName.trim()) return;
        setConfirmAction({
            type: 'ADD_GROUP', title: 'เพิ่มกลุ่มงาน', message: `ต้องการเพิ่ม "${newWorkGroupName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addWorkGroup({ id: `group_${Date.now()}`, name: newWorkGroupName.trim(), isActive: true });
                setNewWorkGroupName(''); setConfirmAction(null);
            }
        });
    };
    const requestEditWorkGroup = (id: string, newName: string) => {
        setConfirmAction({
            type: 'EDIT_GROUP', title: 'บันทึกการแก้ไข', message: 'ยืนยันการแก้ไขชื่อกลุ่มงาน',
            onConfirm: () => {
                updateWorkGroup(id, { name: newName });
                setEditingGroupId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleWorkGroup = (group: WorkGroup) => {
        setConfirmAction({
            type: 'TOGGLE_GROUP', title: group.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน', message: `ยืนยันการเปลี่ยนสถานะของ "${group.name}"`,
            onConfirm: () => { updateWorkGroup(group.id, { isActive: !group.isActive }); setConfirmAction(null); }
        });
    };

    // --- Department ---
    const requestAddDepartment = () => {
        if (!newDeptName.trim()) return;
        setConfirmAction({
            type: 'ADD_DEPT', title: 'เพิ่มฝ่าย/งาน', message: `ต้องการเพิ่ม "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addDepartment({
                    id: `dept_${Date.now()}`, name: newDeptName.trim(), prefix: newDeptPrefix.trim(),
                    requestPrefix: newDeptRequestPrefix.trim(), workGroupId: newDeptWorkGroup || undefined, isActive: true
                });
                setNewDeptName(''); setNewDeptPrefix(''); setNewDeptRequestPrefix(''); 
                if(!selectedWgId) setNewDeptWorkGroup(''); 
                setConfirmAction(null);
            }
        });
    };
    const startEditDept = (dept: Department) => {
        setEditingDeptId(dept.id); setEditDeptName(dept.name); setEditDeptPrefix(dept.prefix || '');
        setEditDeptRequestPrefix(dept.requestPrefix || ''); setEditDeptWorkGroup(dept.workGroupId || '');
    };
    const requestSaveEditDept = () => {
        if (!editDeptName.trim() || !editingDeptId) return;
        setConfirmAction({
            type: 'EDIT_DEPT', title: 'บันทึกการแก้ไข', message: 'ยืนยันการแก้ไขข้อมูลฝ่าย/งาน',
            onConfirm: () => {
                updateDepartment(editingDeptId, {
                    name: editDeptName.trim(), prefix: editDeptPrefix.trim(),
                    requestPrefix: editDeptRequestPrefix.trim(), workGroupId: editDeptWorkGroup || undefined
                });
                setEditingDeptId(null); setConfirmAction(null);
            }
        });
    };
    const requestToggleDept = (dept: Department) => {
        setConfirmAction({
            type: 'TOGGLE_DEPT', title: dept.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน', message: `ยืนยันการเปลี่ยนสถานะของ "${dept.name}"`,
            onConfirm: () => { updateDepartment(dept.id, { isActive: !dept.isActive }); setConfirmAction(null); }
        });
    };

    // --- Category ---
    const requestAddCategory = () => {
        if (!newCategoryName.trim()) return;
        setConfirmAction({
            type: 'ADD_CAT', title: 'เพิ่มหมวดพัสดุ', message: `ต้องการเพิ่มหมวด "${newCategoryName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addCategory({
                    id: `cat_${Date.now()}`, name: newCategoryName.trim(), departmentId: newCategoryDept || undefined, isActive: true
                });
                setNewCategoryName('');
                if(!selectedDeptId) setNewCategoryDept(''); 
                setConfirmAction(null);
            }
        });
    };
    const requestEditCategory = () => {
        if (!editingCatId || !editCatName.trim()) return;
        setConfirmAction({
