export default SettingsPage;

import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { Plus, Edit2, X, Check, Building, Briefcase, Power, AlertCircle, Layers, ChevronRight, FolderTree, Settings } from 'lucide-react';
import { Department, WorkGroup, ProcurementCategory } from '../types';

const SettingsPage: React.FC = () => {
    const { settings, addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory, updateSettings } = useApp();

    // ================= Selection State (The Cascading Logic) =================
    const [selectedWgId, setSelectedWgId] = useState<string | null>(null);
    const [selectedDeptId, setSelectedDeptId] = useState<string | null>(null);

    // ================= Edit/Add States =================
    const [editingId, setEditingId] = useState<string | null>(null); // Shared editing ID for active input
    const [editValue, setEditValue] = useState('');
    const [editExtra, setEditExtra] = useState(''); // For Prefix
    const [editExtra2, setEditExtra2] = useState(''); // For Request Prefix

    // Input States for New Items
    const [newWgName, setNewWgName] = useState('');

    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptReqPrefix, setNewDeptReqPrefix] = useState('');

    const [newCatName, setNewCatName] = useState('');

    // Global Request ID Prefix (System wide fallback)
    const [globalPrefix, setGlobalPrefix] = useState(settings.requestIdPrefix);
    const [isEditingGlobal, setIsEditingGlobal] = useState(false);

    // ================= Filter Logic =================
    // Reset child selection when parent changes
    useEffect(() => { setSelectedDeptId(null); }, [selectedWgId]);

    const visibleDepartments = selectedWgId 
        ? settings.departments.filter(d => d.workGroupId === selectedWgId) 
        : []; // Show nothing if no group selected (Force hierarchy flow)

    const visibleCategories = selectedDeptId
        ? settings.categories.filter(c => c.departmentId === selectedDeptId)
        : [];

    // ================= Handlers =================

    // --- Global Settings ---
    const saveGlobalPrefix = () => {
        updateSettings({ requestIdPrefix: globalPrefix });
        setIsEditingGlobal(false);
    };

    // --- Work Groups ---
    const handleAddWg = () => {
        if(!newWgName.trim()) return;
        addWorkGroup({ id: `g_${Date.now()}`, name: newWgName.trim(), isActive: true });
        setNewWgName('');
    };
    const handleUpdateWg = (id: string) => {
        updateWorkGroup(id, { name: editValue });
        setEditingId(null);
    };

    // --- Departments ---
    const handleAddDept = () => {
        if(!newDeptName.trim() || !selectedWgId) return;
        addDepartment({ 
            id: `d_${Date.now()}`, 
            name: newDeptName.trim(), 
