                        {selectedDeptId && <span className="text-xs bg-white text-green-600 px-2 py-0.5 rounded-full border border-green-200 font-bold">{visibleCategories.length}</span>}
                    </div>

                    <div className="p-3 border-b border-slate-100 bg-white">
