                                        <button onClick={() => handleUpdateCat(cat.id)} className="p-1 bg-green-100 text-green-700 rounded"><Check size={14}/></button>
                                        <button onClick={() => setEditingId(null)} className="p-1 bg-slate-100 text-slate-500 rounded"><X size={14}/></button>
