            </div>

            {/* Confirmation Modal */}
            {confirmDelete && (
                <div className="absolute inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/20 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-slate-200">
