                                    onKeyDown={e => e.key === 'Enter' && handleAddCat()}
                                />
                                <button onClick={handleAddCat} disabled={!newCatName.trim()} className="bg-green-500 hover:bg-green-600 text-white px-3 rounded-r-lg disabled:opacity-50 transition-colors">
                                    <Plus size={18}/>
