import React, { createContext, useContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, Department, WorkGroup, ProcurementCategory } from '../types';

// ==========================================
// 🛠️ API CONFIGURATION
// ==========================================
const BACKEND_PORT = 3002;

const getApiUrl = () => {
    // 1. กรณีรันบน Server (SSR)
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api/procurement`;

    // 2. กรณีรันบน Browser
    let hostname = window.location.hostname;
    if (!hostname || hostname.trim() === '') {
        hostname = 'localhost';
    }

    // ชี้ไปที่ /api/procurement ให้ตรงกับ server/index.js
    return `http://${hostname}:${BACKEND_PORT}/api/procurement`;
};

const API_URL = getApiUrl();
console.log(`%c🔌 Connecting to Backend via: ${API_URL}`, "color: magenta; font-weight: bold;");

interface AppContextType {
    isLoading: boolean;
    serverError: boolean;
    serverErrorMessage: string;
    retryConnection: () => void;

    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth
    currentUser: User | null;
    users: User[];
    login: (u: string, p: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: any, force?: boolean) => Promise<{ success: boolean, message?: string, isWarning?: boolean }>;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: any) => void;
    upsertReceiving: (requestId: string, number: string, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: any) => void;
    upsertConsideration: (requestId: string, number: string, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;

    // Management Actions
    addDepartment: (dept: Department) => void;
    updateDepartment: (id: string, data: Partial<Department>) => void;
    deleteDepartment: (id: string) => void; // Soft Delete Logic
    addWorkGroup: (group: WorkGroup) => void;
    updateWorkGroup: (id: string, data: Partial<WorkGroup>) => void; // Support object update
    deleteWorkGroup: (id: string) => void; // Soft Delete Logic

    addCategory: (category: ProcurementCategory) => void;
    updateCategory: (id: string, data: Partial<ProcurementCategory>) => void;
    deleteCategory: (id: string) => void; // NEW

    checkChronologyIssue: (record: ProcurementRecord) => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);
    const [serverErrorMessage, setServerErrorMessage] = useState('');

    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [rawProcurements, setRawProcurements] = useState<ProcurementRecord[]>([]);
    const [rawReceivings, setRawReceivings] = useState<ReceivingReport[]>([]);
    const [rawConsiderations, setRawConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: [],
        workGroups: []
    });

    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            // Fetch Users
            const userRes = await fetch(`${API_URL}/users`);
            if (!userRes.ok) throw new Error(`User Fetch Failed: ${userRes.statusText}`);
            const userData = await userRes.json();
            setUsers(userData);

            // Fetch Business Data
            const dataRes = await fetch(`${API_URL}/data`);
            if (!dataRes.ok) throw new Error(`Data Fetch Failed: ${dataRes.statusText}`);
            const data = await dataRes.json();

            setRawProcurements(data.procurements);
            setRawReceivings(data.receivings);
            setRawConsiderations(data.considerations);
            setSettings(prev => ({
                ...prev,
                departments: data.settings.departments,
                categories: data.settings.categories,
                workGroups: data.settings.workGroups || []
            }));

        } catch (error: any) {
            console.error("Backend Error:", error);
            setServerError(true);
            setServerErrorMessage(error.message || "Failed to connect to Backend");
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const savedUser = sessionStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => fetchData();

    // Visibility Logic (กรองข้อมูลตามสิทธิ์และกลุ่มงาน)
    const visibleData = useMemo(() => {
        if (!currentUser) return { procurements: [], receivings: [], considerations: [] };
        if (currentUser.role === 'ADMIN') return { procurements: rawProcurements, receivings: rawReceivings, considerations: rawConsiderations };

        const userDept = settings.departments.find(d => d.id === currentUser.departmentId);
        const userWorkGroupId = userDept?.workGroupId;

        // ถ้า User ไม่มีกลุ่มงาน -> เห็นเฉพาะของตัวเอง
        if (!userWorkGroupId) {
            const myProcs = rawProcurements.filter(p => p.createdBy === currentUser.id);
            return {
                procurements: myProcs,
                receivings: rawReceivings.filter(r => myProcs.some(p => p.requestId === r.requestId)),
                considerations: rawConsiderations.filter(c => myProcs.some(p => p.requestId === c.requestId))
            };
        }

        // ถ้ามีกลุ่มงาน -> เห็นของทุกคนในกลุ่มงานเดียวกัน
        const allowedDeptIds = settings.departments.filter(d => d.workGroupId === userWorkGroupId).map(d => d.id);
        const allowedProcs = rawProcurements.filter(p => {
            // 1. ดูจาก departmentId ของใบขอ
            if (p.departmentId && allowedDeptIds.includes(p.departmentId)) return true;
            // 2. ดูจาก departmentId ของคนสร้าง (Backward Compatibility)
            const creator = users.find(u => u.id === p.createdBy);
            return creator?.departmentId && allowedDeptIds.includes(creator.departmentId);
        });
        const allowedRequestIds = new Set(allowedProcs.map(p => p.requestId));

        return {
            procurements: allowedProcs,
            receivings: rawReceivings.filter(r => allowedRequestIds.has(r.requestId)),
            considerations: rawConsiderations.filter(c => allowedRequestIds.has(c.requestId))
        };
    }, [currentUser, rawProcurements, rawReceivings, rawConsiderations, settings.departments, users]);

    // Auth & Users
    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: u, password: p }) });
            const result = await res.json();
            if (result.success) {
                setCurrentUser(result.user);
                sessionStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e) { return { success: false, message: "Server Error" }; }
    };
    const logout = () => { setCurrentUser(null); sessionStorage.removeItem('procurement_session_user'); };
    const registerUser = async (u: any) => {
        try {
            const newUser = { ...u, id: Math.random().toString(36).substr(2, 9) };
            await fetch(`${API_URL}/register`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newUser)});
            fetchData(); return true;
        } catch { return false; }
    };
    const updateUser = async (id: string, d: any) => {
        await fetch(`${API_URL}/users/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        setUsers(prev => prev.map(u => u.id === id ? { ...u, ...d } : u));
    };
    const deleteUser = (id: string) => updateUser(id, { status: 'SUSPENDED' });

    // Core Data Actions
    const addProcurement = async (d: any, force = false) => {
        // Note: Running Number logic handled in Component or could be moved here
        const newRecord = { ...d, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now(), departmentId: currentUser?.departmentId, createdBy: currentUser?.id };
        try {
            await fetch(`${API_URL}/procurements`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newRecord)});
            setRawProcurements(prev => [...prev, newRecord]);
            return { success: true };
        } catch { return { success: false, message: "Error" }; }
    };
    const updateProcurement = async (id: string, d: any) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        setRawProcurements(prev => prev.map(p => p.id === id ? {...p, ...d} : p));
    };
    const deleteProcurement = async (id: string) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
        setRawProcurements(prev => prev.filter(p => p.id !== id));
    };

    // Receivings & Considerations
    const addReceiving = async (d: any) => {
        const n = { ...d, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() };
        await fetch(`${API_URL}/receivings`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(n)});
        setRawReceivings(prev => [...prev, n]);
    };
    const deleteReceiving = async (id: string) => {
        await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' });
        setRawReceivings(prev => prev.filter(r => r.id !== id));
    };
    const upsertReceiving = async (rid: string, no: string, date: string) => {
        const p = rawProcurements.find(x => x.requestId === rid);
        await fetch(`${API_URL}/receivings/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ requestId: rid, deliveryNoteNo: no, receiveDate: date, category: p?.category })});
        fetchData();
    };
    const addConsideration = async (d: any) => {
        const n = { ...d, id: d.id || Math.random().toString(36).substr(2, 9) };
        await fetch(`${API_URL}/considerations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(n)});
        setRawConsiderations(prev => [...prev, n]);
    };
    const upsertConsideration = async (rid: string, no: string, date: string) => {
        await fetch(`${API_URL}/considerations/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ requestId: rid, considerationNumber: no, considerationDate: date })});
        fetchData();
    };
    const getLinkedData = (rid: string) => ({
        receiving: rawReceivings.find(r => r.requestId === rid),
        consideration: rawConsiderations.find(c => c.requestId === rid)
    });

    // Settings Management
    const updateSettings = (s: any) => setSettings(prev => ({...prev, ...s}));

    const addDepartment = async (d: Department) => {
        await fetch(`${API_URL}/department`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        fetchData();
    };
    const updateDepartment = async (id: string, d: Partial<Department>) => {
        await fetch(`${API_URL}/department/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        fetchData();
    };
    const deleteDepartment = async (id: string) => {
        // Now acting as Soft Delete (server handles logic based on method, or we use update)
        // For strict soft delete from frontend, we use updateDepartment
        await updateDepartment(id, { isActive: false });
    };

    const addWorkGroup = async (g: WorkGroup) => {
        await fetch(`${API_URL}/workgroup`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(g)});
        fetchData();
    };
    const updateWorkGroup = async (id: string, data: Partial<WorkGroup>) => {
        await fetch(`${API_URL}/workgroup/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data)});
        fetchData();
    };
    const deleteWorkGroup = async (id: string) => {
        // Soft Delete: Toggle active status
        await updateWorkGroup(id, { isActive: false });
    };

    const addCategory = async (c: ProcurementCategory) => {
        await fetch(`${API_URL}/category`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(c)});
        fetchData();
    };

    const updateCategory = async (id: string, data: Partial<ProcurementCategory>) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data)});
        fetchData();
    };

    const deleteCategory = async (id: string) => {
        // NOTE: Backend now treats DELETE on category as Soft Delete (isActive = false)
        await fetch(`${API_URL}/category/${id}`, { method: 'DELETE' });
        // Update local state to reflect Inactive instead of removing from array
        setSettings(prev => ({
            ...prev,
            categories: prev.categories.map(c => c.id === id ? { ...c, isActive: false } : c)
        }));
    };

    const checkChronologyIssue = () => false; // Simplified for brevity

    return (
        <AppContext.Provider value={{
            isLoading, serverError, serverErrorMessage, retryConnection,
            procurements: visibleData.procurements, receivings: visibleData.receivings, considerations: visibleData.considerations,
            settings, currentUser, users,
            login, logout, registerUser, deleteUser, updateUser,
            addProcurement, updateProcurement, deleteProcurement,
            addReceiving, deleteReceiving, upsertReceiving,
            addConsideration, upsertConsideration,
            getLinkedData, updateSettings,
            addDepartment, updateDepartment, deleteDepartment,
            addWorkGroup, updateWorkGroup, deleteWorkGroup,
            addCategory, updateCategory, deleteCategory, // Added here
            checkChronologyIssue
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { Plus, Edit2, X, Check, Building, Briefcase, Power, Layers, ChevronRight, FolderTree, Settings, Trash2, AlertTriangle, Save, HelpCircle } from 'lucide-react';

const SettingsPage: React.FC = () => {
    const { settings, addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory, deleteCategory, updateSettings } = useApp();

    // ================= Selection State =================
    const [selectedWgId, setSelectedWgId] = useState<string | null>(null);
    const [selectedDeptId, setSelectedDeptId] = useState<string | null>(null);

    // ================= Edit State =================
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');
    const [editExtra, setEditExtra] = useState(''); // Prefix
    const [editExtra2, setEditExtra2] = useState(''); // Request Prefix

    // ================= New Item State =================
    const [newWgName, setNewWgName] = useState('');
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptReqPrefix, setNewDeptReqPrefix] = useState('');
    const [newCatName, setNewCatName] = useState('');

    // ================= Global Settings State =================
    const [globalPrefix, setGlobalPrefix] = useState(settings.requestIdPrefix);
    const [isEditingGlobal, setIsEditingGlobal] = useState(false);

    // ================= Confirmation State (Unified) =================
    const [confirmDialog, setConfirmDialog] = useState<{
        isOpen: boolean;
        type: 'ADD' | 'EDIT' | 'DELETE';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // Filter Logic
    useEffect(() => { setSelectedDeptId(null); }, [selectedWgId]);

    const visibleDepartments = selectedWgId 
        ? settings.departments.filter(d => d.workGroupId === selectedWgId) 
        : []; 

    const visibleCategories = selectedDeptId
        ? settings.categories.filter(c => c.departmentId === selectedDeptId)
        : [];

    // ================= Handlers =================

    // --- Global ---
    const saveGlobalPrefix = () => {
        updateSettings({ requestIdPrefix: globalPrefix });
        setIsEditingGlobal(false);
    };

    // --- Work Groups ---
    const handleAddWg = () => {
        if(!newWgName.trim()) return;
        addWorkGroup({ id: `g_${Date.now()}`, name: newWgName.trim(), isActive: true });
        setNewWgName('');
    };
    const handleUpdateWg = (id: string) => {
        updateWorkGroup(id, { name: editValue });
        setEditingId(null);
    };

    // --- Departments ---
    const handleAddDept = () => {
        if(!newDeptName.trim() || !selectedWgId) return;
        addDepartment({ 
            id: `d_${Date.now()}`, 
            name: newDeptName.trim(), 
            prefix: newDeptPrefix.trim(),
            requestPrefix: newDeptReqPrefix.trim(),
            workGroupId: selectedWgId, 
            isActive: true 
        });
        setNewDeptName(''); setNewDeptPrefix(''); setNewDeptReqPrefix('');
    };
    const handleUpdateDept = (id: string) => {
        updateDepartment(id, { name: editValue, prefix: editExtra, requestPrefix: editExtra2 });
        setEditingId(null);
    };

    // --- Categories (With Confirmation) ---
    const requestAddCat = () => {
        if(!newCatName.trim() || !selectedDeptId) return;

        setConfirmDialog({
            isOpen: true,
            type: 'ADD',
            title: 'ยืนยันการเพิ่มหมวดพัสดุ',
            message: `คุณต้องการเพิ่มหมวด "${newCatName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addCategory({ 
                    id: `c_${Date.now()}`, 
                    name: newCatName.trim(), 
                    departmentId: selectedDeptId, 
                    isActive: true 
                });
                setNewCatName('');
                setConfirmDialog(null);
            }
        });
    };

    const requestUpdateCat = (id: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'EDIT',
            title: 'ยืนยันการแก้ไข',
            message: `คุณต้องการเปลี่ยนชื่อเป็น "${editValue}" ใช่หรือไม่?`,
            onConfirm: () => {
                updateCategory(id, { name: editValue });
                setEditingId(null);
                setConfirmDialog(null);
            }
        });
    };

    const requestDeleteCat = (id: string, name: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'DELETE',
            title: 'ยืนยันการลบ',
            message: `คุณต้องการลบหมวด "${name}" ใช่หรือไม่? \n(ระบบจะทำการปิดการใช้งาน แทนการลบข้อมูลถาวร)`,
            onConfirm: () => {
                deleteCategory(id);
                setConfirmDialog(null);
            }
        });
    };

    // --- Generic Toggle ---
    const toggleActive = (type: 'WG'|'DEPT'|'CAT', item: any) => {
        if(type === 'WG') updateWorkGroup(item.id, { isActive: !item.isActive });
        if(type === 'DEPT') updateDepartment(item.id, { isActive: !item.isActive });
        if(type === 'CAT') updateCategory(item.id, { isActive: !item.isActive });
    };

    return (
        <div className="p-4 sm:p-6 h-[calc(100vh-60px)] flex flex-col bg-slate-50 overflow-hidden font-sans relative">

            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 flex-shrink-0 gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center">
                        <FolderTree className="mr-3 text-blue-600" />
                        โครงสร้างองค์กร (Organization Settings)
                    </h2>
                    <p className="text-sm text-slate-500 mt-1">จัดการข้อมูลตามลำดับชั้น: กลุ่มงาน &gt; ฝ่าย/งาน &gt; หมวดพัสดุ</p>
                </div>

                <div className="bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center text-sm">
                    <Settings size={14} className="mr-2 text-slate-400"/>
                    <span className="text-slate-500 mr-2">รูปแบบเลขที่ใบขอ (ค่าเริ่มต้น):</span>
                    {isEditingGlobal ? (
                        <div className="flex items-center animate-fade-in">
                            <input 
                                className="border rounded px-2 py-0.5 w-32 text-slate-700 outline-none focus:ring-1 focus:ring-blue-500" 
                                value={globalPrefix} 
                                onChange={e => setGlobalPrefix(e.target.value)}
                            />
                            <button onClick={saveGlobalPrefix} className="ml-1 text-green-600 hover:bg-green-50 p-1 rounded"><Check size={16}/></button>
                            <button onClick={() => setIsEditingGlobal(false)} className="ml-1 text-red-500 hover:bg-red-50 p-1 rounded"><X size={16}/></button>
                        </div>
                    ) : (
                        <div className="flex items-center cursor-pointer hover:bg-slate-50 px-2 rounded transition-colors" onClick={() => setIsEditingGlobal(true)}>
                            <span className="font-mono font-medium text-slate-700">{settings.requestIdPrefix}</span>
                            <Edit2 size={12} className="ml-2 text-slate-300"/>
                        </div>
                    )}
                </div>
            </div>

            {/* Miller Columns Container */}
            <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4 min-h-0 overflow-hidden">

                {/* ================= COLUMN 1: WORK GROUPS ================= */}
                <div className="flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-full">
                    <div className="p-3 bg-orange-50 border-b border-orange-100 flex justify-between items-center sticky top-0 z-10">
                        <h3 className="font-bold text-orange-800 flex items-center text-sm">
                            <Briefcase size={16} className="mr-2"/> 1. กลุ่มงาน
                        </h3>
                        <span className="text-xs bg-white text-orange-600 px-2 py-0.5 rounded-full border border-orange-200 font-bold">{settings.workGroups.length}</span>
                    </div>

                    <div className="p-3 border-b border-slate-100 bg-white">
                        <div className="flex relative">
                            <input 
                                className="flex-1 bg-slate-50 border border-slate-200 rounded-l-lg pl-3 pr-2 py-2 text-sm outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all" 
                                placeholder="เพิ่มกลุ่มงานใหม่..." 
                                value={newWgName} 
                                onChange={e => setNewWgName(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && handleAddWg()}
                            />
                            <button onClick={handleAddWg} disabled={!newWgName.trim()} className="bg-orange-500 hover:bg-orange-600 text-white px-3 rounded-r-lg disabled:opacity-50 transition-colors">
                                <Plus size={18}/>
                            </button>
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto p-2 space-y-1">
                        {settings.workGroups.map(g => (
                            <div key={g.id} 
                                onClick={() => { if(editingId !== g.id) setSelectedWgId(g.id); }}
                                className={`group flex items-center p-2.5 rounded-lg cursor-pointer border transition-all duration-200
                                    ${selectedWgId === g.id 
                                        ? 'bg-orange-50 border-orange-300 shadow-sm ring-1 ring-orange-200' 
                                        : 'bg-white border-transparent hover:bg-slate-50 hover:border-slate-200'}
                                    ${!g.isActive ? 'opacity-50 grayscale' : ''}
                                `}
                            >
                                {editingId === g.id ? (
                                    <div className="flex-1 flex items-center space-x-1" onClick={e => e.stopPropagation()}>
                                        <input autoFocus className="flex-1 border rounded px-2 py-1 text-sm w-full" value={editValue} onChange={e => setEditValue(e.target.value)} />
                                        <button onClick={() => handleUpdateWg(g.id)} className="p-1 bg-green-100 text-green-700 rounded"><Check size={14}/></button>
                                        <button onClick={() => setEditingId(null)} className="p-1 bg-slate-100 text-slate-500 rounded"><X size={14}/></button>
                                    </div>
                                ) : (
                                    <>
                                        <div className="flex-1 min-w-0">
                                            <div className={`text-sm font-medium truncate ${selectedWgId === g.id ? 'text-orange-900' : 'text-slate-700'}`}>{g.name}</div>
                                        </div>
                                        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={(e) => { e.stopPropagation(); setEditingId(g.id); setEditValue(g.name); }} className="p-1.5 hover:bg-white rounded text-slate-400 hover:text-orange-600"><Edit2 size={12}/></button>
                                            <button onClick={(e) => { e.stopPropagation(); toggleActive('WG', g); }} className={`p-1.5 hover:bg-white rounded ${g.isActive ? 'text-slate-400 hover:text-red-500' : 'text-red-500 hover:text-green-600'}`}>
                                                <Power size={12}/>
                                            </button>
                                        </div>
                                        <ChevronRight size={16} className={`ml-1 transition-transform ${selectedWgId === g.id ? 'text-orange-500 translate-x-0' : 'text-transparent -translate-x-2'}`}/>
                                    </>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                {/* ================= COLUMN 2: DEPARTMENTS ================= */}
                <div className={`flex flex-col bg-white rounded-xl shadow-sm border overflow-hidden h-full transition-colors ${selectedWgId ? 'border-indigo-200' : 'border-slate-200 opacity-60'}`}>
                    <div className={`p-3 border-b flex justify-between items-center sticky top-0 z-10 ${selectedWgId ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-100 border-slate-200'}`}>
                        <h3 className={`font-bold flex items-center text-sm ${selectedWgId ? 'text-indigo-800' : 'text-slate-500'}`}>
                            <Building size={16} className="mr-2"/> 2. ฝ่าย/งาน
                        </h3>
                        {selectedWgId && <span className="text-xs bg-white text-indigo-600 px-2 py-0.5 rounded-full border border-indigo-200 font-bold">{visibleDepartments.length}</span>}
                    </div>

                    <div className="p-3 border-b border-slate-100 bg-white space-y-2">
                        {selectedWgId ? (
                            <>
                                <input 
                                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all" 
                                    placeholder="ชื่อฝ่าย..." 
                                    value={newDeptName} 
                                    onChange={e => setNewDeptName(e.target.value)}
                                />
                                <div className="flex space-x-2">
                                    <input className="w-1/3 bg-slate-50 border border-slate-200 rounded-l-lg px-2 py-2 text-xs text-center outline-none focus:ring-2 focus:ring-indigo-500" placeholder="ตัวย่อ (พด.)" value={newDeptPrefix} onChange={e => setNewDeptPrefix(e.target.value)}/>
                                    <input className="flex-1 bg-slate-50 border-y border-r border-slate-200 px-2 py-2 text-xs font-mono outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Prefix (สพ...)" value={newDeptReqPrefix} onChange={e => setNewDeptReqPrefix(e.target.value)}/>
                                    <button onClick={handleAddDept} disabled={!newDeptName.trim()} className="bg-indigo-500 hover:bg-indigo-600 text-white px-3 rounded-r-lg disabled:opacity-50 transition-colors">
                                        <Plus size={18}/>
                                    </button>
                                </div>
                            </>
                        ) : (
                            <div className="text-center py-4 text-sm text-slate-400 italic">กรุณาเลือกกลุ่มงานก่อน</div>
                        )}
                    </div>

                    <div className="flex-1 overflow-y-auto p-2 space-y-1">
                        {visibleDepartments.length === 0 && selectedWgId && (
                            <div className="text-center py-8 text-slate-400 text-xs">ยังไม่มีฝ่ายในกลุ่มงานนี้</div>
                        )}
                        {visibleDepartments.map(dept => (
                            <div key={dept.id} 
                                onClick={() => { if(editingId !== dept.id) setSelectedDeptId(dept.id); }}
                                className={`group p-2.5 rounded-lg cursor-pointer border transition-all duration-200
                                    ${selectedDeptId === dept.id 
                                        ? 'bg-indigo-50 border-indigo-300 shadow-sm ring-1 ring-indigo-200' 
                                        : 'bg-white border-transparent hover:bg-slate-50 hover:border-slate-200'}
                                    ${!dept.isActive ? 'opacity-50 grayscale' : ''}
                                `}
                            >
                                {editingId === dept.id ? (
                                    <div className="space-y-2 cursor-default" onClick={e=>e.stopPropagation()}>
                                        <input className="w-full border rounded px-2 py-1 text-sm" value={editValue} onChange={e => setEditValue(e.target.value)} placeholder="ชื่อฝ่าย" />
                                        <div className="flex space-x-1">
                                            <input className="w-16 border rounded px-1 py-1 text-xs text-center" value={editExtra} onChange={e => setEditExtra(e.target.value)} placeholder="ตัวย่อ" />
                                            <input className="flex-1 border rounded px-1 py-1 text-xs font-mono" value={editExtra2} onChange={e => setEditExtra2(e.target.value)} placeholder="Prefix" />
                                            <button onClick={() => handleUpdateDept(dept.id)} className="p-1 bg-green-100 text-green-700 rounded"><Check size={14}/></button>
                                            <button onClick={() => setEditingId(null)} className="p-1 bg-slate-100 text-slate-500 rounded"><X size={14}/></button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex items-center justify-between">
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center">
                                                <div className={`text-sm font-medium truncate ${selectedDeptId === dept.id ? 'text-indigo-900' : 'text-slate-700'}`}>{dept.name}</div>
                                                {dept.prefix && <span className="ml-2 text-[10px] bg-slate-100 text-slate-500 px-1.5 rounded">{dept.prefix}</span>}
                                            </div>
                                            <div className="text-[10px] text-slate-400 font-mono truncate">{dept.requestPrefix || '-'}</div>
                                        </div>
                                        <div className="flex items-center space-x-1">
                                            <div className="flex opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button onClick={(e) => { e.stopPropagation(); setEditingId(dept.id); setEditValue(dept.name); setEditExtra(dept.prefix||''); setEditExtra2(dept.requestPrefix||''); }} className="p-1.5 hover:bg-white rounded text-slate-400 hover:text-indigo-600"><Edit2 size={12}/></button>
                                                <button onClick={(e) => { e.stopPropagation(); toggleActive('DEPT', dept); }} className={`p-1.5 hover:bg-white rounded ${dept.isActive ? 'text-slate-400 hover:text-red-500' : 'text-red-500 hover:text-green-600'}`}>
                                                    <Power size={12}/>
                                                </button>
                                            </div>
                                            <ChevronRight size={16} className={`transition-transform ${selectedDeptId === dept.id ? 'text-indigo-500 translate-x-0' : 'text-transparent -translate-x-2'}`}/>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                {/* ================= COLUMN 3: CATEGORIES ================= */}
                <div className={`flex flex-col bg-white rounded-xl shadow-sm border overflow-hidden h-full transition-colors ${selectedDeptId ? 'border-green-200' : 'border-slate-200 opacity-60'}`}>
                    <div className={`p-3 border-b flex justify-between items-center sticky top-0 z-10 ${selectedDeptId ? 'bg-green-50 border-green-100' : 'bg-slate-100 border-slate-200'}`}>
                        <h3 className={`font-bold flex items-center text-sm ${selectedDeptId ? 'text-green-800' : 'text-slate-500'}`}>
                            <Layers size={16} className="mr-2"/> 3. หมวดพัสดุ
                        </h3>
                        {selectedDeptId && <span className="text-xs bg-white text-green-600 px-2 py-0.5 rounded-full border border-green-200 font-bold">{visibleCategories.length}</span>}
                    </div>

                    <div className="p-3 border-b border-slate-100 bg-white">
                        {selectedDeptId ? (
                            <div className="flex relative">
                                <input 
                                    className="flex-1 bg-slate-50 border border-slate-200 rounded-l-lg pl-3 pr-2 py-2 text-sm outline-none focus:ring-2 focus:ring-green-500 focus:bg-white transition-all" 
                                    placeholder="เพิ่มหมวด (เช่น วัสดุสำนักงาน)..." 
                                    value={newCatName} 
                                    onChange={e => setNewCatName(e.target.value)}
                                    onKeyDown={e => e.key === 'Enter' && requestAddCat()}
                                />
                                <button onClick={requestAddCat} disabled={!newCatName.trim()} className="bg-green-500 hover:bg-green-600 text-white px-3 rounded-r-lg disabled:opacity-50 transition-colors">
                                    <Plus size={18}/>
                                </button>
                            </div>
                        ) : (
                            <div className="text-center py-4 text-sm text-slate-400 italic">กรุณาเลือกฝ่าย/งานก่อน</div>
                        )}
                    </div>

                    <div className="flex-1 overflow-y-auto p-2 space-y-1">
                        {visibleCategories.length === 0 && selectedDeptId && (
                            <div className="text-center py-8 text-slate-400 text-xs">ยังไม่มีหมวดพัสดุในฝ่ายนี้</div>
                        )}
                        {visibleCategories.map(cat => (
                            <div key={cat.id} className={`group flex items-center p-2.5 rounded-lg border bg-white border-transparent hover:bg-slate-50 hover:border-slate-200 transition-all ${!cat.isActive ? 'opacity-50 grayscale' : ''}`}>
                                {editingId === cat.id ? (
                                    <div className="flex-1 flex items-center space-x-1" onClick={e=>e.stopPropagation()}>
                                        <input autoFocus className="flex-1 border rounded px-2 py-1 text-sm w-full" value={editValue} onChange={e => setEditValue(e.target.value)} />
                                        <button onClick={() => requestUpdateCat(cat.id)} className="p-1 bg-green-100 text-green-700 rounded"><Check size={14}/></button>
                                        <button onClick={() => setEditingId(null)} className="p-1 bg-slate-100 text-slate-500 rounded"><X size={14}/></button>
                                    </div>
                                ) : (
                                    <>
                                        <div className="flex-1 text-sm font-medium text-slate-700">{cat.name}</div>
                                        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button 
                                                onClick={() => { setEditingId(cat.id); setEditValue(cat.name); }} 
                                                className="p-1.5 hover:bg-blue-50 text-slate-400 hover:text-blue-600 rounded"
                                                title="แก้ไข"
                                            >
                                                <Edit2 size={12}/>
                                            </button>
                                            <button 
                                                onClick={() => toggleActive('CAT', cat)} 
                                                className={`p-1.5 rounded hover:bg-slate-100 ${cat.isActive ? 'text-slate-400 hover:text-orange-500' : 'text-orange-500'}`}
                                                title={cat.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน'}
                                            >
                                                <Power size={12}/>
                                            </button>
                                            <button 
                                                onClick={() => requestDeleteCat(cat.id, cat.name)} 
                                                className="p-1.5 hover:bg-red-50 text-slate-400 hover:text-red-600 rounded"
                                                title="ลบ"
                                            >
                                                <Trash2 size={12}/>
                                            </button>
                                        </div>
                                    </>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Universal Confirmation Modal */}
            {confirmDialog && (
                <div className="absolute inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/30 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-slate-200">
                        <div className={`mx-auto flex items-center justify-center h-12 w-12 rounded-full mb-4 ${
                            confirmDialog.type === 'DELETE' ? 'bg-red-50 text-red-600' :
                            confirmDialog.type === 'ADD' ? 'bg-green-50 text-green-600' : 'bg-blue-50 text-blue-600'
                        }`}>
                            {confirmDialog.type === 'DELETE' ? <AlertTriangle className="h-6 w-6" /> : 
                             confirmDialog.type === 'ADD' ? <Plus className="h-6 w-6" /> : <HelpCircle className="h-6 w-6" />}
                        </div>
                        <h3 className="text-lg font-bold text-slate-900 mb-2">{confirmDialog.title}</h3>
                        <p className="text-sm text-slate-500 mb-6 leading-relaxed whitespace-pre-line">
                            {confirmDialog.message}
                        </p>
                        <div className="flex space-x-3">
                            <button onClick={() => setConfirmDialog(null)} className="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-semibold transition-all">ยกเลิก</button>
                            <button 
                                onClick={confirmDialog.onConfirm} 
                                className={`flex-1 py-2.5 text-white rounded-lg text-sm font-semibold shadow-md transition-all ${
                                    confirmDialog.type === 'DELETE' ? 'bg-red-600 hover:bg-red-700' :
                                    confirmDialog.type === 'ADD' ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'
                                }`}
                            >
                                ยืนยัน
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SettingsPage;

import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { Plus, Edit2, X, Check, Building, Briefcase, Power, Layers, ChevronRight, FolderTree, Settings, Trash2, AlertTriangle, Save, HelpCircle } from 'lucide-react';

const SettingsPage: React.FC = () => {
    const { settings, addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory, deleteCategory, updateSettings } = useApp();

    // ================= Selection State =================
    const [selectedWgId, setSelectedWgId] = useState<string | null>(null);
    const [selectedDeptId, setSelectedDeptId] = useState<string | null>(null);

    // ================= Edit State =================
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');
    const [editExtra, setEditExtra] = useState(''); // Prefix
    const [editExtra2, setEditExtra2] = useState(''); // Request Prefix

    // ================= New Item State =================
    const [newWgName, setNewWgName] = useState('');
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptReqPrefix, setNewDeptReqPrefix] = useState('');
    const [newCatName, setNewCatName] = useState('');

    // ================= Global Settings State =================
    const [globalPrefix, setGlobalPrefix] = useState(settings.requestIdPrefix);
    const [isEditingGlobal, setIsEditingGlobal] = useState(false);

    // ================= Confirmation State (Unified) =================
    const [confirmDialog, setConfirmDialog] = useState<{
        isOpen: boolean;
        type: 'ADD' | 'EDIT' | 'DELETE';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // Filter Logic
    useEffect(() => { setSelectedDeptId(null); }, [selectedWgId]);

    const visibleDepartments = selectedWgId 
        ? settings.departments.filter(d => d.workGroupId === selectedWgId) 
        : []; 

    const visibleCategories = selectedDeptId
        ? settings.categories.filter(c => c.departmentId === selectedDeptId)
        : [];

    // ================= Handlers =================

    // --- Global ---
    const saveGlobalPrefix = () => {
        updateSettings({ requestIdPrefix: globalPrefix });
        setIsEditingGlobal(false);
    };

    // --- Work Groups ---
    const handleAddWg = () => {
        if(!newWgName.trim()) return;
        addWorkGroup({ id: `g_${Date.now()}`, name: newWgName.trim(), isActive: true });
        setNewWgName('');
    };
    const handleUpdateWg = (id: string) => {
        updateWorkGroup(id, { name: editValue });
        setEditingId(null);
    };

    // --- Departments ---
    const handleAddDept = () => {
        if(!newDeptName.trim() || !selectedWgId) return;
        addDepartment({ 
            id: `d_${Date.now()}`, 
            name: newDeptName.trim(), 
            prefix: newDeptPrefix.trim(),
            requestPrefix: newDeptReqPrefix.trim(),
            workGroupId: selectedWgId, 
            isActive: true 
        });
        setNewDeptName(''); setNewDeptPrefix(''); setNewDeptReqPrefix('');
    };
    const handleUpdateDept = (id: string) => {
        updateDepartment(id, { name: editValue, prefix: editExtra, requestPrefix: editExtra2 });
        setEditingId(null);
    };

    // --- Categories (With Confirmation) ---
    const requestAddCat = () => {
        if(!newCatName.trim() || !selectedDeptId) return;

        setConfirmDialog({
            isOpen: true,
            type: 'ADD',
            title: 'ยืนยันการเพิ่มหมวดพัสดุ',
            message: `คุณต้องการเพิ่มหมวด "${newCatName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addCategory({ 
                    id: `c_${Date.now()}`, 
                    name: newCatName.trim(), 
                    departmentId: selectedDeptId, 
                    isActive: true 
                });
                setNewCatName('');
                setConfirmDialog(null);
            }
        });
    };

    const requestUpdateCat = (id: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'EDIT',
            title: 'ยืนยันการแก้ไข',
            message: `คุณต้องการเปลี่ยนชื่อเป็น "${editValue}" ใช่หรือไม่?`,
            onConfirm: () => {
                updateCategory(id, { name: editValue });
                setEditingId(null);
                setConfirmDialog(null);
            }
        });
    };

    const requestDeleteCat = (id: string, name: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'DELETE',
            title: 'ยืนยันการลบ',
            message: `คุณต้องการลบหมวด "${name}" ใช่หรือไม่? \n(ระบบจะทำการปิดการใช้งาน แทนการลบข้อมูลถาวร)`,
            onConfirm: () => {
                deleteCategory(id);
                setConfirmDialog(null);
            }
        });
    };

    // --- Generic Toggle ---
    const toggleActive = (type: 'WG'|'DEPT'|'CAT', item: any) => {
        if(type === 'WG') updateWorkGroup(item.id, { isActive: !item.isActive });
        if(type === 'DEPT') updateDepartment(item.id, { isActive: !item.isActive });
        if(type === 'CAT') updateCategory(item.id, { isActive: !item.isActive });
    };

    return (
        <div className="p-4 sm:p-6 h-[calc(100vh-60px)] flex flex-col bg-slate-50 overflow-hidden font-sans relative">

            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 flex-shrink-0 gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center">
                        <FolderTree className="mr-3 text-blue-600" />
                        โครงสร้างองค์กร (Organization Settings)
                    </h2>
