import React, { useState, useEffect } from 'react';
import { useApp } from '../services/store';
import { Plus, Edit2, X, Check, Building, Briefcase, Power, Layers, ChevronRight, FolderTree, Settings, Trash2, AlertTriangle, Save, HelpCircle } from 'lucide-react';

const SettingsPage: React.FC = () => {
    const { settings, addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory, deleteCategory, updateSettings } = useApp();

    // ================= Selection State =================
    const [selectedWgId, setSelectedWgId] = useState<string | null>(null);
    const [selectedDeptId, setSelectedDeptId] = useState<string | null>(null);

    // ================= Edit State =================
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');
    const [editExtra, setEditExtra] = useState(''); // Prefix
    const [editExtra2, setEditExtra2] = useState(''); // Request Prefix

    // ================= New Item State =================
    const [newWgName, setNewWgName] = useState('');
    const [newDeptName, setNewDeptName] = useState('');
    const [newDeptPrefix, setNewDeptPrefix] = useState('');
    const [newDeptReqPrefix, setNewDeptReqPrefix] = useState('');
    const [newCatName, setNewCatName] = useState('');

    // ================= Global Settings State =================
    const [globalPrefix, setGlobalPrefix] = useState(settings.requestIdPrefix);
    const [isEditingGlobal, setIsEditingGlobal] = useState(false);

    // ================= Confirmation State (Unified) =================
    const [confirmDialog, setConfirmDialog] = useState<{
        isOpen: boolean;
        type: 'ADD' | 'EDIT' | 'DELETE';
        title: string;
        message: string;
        onConfirm: () => void;
    } | null>(null);

    // Filter Logic
    useEffect(() => { setSelectedDeptId(null); }, [selectedWgId]);

    const visibleDepartments = selectedWgId 
        ? settings.departments.filter(d => d.workGroupId === selectedWgId) 
        : []; 

    const visibleCategories = selectedDeptId
        ? settings.categories.filter(c => c.departmentId === selectedDeptId)
        : [];

    // ================= Handlers =================

    // --- Global ---
    const saveGlobalPrefix = () => {
        setConfirmDialog({
            isOpen: true,
            type: 'EDIT',
            title: 'ยืนยันการตั้งค่า',
            message: 'คุณต้องการบันทึกรูปแบบเลขที่ใบขอใช่หรือไม่?',
            onConfirm: () => {
                updateSettings({ requestIdPrefix: globalPrefix });
                setIsEditingGlobal(false);
                setConfirmDialog(null);
            }
        });
    };

    // --- Work Groups ---
    const requestAddWg = () => {
        if(!newWgName.trim()) return;
        setConfirmDialog({
            isOpen: true,
            type: 'ADD',
            title: 'ยืนยันการเพิ่มกลุ่มงาน',
            message: `คุณต้องการเพิ่มกลุ่มงาน "${newWgName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addWorkGroup({ id: `g_${Date.now()}`, name: newWgName.trim(), isActive: true });
                setNewWgName('');
                setConfirmDialog(null);
            }
        });
    };
    const requestUpdateWg = (id: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'EDIT',
            title: 'ยืนยันการแก้ไข',
            message: `คุณต้องการเปลี่ยนชื่อกลุ่มงานเป็น "${editValue}" ใช่หรือไม่?`,
            onConfirm: () => {
                updateWorkGroup(id, { name: editValue });
                setEditingId(null);
                setConfirmDialog(null);
            }
        });
    };

    // --- Departments ---
    const requestAddDept = () => {
        if(!newDeptName.trim() || !selectedWgId) return;
        setConfirmDialog({
            isOpen: true,
            type: 'ADD',
            title: 'ยืนยันการเพิ่มฝ่าย/งาน',
            message: `คุณต้องการเพิ่มฝ่าย "${newDeptName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addDepartment({ 
                    id: `d_${Date.now()}`, 
                    name: newDeptName.trim(), 
                    prefix: newDeptPrefix.trim(),
                    requestPrefix: newDeptReqPrefix.trim(),
                    workGroupId: selectedWgId, 
                    isActive: true 
                });
                setNewDeptName(''); setNewDeptPrefix(''); setNewDeptReqPrefix('');
                setConfirmDialog(null);
            }
        });
    };
    const requestUpdateDept = (id: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'EDIT',
            title: 'ยืนยันการแก้ไข',
            message: `คุณต้องการบันทึกการแก้ไขข้อมูลฝ่าย/งานใช่หรือไม่?`,
            onConfirm: () => {
                updateDepartment(id, { name: editValue, prefix: editExtra, requestPrefix: editExtra2 });
                setEditingId(null);
                setConfirmDialog(null);
            }
        });
    };

    // --- Categories (With Confirmation) ---
    const requestAddCat = () => {
        if(!newCatName.trim() || !selectedDeptId) return;

        setConfirmDialog({
            isOpen: true,
            type: 'ADD',
            title: 'ยืนยันการเพิ่มหมวดพัสดุ',
            message: `คุณต้องการเพิ่มหมวด "${newCatName.trim()}" ใช่หรือไม่?`,
            onConfirm: () => {
                addCategory({ 
                    id: `c_${Date.now()}`, 
                    name: newCatName.trim(), 
                    departmentId: selectedDeptId, 
                    isActive: true 
                });
                setNewCatName('');
                setConfirmDialog(null);
            }
        });
    };

    const requestUpdateCat = (id: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'EDIT',
            title: 'ยืนยันการแก้ไข',
            message: `คุณต้องการเปลี่ยนชื่อเป็น "${editValue}" ใช่หรือไม่?`,
            onConfirm: () => {
                updateCategory(id, { name: editValue });
                setEditingId(null);
                setConfirmDialog(null);
            }
        });
    };

    const requestDeleteCat = (id: string, name: string) => {
        setConfirmDialog({
            isOpen: true,
            type: 'DELETE',
            title: 'ยืนยันการลบ',
            message: `คุณต้องการลบหมวด "${name}" ใช่หรือไม่? \n(ระบบจะทำการปิดการใช้งาน แทนการลบข้อมูลถาวร)`,
            onConfirm: () => {
                deleteCategory(id);
                setConfirmDialog(null);
            }
        });
    };

    // --- Generic Toggle ---
    const requestToggleActive = (type: 'WG'|'DEPT'|'CAT', item: any) => {
        const action = item.isActive ? 'ปิดการใช้งาน' : 'เปิดการใช้งาน';
        const dialogType = item.isActive ? 'DELETE' : 'ADD'; 

        setConfirmDialog({
            isOpen: true,
            type: dialogType,
            title: `ยืนยันการ${action}`,
            message: `คุณต้องการ${action} "${item.name}" ใช่หรือไม่?`,
            onConfirm: () => {
                if(type === 'WG') updateWorkGroup(item.id, { isActive: !item.isActive });
                if(type === 'DEPT') updateDepartment(item.id, { isActive: !item.isActive });
                if(type === 'CAT') updateCategory(item.id, { isActive: !item.isActive });
                setConfirmDialog(null);
            }
        });
    };

    return (
        <div className="p-4 sm:p-6 h-[calc(100vh-60px)] flex flex-col bg-slate-50 overflow-hidden font-sans relative">

            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 flex-shrink-0 gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-800 flex items-center">
                        <FolderTree className="mr-3 text-blue-600" />
                        โครงสร้างองค์กร (Organization Settings)
                    </h2>
                    <p className="text-sm text-slate-500 mt-1">จัดการข้อมูลตามลำดับชั้น: กลุ่มงาน &gt; ฝ่าย/งาน &gt; หมวดพัสดุ</p>
                </div>

                <div className="bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center text-sm">
                    <Settings size={14} className="mr-2 text-slate-400"/>
                    <span className="text-slate-500 mr-2">รูปแบบเลขที่ใบขอ (ค่าเริ่มต้น):</span>
                    {isEditingGlobal ? (
                        <div className="flex items-center animate-fade-in">
                            <input 
                                className="border rounded px-2 py-0.5 w-32 text-slate-700 outline-none focus:ring-1 focus:ring-blue-500" 
                                value={globalPrefix} 
                                onChange={e => setGlobalPrefix(e.target.value)}
                            />
                            <button onClick={saveGlobalPrefix} className="ml-1 text-green-600 hover:bg-green-50 p-1 rounded"><Check size={16}/></button>
                            <button onClick={() => setIsEditingGlobal(false)} className="ml-1 text-red-500 hover:bg-red-50 p-1 rounded"><X size={16}/></button>
                        </div>
                    ) : (
                        <div className="flex items-center cursor-pointer hover:bg-slate-50 px-2 rounded transition-colors" onClick={() => setIsEditingGlobal(true)}>
                            <span className="font-mono font-medium text-slate-700">{settings.requestIdPrefix}</span>
                            <Edit2 size={12} className="ml-2 text-slate-300"/>
                        </div>
                    )}
                </div>
            </div>

            {/* Miller Columns Container */}
            <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4 min-h-0 overflow-hidden">

                {/* ================= COLUMN 1: WORK GROUPS ================= */}
                <div className="flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-full">
                    <div className="p-3 bg-orange-50 border-b border-orange-100 flex justify-between items-center sticky top-0 z-10">
                        <h3 className="font-bold text-orange-800 flex items-center text-sm">
                            <Briefcase size={16} className="mr-2"/> 1. กลุ่มงาน
                        </h3>
                        <span className="text-xs bg-white text-orange-600 px-2 py-0.5 rounded-full border border-orange-200 font-bold">{settings.workGroups.length}</span>
                    </div>

                    <div className="p-3 border-b border-slate-100 bg-white">
                        <div className="flex relative">
                            <input 
                                className="flex-1 bg-slate-50 border border-slate-200 rounded-l-lg pl-3 pr-2 py-2 text-sm outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all" 
                                placeholder="เพิ่มกลุ่มงานใหม่..." 
                                value={newWgName} 
                                onChange={e => setNewWgName(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && requestAddWg()}
                            />
                            <button onClick={requestAddWg} disabled={!newWgName.trim()} className="bg-orange-500 hover:bg-orange-600 text-white px-3 rounded-r-lg disabled:opacity-50 transition-colors">
                                <Plus size={18}/>
                            </button>
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto p-2 space-y-1">
                        {settings.workGroups.map(g => (
                            <div key={g.id} 
                                onClick={() => { if(editingId !== g.id) setSelectedWgId(g.id); }}
                                className={`group flex items-center p-2.5 rounded-lg cursor-pointer border transition-all duration-200
                                    ${selectedWgId === g.id 
                                        ? 'bg-orange-50 border-orange-300 shadow-sm ring-1 ring-orange-200' 
                                        : !g.isActive 
                                            ? 'bg-red-50 border-red-100' 
                                            : 'bg-white border-transparent hover:bg-slate-50 hover:border-slate-200'}
                                `}
                            >
                                {editingId === g.id ? (
                                    <div className="flex-1 flex items-center space-x-1" onClick={e => e.stopPropagation()}>
                                        <input autoFocus className="flex-1 border rounded px-2 py-1 text-sm w-full" value={editValue} onChange={e => setEditValue(e.target.value)} />
                                        <button onClick={() => requestUpdateWg(g.id)} className="p-1 bg-green-100 text-green-700 rounded"><Check size={14}/></button>
                                        <button onClick={() => setEditingId(null)} className="p-1 bg-slate-100 text-slate-500 rounded"><X size={14}/></button>
                                    </div>
                                ) : (
                                    <>
                                        <div className="flex-1 min-w-0">
                                            <div className={`text-sm font-medium truncate ${selectedWgId === g.id ? 'text-orange-900' : !g.isActive ? 'text-red-700' : 'text-slate-700'}`}>{g.name}</div>
                                        </div>
                                        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={(e) => { e.stopPropagation(); setEditingId(g.id); setEditValue(g.name); }} className="p-1.5 hover:bg-white rounded text-slate-400 hover:text-orange-600"><Edit2 size={12}/></button>
                                            <button onClick={(e) => { e.stopPropagation(); requestToggleActive('WG', g); }} className={`p-1.5 hover:bg-white rounded ${g.isActive ? 'text-slate-400 hover:text-red-500' : 'text-red-500 hover:text-green-600'}`}>
                                                <Power size={12}/>
                                            </button>
                                        </div>
                                        <ChevronRight size={16} className={`ml-1 transition-transform ${selectedWgId === g.id ? 'text-orange-500 translate-x-0' : 'text-transparent -translate-x-2'}`}/>
                                    </>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                {/* ================= COLUMN 2: DEPARTMENTS ================= */}
                <div className={`flex flex-col bg-white rounded-xl shadow-sm border overflow-hidden h-full transition-colors ${selectedWgId ? 'border-indigo-200' : 'border-slate-200 opacity-60'}`}>
                    <div className={`p-3 border-b flex justify-between items-center sticky top-0 z-10 ${selectedWgId ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-100 border-slate-200'}`}>
                        <h3 className={`font-bold flex items-center text-sm ${selectedWgId ? 'text-indigo-800' : 'text-slate-500'}`}>
                            <Building size={16} className="mr-2"/> 2. ฝ่าย/งาน
                        </h3>
