                    </div>

                    <div className="flex-1 overflow-y-auto p-2 space-y-1">
                        {visibleDepartments.length === 0 && selectedWgId && (
                            <div className="text-center py-8 text-slate-400 text-xs">ยังไม่มีฝ่ายในกลุ่มงานนี้</div>
                        )}
                        {visibleDepartments.map(dept => (
                            <div key={dept.id} 
                                onClick={() => { if(editingId !== dept.id) setSelectedDeptId(dept.id); }}
                                className={`group p-2.5 rounded-lg cursor-pointer border transition-all duration-200
                                    ${selectedDeptId === dept.id 
                                        ? 'bg-indigo-50 border-indigo-300 shadow-sm ring-1 ring-indigo-200' 
                                        : !dept.isActive 
                                            ? 'bg-red-50 border-red-100' 
