// --- Helpers ---
const getRandomInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

const getRandomDateInFiscalYear = (year) => {
    // FY68 = Oct 2024 - Sep 2025
    // FY69 = Oct 2025 - Sep 2026
    // Logic: FY Year in AD - 1 (Start Oct) to FY Year in AD (End Sep)

    // Convert Thai FY to AD Year of end date (e.g. 68 -> 2568 -> 2025)
    const adYear = year - 543;

    const start = new Date(`${adYear - 1}-10-01`);
    const end = new Date(`${adYear}-09-30`);

    const timeDiff = end.getTime() - start.getTime();
    const randomTime = Math.random() * timeDiff;
    const d = new Date(start.getTime() + randomTime);
    return d.toISOString().split('T')[0]; // YYYY-MM-DD
};

// Helper to split array into chunks for batch insert (MySQL has packet size limits)
const chunkArray = (myArray, chunk_size) => {
    let index = 0;
    const arrayLength = myArray.length;
    const tempArray = [];

    for (index = 0; index < arrayLength; index += chunk_size) {
        let myChunk = myArray.slice(index, index + chunk_size);
        tempArray.push(myChunk);
    }
    return tempArray;
};

