import React, { createContext, useContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, Department, WorkGroup, ProcurementCategory } from '../types';

// ==========================================
// 🛠️ API CONFIGURATION
// ==========================================
const BACKEND_PORT = 3002;

const getApiUrl = () => {
    // 1. Server-side rendering case
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api/procurement`;

    // 2. Client-side browser case
    let hostname = window.location.hostname;
    if (!hostname || hostname.trim() === '') {
        hostname = 'localhost';
    }

    return `http://${hostname}:${BACKEND_PORT}/api/procurement`;
};

const API_URL = getApiUrl();
console.log(`%c🔌 Connecting to Backend via: ${API_URL}`, "color: magenta; font-weight: bold;");

interface AppContextType {
    isLoading: boolean;
    serverError: boolean;
    serverErrorMessage: string;
    retryConnection: () => void;

    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth
    currentUser: User | null;
    users: User[];
    login: (u: string, p: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: any, force?: boolean) => Promise<{ success: boolean, message?: string, isWarning?: boolean }>;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: any) => void;
    upsertReceiving: (requestId: string, number: string, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: any) => void;
    upsertConsideration: (requestId: string, number: string, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;

    // Management Actions
    addDepartment: (dept: Department) => void;
    updateDepartment: (id: string, data: Partial<Department>) => void;
    deleteDepartment: (id: string) => void; 
    addWorkGroup: (group: WorkGroup) => void;
    updateWorkGroup: (id: string, data: Partial<WorkGroup>) => void; 
    deleteWorkGroup: (id: string) => void; 

    addCategory: (category: ProcurementCategory) => void;
    updateCategory: (id: string, data: Partial<ProcurementCategory>) => void;
    deleteCategory: (id: string) => void; 

    checkChronologyIssue: (record: ProcurementRecord) => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);
    const [serverErrorMessage, setServerErrorMessage] = useState('');

    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [rawProcurements, setRawProcurements] = useState<ProcurementRecord[]>([]);
    const [rawReceivings, setRawReceivings] = useState<ReceivingReport[]>([]);
    const [rawConsiderations, setRawConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: [],
        workGroups: []
    });

    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            // Fetch Users
            const userRes = await fetch(`${API_URL}/users`);
            if (!userRes.ok) throw new Error(`User Fetch Failed: ${userRes.statusText}`);
            const userData = await userRes.json();
            setUsers(userData);

            // Fetch Business Data
            const dataRes = await fetch(`${API_URL}/data`);
            if (!dataRes.ok) throw new Error(`Data Fetch Failed: ${dataRes.statusText}`);
            const data = await dataRes.json();

            setRawProcurements(data.procurements);
            setRawReceivings(data.receivings);
            setRawConsiderations(data.considerations);
            setSettings(prev => ({
                ...prev,
                departments: data.settings.departments,
                categories: data.settings.categories,
                workGroups: data.settings.workGroups || []
            }));

        } catch (error: any) {
            console.error("Backend Error:", error);
            setServerError(true);
            setServerErrorMessage(error.message || "Failed to connect to Backend");
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const savedUser = sessionStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => fetchData();

    // Visibility Logic
    const visibleData = useMemo(() => {
        if (!currentUser) return { procurements: [], receivings: [], considerations: [] };
        if (currentUser.role === 'ADMIN') return { procurements: rawProcurements, receivings: rawReceivings, considerations: rawConsiderations };

        const userDept = settings.departments.find(d => d.id === currentUser.departmentId);
        const userWorkGroupId = userDept?.workGroupId;

        if (!userWorkGroupId) {
            const myProcs = rawProcurements.filter(p => p.createdBy === currentUser.id);
            return {
                procurements: myProcs,
                receivings: rawReceivings.filter(r => myProcs.some(p => p.requestId === r.requestId)),
                considerations: rawConsiderations.filter(c => myProcs.some(p => p.requestId === c.requestId))
            };
        }

        const allowedDeptIds = settings.departments.filter(d => d.workGroupId === userWorkGroupId).map(d => d.id);
        const allowedProcs = rawProcurements.filter(p => {
            if (p.departmentId && allowedDeptIds.includes(p.departmentId)) return true;
            const creator = users.find(u => u.id === p.createdBy);
            return creator?.departmentId && allowedDeptIds.includes(creator.departmentId);
        });
        const allowedRequestIds = new Set(allowedProcs.map(p => p.requestId));

        return {
            procurements: allowedProcs,
            receivings: rawReceivings.filter(r => allowedRequestIds.has(r.requestId)),
            considerations: rawConsiderations.filter(c => allowedRequestIds.has(c.requestId))
        };
    }, [currentUser, rawProcurements, rawReceivings, rawConsiderations, settings.departments, users]);

    // Auth Actions
    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: u, password: p }) });
            const result = await res.json();
            if (result.success) {
                setCurrentUser(result.user);
                sessionStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e) { return { success: false, message: "Server Error" }; }
    };
    const logout = () => { setCurrentUser(null); sessionStorage.removeItem('procurement_session_user'); };
    const registerUser = async (u: any) => {
        try {
            const newUser = { ...u, id: Math.random().toString(36).substr(2, 9) };
            await fetch(`${API_URL}/register`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newUser)});
            fetchData(); return true;
        } catch { return false; }
    };
    const updateUser = async (id: string, d: any) => {
        await fetch(`${API_URL}/users/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        setUsers(prev => prev.map(u => u.id === id ? { ...u, ...d } : u));
    };
    const deleteUser = (id: string) => updateUser(id, { status: 'SUSPENDED' });

    // Core Data Actions
    const addProcurement = async (d: any, force = false) => {
        const newRecord = { ...d, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now(), departmentId: currentUser?.departmentId, createdBy: currentUser?.id };
        try {
            await fetch(`${API_URL}/procurements`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newRecord)});
            setRawProcurements(prev => [...prev, newRecord]);
            return { success: true };
        } catch { return { success: false, message: "Error" }; }
    };
    const updateProcurement = async (id: string, d: any) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        setRawProcurements(prev => prev.map(p => p.id === id ? {...p, ...d} : p));
    };
    const deleteProcurement = async (id: string) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
        setRawProcurements(prev => prev.filter(p => p.id !== id));
    };

    // Receivings & Considerations
    const addReceiving = async (d: any) => {
        const n = { ...d, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() };
        await fetch(`${API_URL}/receivings`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(n)});
        setRawReceivings(prev => [...prev, n]);
    };
    const deleteReceiving = async (id: string) => {
        await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' });
        setRawReceivings(prev => prev.filter(r => r.id !== id));
    };
    const upsertReceiving = async (rid: string, no: string, date: string) => {
        const p = rawProcurements.find(x => x.requestId === rid);
        await fetch(`${API_URL}/receivings/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ requestId: rid, deliveryNoteNo: no, receiveDate: date, category: p?.category })});
        fetchData();
    };
    const addConsideration = async (d: any) => {
        const n = { ...d, id: d.id || Math.random().toString(36).substr(2, 9) };
        await fetch(`${API_URL}/considerations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(n)});
        setRawConsiderations(prev => [...prev, n]);
    };
    const upsertConsideration = async (rid: string, no: string, date: string) => {
        await fetch(`${API_URL}/considerations/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ requestId: rid, considerationNumber: no, considerationDate: date })});
        fetchData();
    };
    const getLinkedData = (rid: string) => ({
        receiving: rawReceivings.find(r => r.requestId === rid),
        consideration: rawConsiderations.find(c => c.requestId === rid)
    });

    // Settings Management
    const updateSettings = (s: any) => setSettings(prev => ({...prev, ...s}));

    const addDepartment = async (d: Department) => {
        await fetch(`${API_URL}/department`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        fetchData();
    };
    const updateDepartment = async (id: string, d: Partial<Department>) => {
        await fetch(`${API_URL}/department/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d)});
        fetchData();
    };
    const deleteDepartment = async (id: string) => {
        await updateDepartment(id, { isActive: false });
    };

    const addWorkGroup = async (g: WorkGroup) => {
        await fetch(`${API_URL}/workgroup`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(g)});
        fetchData();
    };
    const updateWorkGroup = async (id: string, data: Partial<WorkGroup>) => {
        await fetch(`${API_URL}/workgroup/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data)});
        fetchData();
    };
    const deleteWorkGroup = async (id: string) => {
        await updateWorkGroup(id, { isActive: false });
    };

    const addCategory = async (c: ProcurementCategory) => {
        await fetch(`${API_URL}/category`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(c)});
        fetchData();
    };

    const updateCategory = async (id: string, data: Partial<ProcurementCategory>) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data)});
        fetchData();
    };

    const deleteCategory = async (id: string) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'DELETE' });
        setSettings(prev => ({
            ...prev,
            categories: prev.categories.map(c => c.id === id ? { ...c, isActive: false } : c)
        }));
    };

    const checkChronologyIssue = () => false;

    return (
        <AppContext.Provider value={{
            isLoading, serverError, serverErrorMessage, retryConnection,
            procurements: visibleData.procurements, receivings: visibleData.receivings, considerations: visibleData.considerations,
            settings, currentUser, users,
            login, logout, registerUser, deleteUser, updateUser,
            addProcurement, updateProcurement, deleteProcurement,
            addReceiving, deleteReceiving, upsertReceiving,
            addConsideration, upsertConsideration,
            getLinkedData, updateSettings,
            addDepartment, updateDepartment, deleteDepartment,
            addWorkGroup, updateWorkGroup, deleteWorkGroup,
            addCategory, updateCategory, deleteCategory,
            checkChronologyIssue
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

