    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip as ReTooltip, ResponsiveContainer, 
    BarChart, Bar, Cell
} from 'recharts';
import { Wallet, TrendingUp, Clock, AlertCircle, Calendar, Filter, ArrowUpRight, Award, Package, FileText, ListOrdered } from 'lucide-react';

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return new Date().getFullYear() + 543;
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return new Date().getFullYear() + 543;
    return date.getMonth() >= 9 ? date.getFullYear() + 1 + 543 : date.getFullYear() + 543;
};

const formatCurrency = (amount: number | string) => {
    const num = Number(amount);
    if (isNaN(num)) return '0.00';
    return num.toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

const formatCompactNumber = (number: number) => {
    return Intl.NumberFormat('en-US', {
        notation: "compact",
        maximumFractionDigits: 1
    }).format(number);
};

const ExecutiveDashboard: React.FC = () => {
    const { procurements, receivings, settings, users } = useApp();

    const currentFiscalYear = useMemo(() => {
        const now = new Date();
        return now.getMonth() >= 9 ? now.getFullYear() + 1 + 543 : now.getFullYear() + 543;
    }, []);

    const availableYears = useMemo(() => {
        const years = new Set<number>(procurements.map(p => getFiscalYear(p.requestDate)));
        years.add(currentFiscalYear);
        return Array.from(years).sort((a, b) => b - a);
    }, [procurements, currentFiscalYear]);

    const [selectedYear, setSelectedYear] = useState<number>(currentFiscalYear);

    const yearData = useMemo(() => {
        return procurements.filter(p => getFiscalYear(p.requestDate) === selectedYear);
    }, [procurements, selectedYear]);

    // --- KPIs Calculation ---
    const totalBudget = yearData.reduce((acc, curr) => acc + Number(curr.amount), 0);
    const totalProjects = yearData.length;

    const pendingProjects = yearData.filter(p => {
        const hasRec = receivings.some(r => r.requestId === p.requestId);
        return !hasRec;
    });
    const pendingAmount = pendingProjects.reduce((acc, curr) => acc + Number(curr.amount), 0);
    const completionRate = totalProjects > 0 ? ((totalProjects - pendingProjects.length) / totalProjects) * 100 : 0;

    // --- Chart 1: Monthly Spending Trend ---
    const fiscalMonths = [
        { name: 'ต.ค.', monthIndex: 9 }, { name: 'พ.ย.', monthIndex: 10 }, { name: 'ธ.ค.', monthIndex: 11 },
        { name: 'ม.ค.', monthIndex: 0 }, { name: 'ก.พ.', monthIndex: 1 }, { name: 'มี.ค.', monthIndex: 2 },
        { name: 'เม.ย.', monthIndex: 3 }, { name: 'พ.ค.', monthIndex: 4 }, { name: 'มิ.ย.', monthIndex: 5 },
        { name: 'ก.ค.', monthIndex: 6 }, { name: 'ส.ค.', monthIndex: 7 }, { name: 'ก.ย.', monthIndex: 8 },
    ];

    const trendData = fiscalMonths.map(m => {
        const monthlyTotal = yearData
            .filter(p => new Date(p.requestDate).getMonth() === m.monthIndex)
            .reduce((acc, curr) => acc + Number(curr.amount), 0);
        return { name: m.name, amount: monthlyTotal };
    });

    // --- Chart 2: Top Spenders (Departments) ---
    const deptSpendMap = new Map<string, number>();
    yearData.forEach(p => {
        const deptName = settings.departments.find(d => d.id === p.departmentId)?.name || 'ไม่ระบุฝ่าย';
        const current = deptSpendMap.get(deptName) || 0;
        deptSpendMap.set(deptName, current + Number(p.amount));
    });

    const topDepts = Array.from(deptSpendMap.entries())
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 5);

    // --- High Value Items (Table) ---
    const highValueItems = [...yearData]
        .sort((a, b) => Number(b.amount) - Number(a.amount))
