    // --- NEW: Department Running Number Status ---
    const deptRunningStats = useMemo(() => {
        return settings.departments.map(dept => {
            // Filter items for this department in selected year
            const items = yearData.filter(p => {
                 if (p.departmentId === dept.id) return true;
                 const creator = users.find(u => u.id === p.createdBy);
                 return creator?.departmentId === dept.id;
            }).filter(p => p.officialNumber); // Must have a number

            // Find Max Number logic
            let maxNum = 0;
            let latestStr = '-';

            items.forEach(p => {
                if(!p.officialNumber) return;
                const parts = p.officialNumber.split('/');
                // Regex to find digits at end of first part (e.g., "พด. 123" -> 123)
                const numPart = parts[0]?.match(/(\d+)$/); 
                if(numPart) {
                    const val = parseInt(numPart[1]);
                    if(val > maxNum) {
                        maxNum = val;
                        latestStr = p.officialNumber;
                    }
                }
            });

            return {
                id: dept.id,
                name: dept.name,
                prefix: dept.prefix,
                count: items.length,
                latestNumber: latestStr
            };
        }).sort((a, b) => b.count - a.count); // Sort by most active
