                                                {dept.count}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right font-bold text-slate-700 font-mono">
                                            {dept.latestNumber !== '-' ? dept.latestNumber : <span className="text-slate-300">-</span>}
