                    </div>
                    <div className="overflow-x-auto flex-1">
                        <table className="w-full text-sm text-left text-slate-600">
                            <thead className="text-xs text-slate-500 uppercase bg-slate-50 font-semibold">
                                <tr>
                                    <th className="px-4 py-4">วันที่</th>
                                    <th className="px-4 py-4">รายการ</th>
                                    <th className="px-4 py-4 text-right">จำนวนเงิน</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {highValueItems.map((item) => (
                                    <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="px-4 py-4 whitespace-nowrap text-xs text-slate-500">{new Date(item.requestDate).toLocaleDateString('th-TH')}</td>
                                        <td className="px-4 py-4">
                                            <div className="font-medium text-slate-900 truncate max-w-[150px]">{item.company}</div>
                                            <div className="text-[10px] text-slate-400">{item.requestId}</div>
                                        </td>
                                        <td className="px-4 py-4 text-right font-bold text-slate-800">
                                            {formatCurrency(item.amount)}
                                        </td>
                                    </tr>
                                ))}
                                {highValueItems.length === 0 && (
                                    <tr>
                                        <td colSpan={3} className="text-center py-8 text-slate-400">ไม่มีข้อมูลในปีงบประมาณนี้</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ExecutiveDashboard;

import React, { useState, useMemo } from 'react';
import { useApp } from '../services/store';
import { RecordType } from '../types';
import { 
    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip as ReTooltip, ResponsiveContainer, 
    BarChart, Bar, Cell
} from 'recharts';
import { Wallet, TrendingUp, Clock, AlertCircle, Calendar, Filter, ArrowUpRight, Award, Package, FileText, ListOrdered, Briefcase, Layers, ChevronDown, ChevronUp } from 'lucide-react';

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return new Date().getFullYear() + 543;
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return new Date().getFullYear() + 543;
    return date.getMonth() >= 9 ? date.getFullYear() + 1 + 543 : date.getFullYear() + 543;
};

const formatCurrency = (amount: number | string) => {
    const num = Number(amount);
    if (isNaN(num)) return '0.00';
    return num.toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

const formatCompactNumber = (number: number) => {
    return Intl.NumberFormat('en-US', {
        notation: "compact",
        maximumFractionDigits: 1
    }).format(number);
};

const ExecutiveDashboard: React.FC = () => {
    const { procurements, receivings, settings, users } = useApp();

    const currentFiscalYear = useMemo(() => {
        const now = new Date();
        return now.getMonth() >= 9 ? now.getFullYear() + 1 + 543 : now.getFullYear() + 543;
    }, []);

    const availableYears = useMemo(() => {
        const years = new Set<number>(procurements.map(p => getFiscalYear(p.requestDate)));
        years.add(currentFiscalYear);
        return Array.from(years).sort((a, b) => b - a);
    }, [procurements, currentFiscalYear]);

    const [selectedYear, setSelectedYear] = useState<number>(currentFiscalYear);

    // 1. Filter Data by Year
    const yearData = useMemo(() => {
        return procurements.filter(p => getFiscalYear(p.requestDate) === selectedYear);
    }, [procurements, selectedYear]);

    // 2. Optimize Receivings Lookup (O(N) -> O(1))
    const receivedRequestIds = useMemo(() => {
        return new Set(receivings.map(r => r.requestId));
    }, [receivings]);

    // 3. Separate Pending/Completed efficiently
    const { pendingProjects, completedProjects } = useMemo(() => {
        const pending = [];
        const completed = [];
        for (const p of yearData) {
            if (receivedRequestIds.has(p.requestId)) {
                completed.push(p);
            } else {
                pending.push(p);
            }
        }
        return { pendingProjects: pending, completedProjects: completed };
    }, [yearData, receivedRequestIds]);

    // --- KPIs Calculation ---
    const totalBudget = useMemo(() => yearData.reduce((acc, curr) => acc + Number(curr.amount), 0), [yearData]);
    const totalProjects = yearData.length;
    const pendingAmount = useMemo(() => pendingProjects.reduce((acc, curr) => acc + Number(curr.amount), 0), [pendingProjects]);
    const completedAmount = useMemo(() => completedProjects.reduce((acc, curr) => acc + Number(curr.amount), 0), [completedProjects]);

    const completionRate = totalProjects > 0 ? ((completedProjects.length) / totalProjects) * 100 : 0;
    const pendingRate = totalProjects > 0 ? (pendingProjects.length / totalProjects) * 100 : 0;

    // --- Chart 1: Monthly Spending Trend ---
    const trendData = useMemo(() => {
        const fiscalMonths = [
            { name: 'ต.ค.', monthIndex: 9 }, { name: 'พ.ย.', monthIndex: 10 }, { name: 'ธ.ค.', monthIndex: 11 },
            { name: 'ม.ค.', monthIndex: 0 }, { name: 'ก.พ.', monthIndex: 1 }, { name: 'มี.ค.', monthIndex: 2 },
            { name: 'เม.ย.', monthIndex: 3 }, { name: 'พ.ค.', monthIndex: 4 }, { name: 'มิ.ย.', monthIndex: 5 },
            { name: 'ก.ค.', monthIndex: 6 }, { name: 'ส.ค.', monthIndex: 7 }, { name: 'ก.ย.', monthIndex: 8 },
        ];

        return fiscalMonths.map(m => {
            const monthlyTotal = yearData
                .filter(p => new Date(p.requestDate).getMonth() === m.monthIndex)
                .reduce((acc, curr) => acc + Number(curr.amount), 0);
            return { name: m.name, amount: monthlyTotal };
        });
    }, [yearData]);

    // --- Chart 2: Top Spenders (Departments) ---
    const topDepts = useMemo(() => {
        const deptSpendMap = new Map<string, number>();
        const deptNameMap = new Map<string, string>();
        settings.departments.forEach(d => deptNameMap.set(d.id, d.name));

        yearData.forEach(p => {
            const deptName = deptNameMap.get(p.departmentId || '') || 'ไม่ระบุฝ่าย';
            const current = deptSpendMap.get(deptName) || 0;
            deptSpendMap.set(deptName, current + Number(p.amount));
        });

        return Array.from(deptSpendMap.entries())
            .map(([name, value]) => ({ name, value }))
            .sort((a, b) => b.value - a.value)
            .slice(0, 5);
    }, [yearData, settings.departments]);

    // --- Chart 3 (REFINED): Work Group Breakdown List ---
    const { workGroupStats, maxWgTotal } = useMemo(() => {
        // Prepare Maps
        const deptToWgMap = new Map<string, string>();
        settings.departments.forEach(d => {
            if (d.workGroupId) deptToWgMap.set(d.id, d.workGroupId);
        });

        const wgNameMap = new Map<string, string>();
        settings.workGroups.forEach(g => wgNameMap.set(g.id, g.name));

        // Data Structure
        const stats = new Map<string, { id: string, name: string, purchase: number, hiring: number, other: number, total: number }>();

        // Init
        settings.workGroups.filter(g => g.isActive).forEach(g => {
            stats.set(g.id, { id: g.id, name: g.name, purchase: 0, hiring: 0, other: 0, total: 0 });
        });

        const unknownKey = 'unknown';
        if (!stats.has(unknownKey)) {
            stats.set(unknownKey, { id: unknownKey, name: 'ไม่ระบุกลุ่มงาน', purchase: 0, hiring: 0, other: 0, total: 0 });
        }

        yearData.forEach(p => {
            const deptId = p.departmentId;
            let wgId = unknownKey;

            if (deptId && deptToWgMap.has(deptId)) {
                wgId = deptToWgMap.get(deptId)!;
            }

            if (!stats.has(wgId)) {
                const name = wgNameMap.get(wgId) || 'ไม่ระบุกลุ่มงาน';
                stats.set(wgId, { id: wgId, name, purchase: 0, hiring: 0, other: 0, total: 0 });
            }

            const entry = stats.get(wgId)!;
            const amount = Number(p.amount);

            if (p.type === RecordType.PURCHASE) entry.purchase += amount;
            else if (p.type === RecordType.HIRING) entry.hiring += amount;
            else entry.other += amount;

            entry.total += amount;
        });

        const list = Array.from(stats.values())
            .filter(item => item.total > 0)
            .sort((a, b) => b.total - a.total);

        const max = list.length > 0 ? list[0].total : 0;

        return { workGroupStats: list, maxWgTotal: max };

    }, [yearData, settings.departments, settings.workGroups]);

    // --- High Value Items (Table) ---
    const highValueItems = useMemo(() => {
        return [...yearData]
            .sort((a, b) => Number(b.amount) - Number(a.amount))
            .slice(0, 5);
    }, [yearData]);

    // --- Department Running Number Status ---
    const deptRunningStats = useMemo(() => {
        const userDeptMap = new Map<string, string>();
        users.forEach(u => {
            if (u.departmentId) userDeptMap.set(u.id, u.departmentId);
        });

        const statsMap = new Map<string, { count: number, maxNum: number, latestStr: string }>();

        yearData.forEach(p => {
            if (!p.officialNumber) return;
            let deptId = p.departmentId;
            if (!deptId) deptId = userDeptMap.get(p.createdBy);
            if (!deptId) return;

            if (!statsMap.has(deptId)) {
                statsMap.set(deptId, { count: 0, maxNum: 0, latestStr: '-' });
            }
            const stat = statsMap.get(deptId)!;
            stat.count++;
            const parts = p.officialNumber.split('/');
            const numPart = parts[0]?.match(/(\d+)$/); 
            if(numPart) {
                const val = parseInt(numPart[1]);
                if(val > stat.maxNum) {
                    stat.maxNum = val;
                    stat.latestStr = p.officialNumber;
                }
            }
        });

        const results = settings.departments.map(dept => {
            const stat = statsMap.get(dept.id);
            return {
                id: dept.id,
                name: dept.name,
                prefix: dept.prefix,
                count: stat ? stat.count : 0,
                latestNumber: stat ? stat.latestStr : '-'
            };
        });
        return results.sort((a, b) => b.count - a.count);
    }, [settings.departments, yearData, users]);

    const COLORS = ['#3b82f6', '#8b5cf6', '#f59e0b', '#10b981', '#ef4444'];

    return (
        <div className="p-6 sm:p-8 space-y-8 animate-fade-in pb-20 bg-slate-50/50">
            {/* Header Area */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4 border-b border-slate-200 pb-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 tracking-tight">Executive Dashboard</h2>
                    <p className="text-slate-500 mt-1">ภาพรวมการบริหารงานพัสดุและงบประมาณ (มุมมองผู้บริหาร)</p>
                </div>

                <div className="flex items-center bg-white rounded-xl shadow-sm border border-slate-200 p-1">
                    <div className="px-3 py-2 flex items-center space-x-2 border-r border-slate-100">
                        <Filter size={16} className="text-slate-400" />
                        <span className="text-xs font-semibold text-slate-500 uppercase">Fiscal Year</span>
                    </div>
                    <select 
                        value={selectedYear} 
                        onChange={(e) => setSelectedYear(Number(e.target.value))}
                        className="px-3 py-2 text-sm font-bold text-blue-700 bg-transparent outline-none cursor-pointer hover:bg-slate-50 rounded-lg transition-colors"
                    >
                        {availableYears.map(y => (
                            <option key={y} value={y}>พ.ศ. {y}</option>
                        ))}
                    </select>
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl p-6 text-white shadow-lg shadow-blue-200 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-4 opacity-10 transform rotate-12 group-hover:scale-110 transition-transform duration-500">
                        <Wallet size={80} />
                    </div>
                    <p className="text-blue-100 text-sm font-medium mb-1 flex items-center"><TrendingUp size={14} className="mr-1"/> ยอดงบประมาณรวม</p>
                    <h3 className="text-3xl font-bold tracking-tight">{formatCompactNumber(totalBudget)} <span className="text-lg font-normal opacity-70">บาท</span></h3>
                    <p className="text-xs text-blue-200 mt-4 opacity-80">
                        คิดเป็นจริง: {formatCurrency(totalBudget)}
                    </p>
                </div>

                <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative overflow-hidden hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-slate-500 text-sm font-medium mb-1">จำนวนรายการจัดซื้อ/จ้าง</p>
                            <h3 className="text-3xl font-bold text-slate-800">{totalProjects} <span className="text-sm font-normal text-slate-400">รายการ</span></h3>
                        </div>
                        <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl">
                            <Package size={24} />
                        </div>
                    </div>
                    <div className="mt-4 flex flex-col gap-1">
                        <div className="flex items-center text-xs font-medium text-emerald-600 bg-emerald-50 w-fit px-2 py-1 rounded-lg">
                            <Award size={12} className="mr-1" />
                            Completed: {completionRate.toFixed(1)}%
                        </div>
                        <div className="text-xs text-slate-500">
                            มูลค่าที่เสร็จสิ้น: <span className="font-semibold text-slate-700">{formatCompactNumber(completedAmount)}</span>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative overflow-hidden hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-slate-500 text-sm font-medium mb-1">รอตรวจรับ (Pending)</p>
                            <h3 className="text-3xl font-bold text-orange-600">{pendingProjects.length} <span className="text-sm font-normal text-slate-400">รายการ</span></h3>
                        </div>
                        <div className="p-3 bg-orange-50 text-orange-600 rounded-xl">
                            <Clock size={24} />
                        </div>
                    </div>
                    <div className="mt-4 flex flex-col gap-1">
                        <div className="flex items-center text-xs font-medium text-orange-600 bg-orange-50 w-fit px-2 py-1 rounded-lg">
                            <Clock size={12} className="mr-1" />
                            Pending: {pendingRate.toFixed(1)}%
                        </div>
                        <div className="text-xs text-slate-500">
                            มูลค่ารอเบิกจ่าย: <span className="font-semibold text-slate-700">{formatCompactNumber(pendingAmount)}</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* --- WORK GROUP ANALYSIS (Refined View) --- */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4 border-b border-slate-50 pb-4">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center">
                        <Briefcase size={20} className="mr-2 text-indigo-600" />
                        งบประมาณแยกตามกลุ่มงานและประเภท
                    </h3>
                    <div className="flex space-x-4 text-xs font-medium bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100">
                        <div className="flex items-center text-slate-600"><span className="w-2.5 h-2.5 bg-blue-500 rounded-full mr-2"></span> จัดซื้อ (PO)</div>
                        <div className="flex items-center text-slate-600"><span className="w-2.5 h-2.5 bg-purple-500 rounded-full mr-2"></span> จัดจ้าง (HO)</div>
                        <div className="flex items-center text-slate-600"><span className="w-2.5 h-2.5 bg-orange-500 rounded-full mr-2"></span> อื่นๆ</div>
                    </div>
                </div>

                <div className="space-y-5">
                    {workGroupStats.length > 0 ? workGroupStats.map((wg, index) => {
                        // Calculate Percentages
                        const totalPercent = maxWgTotal > 0 ? (wg.total / maxWgTotal) * 100 : 0;
                        const poPercent = wg.total > 0 ? (wg.purchase / wg.total) * 100 : 0;
                        const hoPercent = wg.total > 0 ? (wg.hiring / wg.total) * 100 : 0;
                        const otherPercent = wg.total > 0 ? (wg.other / wg.total) * 100 : 0;

                        return (
                            <div key={wg.id} className="group">
                                {/* Header Row: Name & Total */}
                                <div className="flex justify-between items-end mb-2">
                                    <div className="flex items-center">
                                        <span className={`flex items-center justify-center w-5 h-5 rounded-full text-[10px] font-bold mr-3 ${index < 3 ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-500'}`}>
                                            {index + 1}
                                        </span>
                                        <span className="text-sm font-semibold text-slate-800">{wg.name}</span>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-sm font-bold text-slate-900">{formatCurrency(wg.total)}</span>
                                        <span className="text-[10px] text-slate-400 ml-1">บาท</span>
                                    </div>
                                </div>

                                {/* Stacked Progress Bar */}
                                <div className="relative w-full h-3 bg-slate-100 rounded-full overflow-hidden flex">
                                    {/* Main Container width relative to Max Total */}
                                    <div className="h-full flex rounded-full overflow-hidden transition-all duration-500 ease-out" style={{ width: `${Math.max(totalPercent, 1)}%` }}>
                                        {poPercent > 0 && <div className="h-full bg-blue-500 hover:bg-blue-400 transition-colors" style={{ width: `${poPercent}%` }} title={`จัดซื้อ: ${formatCurrency(wg.purchase)}`}></div>}
                                        {hoPercent > 0 && <div className="h-full bg-purple-500 hover:bg-purple-400 transition-colors" style={{ width: `${hoPercent}%` }} title={`จัดจ้าง: ${formatCurrency(wg.hiring)}`}></div>}
                                        {otherPercent > 0 && <div className="h-full bg-orange-500 hover:bg-orange-400 transition-colors" style={{ width: `${otherPercent}%` }} title={`อื่นๆ: ${formatCurrency(wg.other)}`}></div>}
                                    </div>
                                </div>

