// Helper function for queries with EXTREME UTF8MB4 ENFORCEMENT
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }

        // 🔥 ULTIMATE FIX: Run commands to force every aspect of the connection to UTF-8
        const setCharsetSql = "SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';";

        connection.query(setCharsetSql, (err) => {
            if (err) {
                connection.release();
                console.error("Charset Setup Error:", err);
                return reject(err);
            }

            // Execute the actual query
            connection.query(sql, params, (err, res) => {
                connection.release(); // Always release connection back to pool
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

