// Helper: Get Fiscal Year
const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    const year = date.getFullYear();
    return month >= 9 ? year + 1 + 543 : year + 543;
};

// Procurements (Updated with Server-Side Running Number)
router.post('/procurements', async (req, res) => {
    const p = req.body;
    let newOfficialNumber = p.officialNumber; // Use provided if exists (e.g. from force/migration)

    try {
        // --- Server-Side Running Number Logic ---
        // Only generate if amount > 5000 AND no officialNumber is provided
        if (!newOfficialNumber && p.amount > 5000) {
            const fiscalYear = getFiscalYear(p.requestDate);

            // 1. Get Prefix
            let prefix = '';
            if (p.departmentId) {
                const deptRes = await query('SELECT prefix FROM departments WHERE id = ?', [p.departmentId]);
                if (deptRes.length > 0 && deptRes[0].prefix) {
                    prefix = deptRes[0].prefix.trim();
                }
            }

            // 2. Find Max Number for this Dept & Year
            // We search for numbers ending in "/YYYY" for this department
            const searchPattern = `%/${fiscalYear}`;
            let sql = 'SELECT official_number FROM procurements WHERE official_number LIKE ? AND type = ?';
            const params = [searchPattern, p.type];

            if (p.departmentId) {
                sql += ' AND department_id = ?';
                params.push(p.departmentId);
            }

            const rows = await query(sql, params);

            let maxNum = 0;
            rows.forEach(row => {
                if (row.official_number) {
                    // Split "Prefix 123/2567" -> ["Prefix 123", "2567"]
                    const parts = row.official_number.split('/');
                    const leftSide = parts[0]; 
                    // Extract number from the end of the left side string
                    const match = leftSide.match(/(\d+)$/);
                    if (match) {
                        const num = parseInt(match[1], 10);
                        if (num > maxNum) maxNum = num;
                    }
                }
            });

            // 3. Generate New Number
            const nextNum = maxNum + 1;
            newOfficialNumber = `${prefix ? prefix + ' ' : ''}${nextNum}/${fiscalYear}`;
        }
        // ----------------------------------------

        await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
            [p.id, p.requestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, newOfficialNumber, p.type, p.departmentId, p.createdBy, p.createdAt]);

        // Return the generated number to frontend
        res.json({ success: true, officialNumber: newOfficialNumber });

    } catch (e) {
        console.error("Add Procurement Error:", e);
        res.status(500).json({ success: false, message: e.message });
    }
});

router.patch('/procurements/:id', async (req, res) => {
