// Helper function for queries
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }
        const setCharsetSql = "SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';";
        connection.query(setCharsetSql, (err) => {
            if (err) {
                connection.release();
                return reject(err);
            }
            connection.query(sql, params, (err, res) => {
                connection.release();
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

// Helper: Get Fiscal Year
const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    const year = date.getFullYear();
    return month >= 9 ? year + 1 + 543 : year + 543;
};

// Helper: Generate Running ID
// Mode: 'REQUEST' (uses request_prefix), 'STANDARD' (uses normal prefix)
const generateRunningId = async (deptId, dateStr, table, column, mode = 'STANDARD') => {
    const fiscalYear = getFiscalYear(dateStr);

    // 1. Get Prefix Info
    let prefix = '';
    if (deptId) {
        const deptRes = await query('SELECT prefix, request_prefix FROM departments WHERE id = ?', [deptId]);
        if (deptRes.length > 0) {
            if (mode === 'REQUEST') {
                prefix = deptRes[0].request_prefix ? deptRes[0].request_prefix.trim() : '';
            } else {
                prefix = deptRes[0].prefix ? deptRes[0].prefix.trim() : '';
            }
        }
    }

    // 2. Search for Max Number
    // Pattern: "%/YYYY" (Fiscal Year)
    const searchPattern = `%/${fiscalYear}`;

    // If table has department_id, use it filter (for procurements). 
    // For others (linked tables), usually we run sequence globally or implicitly by dept. 
    // Here we will do a broader search based on pattern to be safe, filtering by matching prefix style.

    let sql = `SELECT ${column} FROM ${table} WHERE ${column} LIKE ?`;
    const params = [searchPattern];

    // Note: For linked tables like considerations, we don't strictly filter by department ID in the query 
    // because they link via request_id. But to keep running numbers consistent per department prefix, 
    // checking "LIKE prefix%" is sufficient.

    const rows = await query(sql, params);

    let maxNum = 0;
    rows.forEach(row => {
        const val = row[column];
        if (val && val.startsWith(prefix)) {
            // Split by '/' to get the number part before the year
            // Ex: "สพ.๐๐๓๓/105/2567" or "กง. 55/2567"
            const parts = val.split('/');
            if (parts.length > 1) {
                // The number is usually the last segment of the first part
                // e.g. "Prefix 123" -> 123
                const leftPart = parts[0]; 
                const match = leftPart.match(/(\d+)$/);
                if (match) {
                    const num = parseInt(match[1], 10);
                    if (num > maxNum) maxNum = num;
                }
            }
        }
    });

    const nextNum = maxNum + 1;
    // Format: "PrefixNumber/Year" or "Prefix Number/Year" depending on if prefix has space
    // Usually request_prefix includes spacing if needed.
    const separator = (prefix && !prefix.endsWith(' ') && !prefix.endsWith('/') && !prefix.endsWith('.')) ? ' ' : '';
    return `${prefix}${separator}${nextNum}/${fiscalYear}`;
};

