    try {
        // 1. Generate Request ID if null (Server-Side)
        if (!finalRequestId) {
            finalRequestId = await generateRunningId(p.departmentId, p.requestDate, 'procurements', 'request_id', 'REQUEST');
        }

        // 2. Generate Official Number if amount > 5000 and not provided
        if (!finalOfficialNumber && p.amount > 5000) {
            // Re-using logic, official number usually uses standard department prefix
            finalOfficialNumber = await generateRunningId(p.departmentId, p.requestDate, 'procurements', 'official_number', 'STANDARD');
        }

        await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
