                                        <input 
                                            type="text"
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 font-bold"
                                            value={formData.officialNumber}
                                            onChange={e => setFormData({...formData, officialNumber: e.target.value})}
                                            placeholder="ระบุเลขที่..."
                                        />
                                    </div>
                                )}

                                {/* Consideration Info */}
                                {type !== RecordType.PURCHASE && (
                                    <>
                                        <div className="col-span-1">
                                            <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.considerationNumber}</label>
                                            <input 
                                                type="text"
                                                className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900"
                                                value={formData.considerationNumber}
                                                onChange={e => setFormData({...formData, considerationNumber: e.target.value})}
                                                placeholder="เว้นว่างเพื่อให้ระบบรันให้อัตโนมัติ"
                                            />
                                        </div>
                                        <div className="col-span-1">
                                            <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.considerationDate}</label>
                                            <input 
                                                type="date"
                                                className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900"
                                                value={formData.considerationDate}
                                                onChange={e => setFormData({...formData, considerationDate: e.target.value})}
                                            />
                                        </div>
                                    </>
                                )}

                                <div className="col-span-1 sm:col-span-2">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                    <textarea rows={2} className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
                                </div>
                            </div>
                            <div className="flex flex-col sm:flex-row justify-end gap-3 mt-8 pt-4 border-t sticky bottom-0 bg-white">
                                <button type="button" onClick={closeModal} className="order-2 sm:order-1 px-6 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">ยกเลิก</button>
                                <button type="submit" className={`order-1 sm:order-2 px-8 py-2.5 ${theme.bgDeep} ${theme.bgHover} text-white rounded-lg shadow-md flex justify-center items-center`}><Check size={18} className="mr-2" /> บันทึกข้อมูล</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Confirmation Dialog before Save */}
            {showConfirm && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-blue-50 mb-6">
                            <AlertCircle className="h-8 w-8 text-blue-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการบันทึกข้อมูล?</h3>
                        <p className="text-sm text-slate-500 mb-8 leading-relaxed">กรุณาตรวจสอบความถูกต้องของข้อมูลอีกครั้ง<br/>คุณต้องการบันทึกรายการนี้ใช่หรือไม่?</p>
                        <div className="flex gap-4">
                            <button onClick={() => setShowConfirm(false)} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold transition-colors">กลับไปแก้ไข</button>
                            <button onClick={handleConfirmSave} className="flex-1 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-sm font-semibold shadow-lg transition-colors">ยืนยันบันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {deleteId && (
                <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/50 no-print">
                    <div className="bg-white rounded-xl p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4"><AlertTriangle className="text-red-600" /></div>
                        <h3 className="text-lg font-bold mb-2">ยืนยันการลบ?</h3>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setDeleteId(null)} className="flex-1 py-2 bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-sm">ลบออก</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { useState, useRef } from 'react';
import { useApp } from '../services/store';
import { RecordType, ProcurementRecord } from '../types';
import { Plus, Edit2, Trash2, X, Check, AlertCircle, Calendar, FileSpreadsheet, Printer, FileText, CalendarPlus, AlertTriangle, User as UserIcon } from 'lucide-react';

interface Props {
    type: RecordType;
    title: string;
}

const normalizeToNr = (str: string) => {
    if (!str) return '0';
    return str.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
};

const toThaiNr = (num: number) => {
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return num.toString().replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const month = date.getMonth(); 
    const year = date.getFullYear();
    const fiscalYear = month >= 9 ? year + 1 : year;
    return fiscalYear + 543;
};

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, considerations, receivings, addProcurement, updateProcurement, deleteProcurement, getLinkedData, upsertConsideration, upsertReceiving, settings, currentUser, users } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [deleteId, setDeleteId] = useState<string | null>(null);
    const [quickDateId, setQuickDateId] = useState<string | null>(null);
    const [quickDateValue, setQuickDateValue] = useState('');
    const [quickDateType, setQuickDateType] = useState<'CONSIDERATION' | 'RECEIVING' | null>(null);
    const [isAutoFilled, setIsAutoFilled] = useState(false);

    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: '',
        considerationNumber: '',
        considerationDate: '',
        officialNumber: '' // Added officialNumber to state for edit mode
    });

    const filteredData = procurements.filter(p => p.type === type);

    let fieldLabels = {
        requestId: "เลขกำหนดขอบเขตงาน",
        requestDate: "วันที่กำหนดขอบเขตงาน",
        considerationNumber: "เลขรายงานขอซื้อ",
        considerationDate: "วันที่รายงานขอซื้อ",
        receivingNumber: "เลขรายงานผลการพิจารณา",
        receivingDate: "วันที่รายงานผลการพิจารณา",
        officialNumber: "เลขสั่งซื้อ"
    };

    if (type === RecordType.HIRING) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขอจ้าง",
            considerationDate: "วันที่รายงานขอจ้าง",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขสั่งจ้าง"
        };
    } else if (type === RecordType.OTHER) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขออนุมัติ",
            considerationDate: "วันที่รายงานขออนุมัติ",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขที่คำสั่ง/สัญญา"
        };
    }

    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return { name: 'violet', bgSoft: 'bg-violet-50', bgDeep: 'bg-violet-600', bgHover: 'hover:bg-violet-700', text: 'text-violet-700', border: 'border-violet-200', ring: 'focus:ring-violet-500', inputBg: 'bg-violet-50/50' };
            case RecordType.OTHER:
                return { name: 'orange', bgSoft: 'bg-orange-50', bgDeep: 'bg-orange-600', bgHover: 'hover:bg-orange-700', text: 'text-orange-700', border: 'border-orange-200', ring: 'focus:ring-orange-500', inputBg: 'bg-orange-50/50' };
            default:
                return { name: 'blue', bgSoft: 'bg-blue-50', bgDeep: 'bg-blue-600', bgHover: 'hover:bg-blue-700', text: 'text-blue-700', border: 'border-blue-200', ring: 'focus:ring-blue-500', inputBg: 'bg-blue-50/50' };
        }
    })();

    const calculateNextRunNumber = () => {
        const prefix = settings.requestIdPrefix;
        if (!prefix) return '';
        const reqIds = procurements.map(p => p.requestId).filter(id => id && id.startsWith(prefix));
        const consIds = considerations.map(c => c.considerationNumber).filter(id => id && id.startsWith(prefix));
        const recvIds = receivings.map(r => r.deliveryNoteNo).filter(id => id && id.startsWith(prefix));
        const allIds = [...reqIds, ...consIds, ...recvIds];
        let maxNum = 0;
        allIds.forEach(id => {
            const suffix = id.substring(prefix.length);
            const normalizedSuffix = normalizeToNr(suffix);
            const num = parseInt(normalizedSuffix);
            if (!isNaN(num) && num > maxNum) maxNum = num;
        });
        return prefix + toThaiNr(maxNum + 1);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowConfirm(true);
    };

    const handleConfirmSave = async () => {
        if (editingId) {
            updateProcurement(editingId, { ...formData });
            if(formData.considerationNumber || formData.considerationDate) {
                 upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
            }
            setShowConfirm(false);
            closeModal();
        } else {
            // New logic: Await the result
            const result = await addProcurement({ ...formData, type: type });

            if (result.success) {
                // Success case
                if(formData.considerationNumber || formData.considerationDate) {
                     upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
                }
                setShowConfirm(false);
                closeModal();
            } else if (result.isWarning) {
                // Warning case (Backdating detected)
                setShowConfirm(false); // Close the initial confirm dialog

                // Show specific warning and ask for confirmation
                setTimeout(async () => {
                    const confirmForce = window.confirm(`⚠️ แจ้งเตือน: ${result.message}\n\nคุณต้องการยืนยันการบันทึกรายการนี้ (ย้อนหลัง) หรือไม่?`);

                    if (confirmForce) {
                        // Call again with force=true
                        const forceResult = await addProcurement({ ...formData, type: type }, true);
                        if (forceResult.success) {
                            if(formData.considerationNumber || formData.considerationDate) {
                                upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
                            }
                            closeModal();
                        } else {
                            alert(forceResult.message || 'บันทึกไม่สำเร็จ');
                        }
                    }
                }, 100);
            } else {
                // Error case
                setShowConfirm(false);
                alert(result.message || 'เกิดข้อผิดพลาดในการบันทึก');
            }
        }
    };

    const handleDeleteClick = (id: string) => {
        const record = procurements.find(p => p.id === id);
        if (record && record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์ลบรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        // const nextRequestId = calculateNextRunNumber() || settings.requestIdPrefix || ''; // Let server handle logic
        setFormData({ 
            requestId: '', // Empty to indicate auto-gen
            requestDate: '', 
            category: '', 
            itemCount: 0, 
            amount: 0, 
            company: '', 
            remarks: '', 
            considerationNumber: '', 
            considerationDate: '',
            officialNumber: ''
        });
        setIsAutoFilled(true);
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        if (record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์แก้ไขรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        const linked = getLinkedData(record.requestId);
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || '',
            officialNumber: record.officialNumber || ''
        });
        setIsAutoFilled(false);
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
        setIsAutoFilled(false);
    };

    const handleSaveQuickDate = () => {
        if (quickDateId && quickDateValue && quickDateType) {
            // Passing null as number to trigger auto-generation in store/backend
            if (quickDateType === 'CONSIDERATION') {
                upsertConsideration(quickDateId, null, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                upsertReceiving(quickDateId, null, quickDateValue);
            }
            setQuickDateId(null);
            setQuickDateValue('');
            setQuickDateType(null);
        }
    };

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'ไม่ระบุ';

    const handleExportCSV = () => {
        const headers = [fieldLabels.requestId, fieldLabels.requestDate, 'ปีงบประมาณ', fieldLabels.considerationNumber, fieldLabels.considerationDate, fieldLabels.officialNumber, fieldLabels.receivingNumber, fieldLabels.receivingDate, 'จำนวนเงิน', 'บริษัท', 'ผู้บันทึก', 'หมายเหตุ'];
        const rows = filteredData.map(item => {
            const linked = getLinkedData(item.requestId);
            return [item.requestId, item.requestDate, getFiscalYear(item.requestDate), linked.consideration?.considerationNumber || '-', linked.consideration?.considerationDate || '-', item.officialNumber || '-', linked.receiving?.deliveryNoteNo || '-', linked.receiving?.receiveDate || '-', item.amount, `"${item.company.replace(/"/g, '""')}"`, getUserName(item.createdBy), `"${item.remarks.replace(/"/g, '""')}"`].join(',');
        });
        const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `procurement_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <div className="p-4 sm:p-6">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 1cm; }
                    .lg\\:ml-64 { margin-left: 0 !important; }
                    .no-print { display: none !important; }
                    table { width: 100% !important; border-collapse: collapse; font-size: 10pt; }
                    th, td { border: 1px solid #cbd5e1 !important; padding: 4px 8px !important; }
                }
            `}</style>

            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                <h2 className="text-xl sm:text-2xl font-bold text-slate-800">{title}</h2>

                <div className="flex flex-wrap gap-2 no-print w-full sm:w-auto">
                    <button onClick={handleExportCSV} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <FileSpreadsheet size={16} />
                        <span>Excel</span>
                    </button>
                    <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <Printer size={16} />
                        <span>Print</span>
                    </button>
