                        <h3 className="text-lg font-bold mb-2">ยืนยันการลบ?</h3>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setDeleteId(null)} className="flex-1 py-2 bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-sm">ลบออก</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, Department, WorkGroup, ProcurementCategory } from '../types';

// ==========================================
// แก้ไข: ใช้ Port 3002 ให้ตรงกับ Backend
// ==========================================
const BACKEND_PORT = 3002; 

const getApiUrl = () => {
    // กรณีรันบน Server (SSR)
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api/procurement`;

    // กรณีรันบน Browser:
    let hostname = window.location.hostname;
    if (!hostname || hostname.trim() === '') {
        hostname = 'localhost';
    }
    // เพิ่ม /procurement ต่อท้ายเพื่อให้ตรงกับ server/index.js (app.use('/api/procurement', ...))
    return `http://${hostname}:${BACKEND_PORT}/api/procurement`;
};

const API_URL = getApiUrl();
console.log(`%c🔌 Connecting to Backend API at: ${API_URL}`, "color: green; font-weight: bold;");

interface AppContextType {
    isLoading: boolean;
    serverError: boolean;
    serverErrorMessage: string;
    retryConnection: () => void;

    // Data
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;

    // Auth & Users
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;

    // Actions
    addProcurement: (record: any, force?: boolean) => Promise<{ success: boolean, message?: string, isWarning?: boolean, requestId?: string, officialNumber?: string }>;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: any) => void;
    upsertReceiving: (requestId: string, number: string | null, date: string) => void;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: any) => void;
    upsertConsideration: (requestId: string, number: string | null, date: string) => void;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
    addDepartment: (dept: Department) => void;
    updateDepartment: (id: string, data: Partial<Department>) => void;

    // Additional Management
    addWorkGroup: (group: WorkGroup) => void;
    updateWorkGroup: (id: string, data: Partial<WorkGroup>) => void;
    addCategory: (category: ProcurementCategory) => void;
    updateCategory: (id: string, data: Partial<ProcurementCategory>) => void;
    deleteCategory: (id: string) => void;

    // Logic Validation
    checkChronologyIssue: (record: ProcurementRecord) => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);
    const [serverErrorMessage, setServerErrorMessage] = useState('');

    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);

    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: [],
        workGroups: []
    });

    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            // Fetch Users
            const userRes = await fetch(`${API_URL}/users`);
            if (!userRes.ok) {
                const errorData = await userRes.json().catch(() => ({ error: userRes.statusText }));
                throw new Error(errorData.error || `User Fetch Failed (${userRes.status})`);
            }
            const userData = await userRes.json();
            setUsers(userData);

            // Fetch Business Data
            const dataRes = await fetch(`${API_URL}/data`);
            if (!dataRes.ok) {
                const errorData = await dataRes.json().catch(() => ({ error: dataRes.statusText }));
                throw new Error(errorData.error || `Data Fetch Failed (${dataRes.status})`);
            }
            const data = await dataRes.json();

            setProcurements(data.procurements);
            setReceivings(data.receivings);
            setConsiderations(data.considerations);
            setSettings(prev => ({
                ...prev,
                departments: data.settings.departments,
                categories: data.settings.categories,
                workGroups: data.settings.workGroups || []
            }));

        } catch (error: any) {
            console.error("Backend Error:", error);
            setServerError(true);
            setServerErrorMessage(error.message || `Failed to connect to server at Port ${BACKEND_PORT}`);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const savedUser = localStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => { fetchData(); };

    // --- Auth Functions ---
    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: u, password: p })
            });

            const contentType = res.headers.get("content-type");
            if (!contentType || !contentType.includes("application/json")) {
                console.error("Server returned non-JSON. Check Port.");
                throw new Error(`Server connection failed (Port ${BACKEND_PORT}).`);
            }

            const result = await res.json();

            if (!res.ok) {
                throw new Error(result.message || result.error || 'Server Error');
            }

            if (result.success) {
                setCurrentUser(result.user);
                localStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e: any) {
            console.error("Login Error:", e);
            return { success: false, message: e.message || "เชื่อมต่อเซิร์ฟเวอร์ไม่ได้" };
        }
    };

    const logout = () => { setCurrentUser(null); localStorage.removeItem('procurement_session_user'); };

    const registerUser = async (userData: Omit<User, 'id' | 'createdAt'>) => {
        try {
            const newUser = { ...userData, id: Math.random().toString(36).substr(2, 9) };
            await fetch(`${API_URL}/register`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newUser) });
            fetchData(); return true;
        } catch (e) { return false; }
    };

    const deleteUser = async (id: string) => { updateUser(id, { status: 'SUSPENDED' }); };

    const updateUser = async (id: string, data: Partial<User>) => {
        try {
            await fetch(`${API_URL}/users/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            setUsers(prev => prev.map(u => u.id === id ? { ...u, ...data } : u));
        } catch(e) { console.error(e); }
    };

    // --- Business Logic ---
    const getThaiYear = (dateString: string) => new Date(dateString).getFullYear() + 543;

    const parseRunningNumber = (officialNumber: string | null) => {
        if (!officialNumber) return 0;
        const parts = officialNumber.split('/');
        const match = parts[0]?.match(/(\d+)$/);
        return match ? parseInt(match[1], 10) : 0;
    };

    const validateChronology = (type: RecordType, dateStr: string): { valid: boolean, message?: string } => {
        const thaiYear = getThaiYear(dateStr);
        const currentDeptId = currentUser?.departmentId;

        const existingInGroup = procurements.filter(p => {
            if (p.type !== type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;
            let recordDeptId = p.departmentId || users.find(u => u.id === p.createdBy)?.departmentId;
            return recordDeptId === currentDeptId;
        });

        if (existingInGroup.length === 0) return { valid: true };

        let maxNum = 0;
        let maxRecord: ProcurementRecord | null = null;

        existingInGroup.forEach(p => {
            const num = parseRunningNumber(p.officialNumber);
            if (num > maxNum) { maxNum = num; maxRecord = p; }
        });

        if (maxRecord) {
            const latestDate = new Date((maxRecord as ProcurementRecord).requestDate).getTime();
            const newDate = new Date(dateStr).getTime();
            if (newDate < latestDate) {
                return { 
                    valid: false, 
                    message: `⚠️ วันที่ย้อนหลังกว่าเลขที่ล่าสุด\nเลขที่ล่าสุด: ${(maxRecord as ProcurementRecord).officialNumber}\nลงวันที่: ${(maxRecord as ProcurementRecord).requestDate}\nคุณกำลังบันทึก: ${dateStr}` 
                };
            }
        }
        return { valid: true };
    };

    const checkChronologyIssue = (record: ProcurementRecord): boolean => {
        if (!record.officialNumber || !record.requestDate) return false;

        const currentNum = parseRunningNumber(record.officialNumber);
        const currentDate = new Date(record.requestDate).getTime();
        const thaiYear = getThaiYear(record.requestDate);

        let ownerDeptId = record.departmentId || users.find(u => u.id === record.createdBy)?.departmentId;

        return procurements.some(p => {
            if (p.type !== record.type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;

            let pDeptId = p.departmentId || users.find(u => u.id === p.createdBy)?.departmentId;
            if (pDeptId !== ownerDeptId) return false;

            const pNum = parseRunningNumber(p.officialNumber);
            const pDate = new Date(p.requestDate).getTime();

            return (pNum < currentNum && pDate > currentDate); 
        });
    };

    const addProcurement = async (data: any, force = false) => {
        // Validation for running number > 5000
        if (data.amount > 5000 && !force) {
            const validation = validateChronology(data.type, data.requestDate);
            if (!validation.valid) return { success: false, isWarning: true, message: validation.message };
        }

        // IMPORTANT: Send officialNumber AND requestId as null to let backend generate them
        const newRecord = { 
            ...data, 
            id: Math.random().toString(36).substr(2, 9), 
            createdAt: Date.now(), 
            departmentId: currentUser?.departmentId, 
            createdBy: currentUser?.id,
            officialNumber: null,
            requestId: null // Server-Side Generation
        };

        try {
            const res = await fetch(`${API_URL}/procurements`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newRecord) });
            if (!res.ok) throw new Error("Server Failed");

            const result = await res.json();
            if (result.success) {
                // Backend returns the generated numbers
                const recordWithNumber = { 
                    ...newRecord, 
                    officialNumber: result.officialNumber,
                    requestId: result.requestId 
                };
                setProcurements(prev => [...prev, recordWithNumber]);
                return { success: true, requestId: result.requestId, officialNumber: result.officialNumber };
            } else {
                return { success: false, message: result.message };
            }
        } catch(e: any) { return { success: false, message: "Server Error: " + e.message }; }
    };

    const updateProcurement = async (id: string, data: Partial<ProcurementRecord>) => {
        try {
            await fetch(`${API_URL}/procurements/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            setProcurements(prev => prev.map(p => p.id === id ? {...p, ...data} : p));
        } catch(e) { console.error(e); }
    };

    const deleteProcurement = async (id: string) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
        setProcurements(prev => prev.filter(p => p.id !== id));
    };

    const addReceiving = async (data: any) => {
        const newRecord = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() };
        await fetch(`${API_URL}/receivings`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newRecord) });
        setReceivings(prev => [...prev, newRecord]);
    };

    const deleteReceiving = async (id: string) => {
        await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' });
        setReceivings(prev => prev.filter(r => r.id !== id));
    };

    const addConsideration = async (record: any) => {
        const newRecord = { ...record, id: record.id || Math.random().toString(36).substr(2, 9) };
        await fetch(`${API_URL}/considerations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(newRecord) });
        setConsiderations(prev => [...prev, newRecord]);
    };

    const upsertReceiving = async (requestId: string, number: string | null, date: string) => {
        const procurement = procurements.find(p => p.requestId === requestId);
        const payload = { requestId, deliveryNoteNo: number, receiveDate: date, category: procurement?.category || '' };
        await fetch(`${API_URL}/receivings/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
        fetchData();
    };

    const upsertConsideration = async (requestId: string, number: string | null, date: string) => {
        const payload = { id: Math.random().toString(36).substr(2, 9), requestId, considerationNumber: number, considerationDate: date };
        await fetch(`${API_URL}/considerations/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
        fetchData();
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = async (s: Partial<AppSettings>) => { setSettings(prev => ({ ...prev, ...s })); };

    const addDepartment = async (dept: Department) => {
        try {
            await fetch(`${API_URL}/department`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dept) });
            setSettings(prev => ({ ...prev, departments: [...prev.departments, dept] }));
        } catch(e) { console.error(e); }
    };

    const updateDepartment = async (id: string, data: Partial<Department>) => {
        try {
            await fetch(`${API_URL}/department/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            setSettings(prev => ({
                ...prev,
                departments: prev.departments.map(d => d.id === id ? { ...d, ...data } : d)
            }));
        } catch(e) { console.error(e); }
    };

    const addWorkGroup = async (g: WorkGroup) => {
        await fetch(`${API_URL}/workgroup`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(g)});
        fetchData();
    };
    const updateWorkGroup = async (id: string, data: Partial<WorkGroup>) => {
        await fetch(`${API_URL}/workgroup/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data)});
        fetchData();
    };
    const addCategory = async (c: ProcurementCategory) => {
        await fetch(`${API_URL}/category`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(c)});
        fetchData();
    };
    const updateCategory = async (id: string, data: Partial<ProcurementCategory>) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data)});
        fetchData();
    };
    const deleteCategory = async (id: string) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'DELETE' });
        setSettings(prev => ({
            ...prev,
            categories: prev.categories.map(c => c.id === id ? { ...c, isActive: false } : c)
        }));
    };

    return (
        <AppContext.Provider value={{
            isLoading, serverError, serverErrorMessage, retryConnection,
            procurements, receivings, considerations, settings, currentUser, users,
            login, logout, registerUser, deleteUser, updateUser, addProcurement, updateProcurement, deleteProcurement,
            addReceiving, upsertReceiving, deleteReceiving, addConsideration, upsertConsideration, getLinkedData, updateSettings,
            addDepartment, updateDepartment, addWorkGroup, updateWorkGroup, addCategory, updateCategory, deleteCategory, checkChronologyIssue
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

