// Helper function for queries
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }
        const setCharsetSql = "SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';";
        connection.query(setCharsetSql, (err) => {
            if (err) {
                connection.release();
                return reject(err);
            }
            connection.query(sql, params, (err, res) => {
                connection.release();
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

// Helper: Get Fiscal Year
const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    const year = date.getFullYear();
    return month >= 9 ? year + 1 + 543 : year + 543;
};

// Helper: Parse Thai or Arabic Number
const parseAnyInt = (str) => {
    if (!str) return 0;
    // Normalize Thai digits to Arabic
    const normalized = str.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
    const match = normalized.match(/(\d+)$/); // Find number at the end
    return match ? parseInt(match[1], 10) : 0;
};

// Helper: Generate Running ID
// Mode: 'REQUEST' (uses request_prefix like สพ.../), 'STANDARD' (uses normal prefix like กง.)
// dateColName: The column name in the table to check fiscal year (e.g., 'request_date', 'receive_date')
const generateRunningId = async (deptId, dateStr, table, column, dateColName, mode = 'STANDARD') => {
    const fiscalYear = getFiscalYear(dateStr);

    // Calculate Fiscal Year Date Range (AD)
    const fiscalYearAD = fiscalYear - 543;
    const startDate = `${fiscalYearAD - 1}-10-01`;
    const endDate = `${fiscalYearAD}-09-30`;

    // 1. Get Prefix Info
    let prefix = '';
    if (deptId) {
        try {
            const deptRes = await query('SELECT prefix, request_prefix FROM departments WHERE id = ?', [deptId]);
            if (deptRes.length > 0) {
                if (mode === 'REQUEST') {
                    // ใช้ Prefix ยาว (เช่น สพ ๐๐๓๓.๐๖/๑/๒/)
                    prefix = deptRes[0].request_prefix ? deptRes[0].request_prefix.trim() : '';
                } else {
                    // ใช้ Prefix สั้น (เช่น พด.)
                    prefix = deptRes[0].prefix ? deptRes[0].prefix.trim() : '';
                }
            }
        } catch (e) {
            console.warn("Prefix fetch failed:", e.message);
        }
    }

    // 2. Search for Max Number within Fiscal Year and Matching Prefix
    // Filter by Date Range AND Prefix
    let sql = `SELECT ${column} FROM ${table} WHERE ${dateColName} >= ? AND ${dateColName} <= ? AND ${column} LIKE ?`;
    const params = [startDate, endDate, `${prefix}%`];

    let maxNum = 0;
    try {
        const rows = await query(sql, params);
        rows.forEach(row => {
            const val = row[column];
            if (val) {
                if (mode === 'REQUEST') {
                    // Logic for Request Mode: "Prefix" + "RunningNumber"
                    // Example: Val = "สพ ๐๐๓๓.๐๖/๑/๒/5", Prefix = "สพ ๐๐๓๓.๐๖/๑/๒/"
                    // Remove prefix to get "5"
                    if (val.startsWith(prefix)) {
                        const suffix = val.slice(prefix.length);
                        const num = parseAnyInt(suffix); // Handles "๑" or "1"
                        if (num > maxNum) maxNum = num;
                    }
                } else {
                    // Logic for Standard Mode (PO): "Prefix" + "RunningNumber" + "/" + "FiscalYear"
                    // Example: "กง. 10/2568"
                    const parts = val.split('/');
                    if (parts.length > 1) {
                        const leftPart = parts[0]; 
                        const num = parseAnyInt(leftPart);
                        if (num > maxNum) maxNum = num;
                    }
                }
            }
        });
    } catch (e) {
        console.error("Running number query failed:", e.message);
    }

    const nextNum = maxNum + 1;

    if (mode === 'REQUEST') {
        // Return: Prefix + Number (e.g., สพ ๐๐๓๓.๐๖/๑/๒/1)
        // Frontend will likely convert '1' to '๑' for display if needed, but keeping DB as Arabic is safer for calculation.
        return `${prefix}${nextNum}`;
    } else {
        // Return: Prefix + Number + / + Year (e.g., กง. 1/2568)
        const separator = (prefix && !prefix.endsWith(' ') && !prefix.endsWith('/') && !prefix.endsWith('.')) ? ' ' : '';
        return `${prefix}${separator}${nextNum}/${fiscalYear}`;
    }
};

