// Helper function for queries
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }
        const setCharsetSql = "SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';";
        connection.query(setCharsetSql, (err) => {
            if (err) {
                connection.release();
                return reject(err);
            }
            connection.query(sql, params, (err, res) => {
                connection.release();
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

// Helper: Get Fiscal Year
const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    const year = date.getFullYear();
    return month >= 9 ? year + 1 + 543 : year + 543;
};

// Helper: Parse Thai or Arabic Number to Integer
const parseAnyInt = (str) => {
    if (!str) return 0;
    // Normalize Thai numerals to Arabic
    const normalized = str.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
    // Extract the FIRST integer found
    const match = normalized.match(/(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
};

// Helper: Convert Arabic to Thai Number
const toThaiNum = (num) => {
    const str = num.toString();
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return str.replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

// Helper: Generate Running ID (Logic Improved to avoid SQL Collation issues)
const generateRunningId = async (deptId, dateStr, table, column, dateColName, mode = 'STANDARD') => {
    const fiscalYear = getFiscalYear(dateStr);
    const fiscalYearAD = fiscalYear - 543;
    const startDate = `${fiscalYearAD - 1}-10-01`;
    const endDate = `${fiscalYearAD}-09-30`;

    let prefix = '';

    // 1. Get Prefix
    if (deptId) {
        try {
            const deptRes = await query('SELECT prefix, request_prefix FROM departments WHERE id = ?', [deptId]);
            if (deptRes.length > 0) {
                if (mode === 'REQUEST') {
                    // e.g., "สพ ๐๐๓๓.๐๖/๑/๒/"
                    prefix = deptRes[0].request_prefix ? deptRes[0].request_prefix.trim() : '';
                } else {
                    // e.g., "พด."
                    prefix = deptRes[0].prefix ? deptRes[0].prefix.trim() : '';
                }
            }
        } catch (e) {
            console.warn("Prefix fetch failed:", e.message);
        }
    }

    // 2. Search for Max Number
    // Instead of filtering by LIKE in SQL (which can fail with Thai encodings),
    // we fetch ALL records for the fiscal year and filter in JS.
    let sql = `SELECT ${column} FROM ${table} WHERE ${dateColName} >= ? AND ${dateColName} <= ?`;
    const params = [startDate, endDate];

    let maxNum = 0;
    try {
        const rows = await query(sql, params);

        rows.forEach(row => {
            const val = row[column];
            if (val) {
                // Ensure value starts with our prefix
                if (val.startsWith(prefix)) {
                    // Logic for extraction
                    if (mode === 'REQUEST') {
                        // For Request ID: Prefix is likely "สพ ๐๐๓๓.๐๖/๑๔/" or similar.
                        // We want the number AFTER the prefix.
                        const suffix = val.slice(prefix.length); 
                        const num = parseAnyInt(suffix);
                        if (num > maxNum) maxNum = num;
                    } else {
                        // For Standard (PO): Format is usually "Prefix Number/Year" e.g., "กง. 123/2569"
                        // Or if prefix is empty: "123/2569"
                        // We need to match the number part before the slash
                        const cleanVal = val.slice(prefix.length).trim();
                        const parts = cleanVal.split('/');
                        const num = parseAnyInt(parts[0]);
                        if (num > maxNum) maxNum = num;
                    }
                }
            }
        });
    } catch (e) {
        console.error("Running number query failed:", e.message);
    }

    const nextNum = maxNum + 1;

    if (mode === 'REQUEST') {
        // Format: Prefix + ThaiNumber (No Fiscal Year suffix)
        // e.g. "สพ ๐๐๓๓.๐๖/๑/๒/" + "๑" -> "สพ ๐๐๓๓.๐๖/๑/๒/๑"
        return `${prefix}${toThaiNum(nextNum)}`;
    } else {
        // Format: Prefix + Number + / + FiscalYear
        // e.g. "กง. 1/2569"
        const separator = (prefix && !prefix.endsWith(' ') && !prefix.endsWith('/') && !prefix.endsWith('.')) ? ' ' : '';
        return `${prefix}${separator}${nextNum}/${fiscalYear}`;
    }
};

