// UPSERT Receivings
router.post('/receivings/upsert', async (req, res) => {
    const r = req.body;
    try {
        let finalNumber = r.deliveryNoteNo;
        // Generate ONLY if null/empty
        if (!finalNumber || finalNumber.trim() === '') {
            const proc = await query('SELECT department_id FROM procurements WHERE request_id = ?', [r.requestId]);
            if (proc.length > 0) {
                // Usually Standard Format "กด 1/2569"
                finalNumber = await generateRunningId(proc[0].department_id, r.receiveDate, 'receivings', 'delivery_note_no', 'receive_date', 'STANDARD');
            }
        }

        if (!finalNumber) finalNumber = '-';

        const existing = await query('SELECT id FROM receivings WHERE request_id = ?', [r.requestId]);
        if (existing.length > 0) {
            await query('UPDATE receivings SET delivery_note_no=?, receive_date=?, category=? WHERE request_id=?', [finalNumber, r.receiveDate, r.category, r.requestId]);
        } else {
            const id = Math.random().toString(36).substr(2, 9);
            await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, category, created_at) VALUES (?,?,?,?,?,?)', [id, r.requestId, finalNumber, r.receiveDate, r.category, Date.now()]);
        }
        res.json({ success: true, deliveryNoteNo: finalNumber });
    } catch (e) { console.error(e); res.status(500).json({ success: false }); }
});

