router.post('/procurements', async (req, res) => {
    const p = req.body;
    let finalOfficialNumber = p.officialNumber;
    let finalRequestId = p.requestId;

    try {
        // 1. Generate Request ID (If null/empty)
        if (!finalRequestId || finalRequestId.trim() === '') {
            finalRequestId = await generateRunningId(p.departmentId, p.requestDate, 'procurements', 'request_id', 'request_date', 'REQUEST');
        }

        // 2. Generate Official Number (If null/empty and amount > 5000)
        // Only for HIRING or PURCHASE where we need an Official Number immediately
        if ((!finalOfficialNumber || finalOfficialNumber.trim() === '') && p.amount > 5000) {
            finalOfficialNumber = await generateRunningId(p.departmentId, p.requestDate, 'procurements', 'official_number', 'request_date', 'STANDARD');
        }

        // Fallback safety
        if (!finalRequestId) finalRequestId = `TEMP-${Date.now()}`;

        await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
            [p.id, finalRequestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, finalOfficialNumber, p.type, p.departmentId, p.createdBy, p.createdAt]);

        res.json({ success: true, officialNumber: finalOfficialNumber, requestId: finalRequestId });

    } catch (e) {
        console.error("Add Procurement Error:", e);
        res.status(500).json({ success: false, message: e.message });
    }
});

router.patch('/procurements/:id', async (req, res) => {
    const id = req.params.id;
    const p = req.body;
    const map = { requestId: 'request_id', requestDate: 'request_date', category: 'category', itemCount: 'item_count', amount: 'amount', company: 'company', remarks: 'remarks', officialNumber: 'official_number', departmentId: 'department_id' };
    let sql = "UPDATE procurements SET ";
    const params = [];
    const fields = [];

    for (const [key, dbCol] of Object.entries(map)) {
        if (p[key] !== undefined) { fields.push(`${dbCol} = ?`); params.push(p[key]); }
    }
    if (fields.length > 0) {
        sql += fields.join(', ') + " WHERE id = ?"; 
        params.push(id); 
        await query(sql, params);
    }
    res.json({ success: true });
});

