const normalizeToNr = (str: string) => {
    if (!str) return '0';
    return str.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
};

const toThaiNr = (num: number) => {
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return num.toString().replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const month = date.getMonth(); 
    const year = date.getFullYear();
    const fiscalYear = month >= 9 ? year + 1 : year;
    return fiscalYear + 543;
};

