    // 1. Get Prefix from Department
    const deptRes = await query('SELECT prefix, request_prefix FROM departments WHERE id = ?', [deptId]);
    if (deptRes.length === 0) return `ERR-NO-DEPT-${Date.now()}`;

    const standardPrefix = deptRes[0].prefix ? deptRes[0].prefix.trim() : '';
    const requestPrefix = deptRes[0].request_prefix ? deptRes[0].request_prefix.trim() : '';

    if (mode === 'REQUEST') {
        // --- SHARED SEQUENCE LOGIC ---
        // We must check 3 tables to find the REAL maximum number used for this prefix
        let maxNum = 0;

        const sql = `
            SELECT val FROM (
                SELECT request_id as val FROM procurements WHERE department_id = ? AND request_date BETWEEN ? AND ? AND request_id LIKE ?
                UNION
                SELECT consideration_number as val FROM considerations c JOIN procurements p ON c.request_id = p.request_id WHERE p.department_id = ? AND p.request_date BETWEEN ? AND ? AND consideration_number LIKE ?
                UNION
                SELECT delivery_note_no as val FROM receivings r JOIN procurements p ON r.request_id = p.request_id WHERE p.department_id = ? AND p.request_date BETWEEN ? AND ? AND delivery_note_no LIKE ?
            ) as combined_docs
        `;

        const pattern = `${requestPrefix}%`;
        const params = [
            deptId, startDate, endDate, pattern,
            deptId, startDate, endDate, pattern,
            deptId, startDate, endDate, pattern
        ];

        const rows = await query(sql, params);
        rows.forEach(row => {
            const num = parseSuffixInt(row.val, requestPrefix);
            if (num > maxNum) maxNum = num;
        });

        return `${requestPrefix}${toThaiNum(maxNum + 1)}`;

    } else {
        // --- STANDARD SEQUENCE LOGIC (PO Number) ---
        let maxNum = 0;
        const sql = `SELECT official_number FROM procurements WHERE department_id = ? AND request_date BETWEEN ? AND ? AND official_number LIKE ?`;
        const pattern = `${standardPrefix}%`;
        const rows = await query(sql, [deptId, startDate, endDate, pattern]);

        rows.forEach(row => {
            if (row.official_number) {
                // Extract number before the slash
                const match = row.official_number.replace(standardPrefix, '').match(/(\d+)/);
                if (match) {
                    const num = parseInt(match[1], 10);
                    if (num > maxNum) maxNum = num;
                }
            }
        });

        const separator = (standardPrefix && !standardPrefix.endsWith(' ')) ? ' ' : '';
        return `${standardPrefix}${separator}${maxNum + 1}/${fiscalYear}`;
    }
};

