// Helper function for queries
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("Connection Error:", err);
            return reject(err);
        }
        const setCharsetSql = "SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';";
        connection.query(setCharsetSql, (err) => {
            if (err) {
                connection.release();
                return reject(err);
            }
            connection.query(sql, params, (err, res) => {
                connection.release();
                if (err) {
                    console.error("SQL Error:", err.sqlMessage); 
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

// Helper: Get Fiscal Year
const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    const year = date.getFullYear();
    return month >= 9 ? year + 1 + 543 : year + 543;
};

// Helper: Parse Thai or Arabic Number to Integer (Extracting ONLY the last part after prefix)
const parseSuffixInt = (fullStr, prefix) => {
    if (!fullStr || !prefix) return 0;

    let str = fullStr.toString().trim();
    let pfx = prefix.toString().trim();

    // 1. Remove the prefix from the start to avoid confusion with numbers inside prefix (e.g. ๐๐๓๓)
    let suffix = str;
    if (str.startsWith(pfx)) {
        suffix = str.substring(pfx.length).trim();
    } else {
        // Fallback: if it doesn't start with prefix, try to get the part after the last slash or space
        const parts = str.split(/[\/\s]/);
        suffix = parts[parts.length - 1];
    }

    if (!suffix) return 0;

    // 2. Normalize Thai numerals to Arabic
    const normalized = suffix.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());

    // 3. Match the first numeric group in the remaining suffix
    const match = normalized.match(/(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
};

// Helper: Convert Arabic to Thai Number
const toThaiNum = (num) => {
    const str = num.toString();
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return str.replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

// Helper: Generate Running ID (Master Shared Sequence Logic)
const generateRunningId = async (deptId, dateStr, mode = 'STANDARD') => {
    const fiscalYear = getFiscalYear(dateStr);
    const fiscalYearAD = fiscalYear - 543;
    const startDate = `${fiscalYearAD - 1}-10-01`;
    const endDate = `${fiscalYearAD}-09-30`;

    // 1. Get Prefixes from Department
    const deptRes = await query('SELECT prefix, request_prefix FROM departments WHERE id = ?', [deptId]);
    if (deptRes.length === 0) return `ERR-NO-DEPT-${Date.now()}`;

    const standardPrefix = deptRes[0].prefix ? deptRes[0].prefix.trim() : '';
    const requestPrefix = deptRes[0].request_prefix ? deptRes[0].request_prefix.trim() : '';

    if (mode === 'REQUEST') {
        // --- SHARED SEQUENCE LOGIC (Thai Numerals) ---
        // We look for the maximum number across ALL 3 procurement-related tables using the same request_prefix
        let maxNum = 0;

        const sql = `
            SELECT val FROM (
                SELECT request_id as val FROM procurements WHERE request_id LIKE ?
                UNION
                SELECT consideration_number as val FROM considerations WHERE consideration_number LIKE ?
                UNION
                SELECT delivery_note_no as val FROM receivings WHERE delivery_note_no LIKE ?
            ) as combined_docs
        `;

        const pattern = `${requestPrefix}%`;
        const rows = await query(sql, [pattern, pattern, pattern]);

        rows.forEach(row => {
            if (row.val) {
                const num = parseSuffixInt(row.val, requestPrefix);
                if (num > maxNum) maxNum = num;
            }
        });

        // Return the combined prefix + incremented Thai number
        return `${requestPrefix}${toThaiNum(maxNum + 1)}`;

    } else {
        // --- STANDARD SEQUENCE LOGIC (PO Number - Arabic) ---
        let maxNum = 0;
        const sql = `SELECT official_number FROM procurements WHERE department_id = ? AND request_date BETWEEN ? AND ? AND official_number LIKE ?`;
        const pattern = `${standardPrefix}%`;
        const rows = await query(sql, [deptId, startDate, endDate, pattern]);

        rows.forEach(row => {
            if (row.official_number) {
                // Find numbers before the slash
                const match = row.official_number.replace(standardPrefix, '').match(/(\d+)/);
                if (match) {
                    const num = parseInt(match[1], 10);
                    if (num > maxNum) maxNum = num;
                }
            }
        });

        const separator = (standardPrefix && !standardPrefix.endsWith(' ') && !standardPrefix.endsWith('/') && !standardPrefix.endsWith('.')) ? ' ' : '';
        return `${standardPrefix}${separator}${maxNum + 1}/${fiscalYear}`;
    }
};

