        if (existing.length > 0) {
            await query('UPDATE considerations SET consideration_number=?, consideration_date=? WHERE request_id=?', [finalNumber, c.considerationDate, c.requestId]);
        } else {
            const id = Math.random().toString(36).substr(2, 9);
            await query('INSERT INTO considerations (id, request_id, consideration_number, consideration_date) VALUES (?,?,?,?)', [id, c.requestId, finalNumber, c.considerationDate]);
        }
        res.json({ success: true, considerationNumber: finalNumber });
    } catch (e) { console.error(e); res.status(500).json({ success: false }); }
});

