                        <input 
                            type="date" 
                            disabled={isSaving}
                            className="w-full border rounded-lg px-3 py-2 mb-6 outline-none focus:ring-2 ring-blue-500 text-slate-900 bg-white disabled:bg-slate-50" 
                            value={quickDateValue} 
                            onChange={e => setQuickDateValue(e.target.value)} 
                        />
                        <div className="flex gap-2">
                            <button 
                                onClick={() => setQuickDateId(null)} 
                                disabled={isSaving}
                                className="flex-1 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm disabled:opacity-50"
                            >
                                ยกเลิก
                            </button>
                            <button 
                                onClick={handleSaveQuickDate} 
                                disabled={isSaving || !quickDateValue}
                                className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium disabled:bg-blue-300 flex items-center justify-center"
                            >
                                {isSaving ? <Loader2 className="animate-spin mr-2" size={16} /> : null}
                                {isSaving ? 'กำลังบันทึก...' : 'บันทึก'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Form Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-0 sm:p-4 no-print">
                    <div className="bg-white sm:rounded-xl shadow-2xl w-full max-w-2xl h-full sm:h-auto max-h-screen flex flex-col overflow-hidden relative">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
                            <h3 className="text-lg font-semibold text-slate-800">{editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}</h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600 p-1"><X size={28} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 flex-1 overflow-y-auto">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestId} *</label>
                                    {editingId ? (
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-100 text-slate-500 cursor-not-allowed outline-none" 
                                            value={formData.requestId} 
                                            readOnly
                                            disabled
                                        />
                                    ) : (
                                        <div className="w-full border border-slate-200 bg-slate-100 rounded-lg px-3 py-2 text-slate-500 italic text-sm cursor-not-allowed">
                                            (ระบบจะรันเลขลำดับถัดไปให้โดยอัตโนมัติ)
                                        </div>
                                    )}
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestDate} *</label>
                                    <input required type="date" className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900" value={formData.requestDate} onChange={e => setFormData({...formData, requestDate: e.target.value})} />
                                </div>

                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                    <select className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                        <option value="">เลือกหมวด...</option>
                                        {settings.categories?.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                    <input type="text" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                    <input 
                                        type="number" 
                                        min="1" 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" 
                                        value={formData.itemCount || ''} 
                                        onChange={e => setFormData({...formData, itemCount: e.target.value === '' ? 0 : Number(e.target.value)})} 
                                        placeholder="0"
                                    />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนเงิน *</label>
                                    <input 
                                        required 
                                        type="number" 
                                        step="0.01" 
                                        className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none bg-white text-slate-900`} 
                                        value={formData.amount || ''} 
                                        onChange={e => setFormData({...formData, amount: e.target.value === '' ? 0 : Number(e.target.value)})} 
                                        placeholder="0.00"
                                    />
                                </div>

                                <div className="col-span-1 sm:col-span-2">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                    <textarea rows={2} className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
                                </div>
                            </div>
                            <div className="flex flex-col sm:flex-row justify-end gap-3 mt-8 pt-4 border-t sticky bottom-0 bg-white">
                                <button type="button" onClick={closeModal} className="order-2 sm:order-1 px-6 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">ยกเลิก</button>
                                <button type="submit" className={`order-1 sm:order-2 px-8 py-2.5 ${theme.bgDeep} ${theme.bgHover} text-white rounded-lg shadow-md flex justify-center items-center`}><Check size={18} className="mr-2" /> บันทึกข้อมูล</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {showConfirm && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-blue-50 mb-6">
                            <AlertCircle className="h-8 w-8 text-blue-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการบันทึกข้อมูล?</h3>
                        <p className="text-sm text-slate-500 mb-8 leading-relaxed">กรุณาตรวจสอบความถูกต้องของข้อมูลอีกครั้ง<br/>คุณต้องการบันทึกรายการนี้ใช่หรือไม่?</p>
                        <div className="flex gap-4">
                            <button onClick={() => setShowConfirm(false)} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold transition-colors">กลับไปแก้ไข</button>
                            <button onClick={handleConfirmSave} className="flex-1 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-sm font-semibold shadow-lg transition-colors">ยืนยันบันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {deleteId && (
                <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/50 no-print">
                    <div className="bg-white rounded-xl p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4"><AlertTriangle className="text-red-600" /></div>
                        <h3 className="text-lg font-bold mb-2">ยืนยันการลบ?</h3>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setDeleteId(null)} className="flex-1 py-2 bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-sm">ลบออก</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { RecordType, ProcurementRecord } from '../types';
import { Plus, Edit2, Trash2, X, Check, AlertCircle, FileSpreadsheet, Printer, User as UserIcon, Loader2, AlertTriangle } from 'lucide-react';

interface Props {
    type: RecordType;
    title: string;
}

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const month = date.getMonth(); 
    const year = date.getFullYear();
    const fiscalYear = month >= 9 ? year + 1 : year;
    return fiscalYear + 543;
};

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, addProcurement, updateProcurement, deleteProcurement, getLinkedData, upsertConsideration, upsertReceiving, settings, currentUser, users } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [deleteId, setDeleteId] = useState<string | null>(null);
    const [quickDateId, setQuickDateId] = useState<string | null>(null);
    const [quickDateValue, setQuickDateValue] = useState('');
    const [quickDateType, setQuickDateType] = useState<'CONSIDERATION' | 'RECEIVING' | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: '',
        considerationNumber: '',
        considerationDate: '',
        officialNumber: ''
    });

    const filteredData = procurements.filter(p => p.type === type);

    let fieldLabels = {
        requestId: "เลขกำหนดขอบเขตงาน",
        requestDate: "วันที่กำหนดขอบเขตงาน",
        considerationNumber: "เลขรายงานขอซื้อ",
        considerationDate: "วันที่รายงานขอซื้อ",
        receivingNumber: "เลขรายงานผลการพิจารณา",
        receivingDate: "วันที่รายงานผลการพิจารณา",
        officialNumber: "เลขสั่งซื้อ"
    };

    if (type === RecordType.HIRING) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขอจ้าง",
            considerationDate: "วันที่รายงานขอจ้าง",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขสั่งจ้าง"
        };
    } else if (type === RecordType.OTHER) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขออนุมัติ",
            considerationDate: "วันที่รายงานขออนุมัติ",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขที่คำสั่ง/สัญญา"
        };
    }

    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return { name: 'violet', bgSoft: 'bg-violet-50', bgDeep: 'bg-violet-600', bgHover: 'hover:bg-violet-700', text: 'text-violet-700', border: 'border-violet-200', ring: 'focus:ring-violet-500', inputBg: 'bg-violet-50/50' };
            case RecordType.OTHER:
                return { name: 'orange', bgSoft: 'bg-orange-50', bgDeep: 'bg-orange-600', bgHover: 'hover:bg-orange-700', text: 'text-orange-700', border: 'border-orange-200', ring: 'focus:ring-orange-500', inputBg: 'bg-orange-50/50' };
            default:
                return { name: 'blue', bgSoft: 'bg-blue-50', bgDeep: 'bg-blue-600', bgHover: 'hover:bg-blue-700', text: 'text-blue-700', border: 'border-blue-200', ring: 'focus:ring-blue-500', inputBg: 'bg-blue-50/50' };
        }
    })();

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowConfirm(true);
    };

    const handleConfirmSave = async () => {
        if (editingId) {
            updateProcurement(editingId, { ...formData });
            setShowConfirm(false);
            closeModal();
        } else {
            // Send requestId as null to trigger backend auto-generation
            const result = await addProcurement({ ...formData, requestId: null, type: type });
            if (result.success) {
                setShowConfirm(false);
                closeModal();
            } else {
                setShowConfirm(false);
                alert(result.message || 'เกิดข้อผิดพลาดในการบันทึก');
            }
        }
    };

    const handleDeleteClick = (id: string) => {
        const record = procurements.find(p => p.id === id);
        if (record && record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์ลบรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        setFormData({ 
            requestId: '', 
            requestDate: new Date().toISOString().split('T')[0], 
            category: '', 
            itemCount: 0, 
            amount: 0, 
            company: '', 
            remarks: '', 
            considerationNumber: '', 
            considerationDate: '',
            officialNumber: ''
        });
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        if (record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์แก้ไขรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        const linked = getLinkedData(record.requestId);
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || '',
            officialNumber: record.officialNumber || ''
        });
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
    };

    const handleSaveQuickDate = async () => {
        if (quickDateId && quickDateValue && quickDateType) {
            setIsSaving(true);
            let success = false;
            // Sending null for number forces Backend to generate from Master Shared Sequence
            if (quickDateType === 'CONSIDERATION') {
                success = await upsertConsideration(quickDateId, null, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                success = await upsertReceiving(quickDateId, null, quickDateValue);
            }

            setIsSaving(false);
            if (success) {
                setQuickDateId(null);
                setQuickDateValue('');
                setQuickDateType(null);
            } else {
                alert('เกิดข้อผิดพลาดในการบันทึกข้อมูล');
            }
        }
    };

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'ไม่ระบุ';

    const hasValue = (val: string | null | undefined) => {
        return val && val.trim() !== '' && val.trim() !== '-';
    };

    return (
        <div className="p-4 sm:p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                <h2 className="text-xl sm:text-2xl font-bold text-slate-800">{title}</h2>
                <div className="flex flex-wrap gap-2 no-print w-full sm:w-auto">
                    <button onClick={openNew} className={`w-full sm:w-auto flex items-center justify-center space-x-2 ${theme.bgDeep} ${theme.bgHover} text-white px-4 py-2 rounded-lg text-sm shadow-md`}>
                        <Plus size={16} />
                        <span>บันทึกใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestId}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestDate}</th>
                                <th className="px-4 py-3 whitespace-nowrap">ปีงบฯ</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.considerationNumber}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.considerationDate}</th>
                                <th className={`px-4 py-3 ${theme.bgSoft} whitespace-nowrap`}>{fieldLabels.officialNumber}</th>
                                <th className="px-4 py-3 bg-green-50 whitespace-nowrap">{fieldLabels.receivingNumber}</th>
                                <th className="px-4 py-3 bg-green-50 whitespace-nowrap">{fieldLabels.receivingDate}</th>
                                <th className="px-4 py-3 text-right whitespace-nowrap">จำนวนเงิน</th>
                                <th className="px-4 py-3 whitespace-nowrap">ผู้บันทึก</th>
                                <th className="px-4 py-3 text-center no-print whitespace-nowrap">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredData.length === 0 ? (
                                <tr><td colSpan={11} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูล</td></tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const isOwner = item.createdBy === currentUser?.id || currentUser?.role === 'ADMIN';
                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                                            <td className="px-4 py-3 font-medium text-slate-900 whitespace-nowrap">{item.requestId}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">{item.requestDate}</td>
                                            <td className="px-4 py-3 text-center whitespace-nowrap">{getFiscalYear(item.requestDate)}</td>

                                            <td className="px-4 py-3 text-orange-600 whitespace-nowrap font-medium">
                                                {hasValue(linked.consideration?.considerationNumber) ? (
                                                    linked.consideration?.considerationNumber
                                                ) : (
                                                    isOwner && (
                                                        <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('CONSIDERATION'); setQuickDateValue(new Date().toISOString().split('T')[0]); }} className="flex items-center text-orange-600 bg-orange-50 px-2 py-1 rounded no-print text-xs hover:bg-orange-100 transition-colors">
                                                            <Plus size={14} className="mr-1" /> เพิ่มรายงานขอซื้อ
                                                        </button>
                                                    )
                                                )}
                                            </td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                {hasValue(linked.consideration?.considerationNumber) ? (linked.consideration?.considerationDate || '-') : '-'}
                                            </td>

                                            <td className={`px-4 py-3 ${theme.bgSoft} font-bold ${theme.text} whitespace-nowrap`}>{item.officialNumber || '-'}</td>

                                            <td className="px-4 py-3 bg-green-50 text-green-700 whitespace-nowrap font-medium">
                                                {hasValue(linked.receiving?.deliveryNoteNo) ? (
                                                    linked.receiving?.deliveryNoteNo
                                                ) : (
                                                    isOwner && (
                                                        <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('RECEIVING'); setQuickDateValue(new Date().toISOString().split('T')[0]); }} className="flex items-center text-green-600 bg-green-100 px-2 py-1 rounded no-print text-xs hover:bg-green-200 transition-colors">
                                                            <Plus size={14} className="mr-1" /> เพิ่มผลพิจารณา
                                                        </button>
                                                    )
                                                )}
                                            </td>
                                            <td className="px-4 py-3 bg-green-50 whitespace-nowrap">
                                                {hasValue(linked.receiving?.deliveryNoteNo) ? (linked.receiving?.receiveDate || '-') : '-'}
                                            </td>

                                            <td className="px-4 py-3 text-right whitespace-nowrap">{Number(item.amount).toLocaleString('th-TH', { minimumFractionDigits: 2 })}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                <div className="flex items-center text-xs text-slate-500"><UserIcon size={12} className="mr-1 opacity-50"/>{getUserName(item.createdBy)}</div>
                                            </td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    {isOwner ? (
                                                        <>
                                                            <button onClick={() => openEdit(item)} className="p-1 text-slate-600 hover:bg-slate-200 rounded"><Edit2 size={16} /></button>
                                                            <button onClick={() => handleDeleteClick(item.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
                                                        </>
                                                    ) : <span className="text-[10px] text-slate-400">อ่านอย่างเดียว</span>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Quick Date Modal */}
            {quickDateId && (
                <div className="fixed inset-0 bg-black/40 z-[100] flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold">ระบุวันที่</h3>
                            <button onClick={() => !isSaving && setQuickDateId(null)} className="text-slate-400"><X size={20}/></button>
                        </div>
                        <p className="text-xs text-slate-500 mb-4">ระบบจะรันเลข <span className="font-bold text-slate-800">ลำดับถัดไป (เลขไทย)</span> ให้อัตโนมัติ</p>
                        <input type="date" disabled={isSaving} className="w-full border rounded-lg px-3 py-2 mb-6 outline-none focus:ring-2 ring-blue-500 text-slate-900 bg-white" value={quickDateValue} onChange={e => setQuickDateValue(e.target.value)} />
                        <div className="flex gap-2">
                            <button onClick={() => setQuickDateId(null)} disabled={isSaving} className="flex-1 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={handleSaveQuickDate} disabled={isSaving || !quickDateValue} className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium flex justify-center items-center">
                                {isSaving && <Loader2 className="animate-spin mr-2" size={16} />}
                                {isSaving ? 'กำลังบันทึก...' : 'บันทึก'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Form Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-0 sm:p-4 no-print">
                    <div className="bg-white sm:rounded-xl shadow-2xl w-full max-w-2xl h-full sm:h-auto max-h-screen flex flex-col overflow-hidden relative">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
                            <h3 className="text-lg font-semibold text-slate-800">{editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}</h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600 p-1"><X size={28} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 flex-1 overflow-y-auto">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestId} *</label>
                                    <div className="w-full border border-slate-200 bg-slate-100 rounded-lg px-3 py-2 text-slate-500 italic text-sm">
                                        {editingId ? formData.requestId : '(ระบบจะรันเลขลำดับถัดไปของฝ่ายให้โดยอัตโนมัติ)'}
                                    </div>
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestDate} *</label>
                                    <input required type="date" className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900" value={formData.requestDate} onChange={e => setFormData({...formData, requestDate: e.target.value})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                    <select className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                        <option value="">เลือกหมวด...</option>
                                        {settings.categories?.filter(c => c.isActive).map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                    <input type="text" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                    <input type="number" min="1" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.itemCount} onChange={e => setFormData({...formData, itemCount: Number(e.target.value)})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนเงิน *</label>
                                    <input required type="number" step="0.01" className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none bg-white text-slate-900`} value={formData.amount} onChange={e => setFormData({...formData, amount: Number(e.target.value)})} />
                                </div>
                                <div className="col-span-1 sm:col-span-2">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมายเหตุ</label>
                                    <textarea rows={2} className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
                                </div>
                            </div>
                            <div className="flex flex-col sm:flex-row justify-end gap-3 mt-8 pt-4 border-t sticky bottom-0 bg-white">
                                <button type="button" onClick={closeModal} className="order-2 sm:order-1 px-6 py-2.5 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors">ยกเลิก</button>
                                <button type="submit" className={`order-1 sm:order-2 px-8 py-2.5 ${theme.bgDeep} ${theme.bgHover} text-white rounded-lg shadow-md flex justify-center items-center`}><Check size={18} className="mr-2" /> บันทึกข้อมูล</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {showConfirm && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm no-print">
                    <div className="bg-white rounded-xl shadow-2xl p-8 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-blue-50 mb-6">
                            <AlertCircle className="h-8 w-8 text-blue-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการบันทึกข้อมูล?</h3>
                        <p className="text-sm text-slate-500 mb-8 leading-relaxed">ข้อมูลจะถูกรันเลขที่เอกสารโดยอัตโนมัติตามลำดับล่าสุดของฝ่ายงาน</p>
                        <div className="flex gap-4">
                            <button onClick={() => setShowConfirm(false)} className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold transition-colors">กลับไปแก้ไข</button>
                            <button onClick={handleConfirmSave} className="flex-1 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-sm font-semibold shadow-lg transition-colors">ยืนยันบันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {deleteId && (
                <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/50 no-print">
                    <div className="bg-white rounded-xl p-6 max-w-sm w-full text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4"><AlertTriangle className="text-red-600" /></div>
                        <h3 className="text-lg font-bold mb-2">ยืนยันการลบ?</h3>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setDeleteId(null)} className="flex-1 py-2 bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={confirmDelete} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-sm">ลบออก</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProcurementTable;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole, Department, ProcurementCategory, UserStatus, WorkGroup } from '../types';

const BACKEND_PORT = 3002; 
const getApiUrl = () => {
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api/procurement`;
    let hostname = window.location.hostname;
    if (!hostname || hostname.trim() === '') hostname = 'localhost';
    return `http://${hostname}:${BACKEND_PORT}/api/procurement`;
};

const API_URL = getApiUrl();

interface AppContextType {
    isLoading: boolean;
    serverError: boolean;
    serverErrorMessage: string;
    retryConnection: () => void;
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>, force?: boolean) => Promise<{ success: boolean, message?: string, isWarning?: boolean, requestId?: string }>;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    upsertReceiving: (requestId: string, number: string | null, date: string) => Promise<boolean>;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    upsertConsideration: (requestId: string, number: string | null, date: string) => Promise<boolean>;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
    addDepartment: (dept: Department) => void;
    updateDepartment: (id: string, data: Partial<Department>) => void;
    addWorkGroup: (group: WorkGroup) => void;
    updateWorkGroup: (id: string, data: Partial<WorkGroup>) => void;
    addCategory: (category: ProcurementCategory) => void;
    updateCategory: (id: string, data: Partial<ProcurementCategory>) => void;
    deleteCategory: (id: string) => void;
    checkChronologyIssue: (record: ProcurementRecord) => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);
    const [serverErrorMessage, setServerErrorMessage] = useState('');
    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);
    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: '',
        departments: [],
        categories: [],
        workGroups: []
    });

    const fetchData = async () => {
        setIsLoading(true);
        setServerError(false);
        try {
            const [userRes, dataRes] = await Promise.all([
                fetch(`${API_URL}/users`),
                fetch(`${API_URL}/data`)
            ]);
            if (!userRes.ok || !dataRes.ok) throw new Error("Failed to fetch data from server");
            const userData = await userRes.json();
            const data = await dataRes.json();
            setUsers(userData);
            setProcurements(data.procurements);
            setReceivings(data.receivings);
            setConsiderations(data.considerations);
            setSettings({
                requestIdPrefix: '',
                departments: data.settings.departments,
                categories: data.settings.categories,
                workGroups: data.settings.workGroups || []
            });
        } catch (error: any) {
            setServerError(true);
            setServerErrorMessage(error.message);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const savedUser = localStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
    }, []);

    const retryConnection = () => fetchData();

    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: u, password: p }) });
            const result = await res.json();
            if (result.success) {
                setCurrentUser(result.user);
                localStorage.setItem('procurement_session_user', JSON.stringify(result.user));
            }
            return result;
        } catch (e: any) { return { success: false, message: e.message }; }
    };

    const logout = () => { setCurrentUser(null); localStorage.removeItem('procurement_session_user'); };

    const registerUser = async (userData: Omit<User, 'id' | 'createdAt'>) => {
        try {
            const newUser = { ...userData, id: Math.random().toString(36).substr(2, 9) };
            const res = await fetch(`${API_URL}/register`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newUser) });
            if(res.ok) { await fetchData(); return true; }
            return false;
        } catch (e) { return false; }
    };

    const deleteUser = async (id: string) => updateUser(id, { status: 'SUSPENDED' });

    const updateUser = async (id: string, data: Partial<User>) => {
        try {
            await fetch(`${API_URL}/users/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            await fetchData();
        } catch(e) { console.error(e); }
    };

    const addProcurement = async (data: any) => {
        const newRecord = { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now(), officialNumber: null, departmentId: currentUser?.departmentId, createdBy: currentUser?.id || 'unknown' };
        try {
            const res = await fetch(`${API_URL}/procurements`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newRecord) });
            const result = await res.json();
            if (result.success) { await fetchData(); return { success: true, requestId: result.requestId }; }
            return { success: false, message: result.message };
        } catch(e) { return { success: false, message: "Server Error" }; }
    };

    const updateProcurement = async (id: string, data: Partial<ProcurementRecord>) => {
        try {
            await fetch(`${API_URL}/procurements/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
            await fetchData();
        } catch(e) { console.error(e); }
    };

    const deleteProcurement = async (id: string) => {
        await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' });
        await fetchData();
    };

    const upsertReceiving = async (requestId: string, number: string | null, date: string) => {
        const payload = { requestId, deliveryNoteNo: (number && number !== '-') ? number : null, receiveDate: date };
        try {
            const res = await fetch(`${API_URL}/receivings/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
            if (res.ok) { await fetchData(); return true; }
        } catch (e) { console.error(e); }
        return false;
    };

    const upsertConsideration = async (requestId: string, number: string | null, date: string) => {
        const payload = { requestId, considerationNumber: (number && number !== '-') ? number : null, considerationDate: date };
        try {
            const res = await fetch(`${API_URL}/considerations/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) });
            if (res.ok) { await fetchData(); return true; }
        } catch (e) { console.error(e); }
        return false;
    };

    const getLinkedData = (requestId: string) => {
        const receiving = receivings.find(r => r.requestId === requestId);
        const consideration = considerations.find(c => c.requestId === requestId);
        return { receiving, consideration };
    };

    const updateSettings = async (s: Partial<AppSettings>) => fetchData();

    const addDepartment = async (dept: Department) => {
        await fetch(`${API_URL}/department`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dept) });
        await fetchData();
    };

    const updateDepartment = async (id: string, data: Partial<Department>) => {
        await fetch(`${API_URL}/department/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        await fetchData();
    };

    const addWorkGroup = async (group: WorkGroup) => {
        await fetch(`${API_URL}/workgroup`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(group) });
        await fetchData();
    };

    const updateWorkGroup = async (id: string, data: Partial<WorkGroup>) => {
        await fetch(`${API_URL}/workgroup/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        await fetchData();
    };

    const addCategory = async (category: ProcurementCategory) => {
        await fetch(`${API_URL}/category`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(category) });
        await fetchData();
    };

    const updateCategory = async (id: string, data: Partial<ProcurementCategory>) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
        await fetchData();
    };

    const deleteCategory = async (id: string) => {
        await fetch(`${API_URL}/category/${id}`, { method: 'DELETE' });
        await fetchData();
    };

    const checkChronologyIssue = (record: ProcurementRecord) => false;

    return (
        <AppContext.Provider value={{
            isLoading, serverError, serverErrorMessage, retryConnection,
            procurements, receivings, considerations, settings, currentUser, users,
            login, logout, registerUser, deleteUser, updateUser, 
            addProcurement, updateProcurement, deleteProcurement,
            addReceiving: () => {}, upsertReceiving, deleteReceiving: () => {}, 
            addConsideration: () => {}, upsertConsideration, getLinkedData, updateSettings,
            addDepartment, updateDepartment, addWorkGroup, updateWorkGroup,
            addCategory, updateCategory, deleteCategory, checkChronologyIssue
        }}>
            {children}
        </AppContext.Provider>
    );
};

