const toArabic = (str) => {
    if (!str) return "";
    return str.toString().replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
};

const toThaiNum = (num) => {
    const str = num.toString();
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return str.replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

const parseLastInt = (fullStr, prefix) => {
    if (!fullStr) return 0;
    let normStr = toArabic(fullStr.toString().trim());
    let normPfx = prefix ? toArabic(prefix.toString().trim()) : "";
    let remainder = normStr;
    if (normPfx && normStr.startsWith(normPfx)) remainder = normStr.substring(normPfx.length).trim();
    const match = remainder.match(/(\d+)$/);
    return match ? parseInt(match[1], 10) : 0;
};

const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    return month >= 9 ? date.getFullYear() + 1 + 543 : date.getFullYear() + 543;
};

const generateRunningId = async (deptId, dateStr, mode = 'STANDARD', explicitPrefix = null) => {
    const deptRes = await query('SELECT prefix, request_prefix FROM departments WHERE id = ?', [deptId]);
    if (deptRes.length === 0 && !explicitPrefix) return `ERR-DEPT-${Date.now()}`;

    const stdPrefix = deptRes[0]?.prefix?.trim() || 'กด';
    const reqPrefix = explicitPrefix || deptRes[0]?.request_prefix?.trim() || 'กด';

    if (mode === 'REQUEST') {
        const pattern = `${reqPrefix}%`;
        const sql = `
            SELECT val FROM (
                SELECT request_id as val FROM procurements WHERE request_id LIKE ?
                UNION ALL
                SELECT consideration_number as val FROM considerations WHERE consideration_number LIKE ?
                UNION ALL
                SELECT delivery_note_no as val FROM receivings WHERE delivery_note_no LIKE ?
            ) as docs
        `;
        const rows = await query(sql, [pattern, pattern, pattern]);
        let maxNum = 0;
        rows.forEach(row => {
            const num = parseLastInt(row.val, reqPrefix);
            if (num > maxNum) maxNum = num;
        });
        return `${reqPrefix}${toThaiNum(maxNum + 1)}`;
    } else {
        const fy = getFiscalYear(dateStr);
        const start = `${fy - 544}-10-01`, end = `${fy - 543}-09-30`;
        const rows = await query('SELECT official_number FROM procurements WHERE department_id = ? AND request_date BETWEEN ? AND ? AND official_number LIKE ?', [deptId, start, end, `${stdPrefix}%`]);
        let maxNum = 0;
        rows.forEach(row => {
            const parts = row.official_number.replace(stdPrefix, '').split('/');
            const num = parseInt(parts[0]?.match(/(\d+)/)?.[0] || 0);
            if (num > maxNum) maxNum = num;
        });
        return `${stdPrefix} ${maxNum + 1}/${fy}`;
    }
};

