const generateSOWNumber = async (deptId, dateStr) => {
    const deptRes = await query('SELECT request_prefix FROM departments WHERE id = ?', [deptId]);
    const prefix = deptRes[0]?.request_prefix?.trim() || 'สพ.';

    const pattern = `${prefix}%`;
    const sql = `SELECT request_id as val FROM procurements WHERE request_id LIKE ?`;
    const rows = await query(sql, [pattern]);

    const toArabic = (str) => str.toString().replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
    const toThaiNum = (num) => num.toString().replace(/\d/g, d => ['๐','๑','๒','๓','๔','๕','๖','๗','๘','๙'][parseInt(d)]);

    let maxNum = 0;
    rows.forEach(row => {
        const normStr = toArabic(row.val);
        const normPfx = toArabic(prefix);
        const remainder = normStr.replace(normPfx, '');
        const match = remainder.match(/(\d+)$/);
        if (match) {
            const num = parseInt(match[1], 10);
            if (num > maxNum) maxNum = num;
        }
    });

    return `${prefix}${toThaiNum(maxNum + 1)}`;
};

