router.post('/procurements', async (req, res) => {
    const p = req.body;
    try {
        const finalRequestId = await generateMasterSequence(p.departmentId);

        let finalOfficialNumber = null;
        if (p.amount > 5000) {
            const deptRes = await query('SELECT prefix FROM departments WHERE id = ?', [p.departmentId]);
            const stdPrefix = deptRes[0]?.prefix?.trim() || 'พด.';
            const fy = getFiscalYear(p.requestDate);
            const start = `${fy - 544}-10-01`, end = `${fy - 543}-09-30`;
            const rows = await query('SELECT official_number FROM procurements WHERE department_id = ? AND request_date BETWEEN ? AND ? AND official_number LIKE ?', [p.departmentId, start, end, `${stdPrefix}%`]);
            let maxNum = 0;
            rows.forEach(row => {
                const parts = row.official_number.replace(stdPrefix, '').split('/');
                const num = parseInt(parts[0]?.match(/(\d+)/)?.[0] || 0);
                if (num > maxNum) maxNum = num;
            });
            finalOfficialNumber = `${stdPrefix} ${maxNum + 1}/${fy}`;
        }

        const newId = `proc_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
        await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
            [newId, finalRequestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, finalOfficialNumber, p.type, p.departmentId, p.createdBy, Date.now()]);

        res.json({ success: true, requestId: finalRequestId });
    } catch (e) { res.status(500).json({ success: false, message: e.message }); }
});

router.post('/receivings/upsert', async (req, res) => {
    const r = req.body;
    console.log("Upsert Receiving Payload:", r);
    try {
        const proc = await query('SELECT request_id, department_id FROM procurements WHERE request_id = ?', [r.requestId]);
        if (proc.length === 0) return res.status(404).json({ success: false, message: "ไม่พบเลขขอบเขตงาน" });

        let finalNumber = r.deliveryNoteNo;
        if (!finalNumber || finalNumber.trim() === '') {
            const fullId = proc[0].request_id;
            const lastPartMatch = toArabic(fullId).match(/(\d+)$/);
            let prefix = fullId;
            if (lastPartMatch) {
                prefix = fullId.substring(0, fullId.length - lastPartMatch[0].length);
            }
            finalNumber = await generateMasterSequence(proc[0].department_id, prefix);
        }

        const existing = await query('SELECT id FROM receivings WHERE request_id = ?', [r.requestId]);
        if (existing.length > 0) {
            await query('UPDATE receivings SET delivery_note_no=?, receive_date=? WHERE request_id=?', [finalNumber, r.receiveDate, r.requestId]);
        } else {
            const newId = `recv_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`;
            await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, created_at) VALUES (?,?,?,?,?)', 
                [newId, r.requestId, finalNumber, r.receiveDate, Date.now()]);
        }
        res.json({ success: true, deliveryNoteNo: finalNumber });
    } catch (e) { 
        console.error("Receiving Upsert Error:", e);
        res.status(500).json({ success: false, message: e.message }); 
    }
});

