import React from 'react';
import { useApp } from '../services/store';
import { LayoutDashboard, ShoppingCart, Briefcase, Settings, Users, LogOut, User as UserIcon, Archive, X, UserCheck, TrendingUp } from 'lucide-react';

interface SidebarProps {
    activeTab: string;
    setActiveTab: (tab: string) => void;
    isOpen: boolean;
    setIsOpen: (open: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isOpen, setIsOpen }) => {
    const { currentUser, logout, users } = useApp();

    const pendingCount = users.filter(u => u.status === 'PENDING').length;

    // Determine Menu Items based on Role
    const getMenuItems = () => {
        const role = currentUser?.role;

        const baseItems = [
            { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
        ];

        // Executive: Only Dashboard & Executive Dashboard
        if (role === 'EXECUTIVE') {
            return [
                ...baseItems,
                { id: 'executive', label: 'Dashboard ผู้บริหาร', icon: TrendingUp }
            ];
        }

        // User: Dashboard + Operations (No Executive Dash)
        if (role === 'USER') {
            return [
                ...baseItems,
                { id: 'purchase', label: 'ทะเบียนคุมจัดซื้อ (PO)', icon: ShoppingCart },
                { id: 'hiring', label: 'ทะเบียนคุมจัดจ้าง (HO)', icon: Briefcase },
                { id: 'other', label: 'ทะเบียนคุมอื่นๆ', icon: Archive },
            ];
        }

        // Admin: Everything
        if (role === 'ADMIN') {
            return [
                ...baseItems,
                { id: 'executive', label: 'Dashboard ผู้บริหาร', icon: TrendingUp },
                { id: 'purchase', label: 'ทะเบียนคุมจัดซื้อ (PO)', icon: ShoppingCart },
                { id: 'hiring', label: 'ทะเบียนคุมจัดจ้าง (HO)', icon: Briefcase },
                { id: 'other', label: 'ทะเบียนคุมอื่นๆ', icon: Archive },
            ];
        }

        return baseItems;
    };

    const menuItems = getMenuItems();

    const adminItems = [];
    if (currentUser?.role === 'ADMIN') {
        adminItems.push({ 
            id: 'pending_users', 
            label: 'รอยืนยันการสมัคร', 
            icon: UserCheck,
            badge: pendingCount > 0 ? pendingCount : null 
        });
        adminItems.push({ id: 'users', label: 'จัดการผู้ใช้งาน', icon: Users });
        adminItems.push({ id: 'settings', label: 'ตั้งค่าระบบ', icon: Settings });
    }

    const handleMenuClick = (id: string) => {
        setActiveTab(id);
        if (window.innerWidth < 1024) {
            setIsOpen(false);
        }
    };

    return (
        <>
            {/* Overlay for mobile */}
            {isOpen && (
                <div 
                    className="fixed inset-0 bg-black/50 z-[60] lg:hidden backdrop-blur-sm transition-opacity"
                    onClick={() => setIsOpen(false)}
                />
            )}

            {/* Sidebar Container */}
            <div className={`fixed left-0 top-0 h-screen bg-slate-900 text-white flex flex-col overflow-y-auto z-[70] transition-all duration-300 ease-in-out shadow-2xl
                ${isOpen ? 'w-64 translate-x-0' : 'w-64 -translate-x-full lg:translate-x-0'}`}>

                <div className="p-6 border-b border-slate-700 flex justify-between items-center">
                    <div>
                        <h1 className="text-xl font-bold text-blue-400">Procurement OS</h1>
                        <p className="text-xs text-slate-400 mt-1">ระบบทะเบียนจัดซื้อ จัดจ้าง รพ.สามชุก</p>
                    </div>
                    <button onClick={() => setIsOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1">
                        <X size={24} />
                    </button>
                </div>

                {/* User Profile Summary */}
                <div className="px-6 py-4 flex items-center space-x-3 border-b border-slate-800">
                    <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-blue-300 flex-shrink-0">
                        <UserIcon size={20} />
                    </div>
                    <div className="overflow-hidden">
                        <p className="text-sm font-semibold truncate">{currentUser?.name}</p>
                        <p className="text-xs text-slate-500 uppercase">{currentUser?.role}</p>
                    </div>
                </div>

                <nav className="flex-1 p-4 space-y-1">
                    {menuItems.map((item) => {
                        const Icon = item.icon;
                        const isExecutive = item.id === 'executive';
                        return (
                            <button
                                key={item.id}
                                onClick={() => handleMenuClick(item.id)}
                                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                                    activeTab === item.id 
                                    ? 'bg-blue-600 text-white shadow-lg' 
                                    : isExecutive 
                                        ? 'text-amber-400 hover:bg-slate-800 hover:text-amber-300' 
                                        : 'text-slate-300 hover:bg-slate-800'
                                }`}
                            >
                                <Icon size={20} />
                                <span className="font-medium text-sm">{item.label}</span>
                            </button>
                        );
                    })}

                    {adminItems.length > 0 && (
                        <div className="pt-4 pb-2">
                            <p className="px-4 text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2">Admin Panel</p>
                            {adminItems.map((item) => {
                                const Icon = item.icon;
                                return (
                                    <button
                                        key={item.id}
                                        onClick={() => handleMenuClick(item.id)}
                                        className={`w-full flex items-center justify-between px-4 py-3 rounded-lg transition-colors mb-1 ${
                                            activeTab === item.id 
                                            ? 'bg-indigo-600 text-white shadow-lg' 
                                            : 'text-slate-300 hover:bg-slate-800'
                                        }`}
                                    >
                                        <div className="flex items-center space-x-3">
                                            <Icon size={20} />
                                            <span className="font-medium text-sm">{item.label}</span>
                                        </div>
                                        {item.badge && (
                                            <span className="bg-red-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[18px] text-center animate-pulse">
                                                {item.badge}
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                    )}
                </nav>

                <div className="p-4 border-t border-slate-700">
                    <button 
                        onClick={logout}
                        className="w-full flex items-center justify-center space-x-2 px-4 py-2 bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white rounded-lg transition-all"
                    >
                        <LogOut size={18} />
                        <span>ออกจากระบบ</span>
                    </button>
                    <div className="text-xs text-slate-500 text-center mt-4 leading-tight space-y-1">
                        <p>โรงพยาบาลสามชุก</p>
                        <p>กลุ่มงานสุขภาพดิจิทัล</p>
                        <p className="opacity-60">Version 1.5.0 (Auto-Fetch)</p>
                    </div>
                </div>
            </div>
        </>
    );
};

