                                <div>
                                    <p className="text-xs text-slate-400 uppercase font-semibold mb-0.5">ชื่อผู้ใช้งาน</p>
                                    <p className="text-sm font-bold text-slate-700">{username}</p>
                                </div>
                                <div>
                                    <p className="text-xs text-slate-400 uppercase font-semibold mb-0.5">ชื่อ-นามสกุล</p>
                                    <p className="text-sm font-bold text-slate-700">{name}</p>
                                </div>
                                <div className="grid grid-cols-2 gap-2 pt-2 border-t border-slate-200 mt-2">
                                    <div>
                                        <p className="text-xs text-slate-400 uppercase font-semibold mb-0.5">กลุ่มงาน</p>
                                        <p className="text-xs font-bold text-slate-700 truncate">{getWorkGroupName(workGroupId)}</p>
                                    </div>
                                    <div>
                                        <p className="text-xs text-slate-400 uppercase font-semibold mb-0.5">ฝ่าย/งาน</p>
                                        <p className="text-xs font-bold text-slate-700 truncate">{getDeptName(deptId)}</p>
