    try {
        const p = req.body;
        const fields = [];
        const params = [];

        Object.entries(p).forEach(([key, val]) => {
            // Map Frontend CamelCase to Backend snake_case
            if (key === 'requestId') key = 'request_id';
            else if (key === 'requestDate') key = 'request_date';
            else if (key === 'officialNumber') key = 'official_number';
            else if (key === 'departmentId') key = 'department_id';
            else if (key === 'itemCount') key = 'item_count';
            else if (key === 'createdBy') key = 'created_by';
            else if (key === 'createdAt') key = 'created_at';

            // Skip non-database fields that might be in the spread
            if (['considerationNumber', 'considerationDate'].includes(key)) return;

            fields.push(`${key} = ?`);
            params.push(val);
        });

        if (fields.length > 0) {
            params.push(req.params.id);
            await query(`UPDATE procurements SET ${fields.join(', ')} WHERE id = ?`, params);
        }
        res.json({ success: true });
    } catch (e) { res.status(500).json({ success: false, message: e.message }); }
});

