const express = require('express');
const mysql = require('mysql2');
const router = express.Router();

// ==========================================
// 🛠️ DATABASE CONFIGURATION
// ==========================================
const DB_CONFIG = { 
    host: '10.1.0.201', user: 'sa', password: 'Sam#11294', database: 'procurement_db', 
    port: 3306, waitForConnections: true, connectionLimit: 10, timezone: '+07:00',
    dateStrings: true, charset: 'utf8mb4', supportBigNumbers: true, bigNumberStrings: true
};

const db = mysql.createPool(DB_CONFIG);

// Helper: Query with detailed error logging
const query = (sql, params) => new Promise((resolve, reject) => {
    db.getConnection((err, connection) => {
        if (err) {
            console.error("❌ DB Connection Error:", err);
            return reject(err);
        }
        connection.query("SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';", (err) => {
            if (err) { connection.release(); return reject(err); }
            connection.query(sql, params, (err, res) => {
                connection.release();
                if (err) {
                    console.error("❌ SQL Error Execute:", sql);
                    console.error("❌ Error Detail:", err.sqlMessage);
                    reject(err);
                } else {
                    resolve(res);
                }
            });
        });
    });
});

// Helper: Thai/Arabic Number Converters
const toArabic = (str) => str ? str.toString().replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString()) : "";
const toThaiNum = (num) => num.toString().replace(/\d/g, d => ['๐','๑','๒','๓','๔','๕','๖','๗','๘','๙'][parseInt(d)]);

// Helper: Master Shared Sequence Generator
const generateMasterSequence = async (deptId, explicitPrefix = null) => {
    let prefix = explicitPrefix;
    if (!prefix) {
        const deptRes = await query('SELECT request_prefix FROM departments WHERE id = ?', [deptId]);
        prefix = deptRes[0]?.request_prefix?.trim() || 'สพ.';
    }

    const pattern = `${prefix}%`;
    const sql = `
        SELECT val FROM (
            SELECT request_id as val FROM procurements WHERE request_id LIKE ?
            UNION ALL
            SELECT consideration_number as val FROM considerations WHERE consideration_number LIKE ?
            UNION ALL
            SELECT delivery_note_no as val FROM receivings WHERE delivery_note_no LIKE ?
        ) as master_docs
    `;

    const rows = await query(sql, [pattern, pattern, pattern]);
    let maxNum = 0;

    const normPfx = toArabic(prefix);
    rows.forEach(row => {
        const normVal = toArabic(row.val);
        const remainder = normVal.replace(normPfx, '');
        const match = remainder.match(/(\d+)/);
        if (match) {
            const num = parseInt(match[1], 10);
            if (num > maxNum) maxNum = num;
        }
    });

    return `${prefix}${toThaiNum(maxNum + 1)}`;
};

const getFiscalYear = (dateStr) => {
    const date = new Date(dateStr);
    const month = date.getMonth(); 
    return month >= 9 ? date.getFullYear() + 1 + 543 : date.getFullYear() + 543;
};

// ==========================================
// 🚀 API ROUTES
// ==========================================

router.get('/data', async (req, res) => {
    try {
        const [p, r, c, d, w, cat] = await Promise.all([
            query('SELECT * FROM procurements'), 
