    );
};

export default ProcurementTable;

import React, { useState } from 'react';
import { useApp } from '../services/store';
import { RecordType, ProcurementRecord } from '../types';
import { Plus, Edit2, Trash2, X, Check, AlertCircle, CalendarPlus, AlertTriangle, User as UserIcon, FileSpreadsheet, Printer } from 'lucide-react';

interface Props {
    type: RecordType;
    title: string;
}

const normalizeToNr = (str: string) => {
    if (!str) return '0';
    return str.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
};

const toThaiNr = (num: number) => {
    const thaiDigits = ['๐', '๑', '๒', '๓', '๔', '๕', '๖', '๗', '๘', '๙'];
    return num.toString().replace(/\d/g, d => thaiDigits[parseInt(d)]);
};

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const month = date.getMonth(); 
    const year = date.getFullYear();
    const fiscalYear = month >= 9 ? year + 1 : year;
    return fiscalYear + 543;
};

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, considerations, receivings, addProcurement, updateProcurement, deleteProcurement, getLinkedData, upsertConsideration, upsertReceiving, settings, currentUser, users } = useApp();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [deleteId, setDeleteId] = useState<string | null>(null);
    const [quickDateId, setQuickDateId] = useState<string | null>(null);
    const [quickDateValue, setQuickDateValue] = useState('');
    const [quickDateType, setQuickDateType] = useState<'CONSIDERATION' | 'RECEIVING' | null>(null);
    const [isAutoFilled, setIsAutoFilled] = useState(false);

    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: '',
        considerationNumber: '',
        considerationDate: ''
    });

    const filteredData = procurements.filter(p => p.type === type);

    let fieldLabels = {
        requestId: "เลขกำหนดขอบเขตงาน",
        requestDate: "วันที่กำหนดขอบเขตงาน",
        considerationNumber: "เลขรายงานขอซื้อ",
        considerationDate: "วันที่รายงานขอซื้อ",
        receivingNumber: "เลขรายงานผลการพิจารณา",
        receivingDate: "วันที่รายงานผลการพิจารณา",
        officialNumber: "เลขสั่งซื้อ"
    };

    if (type === RecordType.HIRING) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขอจ้าง",
            considerationDate: "วันที่รายงานขอจ้าง",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขสั่งจ้าง"
        };
    } else if (type === RecordType.OTHER) {
        fieldLabels = {
            requestId: "เลขกำหนดขอบเขตงาน",
            requestDate: "วันที่กำหนดขอบเขตงาน",
            considerationNumber: "เลขรายงานขออนุมัติ",
            considerationDate: "วันที่รายงานขออนุมัติ",
            receivingNumber: "เลขรายงานผลการพิจารณา",
            receivingDate: "วันที่รายงานผลการพิจารณา",
            officialNumber: "เลขที่คำสั่ง/สัญญา"
        };
    }

    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return { name: 'violet', bgSoft: 'bg-violet-50', bgDeep: 'bg-violet-600', bgHover: 'hover:bg-violet-700', text: 'text-violet-700', border: 'border-violet-200', ring: 'focus:ring-violet-500', inputBg: 'bg-violet-50/50' };
            case RecordType.OTHER:
                return { name: 'orange', bgSoft: 'bg-orange-50', bgDeep: 'bg-orange-600', bgHover: 'hover:bg-orange-700', text: 'text-orange-700', border: 'border-orange-200', ring: 'focus:ring-orange-500', inputBg: 'bg-orange-50/50' };
            default:
                return { name: 'blue', bgSoft: 'bg-blue-50', bgDeep: 'bg-blue-600', bgHover: 'hover:bg-blue-700', text: 'text-blue-700', border: 'border-blue-200', ring: 'focus:ring-blue-500', inputBg: 'bg-blue-50/50' };
        }
    })();

    const calculateNextRunNumber = () => {
        const prefix = settings.requestIdPrefix;
        if (!prefix) return '';
        const reqIds = procurements.map(p => p.requestId).filter(id => id && id.startsWith(prefix));
        const consIds = considerations.map(c => c.considerationNumber).filter(id => id && id.startsWith(prefix));
        const recvIds = receivings.map(r => r.deliveryNoteNo).filter(id => id && id.startsWith(prefix));
        const allIds = [...reqIds, ...consIds, ...recvIds];
        let maxNum = 0;
        allIds.forEach(id => {
            const suffix = id.substring(prefix.length);
            const normalizedSuffix = normalizeToNr(suffix);
            const num = parseInt(normalizedSuffix);
            if (!isNaN(num) && num > maxNum) maxNum = num;
        });
        return prefix + toThaiNr(maxNum + 1);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowConfirm(true);
    };

    const handleConfirmSave = async () => {
        if (editingId) {
            updateProcurement(editingId, { ...formData });
        } else {
            await addProcurement({ ...formData, type: type });
        }
        if(formData.considerationNumber || formData.considerationDate) {
             upsertConsideration(formData.requestId, formData.considerationNumber, formData.considerationDate);
        }
        setShowConfirm(false);
        closeModal();
    };

    const handleDeleteClick = (id: string) => {
        const record = procurements.find(p => p.id === id);
        if (record && record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์ลบรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        const nextRequestId = calculateNextRunNumber() || settings.requestIdPrefix || '';
        setFormData({ requestId: nextRequestId, requestDate: '', category: '', itemCount: 0, amount: 0, company: '', remarks: '', considerationNumber: '', considerationDate: '' });
        setIsAutoFilled(true);
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        if (record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์แก้ไขรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        const linked = getLinkedData(record.requestId);
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || ''
        });
        setIsAutoFilled(false);
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
        setIsAutoFilled(false);
    };

    const handleSaveQuickDate = () => {
        if (quickDateId && quickDateValue && quickDateType) {
            let nextNumber = calculateNextRunNumber() || quickDateId;
            if (quickDateType === 'CONSIDERATION') {
                upsertConsideration(quickDateId, nextNumber, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                upsertReceiving(quickDateId, nextNumber, quickDateValue);
            }
            setQuickDateId(null);
            setQuickDateValue('');
            setQuickDateType(null);
        }
    };

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'ไม่ระบุ';

    const handleExportCSV = () => {
        const headers = [fieldLabels.requestId, fieldLabels.requestDate, 'ปีงบประมาณ', fieldLabels.considerationNumber, fieldLabels.considerationDate, fieldLabels.officialNumber, fieldLabels.receivingNumber, fieldLabels.receivingDate, 'จำนวนเงิน', 'บริษัท', 'ผู้บันทึก', 'หมายเหตุ'];
        const rows = filteredData.map(item => {
            const linked = getLinkedData(item.requestId);
            return [item.requestId, item.requestDate, getFiscalYear(item.requestDate), linked.consideration?.considerationNumber || '-', linked.consideration?.considerationDate || '-', item.officialNumber || '-', linked.receiving?.deliveryNoteNo || '-', linked.receiving?.receiveDate || '-', item.amount, `"${item.company.replace(/"/g, '""')}"`, getUserName(item.createdBy), `"${item.remarks.replace(/"/g, '""')}"`].join(',');
        });
        const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `procurement_export_${new Date().toISOString().slice(0,10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const previewNextNum = (quickDateId && quickDateType) ? (calculateNextRunNumber() || quickDateId) : '';

    return (
        <div className="p-4 sm:p-6">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 1cm; }
                    .lg\\:ml-64 { margin-left: 0 !important; }
                    .no-print { display: none !important; }
                    table { width: 100% !important; border-collapse: collapse; font-size: 10pt; }
                    th, td { border: 1px solid #cbd5e1 !important; padding: 4px 8px !important; }
                }
            `}</style>

            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                <h2 className="text-xl sm:text-2xl font-bold text-slate-800">{title}</h2>

                <div className="flex flex-wrap gap-2 no-print w-full sm:w-auto">
                    <button onClick={handleExportCSV} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <FileSpreadsheet size={16} />
                        <span>Excel</span>
                    </button>
                    <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm">
                        <Printer size={16} />
                        <span>Print</span>
                    </button>
                    <button onClick={openNew} className={`w-full sm:w-auto flex items-center justify-center space-x-2 ${theme.bgDeep} ${theme.bgHover} text-white px-4 py-2 rounded-lg text-sm shadow-md`}>
                        <Plus size={16} />
                        <span>บันทึกใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestId}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.requestDate}</th>
                                <th className="px-4 py-3 whitespace-nowrap">ปีงบฯ</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.considerationNumber}</th>
                                <th className="px-4 py-3 whitespace-nowrap">{fieldLabels.considerationDate}</th>
                                <th className={`px-4 py-3 ${theme.bgSoft} whitespace-nowrap`}>{fieldLabels.officialNumber}</th>
                                <th className="px-4 py-3 bg-green-50 whitespace-nowrap">{fieldLabels.receivingNumber}</th>
                                <th className="px-4 py-3 bg-green-50 whitespace-nowrap">{fieldLabels.receivingDate}</th>
                                <th className="px-4 py-3 text-right whitespace-nowrap">จำนวนเงิน</th>
                                <th className="px-4 py-3 whitespace-nowrap">ผู้บันทึก</th>
                                <th className="px-4 py-3 whitespace-nowrap">บริษัท</th>
                                <th className="px-4 py-3 text-center no-print whitespace-nowrap">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredData.length === 0 ? (
                                <tr><td colSpan={12} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูล</td></tr>
                            ) : (
                                filteredData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const isOwner = item.createdBy === currentUser?.id || currentUser?.role === 'ADMIN';
                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                                            <td className="px-4 py-3 font-medium text-slate-900 whitespace-nowrap">{item.requestId}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">{item.requestDate}</td>
                                            <td className="px-4 py-3 text-center whitespace-nowrap">{getFiscalYear(item.requestDate)}</td>
                                            <td className="px-4 py-3 text-orange-600 whitespace-nowrap">{linked.consideration?.considerationNumber || '-'}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                {linked.consideration?.considerationDate || (isOwner && (
                                                    <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('CONSIDERATION'); setQuickDateValue(new Date().toISOString().split('T')[0]); }} className={`flex items-center ${theme.text} ${theme.bgSoft} px-2 py-1 rounded no-print text-xs`}><CalendarPlus size={14} className="mr-1" /> เพิ่ม</button>
                                                )) || '-'}
                                            </td>
                                            <td className={`px-4 py-3 ${theme.bgSoft} font-bold ${theme.text} whitespace-nowrap`}>{item.officialNumber || '-'}</td>
                                            <td className="px-4 py-3 bg-green-50 text-green-700 whitespace-nowrap">{linked.receiving?.deliveryNoteNo || '-'}</td>
                                            <td className="px-4 py-3 bg-green-50 whitespace-nowrap">
                                                {linked.receiving?.receiveDate || (isOwner && (
                                                    <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('RECEIVING'); setQuickDateValue(new Date().toISOString().split('T')[0]); }} className="flex items-center text-green-600 bg-green-100 px-2 py-1 rounded no-print text-xs"><CalendarPlus size={14} className="mr-1" /> เพิ่ม</button>
                                                )) || '-'}
                                            </td>
                                            <td className="px-4 py-3 text-right whitespace-nowrap">{item.amount.toLocaleString()}</td>
                                            <td className="px-4 py-3 whitespace-nowrap">
                                                <div className="flex items-center text-xs text-slate-500"><UserIcon size={12} className="mr-1 opacity-50"/>{getUserName(item.createdBy)}</div>
                                            </td>
                                            <td className="px-4 py-3 truncate max-w-[150px]">{item.company}</td>
                                            <td className="px-4 py-3 text-center no-print">
                                                <div className="flex justify-center space-x-2">
                                                    {isOwner ? (
                                                        <>
                                                            <button onClick={() => openEdit(item)} className="p-1 text-slate-600 hover:bg-slate-200 rounded"><Edit2 size={16} /></button>
                                                            <button onClick={() => handleDeleteClick(item.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16} /></button>
                                                        </>
                                                    ) : <span className="text-[10px] text-slate-400">Read Only</span>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Quick Date Modal */}
            {quickDateId && (
                <div className="fixed inset-0 bg-black/40 z-[100] flex items-center justify-center p-4">
                    <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold">ระบุวันที่</h3>
                            <button onClick={() => setQuickDateId(null)} className="text-slate-400"><X size={20}/></button>
                        </div>
                        <p className="text-xs text-slate-500 mb-4">ระบบจะรันเลข <span className="font-bold text-slate-800">{previewNextNum}</span> ให้อัตโนมัติ</p>
                        <input type="date" className="w-full border rounded-lg px-3 py-2 mb-6 outline-none focus:ring-2 ring-blue-500 text-slate-900 bg-white" value={quickDateValue} onChange={e => setQuickDateValue(e.target.value)} />
                        <div className="flex gap-2">
                            <button onClick={() => setQuickDateId(null)} className="flex-1 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm">ยกเลิก</button>
                            <button onClick={handleSaveQuickDate} className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium">บันทึก</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Form Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-0 sm:p-4 no-print">
                    <div className="bg-white sm:rounded-xl shadow-2xl w-full max-w-2xl h-full sm:h-auto max-h-screen flex flex-col overflow-hidden relative">
                        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 sticky top-0">
                            <h3 className="text-lg font-semibold text-slate-800">{editingId ? 'แก้ไขรายการ' : 'บันทึกรายการใหม่'}</h3>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600 p-1"><X size={28} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 flex-1 overflow-y-auto">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestId} *</label>
                                    <input 
                                        required 
                                        type="text" 
                                        className={`w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 ${theme.ring} outline-none bg-white font-medium ${isAutoFilled ? 'text-red-600' : 'text-slate-900'}`} 
                                        value={formData.requestId} 
                                        onChange={e => {
                                            setFormData({...formData, requestId: e.target.value});
                                            setIsAutoFilled(false);
                                        }} 
                                    />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{fieldLabels.requestDate} *</label>
                                    <input required type="date" className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 outline-none bg-white text-slate-900" value={formData.requestDate} onChange={e => setFormData({...formData, requestDate: e.target.value})} />
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">หมวดพัสดุ</label>
                                    <select className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                        <option value="">เลือกหมวด...</option>
                                        {settings.categories?.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                                    </select>
                                </div>
                                <div className="col-span-1">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
