            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        setFormData({ 
