};

export default ProcurementTable;

import React, { useState, useMemo } from 'react';
import { useApp } from '../services/store';
import { RecordType, ProcurementRecord } from '../types';
import { Plus, Edit2, Trash2, X, Check, AlertCircle, FileSpreadsheet, Printer, User as UserIcon, Loader2, AlertTriangle, Search, ChevronLeft, ChevronRight, Calendar } from 'lucide-react';

interface Props {
    type: RecordType;
    title: string;
}

const getFiscalYear = (dateStr: string) => {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const month = date.getMonth(); 
    const year = date.getFullYear();
    const fiscalYear = month >= 9 ? year + 1 : year;
    return fiscalYear + 543;
};

// Helper function to extract numeric sequence from Request ID string (handles Thai/Arabic digits)
const extractRequestNumber = (requestId: string) => {
    if (!requestId) return 0;
    // Convert Thai digits to Arabic digits for comparison
    const normalized = requestId.replace(/[๐-๙]/g, d => "๐๑๒๓๔๕๖๗๘๙".indexOf(d).toString());
    // Extract trailing digits (the actual running number)
    const match = normalized.match(/(\d+)$/);
    return match ? parseInt(match[1], 10) : 0;
};

const ProcurementTable: React.FC<Props> = ({ type, title }) => {
    const { procurements, addProcurement, updateProcurement, deleteProcurement, getLinkedData, upsertConsideration, upsertReceiving, settings, currentUser, users } = useApp();

    // --- State ---
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [deleteId, setDeleteId] = useState<string | null>(null);

    // Quick Date Modal States
    const [quickDateId, setQuickDateId] = useState<string | null>(null);
    const [quickDateValue, setQuickDateValue] = useState('');
    const [quickDateType, setQuickDateType] = useState<'CONSIDERATION' | 'RECEIVING' | null>(null);
    const [existingDocNumber, setExistingDocNumber] = useState<string | null>(null);

    const [isSaving, setIsSaving] = useState(false);

    // --- Search & Pagination State ---
    const [searchTerm, setSearchTerm] = useState('');
    const [itemsPerPage, setItemsPerPage] = useState<number>(10);
    const [currentPage, setCurrentPage] = useState<number>(1);

    const [formData, setFormData] = useState({
        requestId: '',
        requestDate: '',
        category: '',
        itemCount: 0,
        amount: 0,
        company: '',
        remarks: '',
        considerationNumber: '',
        considerationDate: '',
        officialNumber: ''
    });

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'ไม่ระบุ';

    // --- Data Processing (Search & Sort) ---
    const processedData = useMemo(() => {
        let data = procurements.filter(p => p.type === type);

        // 1. Search Filter
        if (searchTerm.trim()) {
            const lowerTerm = searchTerm.toLowerCase();
            data = data.filter(item => {
                const linked = getLinkedData(item.requestId);
                const userName = getUserName(item.createdBy).toLowerCase();
                const fiscalYear = getFiscalYear(item.requestDate);

                return (
                    (item.requestId && item.requestId.toLowerCase().includes(lowerTerm)) ||
                    (item.requestDate && item.requestDate.includes(lowerTerm)) ||
                    (item.category && item.category.toLowerCase().includes(lowerTerm)) ||
                    (item.company && item.company.toLowerCase().includes(lowerTerm)) ||
                    (item.remarks && item.remarks.toLowerCase().includes(lowerTerm)) ||
                    (item.officialNumber && item.officialNumber.toLowerCase().includes(lowerTerm)) ||
                    (String(item.amount).includes(lowerTerm)) ||
                    (userName.includes(lowerTerm)) ||
                    (String(fiscalYear).includes(lowerTerm)) ||
                    (linked.consideration?.considerationNumber && linked.consideration.considerationNumber.toLowerCase().includes(lowerTerm)) ||
                    (linked.consideration?.considerationDate && linked.consideration.considerationDate.includes(lowerTerm)) ||
                    (linked.receiving?.deliveryNoteNo && linked.receiving.deliveryNoteNo.toLowerCase().includes(lowerTerm)) ||
                    (linked.receiving?.receiveDate && linked.receiving.receiveDate.includes(lowerTerm))
                );
            });
        }

        // 2. Sort Logic
        return data.sort((a, b) => {
            const numA = extractRequestNumber(a.requestId);
            const numB = extractRequestNumber(b.requestId);
            if (numB !== numA) return numB - numA;
            return b.createdAt - a.createdAt;
        });
    }, [procurements, type, searchTerm, users]);

    // --- Pagination Logic ---
    const totalItems = processedData.length;
    const totalPages = itemsPerPage === -1 ? 1 : Math.ceil(totalItems / itemsPerPage);

    React.useEffect(() => {
        setCurrentPage(1);
    }, [searchTerm, itemsPerPage]);

    const paginatedData = useMemo(() => {
        if (itemsPerPage === -1) return processedData;
        const startIndex = (currentPage - 1) * itemsPerPage;
        return processedData.slice(startIndex, startIndex + itemsPerPage);
    }, [processedData, currentPage, itemsPerPage]);


    // Dynamic Labels
    let fieldLabels = {
        requestId: "กำหนดขอบเขตงานขอซื้อ / วันที่",
        officialNumber: "เลขสั่งซื้อ",
        considerationLabel: "รายงานขอซื้อ / วันที่",
        receivingLabel: "ผลพิจารณาขอซื้อ / วันที่"
    };

    if (type === RecordType.HIRING) {
        fieldLabels = {
            requestId: "กำหนดขอบเขตงานขอจ้าง / วันที่",
            officialNumber: "เลขสั่งจ้าง",
            considerationLabel: "รายงานขอจ้าง / วันที่",
            receivingLabel: "ผลพิจารณาขอจ้าง / วันที่"
        };
    } else if (type === RecordType.OTHER) {
        fieldLabels = {
            requestId: "กำหนดขอบเขตงาน / วันที่",
            officialNumber: "เลขสั่งซื้อ/จ้าง",
            considerationLabel: "รายงานขอ / วันที่",
            receivingLabel: "ผลพิจารณา / วันที่"
        };
    }

    const theme = (() => {
        switch (type) {
            case RecordType.HIRING:
                return { name: 'violet', bgSoft: 'bg-violet-50', bgDeep: 'bg-violet-600', bgHover: 'hover:bg-violet-700', text: 'text-violet-700', border: 'border-violet-200', ring: 'focus:ring-violet-500', inputBg: 'bg-violet-50/50' };
            case RecordType.OTHER:
                return { name: 'orange', bgSoft: 'bg-orange-50', bgDeep: 'bg-orange-600', bgHover: 'hover:bg-orange-700', text: 'text-orange-700', border: 'border-orange-200', ring: 'focus:ring-orange-500', inputBg: 'bg-orange-50/50' };
            default:
                return { name: 'blue', bgSoft: 'bg-blue-50', bgDeep: 'bg-blue-600', bgHover: 'hover:bg-blue-700', text: 'text-blue-700', border: 'border-blue-200', ring: 'focus:ring-blue-500', inputBg: 'bg-blue-50/50' };
        }
    })();

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setShowConfirm(true);
    };

    const handleConfirmSave = async () => {
        if (editingId) {
            updateProcurement(editingId, { ...formData });
            setShowConfirm(false);
            closeModal();
        } else {
            const result = await addProcurement({ ...formData, requestId: null, type: type });
            if (result.success) {
                setShowConfirm(false);
                closeModal();
            } else {
                setShowConfirm(false);
                alert(result.message || 'เกิดข้อผิดพลาดในการบันทึก');
            }
        }
    };

    const handleDeleteClick = (id: string) => {
        const record = procurements.find(p => p.id === id);
        if (record && record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์ลบรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        setDeleteId(id);
    };

    const confirmDelete = () => {
        if (deleteId) {
            deleteProcurement(deleteId);
            setDeleteId(null);
        }
    };

    const openNew = () => {
        setEditingId(null);
        setFormData({ 
            requestId: '', 
            requestDate: '', 
            category: '', 
            itemCount: 0, 
            amount: 0, 
            company: '', 
            remarks: '', 
            considerationNumber: '', 
            considerationDate: '',
            officialNumber: ''
        });
        setIsModalOpen(true);
    };

    const openEdit = (record: ProcurementRecord) => {
        if (record.createdBy !== currentUser?.id && currentUser?.role !== 'ADMIN') {
            alert('คุณไม่มีสิทธิ์แก้ไขรายการนี้ (เฉพาะผู้บันทึกข้อมูลเท่านั้น)');
            return;
        }
        const linked = getLinkedData(record.requestId);
        setEditingId(record.id);
        setFormData({
            requestId: record.requestId,
            requestDate: record.requestDate,
            category: record.category,
            itemCount: record.itemCount,
            amount: record.amount,
            company: record.company,
            remarks: record.remarks,
            considerationNumber: linked.consideration?.considerationNumber || '',
            considerationDate: linked.consideration?.considerationDate || '',
            officialNumber: record.officialNumber || ''
        });
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingId(null);
        setShowConfirm(false);
    };

    const handleSaveQuickDate = async () => {
        if (quickDateId && quickDateValue && quickDateType) {
            setIsSaving(true);
            let success = false;
            if (quickDateType === 'CONSIDERATION') {
                // Pass existing doc number to keep it the same, just update the date
                success = await upsertConsideration(quickDateId, existingDocNumber, quickDateValue);
            } else if (quickDateType === 'RECEIVING') {
                // Pass existing doc number to keep it the same, just update the date
                success = await upsertReceiving(quickDateId, existingDocNumber, quickDateValue);
            }

            setIsSaving(false);
            if (success) {
                setQuickDateId(null);
                setQuickDateValue('');
                setQuickDateType(null);
                setExistingDocNumber(null);
            } else {
                alert('เกิดข้อผิดพลาดในการบันทึกข้อมูล');
            }
        }
    };

    const hasValue = (val: string | null | undefined) => {
        return val && val.trim() !== '' && val.trim() !== '-';
    };

    const exportToExcel = () => {
        const headers = [
            "ปีงบประมาณ", "หมวดพัสดุ", "กำหนดขอบเขตงาน", "วันที่กำหนดขอบเขต", 
            fieldLabels.officialNumber,
            "รายงานขอซื้อ/จ้าง", "วันที่รายงาน",
            "ผลพิจารณา", "วันที่พิจารณา",
            "รายการ", "จำนวนเงิน", "บริษัท", "หมายเหตุ", "ผู้บันทึก"
        ];

        const rows = processedData.map(item => {
            const linked = getLinkedData(item.requestId);
            return [
                getFiscalYear(item.requestDate),
                `"${item.category || '-'}"`,
                `"${item.requestId}"`,
                item.requestDate,
                `"${item.officialNumber || '-'}"`,
                `"${linked.consideration?.considerationNumber || '-'}"`,
                linked.consideration?.considerationDate || '-',
                `"${linked.receiving?.deliveryNoteNo || '-'}"`,
                linked.receiving?.receiveDate || '-',
                item.itemCount,
                item.amount,
                `"${item.company.replace(/"/g, '""')}"`,
                `"${item.remarks?.replace(/"/g, '""') || '-'}"`,
                `"${getUserName(item.createdBy)}"`
            ].join(',');
        });

        const csvContent = "\uFEFF" + [headers.join(','), ...rows].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', `${title.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <div className="p-4 sm:p-6 w-full max-w-full">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 5mm; }
                    body { background: white; }
                    .no-print { display: none !important; }
                    .lg\\:ml-64 { margin-left: 0 !important; }
                    table { width: 100% !important; border-collapse: collapse !important; font-size: 8pt !important; table-layout: auto !important; }
                    th, td { border: 1px solid #ccc !important; padding: 2px 4px !important; }
                    .bg-slate-50 { background-color: #f8fafc !important; -webkit-print-color-adjust: exact; }
                    .bg-orange-50 { background-color: #fff7ed !important; -webkit-print-color-adjust: exact; }
                    .bg-blue-50 { background-color: #eff6ff !important; -webkit-print-color-adjust: exact; }
                    .bg-green-50 { background-color: #f0fdf4 !important; -webkit-print-color-adjust: exact; }
                }
            `}</style>

            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4 no-print">
                <h2 className="text-xl sm:text-2xl font-bold text-slate-800">{title}</h2>
                <div className="flex flex-wrap gap-2 w-full sm:w-auto">
                    <button onClick={exportToExcel} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm transition-colors">
                        <FileSpreadsheet size={16} />
                        <span className="hidden sm:inline">Excel</span>
                    </button>
                    <button onClick={() => window.print()} className="flex-1 sm:flex-none flex items-center justify-center space-x-2 bg-slate-600 hover:bg-slate-700 text-white px-3 py-2 rounded-lg text-sm shadow-sm transition-colors">
                        <Printer size={16} />
                        <span className="hidden sm:inline">พิมพ์ PDF</span>
                    </button>
                    <button onClick={openNew} className={`flex-[2] sm:flex-none flex items-center justify-center space-x-2 ${theme.bgDeep} ${theme.bgHover} text-white px-4 py-2 rounded-lg text-sm shadow-md transition-all`}>
                        <Plus size={16} />
                        <span>บันทึกใหม่</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-4 mb-4 flex justify-end items-center gap-4 no-print">
                <div className="relative w-full sm:w-72">
                    <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                        <Search size={16} className="text-slate-400" />
                    </div>
                    <input 
                        type="text" 
                        className="bg-slate-50 border border-slate-300 text-slate-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full pl-10 p-2 outline-none transition-all" 
                        placeholder="ค้นหาทุกคอลัมน์..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    {searchTerm && (
                        <button onClick={() => setSearchTerm('')} className="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-400 hover:text-slate-600">
                            <X size={14} />
                        </button>
                    )}
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden w-full flex flex-col">
                <div className="w-full overflow-x-auto">
                    <table className="w-full text-[13px] text-left text-slate-600 table-auto border-collapse">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-2 py-3 text-center whitespace-nowrap w-[4%]">ปีงบฯ</th>
                                <th className="px-3 py-3 whitespace-nowrap w-[9%]">หมวดพัสดุ</th>
                                <th className="px-3 py-3 whitespace-nowrap w-[10%]">{fieldLabels.requestId}</th>
                                <th className={`px-3 py-3 ${theme.bgSoft} whitespace-nowrap w-[9%]`}>{fieldLabels.officialNumber}</th>
                                <th className="px-3 py-3 bg-orange-50 whitespace-nowrap text-orange-800 font-bold w-[10%]">{fieldLabels.considerationLabel}</th>
                                <th className="px-3 py-3 bg-green-50 whitespace-nowrap w-[10%]">{fieldLabels.receivingLabel}</th>
                                <th className="px-2 py-3 text-center whitespace-nowrap w-[3%]">รายการ</th>
                                <th className="px-3 py-3 text-right whitespace-nowrap w-[8%]">จำนวนเงิน</th>
                                <th className="px-3 py-3 w-[18%]">หมายเหตุ</th>
                                <th className="px-3 py-3 w-[12%]">ผู้บันทึก</th>
                                <th className="px-3 py-3 text-center no-print w-[7%]">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody>
                            {paginatedData.length === 0 ? (
                                <tr><td colSpan={11} className="px-4 py-8 text-center text-slate-400">ไม่พบข้อมูล</td></tr>
                            ) : (
                                paginatedData.map((item) => {
                                    const linked = getLinkedData(item.requestId);
                                    const isOwner = item.createdBy === currentUser?.id || currentUser?.role === 'ADMIN';
                                    const user = users.find(u => u.id === item.createdBy);
                                    const dept = settings.departments.find(d => d.id === user?.departmentId);
                                    const wg = settings.workGroups.find(g => g.id === dept?.workGroupId);

                                    return (
                                        <tr key={item.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
