                                                                        setQuickDateType('CONSIDERATION'); 
                                                                        setQuickDateValue(linked.consideration?.considerationDate || ''); 
                                                                        setExistingDocNumber(linked.consideration?.considerationNumber || null);
                                                                    }}
                                                                    className="ml-2 p-1 text-slate-300 hover:text-orange-500 no-print opacity-0 group-hover/cell:opacity-100 transition-all"
                                                                    title="แก้ไขวันที่"
                                                                >
                                                                    <Edit2 size={12} />
                                                                </button>
                                                            )}
                                                        </div>
                                                    </div>
                                                ) : (
                                                    isOwner && (
                                                        <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('CONSIDERATION'); setQuickDateValue(new Date().toISOString().split('T')[0]); setExistingDocNumber(null); }} className="flex items-center text-orange-600 bg-orange-50 px-2 py-1 rounded no-print text-[11px] hover:bg-orange-100 transition-colors">
                                                            <Plus size={12} className="mr-1" /> เพิ่มข้อมูล
                                                        </button>
                                                    )
                                                )}
                                            </td>

                                            {/* Receiving Column (Green Theme) */}
                                            <td className="px-3 py-3 bg-green-50/30 align-top group/cell">
                                                {hasValue(linked.receiving?.deliveryNoteNo) ? (
                                                    <div className="flex flex-col text-green-700">
                                                        <span className="font-bold leading-tight">{linked.receiving?.deliveryNoteNo}</span>
                                                        <div className="flex items-center mt-0.5">
                                                            <span className="text-[13px] font-bold text-green-500">{linked.receiving?.receiveDate || '-'}</span>
                                                            {isOwner && (
                                                                <button 
                                                                    onClick={() => { 
                                                                        setQuickDateId(item.requestId); 
                                                                        setQuickDateType('RECEIVING'); 
                                                                        setQuickDateValue(linked.receiving?.receiveDate || ''); 
                                                                        setExistingDocNumber(linked.receiving?.deliveryNoteNo || null);
                                                                    }}
                                                                    className="ml-2 p-1 text-slate-300 hover:text-green-500 no-print opacity-0 group-hover/cell:opacity-100 transition-all"
                                                                    title="แก้ไขวันที่"
                                                                >
                                                                    <Edit2 size={12} />
                                                                </button>
                                                            )}
                                                        </div>
                                                    </div>
                                                ) : (
                                                    isOwner && (
                                                        <button onClick={() => { setQuickDateId(item.requestId); setQuickDateType('RECEIVING'); setQuickDateValue(new Date().toISOString().split('T')[0]); setExistingDocNumber(null); }} className="flex items-center text-green-600 bg-green-100 px-2 py-1 rounded no-print text-[11px] hover:bg-green-100 transition-colors">
                                                            <Plus size={12} className="mr-1" /> เพิ่มข้อมูล
                                                        </button>
                                                    )
                                                )}
                                            </td>

                                            <td className="px-2 py-3 text-center align-top font-medium text-slate-600">{item.itemCount || '0'}</td>
                                            <td className="px-3 py-3 text-right align-top font-bold text-slate-800 whitespace-nowrap">
                                                {Number(item.amount).toLocaleString('th-TH', { minimumFractionDigits: 2 })}
                                            </td>
                                            <td className="px-3 py-3 align-top">
                                                <div className="text-[12px] text-slate-600 leading-relaxed break-words overflow-hidden whitespace-normal" style={{ wordBreak: 'break-word' }}>{item.remarks || '-'}</div>
                                            </td>
                                            <td className="px-3 py-3 align-top border-l border-slate-50">
                                                <div className="flex flex-col text-[10px] leading-tight text-slate-500 whitespace-normal">
                                                    <span className="font-semibold text-slate-700 mb-1 flex items-center">
                                                        <UserIcon size={10} className="mr-1 opacity-50 flex-shrink-0" />
                                                        {user?.name || 'ไม่ระบุ'}
                                                    </span>
                                                    <span className="opacity-80 leading-[1.2]">{wg?.name || '-'}</span>
                                                    <span className="opacity-60 leading-[1.2] mt-0.5">{dept?.name || '-'}</span>
                                                </div>
                                            </td>
                                            <td className="px-3 py-3 text-center no-print align-top">
                                                <div className="flex justify-center space-x-1.5">
                                                    {isOwner ? (
                                                        <>
                                                            <button onClick={() => openEdit(item)} className="p-1 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded transition-colors" title="แก้ไข"><Edit2 size={14} /></button>
                                                            <button onClick={() => handleDeleteClick(item.id)} className="p-1 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors" title="ลบ"><Trash2 size={14} /></button>
                                                        </>
                                                    ) : <span className="text-[10px] text-slate-300">อ่าน</span>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Footer */}
                <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 flex flex-col sm:flex-row justify-between items-center gap-4 no-print">
                    <div className="flex items-center space-x-4">
                        <div className="flex items-center space-x-2 bg-white rounded-lg border border-slate-300 px-2 py-1">
                            <span className="text-xs text-slate-600 whitespace-nowrap">แสดง</span>
                            <select 
                                value={itemsPerPage} 
                                onChange={(e) => setItemsPerPage(Number(e.target.value))}
                                className="text-xs text-slate-900 font-bold bg-transparent outline-none cursor-pointer"
                            >
                                <option value={10}>10</option>
                                <option value={30}>30</option>
                                <option value={50}>50</option>
                                <option value={-1}>ทั้งหมด</option>
                            </select>
                            <span className="text-xs text-slate-600 whitespace-nowrap">รายการ</span>
                        </div>
                        <span className="text-xs text-slate-500 hidden sm:inline">(ทั้งหมด {totalItems} รายการ)</span>
                    </div>

                    {itemsPerPage !== -1 && (
                        <div className="flex items-center space-x-3">
                            <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-1.5 rounded-full hover:bg-slate-200 disabled:opacity-30 disabled:hover:bg-transparent transition-colors">
                                <ChevronLeft size={18} className="text-slate-600"/>
                            </button>
                            <div className="flex items-center space-x-2 text-sm text-slate-600">
                                <span>หน้า</span>
                                <select value={currentPage} onChange={(e) => setCurrentPage(Number(e.target.value))} className="bg-white border border-slate-300 rounded px-2 py-1 text-sm font-bold text-slate-800 outline-none focus:border-blue-500">
                                    {Array.from({ length: totalPages }, (_, i) => i + 1).map(pageNum => (
                                        <option key={pageNum} value={pageNum}>{pageNum}</option>
                                    ))}
                                </select>
                                <span>จาก {totalPages}</span>
                            </div>
                            <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="p-1.5 rounded-full hover:bg-slate-200 disabled:opacity-30 disabled:hover:bg-transparent transition-colors">
                                <ChevronRight size={18} className="text-slate-600"/>
                            </button>
                        </div>
                    )}
                </div>
            </div>

            {/* Quick Date Modal (Enhanced for Date Editing) */}
