                            </h3>
                            <button onClick={() => !isSaving && setQuickDateId(null)} className="text-slate-400 hover:bg-slate-100 p-1 rounded-full"><X size={20}/></button>
                        </div>

                        <div className="bg-slate-50 p-3 rounded-lg mb-4 border border-slate-100">
                            {existingDocNumber ? (
                                <>
                                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-1">เลขที่เอกสารปัจจุบัน (แก้ไขไม่ได้)</p>
                                    <p className="text-sm font-bold text-slate-800 font-mono">{existingDocNumber}</p>
                                    <p className="text-[10px] text-slate-500 mt-2 italic font-medium">* ระบบจะบันทึกวันที่ใหม่โดยใช้เลขที่เดิม</p>
