                                    <label className="block text-sm font-medium text-slate-700 mb-1">บริษัท/ร้านค้า</label>
                                    <input type="text" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.company} onChange={e => setFormData({...formData, company: e.target.value})} />
