                                    <label className="block text-sm font-medium text-slate-700 mb-1">จำนวนรายการ</label>
                                    <input type="number" min="1" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white text-slate-900" value={formData.itemCount === 0 ? '' : formData.itemCount} onChange={e => setFormData({...formData, itemCount: Number(e.target.value)})} />
