router.post('/procurements', async (req, res) => {
    const p = req.body;
    try {
        const finalRequestId = await generateMasterSequence(p.departmentId);

        let finalOfficialNumber = null;
        // ปรับเงื่อนไขใหม่: ออกเลขเฉพาะยอดเงิน > 5000 และ < 500000
        if (p.amount > 5000 && p.amount < 500000) {
            const deptRes = await query('SELECT prefix FROM departments WHERE id = ?', [p.departmentId]);
            const stdPrefix = deptRes[0]?.prefix?.trim() || 'พด.';
            const fy = getFiscalYear(p.requestDate);
            const start = `${fy - 544}-10-01`, end = `${fy - 543}-09-30`;
            const rows = await query('SELECT official_number FROM procurements WHERE department_id = ? AND request_date BETWEEN ? AND ? AND official_number LIKE ?', [p.departmentId, start, end, `${stdPrefix}%`]);
            let maxNum = 0;
            rows.forEach(row => {
                const parts = row.official_number.replace(stdPrefix, '').split('/');
                const num = parseInt(parts[0]?.match(/(\d+)/)?.[0] || 0);
                if (num > maxNum) maxNum = num;
            });
            finalOfficialNumber = `${stdPrefix} ${maxNum + 1}/${fy}`;
        }

        const newId = `proc_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`;
        // Ensure p.itemCount is passed correctly
        await query('INSERT INTO procurements (id, request_id, request_date, category, item_count, amount, company, remarks, official_number, type, department_id, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
            [newId, finalRequestId, p.requestDate, p.category, p.itemCount, p.amount, p.company, p.remarks, finalOfficialNumber, p.type, p.departmentId, p.createdBy, Date.now()]);

        res.json({ success: true, requestId: finalRequestId });
    } catch (e) { res.status(500).json({ success: false, message: e.message }); }
});

