export default SettingsPage;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ProcurementRecord, ReceivingReport, RecordType, ConsiderationRecord, AppSettings, User, UserRole, Department, ProcurementCategory, UserStatus, WorkGroup } from '../types';

// ==========================================
// ⚙️ BACKEND CONFIGURATION
// ==========================================
const BACKEND_PORT = 3002; 

const getApiUrl = () => {
    if (typeof window === 'undefined') return `http://localhost:${BACKEND_PORT}/api/procurement`;
    if (window.location.protocol === 'https:') return 'api'; 
    let hostname = window.location.hostname;
    if (!hostname || hostname.trim() === '') hostname = 'localhost';
    return `http://${hostname}:${BACKEND_PORT}/api/procurement`;
};

const API_URL = getApiUrl();
console.log(`%c🔌 Connecting to Backend API via: ${API_URL}`, "color: #3b82f6; font-weight: bold;");

interface AppContextType {
    isLoading: boolean;
    serverError: boolean;
    serverErrorMessage: string;
    retryConnection: () => void;
    procurements: ProcurementRecord[];
    receivings: ReceivingReport[];
    considerations: ConsiderationRecord[];
    settings: AppSettings;
    currentUser: User | null;
    users: User[];
    login: (username: string, password: string) => Promise<{ success: boolean, message?: string }>;
    logout: () => void;
    registerUser: (userData: Omit<User, 'id' | 'createdAt'>) => Promise<boolean>;
    deleteUser: (id: string) => void;
    updateUser: (id: string, data: Partial<User>) => void;
    addProcurement: (record: Omit<ProcurementRecord, 'id' | 'createdAt' | 'officialNumber' | 'createdBy'>, force?: boolean) => Promise<{ success: boolean, message?: string, isWarning?: boolean }>;
    updateProcurement: (id: string, record: Partial<ProcurementRecord>) => void;
    deleteProcurement: (id: string) => void;
    addReceiving: (record: Omit<ReceivingReport, 'id' | 'createdAt'>) => void;
    upsertReceiving: (requestId: string, number: string | null, date: string) => Promise<boolean>;
    deleteReceiving: (id: string) => void;
    addConsideration: (record: ConsiderationRecord) => void;
    upsertConsideration: (requestId: string, number: string | null, date: string) => Promise<boolean>;
    getLinkedData: (requestId: string) => { receiving?: ReceivingReport; consideration?: ConsiderationRecord };
    updateSettings: (newSettings: Partial<AppSettings>) => void;
    addDepartment: (dept: Department) => void;
    updateDepartment: (id: string, data: Partial<Department>) => void;
    addWorkGroup: (group: WorkGroup) => void;
    updateWorkGroup: (id: string, data: Partial<WorkGroup>) => void;
    addCategory: (category: ProcurementCategory) => void;
    updateCategory: (id: string, data: Partial<ProcurementCategory>) => void;
    deleteCategory: (id: string) => void;
    checkChronologyIssue: (record: ProcurementRecord) => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [serverError, setServerError] = useState(false);
    const [serverErrorMessage, setServerErrorMessage] = useState('');
    const [users, setUsers] = useState<User[]>([]);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [procurements, setProcurements] = useState<ProcurementRecord[]>([]);
    const [receivings, setReceivings] = useState<ReceivingReport[]>([]);
    const [considerations, setConsiderations] = useState<ConsiderationRecord[]>([]);
    const [settings, setSettings] = useState<AppSettings>({
        requestIdPrefix: 'สพ.๐๐๓๓.๐๒/',
        departments: [],
        categories: [],
        workGroups: []
    });

    const fetchData = async (isBackground = false) => {
        if (!isBackground) { setIsLoading(true); setServerError(false); }
        try {
            const userRes = await fetch(`${API_URL}/users`);
            const userData = await userRes.json();
            setUsers(userData);
            const dataRes = await fetch(`${API_URL}/data`);
            const data = await dataRes.json();
            setProcurements(data.procurements || []);
            setReceivings(data.receivings || []);
            setConsiderations(data.considerations || []);
            setSettings({
                requestIdPrefix: data.settings?.requestIdPrefix || 'สพ.๐๐๓๓.๐๒/',
                departments: data.settings?.departments || [],
                categories: data.settings?.categories || [],
                workGroups: data.settings?.workGroups || []
            });
            if (isBackground) setServerError(false);
        } catch (error: any) {
            if (!isBackground) { setServerError(true); setServerErrorMessage(error.message); }
        } finally {
            if (!isBackground) setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData(false);
        const intervalId = setInterval(() => fetchData(true), 5000);
        const savedUser = sessionStorage.getItem('procurement_session_user');
        if (savedUser) setCurrentUser(JSON.parse(savedUser));
        return () => clearInterval(intervalId);
    }, []);

    const retryConnection = () => { fetchData(false); };

    const login = async (u: string, p: string) => {
        try {
            const res = await fetch(`${API_URL}/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: u, password: p }) });
            const result = await res.json();
            if (result.success) { setCurrentUser(result.user); sessionStorage.setItem('procurement_session_user', JSON.stringify(result.user)); }
            return result;
        } catch (e: any) { return { success: false, message: e.message }; }
    };

    const logout = () => { setCurrentUser(null); sessionStorage.removeItem('procurement_session_user'); };
    const registerUser = async (userData: any) => {
        try { await fetch(`${API_URL}/register`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(userData) }); fetchData(true); return true; } catch (e) { return false; }
    };
    const updateUser = async (id: string, data: any) => {
        try { await fetch(`${API_URL}/users/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); fetchData(true); } catch(e) {}
    };
    const deleteUser = (id: string) => updateUser(id, { status: 'SUSPENDED' });

    const getThaiYear = (dateString: string) => new Date(dateString).getFullYear() + 543;
    const parseRunningNumber = (officialNumber: string | null) => {
        if (!officialNumber) return 0;
        const parts = officialNumber.split('/');
        const match = parts[0]?.match(/(\d+)$/);
        return match ? parseInt(match[1], 10) : 0;
    };

    // Logic: Share sequence across all departments in the same Work Group
    const generateRunningNumber = (type: RecordType, amount: number, dateStr: string) => {
        // Condition: amount > 5,000 AND amount < 500,000
        if (amount <= 5000 || amount >= 500000) return null;

        const userDept = settings.departments?.find(d => d.id === currentUser?.departmentId);
        if (!userDept || !userDept.workGroupId) return null;

        const workGroup = settings.workGroups?.find(g => g.id === userDept.workGroupId);
        const prefix = workGroup?.prefix ? workGroup.prefix.trim() : '';
        const thaiYear = getThaiYear(dateStr);

        // Find all departments in this work group
        const groupDeptIds = settings.departments
            .filter(d => d.workGroupId === userDept.workGroupId)
            .map(d => d.id);

        const existingInGroup = procurements.filter(p => {
            if (p.type !== type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;
            return groupDeptIds.includes(p.departmentId || '');
        });

        let maxNum = 0;
        existingInGroup.forEach(p => {
            const num = parseRunningNumber(p.officialNumber);
            if (!isNaN(num) && num > maxNum) maxNum = num;
        });
        return `${prefix ? prefix + ' ' : ''}${maxNum + 1}/${thaiYear}`;
    };

    const validateChronology = (type: RecordType, dateStr: string): { valid: boolean, message?: string } => {
        const thaiYear = getThaiYear(dateStr);
        const userDept = settings.departments?.find(d => d.id === currentUser?.departmentId);
        if (!userDept) return { valid: true };

        const groupDeptIds = settings.departments
            .filter(d => d.workGroupId === userDept.workGroupId)
            .map(d => d.id);

        const existingInGroup = procurements.filter(p => {
            if (p.type !== type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;
            return groupDeptIds.includes(p.departmentId || '');
        });

        if (existingInGroup.length === 0) return { valid: true };
        let maxNum = 0;
        let maxRecord: ProcurementRecord | null = null;
        existingInGroup.forEach(p => {
            const num = parseRunningNumber(p.officialNumber);
            if (num > maxNum) { maxNum = num; maxRecord = p; }
        });

        if (maxRecord) {
            const latestDate = new Date((maxRecord as ProcurementRecord).requestDate).getTime();
            const newDate = new Date(dateStr).getTime();
            if (newDate < latestDate) {
                return { valid: false, message: `⚠️ วันที่ย้อนหลังกว่าเลขที่ล่าสุดของกลุ่มงาน\nเลขที่ล่าสุด: ${(maxRecord as ProcurementRecord).officialNumber}\nลงวันที่: ${(maxRecord as ProcurementRecord).requestDate}\nคุณกำลังบันทึก: ${dateStr}` };
            }
        }
        return { valid: true };
    };

    const checkChronologyIssue = (record: ProcurementRecord): boolean => {
        if (!record.officialNumber || !record.requestDate) return false;
        const currentNum = parseRunningNumber(record.officialNumber);
        const currentDate = new Date(record.requestDate).getTime();
        const thaiYear = getThaiYear(record.requestDate);
        const dept = settings.departments.find(d => d.id === record.departmentId);
        if (!dept) return false;
        const groupDeptIds = settings.departments.filter(d => d.workGroupId === dept.workGroupId).map(d => d.id);

        return procurements.some(p => {
            if (p.type !== record.type || !p.officialNumber) return false;
            if (getThaiYear(p.requestDate) !== thaiYear) return false;
            if (!groupDeptIds.includes(p.departmentId || '')) return false;
            const pNum = parseRunningNumber(p.officialNumber);
            const pDate = new Date(p.requestDate).getTime();
            return (pNum < currentNum && pDate > currentDate); 
        });
    };

    const addProcurement = async (data: any, force = false) => {
        if (data.amount > 5000 && data.amount < 500000 && !force) {
            const validation = validateChronology(data.type, data.requestDate);
            if (!validation.valid) return { success: false, isWarning: true, message: validation.message };
        }
        const officialNumber = generateRunningNumber(data.type, data.amount, data.requestDate);
        const newRecord = { ...data, officialNumber, departmentId: currentUser?.departmentId, createdBy: currentUser?.id || 'unknown' };
        try {
            await fetch(`${API_URL}/procurements`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newRecord) });
            fetchData(true); return { success: true };
        } catch(e) { return { success: false, message: "Server Error" }; }
    };

    const updateProcurement = async (id: string, data: Partial<ProcurementRecord>) => {
        const currentItem = procurements.find(p => p.id === id);
        if (!currentItem) return;

        let newOfficialNumber = currentItem.officialNumber;
        const amount = data.amount !== undefined ? data.amount : currentItem.amount;
        const reqDate = data.requestDate || currentItem.requestDate;

        // Condition for Update: amount > 5k and < 500k
        if (amount > 5000 && amount < 500000 && !newOfficialNumber) {
            newOfficialNumber = generateRunningNumber(currentItem.type, amount, reqDate);
        } else if (amount <= 5000 || amount >= 500000) {
            newOfficialNumber = null;
        }

        const payload = { ...data, officialNumber: newOfficialNumber };
        try {
            await fetch(`${API_URL}/procurements/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
            fetchData(true);
        } catch(e) { console.error(e); }
    };

    const deleteProcurement = async (id: string) => { await fetch(`${API_URL}/procurements/${id}`, { method: 'DELETE' }); fetchData(true); };
    const addReceiving = async (data: any) => { await fetch(`${API_URL}/receivings`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(data) }); fetchData(true); };
    const deleteReceiving = async (id: string) => { await fetch(`${API_URL}/receivings/${id}`, { method: 'DELETE' }); fetchData(true); };
    const addConsideration = async (record: any) => { await fetch(`${API_URL}/considerations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(record) }); fetchData(true); };
    const upsertReceiving = async (requestId: string, number: string | null, date: string) => {
        try { const res = await fetch(`${API_URL}/receivings/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ requestId, deliveryNoteNo: number, receiveDate: date }) }); if (res.ok) { await fetchData(true); return true; } } catch (e) {} return false;
    };
    const upsertConsideration = async (requestId: string, number: string | null, date: string) => {
        try { const res = await fetch(`${API_URL}/considerations/upsert`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ requestId, considerationNumber: number, considerationDate: date }) }); if (res.ok) { await fetchData(true); return true; } } catch (e) {} return false;
    };
    const getLinkedData = (requestId: string) => ({ receiving: receivings.find(r => r.requestId === requestId), consideration: considerations.find(c => c.requestId === requestId) });
    const updateSettings = async (s: any) => fetchData(true);
    const addDepartment = async (dept: any) => { try { await fetch(`${API_URL}/department`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dept) }); fetchData(true); } catch(e) {} };
    const updateDepartment = async (id: string, data: any) => { try { await fetch(`${API_URL}/department/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); fetchData(true); } catch(e) {} };
    const addWorkGroup = async (group: any) => { await fetch(`${API_URL}/workgroup`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(group) }); fetchData(true); };
    const updateWorkGroup = async (id: string, data: any) => { await fetch(`${API_URL}/workgroup/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); fetchData(true); };
    const addCategory = async (category: any) => { await fetch(`${API_URL}/category`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(category) }); fetchData(true); };
    const updateCategory = async (id: string, data: any) => { await fetch(`${API_URL}/category/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); fetchData(true); };
    const deleteCategory = async (id: string) => { await fetch(`${API_URL}/category/${id}`, { method: 'DELETE' }); fetchData(true); };

    return (
        <AppContext.Provider value={{
            isLoading, serverError, serverErrorMessage, retryConnection,
            procurements, receivings, considerations, settings, currentUser, users,
            login, logout, registerUser, deleteUser, updateUser, addProcurement, updateProcurement, deleteProcurement,
            addReceiving, upsertReceiving, deleteReceiving, addConsideration, upsertConsideration, getLinkedData, updateSettings,
            addDepartment, updateDepartment, addWorkGroup, updateWorkGroup,
            addCategory, updateCategory, deleteCategory, checkChronologyIssue
        }}>
            {children}
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error("useApp must be used within AppProvider");
    return context;
};

