router.post('/receivings/upsert', async (req, res) => {
    const r = req.body;
    try {
        const proc = await query('SELECT request_id, department_id FROM procurements WHERE request_id = ?', [r.requestId]);
        if (proc.length === 0) return res.status(404).json({ success: false, message: "ไม่พบเลขขอบเขตงาน" });
        let finalNumber = r.deliveryNoteNo;
        if (!finalNumber || finalNumber.trim() === '') {
            const fullId = proc[0].request_id;
            const lastPartMatch = toArabic(fullId).match(/(\d+)$/);
            let prefix = lastPartMatch ? fullId.substring(0, fullId.length - lastPartMatch[0].length) : fullId;
            finalNumber = await generateMasterSequence(proc[0].department_id, prefix);
        }
        const existing = await query('SELECT id FROM receivings WHERE request_id = ?', [r.requestId]);
        if (existing.length > 0) await query('UPDATE receivings SET delivery_note_no=?, receive_date=? WHERE request_id=?', [finalNumber, r.receiveDate, r.requestId]);
        else await query('INSERT INTO receivings (id, request_id, delivery_note_no, receive_date, created_at) VALUES (?,?,?,?,?)', [`recv_${Date.now()}`, r.requestId, finalNumber, r.receiveDate, Date.now()]);
        res.json({ success: true });
    } catch (e) { res.status(500).json({ success: false, message: e.message }); }
});

